*/\n  width?: number;\n  /**\n   * Height of the cross in pixels.\n   */\n  height?: number;\n  /**\n   * The y-coordinate of the top left point in the boundary box of the cross.\n   */\n  top?: number;\n  /**\n   * The x-coordinate of the top left point in the boundary box of the cross.\n   */\n  left?: number;\n  className?: number;\n}\n\nexport type Props = SVGProps<SVGPathElement> & CrossProps;\n\nconst getPath = (x: number, y: number, width: number, height: number, top: number, left: number) => {\n  return `M${x},${top}v${height}M${left},${y}h${width}`;\n};\n\nexport const Cross: React.FC<Props> = ({\n  x = 0,\n  y = 0,\n  top = 0,\n  left = 0,\n  width = 0,\n  height = 0,\n  className,\n  ...rest\n}) => {\n  const props = { x, y, top, left, width, height, ...rest };\n\n  if (!isNumber(x) || !isNumber(y) || !isNumber(width) || !isNumber(height) || !isNumber(top) || !isNumber(left)) {\n    return null;\n  }\n\n  return (\n    <path\n      {...svgPropertiesAndEvents(props)}\n      className={clsx('recharts-cross', className)}\n      d={getPath(x, y, width, height, top, left)}\n    />\n  );\n};\n","/*\n * @description: convert camel case to dash case\n * string => string\n */\nexport const getDashCase = (name: string) => name.replace(/([A-Z])/g, v => `-${v.toLowerCase()}`);\n\nexport const getTransitionVal = (props: ReadonlyArray<string>, duration: string | number, easing: string): string =>\n  props.map(prop => `${getDashCase(prop)} ${duration}ms ${easing}`).join(',');\n\n/**\n * Finds the intersection of keys between two objects\n * @param {object} preObj previous object\n * @param {object} nextObj next object\n * @returns an array of keys that exist in both objects\n */\nexport const getIntersectionKeys = (preObj: Record<string, unknown>, nextObj: Record<string, unknown>): string[] =>\n  [Object.keys(preObj), Object.keys(nextObj)].reduce((a, b) => a.filter(c => b.includes(c)));\n\n/**\n * Maps an object to another object\n * @param {function} fn function to map\n * @param {object} obj object to map\n * @returns mapped object\n */\nexport const mapObject = <T extends Record<string, any>, R>(\n  fn: (key: keyof T, value: T[keyof T]) => R,\n  obj: T,\n): { [K in keyof T]: R } =>\n  Object.keys(obj).reduce(\n    (res, key) => ({\n      ...res,\n      [key]: fn(key as keyof T, obj[key as keyof T]),\n    }),\n    {} as { [K in keyof T]: R },\n  );\n","import { getIntersectionKeys, mapObject } from './util';\nimport { BezierEasingFunction, EasingFunction, SpringEasingFunction } from './easing';\nimport { TimeoutController } from './timeoutController';\n\nexport const alpha = (begin: number, end: number, k: number) => begin + (end - begin) * k;\nconst needContinue = ({ from, to }: Val) => from !== to;\n\ntype Val = {\n  from: number;\n  to: number;\n  velocity: number;\n};\n\n/*\n * @description: cal new from value and velocity in each stepper\n * @return: { [styleProperty]: { from, to, velocity } }\n */\nconst calStepperVals = (easing: SpringEasingFunction, preVals: Record<string, Val>, steps: number) => {\n  const nextStepVals: Record<string, Val> = mapObject((key, val: Val): Val => {\n    if (needContinue(val)) {\n      const [newX, newV] = easing(val.from, val.to, val.velocity);\n      return {\n        ...val,\n        from: newX,\n        velocity: newV,\n      };\n    }\n\n    return val;\n  }, preVals);\n\n  if (steps < 1) {\n    return mapObject((key, val: Val): Val => {\n      if (needContinue(val) && nextStepVals[key] != null) {\n        return {\n          ...val,\n          velocity: alpha(val.velocity, nextStepVals[key].velocity, steps),\n          from: alpha(val.from, nextStepVals[key].from, steps),\n        };\n      }\n\n      return val;\n    }, preVals);\n  }\n\n  return calStepperVals(easing, nextStepVals, steps - 1);\n};\n\nexport type FrameId = number;\n\nexport type RequestAnimationFrameCallback = (time: number) => void;\n\nexport type RequestAnimationFrameDi = (callback: RequestAnimationFrameCallback) => FrameId;\n\nexport type CancelAnimationFrameDi = (handle: FrameId) => void;\n\nexport type CancelAnimationFunction = () => void;\n\nexport type StartAnimationFunction = () => CancelAnimationFunction;\n\nfunction createStepperUpdate<T extends Record<string, unknown>>(\n  from: T,\n  to: T,\n  easing: SpringEasingFunction,\n  interKeys: ReadonlyArray<string>,\n  render: (currentStyle: T) => void,\n  timeoutController: TimeoutController,\n) {\n  let preTime: number;\n  let stepperStyle: Record<string, Val> = interKeys.reduce(\n    (res, key) => ({\n      ...res,\n      [key]: {\n        from: from[key],\n        velocity: 0,\n        to: to[key],\n      },\n    }),\n    {},\n  );\n  const getCurrStyle = () => mapObject((key, val: Val) => val.from, stepperStyle);\n  const shouldStopAnimation = () => !Object.values(stepperStyle).filter(needContinue).length;\n\n  let stopAnimation: CancelAnimationFunction | null = null;\n\n  const stepperUpdate = (now: number) => {\n    if (!preTime) {\n      preTime = now;\n    }\n    const deltaTime = now - preTime;\n    const steps = deltaTime / easing.dt;\n\n    stepperStyle = calStepperVals(easing, stepperStyle, steps);\n    // get union set and add compatible prefix\n    render({\n      ...from,\n      ...to,\n      ...getCurrStyle(),\n    });\n\n    preTime = now;\n\n    if (!shouldStopAnimation()) {\n      stopAnimation = timeoutController.setTimeout(stepperUpdate);\n    }\n  };\n\n  // return start animation method\n  return () => {\n    stopAnimation = timeoutController.setTimeout(stepperUpdate);\n\n    // return stop animation method\n    return () => {\n      stopAnimation?.();\n    };\n  };\n}\n\ntype TimingStyle = Record<string, [number, number]>;\n\nfunction createTimingUpdate<T extends Record<string, number>>(\n  from: T,\n  to: T,\n  easing: BezierEasingFunction,\n  duration: number,\n  interKeys: ReadonlyArray<string>,\n  render: (currentStyle: T) => void,\n  timeoutController: TimeoutController,\n) {\n  let stopAnimation: CancelAnimationFunction | null = null;\n\n  const timingStyle: TimingStyle = interKeys.reduce((res: TimingStyle, key: string): TimingStyle => {\n    const fromElement = from[key];\n    const toElement = to[key];\n    if (fromElement == null || toElement == null) {\n      return res;\n    }\n    return {\n      ...res,\n      [key]: [fromElement, toElement] as const,\n    };\n  }, {});\n\n  let beginTime: number;\n\n  const timingUpdate = (now: number) => {\n    if (!beginTime) {\n      beginTime = now;\n    }\n\n    const t = (now - beginTime) / duration;\n    const currStyle = mapObject((key, val) => alpha(...val, easing(t)), timingStyle);\n\n    // get union set and add compatible prefix\n    render({\n      ...from,\n      ...to,\n      ...currStyle,\n    });\n\n    if (t < 1) {\n      stopAnimation = timeoutController.setTimeout(timingUpdate);\n    } else {\n      const finalStyle = mapObject((key, val) => alpha(...val, easing(1)), timingStyle);\n\n      render({\n        ...from,\n        ...to,\n        ...finalStyle,\n      });\n    }\n  };\n\n  // return start animation method\n  return () => {\n    stopAnimation = timeoutController.setTimeout(timingUpdate);\n\n    // return stop animation method\n    return () => {\n      stopAnimation?.();\n    };\n  };\n}\n\n// configure update function\n// eslint-disable-next-line import/no-default-export\nexport default <T extends Record<string, number>>(\n  from: T,\n  to: T,\n  easing: EasingFunction | null,\n  duration: number,\n  render: (currentStyle: T) => void,\n  timeoutController: TimeoutController,\n): StartAnimationFunction => {\n  const interKeys: ReadonlyArray<string> = getIntersectionKeys(from, to);\n\n  if (easing == null) {\n    // no animation, just set to final state\n    return () => {\n      render({\n        ...from,\n        ...to,\n      });\n      return () => {};\n    };\n  }\n\n  return easing.isStepper === true\n    ? createStepperUpdate(from, to, easing, interKeys, render, timeoutController)\n    : createTimingUpdate(from, to, easing, duration, interKeys, render, timeoutController);\n};\n","export const ACCURACY = 1e-4;\n\nconst cubicBezierFactor = (c1: number, c2: number) => [0, 3 * c1, 3 * c2 - 6 * c1, 3 * c1 - 3 * c2 + 1];\n\nconst evaluatePolynomial = (params: ReadonlyArray<number>, t: number) =>\n  params.map((param, i) => param * t ** i).reduce((pre, curr) => pre + curr);\n\nconst cubicBezier = (c1: number, c2: number) => (t: number) => {\n  const params = cubicBezierFactor(c1, c2);\n\n  return evaluatePolynomial(params, t);\n};\n\nconst derivativeCubicBezier = (c1: number, c2: number) => (t: number) => {\n  const params = cubicBezierFactor(c1, c2);\n  const newParams = [...params.map((param, i) => param * i).slice(1), 0];\n\n  return evaluatePolynomial(newParams, t);\n};\n\ntype CubicBezierTemplate = `cubic-bezier(${number},${number},${number},${number})`;\n\ntype NamedBezier = 'linear' | 'ease' | 'ease-in' | 'ease-out' | 'ease-in-out' | CubicBezierTemplate;\n\ntype BezierInput = [NamedBezier] | [number, number, number, number];\n\nexport type BezierEasingFunction = {\n  isStepper: false;\n  (t: number): number;\n};\n\nconst parseCubicBezier = (easing: string): [number, number, number, number] | null => {\n  const easingParts = easing.split('(');\n  if (easingParts.length !== 2 || easingParts[0] !== 'cubic-bezier') {\n    return null;\n  }\n  const numbers = easingParts[1]?.split(')')[0]?.split(',');\n  if (numbers == null || numbers.length !== 4) {\n    return null;\n  }\n  const coords = numbers.map((x: string) => parseFloat(x));\n  return [coords[0]!, coords[1]!, coords[2]!, coords[3]!];\n};\n\nconst getBezierCoordinates = (...args: BezierInput): [number, number, number, number] => {\n  if (args.length === 1) {\n    switch (args[0]) {\n      case 'linear':\n        return [0.0, 0.0, 1.0, 1.0];\n      case 'ease':\n        return [0.25, 0.1, 0.25, 1.0];\n      case 'ease-in':\n        return [0.42, 0.0, 1.0, 1.0];\n      case 'ease-out':\n        return [0.42, 0.0, 0.58, 1.0];\n      case 'ease-in-out':\n        return [0.0, 0.0, 0.58, 1.0];\n      default: {\n        const easing = parseCubicBezier(args[0]);\n        if (easing) {\n          return easing;\n        }\n      }\n    }\n  }\n\n  if (args.length === 4) {\n    return args;\n  }\n\n  // Fallback for invalid inputs. The previous implementation was buggy and would lead to NaN.\n  // Returning linear easing is a safe default.\n  return [0.0, 0.0, 1.0, 1.0];\n};\n\nconst createBezierEasing = (x1: number, y1: number, x2: number, y2: number): BezierEasingFunction => {\n  const curveX = cubicBezier(x1, x2);\n  const curveY = cubicBezier(y1, y2);\n  const derCurveX = derivativeCubicBezier(x1, x2);\n  const rangeValue = (value: number): number => {\n    if (value > 1) {\n      return 1;\n    }\n    if (value < 0) {\n      return 0;\n    }\n\n    return value;\n  };\n\n  const bezier = (_t: number) => {\n    const t = _t > 1 ? 1 : _t;\n    let x = t;\n\n    for (let i = 0; i < 8; ++i) {\n      const evalT = curveX(x) - t;\n      const derVal = derCurveX(x);\n\n      if (Math.abs(evalT - t) < ACCURACY || derVal < ACCURACY) {\n        return curveY(x);\n      }\n\n      x = rangeValue(x - evalT / derVal);\n    }\n\n    return curveY(x);\n  };\n\n  bezier.isStepper = false as const;\n\n  return bezier;\n};\n\n// calculate cubic-bezier using Newton's method\nexport const configBezier = (...args: BezierInput): BezierEasingFunction => {\n  return createBezierEasing(...getBezierCoordinates(...args));\n};\n\ntype SpringInput = {\n  stiff?: number;\n  damping?: number;\n  dt?: number;\n};\n\nexport type SpringEasingFunction = {\n  isStepper: true;\n  dt: number;\n  (currX: number, destX: number, currV: number): [number, number];\n};\n\nexport const configSpring = (config: SpringInput = {}): SpringEasingFunction => {\n  const { stiff = 100, damping = 8, dt = 17 } = config;\n  const stepper = (currX: number, destX: number, currV: number): ReturnType<SpringEasingFunction> => {\n    const FSpring = -(currX - destX) * stiff;\n    const FDamping = currV * damping;\n    const newV = currV + ((FSpring - FDamping) * dt) / 1000;\n    const newX = (currV * dt) / 1000 + currX;\n\n    if (Math.abs(newX - destX) < ACCURACY && Math.abs(newV) < ACCURACY) {\n      return [destX, 0];\n    }\n    return [newX, newV];\n  };\n\n  stepper.isStepper = true as const;\n  stepper.dt = dt;\n\n  return stepper;\n};\n\nexport type EasingFunction = BezierEasingFunction | SpringEasingFunction;\n\nexport type EasingInput = NamedBezier | 'spring' | EasingFunction;\n\nexport const configEasing = (easing: EasingInput): EasingFunction | null => {\n  if (typeof easing === 'string') {\n    switch (easing) {\n      case 'ease':\n      case 'ease-in-out':\n      case 'ease-out':\n      case 'ease-in':\n      case 'linear':\n        return configBezier(easing);\n      case 'spring':\n        return configSpring();\n      default:\n        if (easing.split('(')[0] === 'cubic-bezier') {\n          return configBezier(easing);\n        }\n    }\n  }\n\n  if (typeof easing === 'function') {\n    return easing;\n  }\n\n  return null;\n};\n","/**\n * Callback type for the timeout function.\n * Receives current time in milliseconds as an argument.\n */\nexport type CallbackType = (now: number) => void;\n\n/**\n * A function that, when called, cancels the timeout.\n */\nexport type CancelableTimeout = () => void;\n\nexport interface TimeoutController {\n  /**\n   * Sets a timeout that executes a callback after a specified delay.\n   * Allows setting multiple timeouts and provides a way to cancel them independently.\n   * @param callback - The function to execute after the delay. Receives the current time in milliseconds as an argument.\n   * @param delay (optional) - The time in milliseconds to wait before executing the callback. Defaults to 0.\n   */\n  setTimeout(callback: CallbackType, delay?: number): CancelableTimeout;\n}\n\nexport class RequestAnimationFrameTimeoutController implements TimeoutController {\n  setTimeout(callback: CallbackType, delay: number = 0): CancelableTimeout {\n    const startTime = performance.now();\n\n    let requestId: number | null = null;\n\n    const executeCallback = (now: number): void => {\n      if (now - startTime >= delay) {\n        callback(now);\n        // tests fail without the extra if, even when five lines below it's not needed\n        // TODO finish transition to the mocked timeout controller and then remove this condition\n      } else if (typeof requestAnimationFrame === 'function') {\n        requestId = requestAnimationFrame(executeCallback);\n      }\n    };\n\n    requestId = requestAnimationFrame(executeCallback);\n\n    return () => {\n      if (requestId != null) {\n        cancelAnimationFrame(requestId);\n      }\n    };\n  }\n}\n","import { AnimationManager, createAnimateManager } from './AnimationManager';\nimport { RequestAnimationFrameTimeoutController } from './timeoutController';\n\nexport function createDefaultAnimationManager(): AnimationManager {\n  return createAnimateManager(new RequestAnimationFrameTimeoutController());\n}\n","import { CancelableTimeout, TimeoutController } from './timeoutController';\nimport { StartAnimationFunction } from './configUpdate';\n\nexport type ReactSmoothStyle = string | Record<string, unknown>;\n\n/**\n * Represents a single item in the ReactSmoothQueue.\n * The item can be:\n * - A number representing a delay in milliseconds.\n * - An object representing a style change\n * - A StartAnimationFunction that starts eased transition and calls different render\n *      because of course in Recharts we have to have three ways to do everything\n * - An arbitrary function to be executed\n */\nexport type ReactSmoothQueueItem = number | ReactSmoothStyle | StartAnimationFunction | (() => void);\n\nexport type ReactSmoothQueue = ReadonlyArray<ReactSmoothQueueItem>;\n\nexport type HandleChangeFn = (currentStyle: ReactSmoothStyle) => null | void;\n\nexport type AnimationManager = {\n  stop: () => void;\n  start: (style: ReactSmoothQueue) => void;\n  subscribe: (handleChange: (style: ReactSmoothStyle) => void) => () => void;\n  getTimeoutController(): TimeoutController;\n};\n\nexport function createAnimateManager(timeoutController: TimeoutController): AnimationManager {\n  let currStyle: ReactSmoothQueueItem | ReactSmoothQueue | undefined;\n  let handleChange: HandleChangeFn = () => null;\n  let shouldStop = false;\n  let cancelTimeout: CancelableTimeout | null = null;\n\n  const setStyle = (_style: ReactSmoothQueueItem | ReactSmoothQueue | undefined) => {\n    if (shouldStop) {\n      return;\n    }\n\n    if (Array.isArray(_style)) {\n      if (!_style.length) {\n        return;\n      }\n\n      const styles: ReactSmoothQueue = _style;\n      const [curr, ...restStyles] = styles;\n\n      if (typeof curr === 'number') {\n        cancelTimeout = timeoutController.setTimeout(setStyle.bind(null, restStyles), curr);\n\n        return;\n      }\n\n      setStyle(curr);\n      cancelTimeout = timeoutController.setTimeout(setStyle.bind(null, restStyles));\n      return;\n    }\n\n    if (typeof _style === 'string') {\n      currStyle = _style;\n      handleChange(currStyle);\n    }\n\n    if (typeof _style === 'object') {\n      currStyle = _style;\n      handleChange(currStyle);\n    }\n\n    if (typeof _style === 'function') {\n      _style();\n    }\n  };\n\n  return {\n    stop: () => {\n      shouldStop = true;\n    },\n    start: (style: ReactSmoothQueue) => {\n      shouldStop = false;\n      if (cancelTimeout) {\n        cancelTimeout();\n        cancelTimeout = null;\n      }\n      setStyle(style);\n    },\n    subscribe: (_handleChange: HandleChangeFn) => {\n      handleChange = _handleChange;\n\n      return () => {\n        handleChange = () => null;\n      };\n    },\n    getTimeoutController: () => timeoutController,\n  } satisfies AnimationManager;\n}\n","import { createContext, useContext, useMemo } from 'react';\nimport { AnimationManager } from './AnimationManager';\nimport { createDefaultAnimationManager } from './createDefaultAnimationManager';\n\nexport type AnimationManagerFactory = (animationId: string) => AnimationManager;\n\nexport const AnimationManagerContext = createContext<AnimationManagerFactory>(createDefaultAnimationManager);\n\nexport function useAnimationManager(\n  animationId: string,\n  animationManagerFromProps: AnimationManager | undefined,\n): AnimationManager {\n  const contextAnimationManager = useContext(AnimationManagerContext);\n  return useMemo(\n    () => animationManagerFromProps ?? contextAnimationManager(animationId),\n    [animationId, animationManagerFromProps, contextAnimationManager],\n  );\n}\n","import * as React from 'react';\nimport { useEffect, useRef, useState } from 'react';\nimport { noop } from '../util/DataUtils';\nimport { resolveDefaultProps } from '../util/resolveDefaultProps';\nimport configUpdate from './configUpdate';\nimport { configEasing, EasingInput } from './easing';\nimport { AnimationManager } from './AnimationManager';\nimport { useAnimationManager } from './useAnimationManager';\nimport { Global } from '../util/Global';\nimport { usePrefersReducedMotion } from '../util/usePrefersReducedMotion';\n\ntype JavascriptAnimateProps = {\n  animationId: string;\n  animationManager?: AnimationManager;\n  duration?: number;\n  begin?: number;\n  easing?: EasingInput;\n  isActive?: boolean | 'auto';\n  canBegin?: boolean;\n  onAnimationStart?: () => void;\n  onAnimationEnd?: () => void;\n  children: (time: number) => React.ReactNode;\n};\n\nconst defaultJavascriptAnimateProps = {\n  begin: 0,\n  duration: 1000,\n  easing: 'ease',\n  isActive: true,\n  canBegin: true,\n  onAnimationEnd: () => {},\n  onAnimationStart: () => {},\n} as const satisfies Partial<JavascriptAnimateProps>;\n\ntype TimeAsObject = {\n  t: number;\n};\n\nconst from: TimeAsObject = { t: 0 };\nconst to: TimeAsObject = { t: 1 };\n\nexport function JavascriptAnimate(outsideProps: JavascriptAnimateProps) {\n  const props = resolveDefaultProps(outsideProps, defaultJavascriptAnimateProps);\n  const {\n    isActive: isActiveProp,\n    canBegin,\n    duration,\n    easing,\n    begin,\n    onAnimationEnd,\n    onAnimationStart,\n    children,\n  } = props;\n\n  const prefersReducedMotion = usePrefersReducedMotion();\n\n  const isActive = isActiveProp === 'auto' ? !Global.isSsr && !prefersReducedMotion : isActiveProp;\n\n  const animationManager = useAnimationManager(props.animationId, props.animationManager);\n\n  const [style, setStyle] = useState<TimeAsObject>(isActive ? from : to);\n  const stopJSAnimation = useRef<(() => void) | null>(null);\n\n  useEffect(() => {\n    if (!isActive) {\n      setStyle(to);\n    }\n  }, [isActive]);\n\n  useEffect(() => {\n    if (!isActive || !canBegin) {\n      return noop;\n    }\n\n    const startAnimation = configUpdate<TimeAsObject>(\n      from,\n      to,\n      configEasing(easing),\n      duration,\n      setStyle,\n      animationManager.getTimeoutController(),\n    );\n\n    const onAnimationActive = () => {\n      stopJSAnimation.current = startAnimation();\n    };\n\n    animationManager.start([onAnimationStart, begin, onAnimationActive, duration, onAnimationEnd]);\n\n    return () => {\n      animationManager.stop();\n      if (stopJSAnimation.current) {\n        stopJSAnimation.current();\n      }\n      onAnimationEnd();\n    };\n  }, [isActive, canBegin, duration, easing, begin, onAnimationStart, onAnimationEnd, animationManager]);\n\n  return children(style.t);\n}\n","import { useRef } from 'react';\nimport { uniqueId } from './DataUtils';\n\n/**\n * This hook returns a unique animation id for the object input.\n * If input changes (as in, reference equality is different), the animation id will change.\n * If input does not change, the animation id will not change.\n *\n * This is useful for animations. The Animate component\n * does have a `shouldReAnimate` prop but that doesn't seem to be doing what the name implies.\n * Also, we don't always want to re-animate on every render;\n * we only want to re-animate when the input changes. Not the internal state (e.g. `isAnimating`).\n *\n * @param input The object to check for changes. Uses reference equality (=== operator)\n * @param prefix Optional prefix to use for the animation id\n * @returns A unique animation id\n */\nexport function useAnimationId(input: unknown, prefix: string = 'animation-'): string {\n  const animationId = useRef<string>(uniqueId(prefix));\n  const prevProps = useRef<unknown>(input);\n\n  if (prevProps.current !== input) {\n    animationId.current = uniqueId(prefix);\n    prevProps.current = input;\n  }\n\n  return animationId.current;\n}\n","/**\n * @fileOverview Rectangle\n */\nimport * as React from 'react';\nimport { SVGProps, useEffect, useMemo, useRef, useState } from 'react';\nimport { clsx } from 'clsx';\nimport { AnimationDuration } from '../util/types';\nimport { resolveDefaultProps } from '../util/resolveDefaultProps';\nimport { JavascriptAnimate } from '../animation/JavascriptAnimate';\nimport { EasingInput } from '../animation/easing';\nimport { interpolate } from '../util/DataUtils';\nimport { useAnimationId } from '../util/useAnimationId';\nimport { getTransitionVal } from '../animation/util';\nimport { svgPropertiesAndEvents } from '../util/svgPropertiesAndEvents';\nimport { round, roundTemplateLiteral } from '../util/round';\n\n/**\n * @inline\n */\nexport type RectRadius = number | [number, number, number, number];\n\nconst getRectanglePath = (x: number, y: number, width: number, height: number, radius: RectRadius): string => {\n  const roundedWidth = round(width);\n  const roundedHeight = round(height);\n  const maxRadius = Math.min(Math.abs(roundedWidth) / 2, Math.abs(roundedHeight) / 2);\n  const ySign = roundedHeight >= 0 ? 1 : -1;\n  const xSign = roundedWidth >= 0 ? 1 : -1;\n  const clockWise = (roundedHeight >= 0 && roundedWidth >= 0) || (roundedHeight < 0 && roundedWidth < 0) ? 1 : 0;\n  let path;\n\n  if (maxRadius > 0 && Array.isArray(radius)) {\n    const newRadius: RectRadius = [0, 0, 0, 0];\n    for (let i = 0, len = 4; i < len; i++) {\n      const r: number = radius[i] ?? 0;\n      newRadius[i] = r > maxRadius ? maxRadius : r;\n    }\n\n    path = roundTemplateLiteral`M${x},${y + ySign * newRadius[0]}`;\n\n    if (newRadius[0] > 0) {\n      path += roundTemplateLiteral`A ${newRadius[0]},${newRadius[0]},0,0,${clockWise},${x + xSign * newRadius[0]},${y}`;\n    }\n\n    path += roundTemplateLiteral`L ${x + width - xSign * newRadius[1]},${y}`;\n\n    if (newRadius[1] > 0) {\n      path += roundTemplateLiteral`A ${newRadius[1]},${newRadius[1]},0,0,${clockWise},\n        ${x + width},${y + ySign * newRadius[1]}`;\n    }\n    path += roundTemplateLiteral`L ${x + width},${y + height - ySign * newRadius[2]}`;\n\n    if (newRadius[2] > 0) {\n      path += roundTemplateLiteral`A ${newRadius[2]},${newRadius[2]},0,0,${clockWise},\n        ${x + width - xSign * newRadius[2]},${y + height}`;\n    }\n    path += roundTemplateLiteral`L ${x + xSign * newRadius[3]},${y + height}`;\n\n    if (newRadius[3] > 0) {\n      path += roundTemplateLiteral`A ${newRadius[3]},${newRadius[3]},0,0,${clockWise},\n        ${x},${y + height - ySign * newRadius[3]}`;\n    }\n    path += 'Z';\n  } else if (maxRadius > 0 && radius === +radius && radius > 0) {\n    const newRadius = Math.min(maxRadius, radius);\n\n    path = roundTemplateLiteral`M ${x},${y + ySign * newRadius}\n            A ${newRadius},${newRadius},0,0,${clockWise},${x + xSign * newRadius},${y}\n            L ${x + width - xSign * newRadius},${y}\n            A ${newRadius},${newRadius},0,0,${clockWise},${x + width},${y + ySign * newRadius}\n            L ${x + width},${y + height - ySign * newRadius}\n            A ${newRadius},${newRadius},0,0,${clockWise},${x + width - xSign * newRadius},${y + height}\n            L ${x + xSign * newRadius},${y + height}\n            A ${newRadius},${newRadius},0,0,${clockWise},${x},${y + height - ySign * newRadius} Z`;\n  } else {\n    path = roundTemplateLiteral`M ${x},${y} h ${width} v ${height} h ${-width} Z`;\n  }\n\n  return path;\n};\ninterface RectangleProps {\n  className?: string;\n  /**\n   * The x-coordinate of top left point of the rectangle.\n   * @defaultValue 0\n   */\n  x?: number;\n  /**\n   * The y-coordinate of top left point of the rectangle.\n   * @defaultValue 0\n   */\n  y?: number;\n  /**\n   * Width of the rectangle in pixels.\n   * @defaultValue 0\n   */\n  width?: number;\n  /**\n   * Height of the rectangle in pixels.\n   * @defaultValue 0\n   */\n  height?: number;\n  /**\n   * The radius of corners.\n   *\n   * If you provide a single number, it applies to all four corners.\n   * If you provide an array of four numbers, they apply to top-left, top-right, bottom-right, bottom-left corners respectively.\n   *\n   * @see {@link https://recharts.github.io/en-US/guide/roundedBars/ Guide: Rounded bar corners}\n   *\n   * @defaultValue 0\n   */\n  radius?: RectRadius;\n  /**\n   * @defaultValue false\n   */\n  isAnimationActive?: boolean;\n  /**\n   * @defaultValue false\n   */\n  isUpdateAnimationActive?: boolean;\n  /**\n   * @defaultValue 0\n   */\n  animationBegin?: number;\n  /**\n   * @defaultValue 1500\n   */\n  animationDuration?: AnimationDuration;\n  /**\n   * @defaultValue ease\n   */\n  animationEasing?: EasingInput;\n\n  /**\n   * The customized event handler of click on the rectangle\n   */\n  onClick?: (e: React.MouseEvent<SVGPathElement>) => void;\n  /**\n   * The customized event handler of mousedown on the rectangle\n   */\n  onMouseDown?: (e: React.MouseEvent<SVGPathElement>) => void;\n  /**\n   * The customized event handler of mouseup on the rectangle\n   */\n  onMouseUp?: (e: React.MouseEvent<SVGPathElement>) => void;\n  /**\n   * The customized event handler of mousemove on the rectangle\n   */\n  onMouseMove?: (e: React.MouseEvent<SVGPathElement>) => void;\n  /**\n   * The customized event handler of mouseover on the rectangle\n   */\n  onMouseOver?: (e: React.MouseEvent<SVGPathElement>) => void;\n  /**\n   * The customized event handler of mouseout on the rectangle\n   */\n  onMouseOut?: (e: React.MouseEvent<SVGPathElement>) => void;\n  /**\n   * The customized event handler of mouseenter on the rectangle\n   */\n  onMouseEnter?: (e: React.MouseEvent<SVGPathElement>) => void;\n  /**\n   * The customized event handler of mouseleave on the rectangle\n   */\n  onMouseLeave?: (e: React.MouseEvent<SVGPathElement>) => void;\n}\n\nexport type Props = Omit<SVGProps<SVGPathElement>, 'radius'> & RectangleProps;\n\nexport const defaultRectangleProps = {\n  x: 0,\n  y: 0,\n  width: 0,\n  height: 0,\n  radius: 0,\n  isAnimationActive: false,\n  isUpdateAnimationActive: false,\n  animationBegin: 0,\n  animationDuration: 1500,\n  animationEasing: 'ease',\n} as const satisfies Partial<Props>;\n\n/**\n * Renders a rectangle element. Unlike the {@link https://developer.mozilla.org/en-US/docs/Web/SVG/Reference/Element/rect rect SVG element}, this component supports rounded corners\n * and animation.\n *\n * This component accepts X and Y coordinates in pixels.\n * If you need to position the rectangle based on your chart's data,\n * consider using the {@link ReferenceArea} component instead.\n *\n * @param rectangleProps\n * @constructor\n */\nexport const Rectangle: React.FC<Props> = rectangleProps => {\n  const props = resolveDefaultProps(rectangleProps, defaultRectangleProps);\n  const pathRef = useRef<SVGPathElement>(null);\n  const [totalLength, setTotalLength] = useState(-1);\n\n  useEffect(() => {\n    if (pathRef.current && pathRef.current.getTotalLength) {\n      try {\n        const pathTotalLength = pathRef.current.getTotalLength();\n\n        if (pathTotalLength) {\n          setTotalLength(pathTotalLength);\n        }\n      } catch {\n        // calculate total length error