Function;\n}\n\nexport function combineConfiguredScale(\n  axis: BaseCartesianAxis,\n  realScaleType: D3ScaleType | RechartsScaleType | undefined,\n  axisDomain: NumberDomain | CategoricalDomain | undefined,\n  axisRange: AxisRange | undefined,\n): CustomScaleDefinition | undefined {\n  if (axisDomain == null || axisRange == null) {\n    return undefined;\n  }\n  if (typeof axis.scale === 'function') {\n    return combineConfiguredScaleInternal(axis.scale, axisDomain, axisRange);\n  }\n  return combineConfiguredScaleInternal(realScaleType, axisDomain, axisRange);\n}\n","import * as d3Scales from 'victory-vendor/d3-scale';\nimport { D3ScaleType, RechartsScaleType } from '../../../util/types';\nimport { BaseCartesianAxis } from '../../cartesianAxisSlice';\nimport { upperFirst } from '../../../util/DataUtils';\n\nfunction getD3ScaleName(name: string): D3ScaleType {\n  return `scale${upperFirst(name)}` as D3ScaleType;\n}\n\nfunction isSupportedScaleName(name: string): name is RechartsScaleType {\n  return getD3ScaleName(name) in d3Scales;\n}\n\nexport const combineRealScaleType = (\n  axisConfig: BaseCartesianAxis | undefined,\n  hasBar: boolean,\n  chartType: string,\n): RechartsScaleType | undefined => {\n  if (axisConfig == null) {\n    return undefined;\n  }\n  const { scale, type } = axisConfig;\n  if (scale === 'auto') {\n    if (\n      type === 'category' &&\n      chartType &&\n      (chartType.indexOf('LineChart') >= 0 ||\n        chartType.indexOf('AreaChart') >= 0 ||\n        (chartType.indexOf('ComposedChart') >= 0 && !hasBar))\n    ) {\n      return 'point';\n    }\n    if (type === 'category') {\n      return 'band';\n    }\n\n    return 'linear';\n  }\n  if (typeof scale === 'string') {\n    return isSupportedScaleName(scale) ? scale : 'point';\n  }\n  return undefined;\n};\n","import { InverseScaleFunction } from '../../hooks';\nimport { CustomScaleDefinition } from './CustomScaleDefinition';\n\n/**\n * Binary search to find the index where x would fit in array a.\n * Works for arrays that are sorted both ascending and descending.\n *\n * Unlike d3.bisect, this implementation handles both ascending and descending arrays.\n *\n * @param haystack Sorted array of numbers\n * @param needle Number to find the insertion index for\n * @returns Index where x would fit in array a\n */\nexport function bisect(haystack: ReadonlyArray<number>, needle: number): number {\n  let lo = 0;\n  let hi = haystack.length;\n  const ascending = haystack[0]! < haystack[haystack.length - 1]!;\n\n  while (lo < hi) {\n    const mid = Math.floor((lo + hi) / 2);\n    if (ascending ? haystack[mid]! < needle : haystack[mid]! > needle) {\n      lo = mid + 1;\n    } else {\n      hi = mid;\n    }\n  }\n  return lo;\n}\n\n/**\n * Computes an inverse scale function for categorical/ordinal scales.\n * Uses bisect to find the closest domain value for a given pixel coordinate.\n */\nexport function createCategoricalInverse(\n  scale: CustomScaleDefinition | undefined,\n  allDataPointsOnAxis?: ReadonlyArray<unknown>,\n): InverseScaleFunction | undefined {\n  if (!scale) {\n    return undefined;\n  }\n  const domain = allDataPointsOnAxis ?? scale.domain();\n  // Build an array of pixel positions for each domain value\n  // @ts-expect-error we're attempting to scale unknown without having guarantee that it is a Domain type\n  const pixelPositions: number[] = domain.map(d => scale(d) ?? 0);\n  const range = scale.range();\n\n  if (domain.length === 0 || range.length < 2) {\n    return undefined;\n  }\n\n  return (pixelValue: number): unknown => {\n    // Find the closest domain value using bisect\n    const index = bisect(pixelPositions, pixelValue);\n\n    // Clamp to valid range\n    if (index <= 0) {\n      return domain[0];\n    }\n    if (index >= domain.length) {\n      return domain[domain.length - 1];\n    }\n\n    // Check which neighbor is closer\n    const leftPixel = pixelPositions[index - 1] ?? 0;\n    const rightPixel = pixelPositions[index] ?? 0;\n    if (Math.abs(pixelValue - leftPixel) <= Math.abs(pixelValue - rightPixel)) {\n      return domain[index - 1];\n    }\n    return domain[index];\n  };\n}\n","import { createSelector } from 'reselect';\nimport range from 'es-toolkit/compat/range';\nimport { selectChartLayout } from '../../context/chartLayoutContext';\nimport {\n  getDomainOfStackGroups,\n  getStackedData,\n  getValueByDataKey,\n  isCategoricalAxis,\n  StackId,\n} from '../../util/ChartUtils';\nimport {\n  AxisDomain,\n  AxisTick,\n  AxisType,\n  CartesianTickItem,\n  CategoricalDomain,\n  CategoricalDomainItem,\n  ChartOffsetInternal,\n  Coordinate,\n  RechartsScaleType,\n  DataKey,\n  LayoutType,\n  NumberDomain,\n  Size,\n  StackOffsetType,\n  TickItem,\n} from '../../util/types';\nimport {\n  AxisId,\n  BaseCartesianAxis,\n  CartesianAxisSettings,\n  XAxisOrientation,\n  XAxisSettings,\n  YAxisOrientation,\n  YAxisSettings,\n  ZAxisSettings,\n} from '../cartesianAxisSlice';\nimport { RechartsRootState } from '../store';\nimport {\n  selectChartDataWithIndexes,\n  selectChartDataWithIndexesIfNotInPanoramaPosition4,\n  selectChartDataSliceIfNotInPanorama,\n} from './dataSelectors';\nimport {\n  isWellFormedNumberDomain,\n  numericalDomainSpecifiedWithoutRequiringData,\n  parseNumericalUserDomain,\n} from '../../util/isDomainSpecifiedByUser';\nimport { AppliedChartData, ChartData, ChartDataState } from '../chartDataSlice';\nimport { getPercentValue, hasDuplicate, isNan, isNotNil, isNumOrStr, mathSign } from '../../util/DataUtils';\nimport {\n  BaseCartesianGraphicalItemSettings,\n  BasePolarGraphicalItemSettings,\n  CartesianGraphicalItemSettings,\n  GraphicalItemSettings,\n} from '../graphicalItemsSlice';\nimport { isWellBehavedNumber } from '../../util/isWellBehavedNumber';\nimport { getNiceTickValues, getTickValuesFixedDomain } from '../../util/scale';\nimport {\n  ReferenceAreaSettings,\n  ReferenceDotSettings,\n  ReferenceElementSettings,\n  ReferenceLineSettings,\n} from '../reference