efined = createSelector(\n  (state: RechartsRootState, _axisType: 'zAxis', axisId: AxisId) => selectZAxisSettings(state, axisId),\n  selectZAxisScale,\n  (axis: ZAxisSettings, scale: RechartsScale | undefined): ZAxisWithScale | undefined => {\n    if (axis == null || scale == null) {\n      return undefined;\n    }\n    return {\n      ...axis,\n      scale,\n    };\n  },\n);\n\n/**\n * We are also going to need to implement polar chart directions if we want to support keyboard controls for those.\n */\nexport type AxisDirection = 'left-to-right' | 'right-to-left' | 'top-to-bottom' | 'bottom-to-top';\n\nexport const selectChartDirection: (state: RechartsRootState) => AxisDirection | undefined = createSelector(\n  [selectChartLayout, selectAllXAxes, selectAllYAxes],\n  (\n    layout: LayoutType,\n    allXAxes: ReadonlyArray<XAxisSettings>,\n    allYAxes: ReadonlyArray<YAxisSettings>,\n  ): AxisDirection | undefined => {\n    switch (layout) {\n      case 'horizontal': {\n        return allXAxes.some(axis => axis.reversed) ? 'right-to-left' : 'left-to-right';\n      }\n      case 'vertical': {\n        return allYAxes.some(axis => axis.reversed) ? 'bottom-to-top' : 'top-to-bottom';\n      }\n      // TODO: make this better. For now, right arrow triggers \"forward\", left arrow \"back\"\n      // however, the tooltip moves an unintuitive direction because of how the indices are rendered\n      case 'centric':\n      case 'radial': {\n        return 'left-to-right';\n      }\n      default: {\n        return undefined;\n      }\n    }\n  },\n);\n\nexport const selectRenderedTicksOfAxis: (\n  state: RechartsRootState,\n  axisType: 'xAxis' | 'yAxis',\n  axisId: AxisId,\n) => ReadonlyArray<TickItem> | undefined = (state, axisType, axisId) => {\n  return state.renderedTicks[axisType]?.[axisId];\n};\n\nexport const selectAxisInverseTickSnapScale: (\n  state: RechartsRootState,\n  axisType: 'xAxis' | 'yAxis',\n  axisId: AxisId,\n) => InverseScaleFunction | undefined = createSelector(\n  [selectRenderedTicksOfAxis],\n  (ticks: ReadonlyArray<TickItem> | undefined) => {\n    if (!ticks || ticks.length === 0) {\n      return undefined;\n    }\n\n    return (pixelValue: number) => {\n      // Find the tick with the closest coordinate to pixelValue\n      let minDistance = Infinity;\n      let closestTick = ticks[0];\n\n      for (const tick of ticks) {\n        const distance = Math.abs(tick.coordinate - pixelValue);\n        if (distance < minDistance) {\n          minDistance = distance;\n          closestTick = tick;\n        }\n      }\n      return closestTick?.value;\n    };\n  },\n);\n","import { InverseScaleFunction } from '../../../hooks';\nimport { createCategoricalInverse } from '../../../util/scale/createCategoricalInverse';\nimport { CustomScaleDefinition } from '../../../util/scale/CustomScaleDefinition';\n\nexport function combineInverseScaleFunction(\n  configuredScale: CustomScaleDefinition | undefined,\n): InverseScaleFunction | undefined {\n  if (configuredScale == null) {\n    return undefined;\n  }\n  if ('invert' in configuredScale && typeof configuredScale.invert === 'function') {\n    return configuredScale.invert.bind(configuredScale);\n  }\n  return createCategoricalInverse(configuredScale, undefined);\n}\n","import { RechartsRootState } from '../store';\nimport { TooltipEventType } from '../../util/types';\nimport { useAppSelector } from '../hooks';\nimport { SharedTooltipSettings } from '../tooltipSlice';\n\nexport const selectDefaultTooltipEventType = (state: RechartsRootState): TooltipEventType =>\n  state.options.defaultTooltipEventType;\nexport const selectValidateTooltipEventTypes = (\n  state: RechartsRootState,\n): ReadonlyArray<TooltipEventType> | undefined => state.options.validateTooltipEventTypes;\n\nexport function combineTooltipEventType(\n  shared: SharedTooltipSettings,\n  defaultTooltipEventType: TooltipEventType,\n  validateTooltipEventTypes: ReadonlyArray<TooltipEventType> | undefined,\n): TooltipEventType {\n  if (shared == null) {\n    return defaultTooltipEventType;\n  }\n  const eventType = shared ? 'axis' : 'item';\n  if (validateTooltipEventTypes == null) {\n    return defaultTooltipEventType;\n  }\n  return validateTooltipEventTypes.includes(eventType) ? eventType : defaultTooltipEventType;\n}\n\nexport function selectTooltipEventType(state: RechartsRootState, shared: SharedTooltipSettings): TooltipEventType {\n  const defaultTooltipEventType = selectDefaultTooltipEventType(state);\n  const validateTooltipEventTypes = selectValidateTooltipEventTypes(state);\n  return combineTooltipEventType(shared, defaultTooltipEventType, validateTooltipEventTypes);\n}\n\nexport function useTooltipEventType(shared: SharedTooltipSettings): TooltipEventType | undefined {\n  return useAppSelector(state => selectTooltipEventType(state, shared));\n}\n","import { TickItem } from '../../../util/types';\nimport { TooltipIndex } from '../../tooltipSlice';\nimport { isNan } from '../../../util/DataUtils';\nimport { ActiveLabel } from '../../../synchronisation/types';\n\nexport const combineActiveLabel = (\n  tooltipTicks: ReadonlyArray<TickItem> | undefined,\n  activeIndex: TooltipIndex,\n): ActiveLabel => {\n  const n = Number(activeIndex);\n  if (isNan(n) || activeIndex == null) {\n    return undefined;\n  }\n  return n >= 0 ? tooltipTicks?.[n]?.value : undefined;\n};\n","import { createSlice, current, PayloadAction, prepareAutoBatched } from '@reduxjs/toolkit';\nimport { castDraft } from 'immer';\nimport { TooltipTrigger } from '../chart/types';\nimport type { NameType, Payload, ValueType } from '../component/DefaultTooltipContent';\nimport { CartesianViewBoxRequired, Coordinate, DataKey, PolarCoordinate } from '../util/types';\nimport { AxisId } from './cartesianAxisSlice';\nimport { GraphicalItemId } from './graphicalItemsSlice';\n\n/**\n * One Tooltip can display multiple TooltipPayloadEntries at a time.\n */\nexport type TooltipPayloadEntry = Payload<ValueType, NameType>;\n\n/**\n * So what happens is that the tooltip payload is decided based on the available data, and the dataKey.\n * The dataKey can either be defined on the graphical element (like Line, or Bar)\n * or on the tooltip itself.\n *\n * The data can be defined in the chart element, or in the graphical item.\n *\n * So this type is all the settings, other than the data + dataKey complications.\n */\nexport type TooltipEntrySettings = Omit<TooltipPayloadEntry, 'payload' | 'value'> & {\n  nameKey: DataKey<any> | undefined;\n};\n\n/**\n * This is what Tooltip renders.\n */\nexport type TooltipPayload = ReadonlyArray<TooltipPayloadEntry>;\n\n/**\n * null means no active index\n * string means: whichever index from the chart data it is.\n * Different charts have different requirements on data shapes,\n * and are also responsible for providing a function that will accept this index\n * and return data.\n */\nexport type TooltipIndex = string | null;\n\n/**\n * Different items have different data shapes so the state has no opinion on what the data shape should be;\n * the only requirement is that the chart also provides a searcher function\n * that accepts the data, and a key, and returns whatever the payload in Tooltip should be.\n */\nexport type TooltipPayloadSearcher<T = unknown> = (\n  data: T,\n  index: TooltipIndex,\n  computedData?: unknown,\n  nameKey?: DataKey<any>,\n) => T | undefined;\n\nexport type TooltipPayloadConfiguration = {\n  // This is the data that is the same for all tooltip payloads, regardless of activeIndex\n  settings: TooltipEntrySettings;\n  /**\n   * This is the data that the item has provided, all of it mixed together.\n   * Later as user is interacting with the chart, a redux selector will use this\n   * data + activeIndex, pass it to the TooltipPayloadSearcher, and render the result in a Tooltip.\n   *\n   * Because we have no controls over which data shape the graphical item provides,\n   * this is typed as unknown, and it is the responsibility of the selector\n   * to know what to do with it.\n   *\n   * We can't have better typing here because different graphical items\n   * may provide different data shapes. For example someone may decide to put Area element\n   * in a Sankey chart.\n   */\n  dataDefinedOnItem: unknown;\n  /**\n   * Opportunity for the graphical item to define its own Tooltip coordinates\n   * instead of relying on the axes.\n   *\n   * If undefined, then Recharts will use mouse interaction coordinates, or the axis coordinates,\n   * with some defaults (like, top/left of the chart).\n   *\n   * Unlike the chart data which can be nested, the positions are expected to be flat array or record.\n   * They however should reuse the same tooltip index format as the chart data.\n   */\n  getPosition: (tooltipIndex: NonNullable<TooltipIndex>) => Coordinate | undefined;\n};\n\nexport type ActiveTooltipProps = {\n  activeIndex: TooltipIndex;\n  activeCoordinate: Coordinate | undefined;\n};\n\n/**\n * So this informs the \"tooltip event type\". Tooltip event type can be either \"axis\" or \"item\"\n * and it is used for two things:\n * 1. Sets the active area\n * 2. Sets the background and cursor highlights\n *\n * Some charts only allow to have one type of tooltip event type, some allow both.\n * Those charts that allow both will have one default, and the \"shared\" prop will be used to switch between them.\n * Undefined means \"use the chart default\".\n *\n * Charts that only allow one tooltip event type, will ignore the shared prop.\n */\nexport type SharedTooltipSettings = boolean | undefined;\n\nexport type TooltipSettingsState = {\n  shared: SharedTooltipSettings;\n  trigger: TooltipTrigger;\n  axisId: AxisId;\n  /**\n   * The `active` prop, despite its name, does not mean \"always active\".\n   * It means \"active after user interaction has ended\".\n   * By default, the tooltip is only active while the user is hovering over the chart.\n   * With `active=true`, the tooltip will remain visible after mouse leave event.\n   *\n   * If you want to see the \"active before user interaction\" settings, see `defaultIndex`.\n   *\n   * Undefined means \"depends on user interactions\".\n   */\n  active: boolean | undefined;\n  /**\n   * If you want to set the tooltip to be active before user interaction, you can set this property.\n   */\n  defaultIndex: TooltipIndex | undefined;\n};\n\n/**\n * A generic state for user interaction with the chart.\n * User interaction can come through multiple channels: mouse events, keyboard events, or hardcoded in props, or synchronised from other charts.\n *\n * Each of the interaction states is represented as TooltipInteractionState,\n * and then the selectors and Tooltip will decide which of the interaction states to use.\n */\nexport type TooltipInteractionState = {\n  /**\n   * If user interaction is in progress or not.\n   * Why is this its own property? Why is this not computed from the index?\n   * Certainly if index !== -1 then the tooltip is active, right?\n   * Well not so fast. Recharts allows Tooltips can be set to `active=true`\n   * which means the tooltip remains displayed after the user stops interacting.\n   * - This implies that we cannot set index to <empty value> after interaction ends,\n   *   because the chart must remember the last position just in case the `active` prop on Tooltip is set to true.\n   */\n  active: boolean;\n  /**\n   * This is the current data index that is set for the chart.\n   * This can come from mouse events, keyboard events, or hardcoded in props\n   * in property `defaultIndex` on Tooltip.\n   */\n  index: TooltipIndex | undefined;\n  /**\n   * DataKey filter.\n   *\n   * In case of multiple graphical items, this is the dataKey that is set for the item.\n   * Very useful for `Tooltip.shared=false`, where activeIndex can display multiple values,\n   * but we only want to display one of them.\n   *\n   * If we want to interact with all the graphical items, then this is undefined.\n   * This is the case for eventTooltipType === 'axis' for example.\n   */\n  dataKey: DataKey<any> | undefined;\n  /**\n   * GraphicalItemId filter.\n   *\n   * In case of multiple graphical items with the same dataKey (e.g., multiple Pie charts),\n   * this identifies which specific graphical item is being interacted with.\n   * This is more reliable than coordinate matching for distinguishing between items.\n   */\n  graphicalItemId: string | undefined;\n  /**\n   * The Coordinate where user last interacted with the chart. This needs saved so we can continue to render the tooltip at that point.\n   * This is undefined on several occasions:\n   * - before the user started interacting with the chart,\n   * - when the chart is controlled programmatically through `defaultIndex` prop\n   * - when the chart is controlled using keyboard interactions\n   */\n  coordinate: Coordinate | PolarCoordinate | undefined;\n};\n\nexport type TooltipSyncState = TooltipInteractionState & {\n  /**\n   * Tooltip synchronization is a feature that allows multiple charts to share the same interaction state.\n   * This comes with one specialty - the syncMethod. `syncMethod=value` allows the user to synchronise charts\n   * based on the active label (which is rendered as the title of the Tooltip).\n   * To allow that, we need the label to be stored in the sync state.\n   */\n  label: string | undefined;\n  /**\n   * ViewBox of the chart that sent the sync event.\n   * Used to scale coordinates between charts of different sizes so tooltips\n   * show up in the right place on all synchronized charts.\n   */\n  sourceViewBox: CartesianViewBoxRequired | undefined;\n};\n\nexport const noInteraction: TooltipInteractionState = {\n  active: false,\n  index: null,\n  dataKey: undefined,\n  graphicalItemId: undefined,\n  coordinate: undefined,\n};\n\n/**\n * The tooltip interaction state stores:\n *\n * - Which graphical item is user interacting with at the moment,\n * - which axis (or, which part of chart background) is user interacting with at the moment\n * - The data that individual graphical items wish to be displayed in case the tooltip gets activated\n */\nexport type TooltipState = {\n  /**\n   * This is the state of interactions with individual graphical items.\n   */\n  itemInteraction: {\n    click: TooltipInteractionState;\n    /**\n     * Why is hover activation separate from click activation? Because they are independent:\n     * If a click is set, then mouseLeave should not clear it.\n     * - the opposite is technically true too - but it's difficult to click on things without also hovering.\n     */\n    hover: TooltipInteractionState;\n  };\n  /**\n   * This is the state of interaction with the bar background - which will get mapped\n   * to the axis index.\n   *\n   * Axis interaction is independent of item interaction so the state must also be independent.\n   */\n  axisInteraction: {\n    click: TooltipInteractionState;\n    hover: TooltipInteractionState;\n  };\n  keyboardInteraction: TooltipInteractionState;\n  /**\n   * This part of the state is the information coming from other charts.\n   * If there are two charts with the same syncId, events from one chart will be transferred\n   * to other charts. So this is what the other charts are reporting.\n   */\n  syncInteraction: TooltipSyncState;\n  /**\n   * One graphical item will have one configuration;\n   * hovering over multiple of them (for example with tooltipEventType===axis)\n   * may render multiple tooltip payloads.\n   */\n  tooltipItemPayloads: ReadonlyArray<TooltipPayloadConfiguration>;\n  /**\n   * Tooltip props or other settings that need redux access.\n   * This assumes that there is always only one Tooltip. In case we want to start supporting multiple Tooltips,\n   * we have to change this to an array - and update all the places reading this state too.\n   */\n  settings: TooltipSettingsState;\n};\n\nexport const initialState: TooltipState = {\n  itemInteraction: {\n    click: noInteraction,\n    hover: noInteraction,\n  },\n  axisInteraction: {\n    click: noInteraction,\n    hover: noInteraction,\n  },\n  keyboardInteraction: noInteraction,\n  syncInteraction: {\n    active: false,\n    index: null,\n    dataKey: undefined,\n    label: undefined,\n    coordinate: undefined,\n    sourceViewBox: undefined,\n    graphicalItemId: undefined,\n  },\n  tooltipItemPayloads: [],\n  settings: {\n    shared: undefined,\n    trigger: 'hover',\n    axisId: 0,\n    active: false,\n    defaultIndex: undefined,\n  },\n};\n\n/**\n * This is the event we get when user is interacting with a specific graphical item.\n */\nexport type GraphicalItemTooltipActionPayload = {\n  /**\n   * Every graphical item must report its own index.\n   */\n  activeIndex: TooltipIndex;\n  /**\n   * A graphical item may or may not have a particular dataKey specified.\n   * This is undefined in case the user did not set a dataKey on the graphical item.\n   * In which case the dataKey is implied by the axes settings.\n   */\n  activeDataKey: DataKey<any> | undefined;\n  /**\n   * This is the coordinate where Recharts think the tooltip should appear.\n   *\n   * Graphical items have a preference where to render the actual tooltip\n   * which is defined in the TooltipPayloadConfiguration.positions.\n   *\n   * This property is resolved by combining that preference with the actual user interaction coordinate.\n   * This is not the raw mouse coordinate! We don't store that currently in this slice.\n   *\n   * This can be undefined depending on the graphical item settings, and the tooltip searcher.\n   */\n  activeCoordinate: Coordinate | undefined;\n  /**\n   * ID of the element user is interacting with.\n   * Cannot be undefined - each graphical item is responsible for generating its own ID\n   * in case user did not provide an explicit one.\n   */\n  activeGraphicalItemId: GraphicalItemId;\n};\n\nexport type AxisTooltipActionPayload = {\n  /**\n   * Each axis interaction must report the index of where the user is interacting.\n   */\n  activeIndex: TooltipIndex;\n  /**\n   * DataKey filter. An axis may or may not have a particular dataKey specified.\n   * This is undefined in case the user did not set a dataKey on the axis.\n   * In which case the dataKey is implied by the graphical item settings.\n   */\n  activeDataKey: DataKey<any> | undefined;\n  /**\n   This is the coordinate where Recharts think the tooltip should appear.\n   *\n   * Graphical items have a preference where to render the actual tooltip\n   * which is defined in the TooltipPayloadConfiguration.positions.\n   *\n   * This property is resolved by combining that preference with the actual user interaction coordinate.\n   * This is not the raw mouse coordinate! We don't store that currently in this slice.\n   *\n   * This can be undefined depending on the graphical item settings, and the tooltip searcher.\n   */\n  activeCoordinate?: Coordinate;\n};\n\n/**\n * Keyboard interaction payload has no graphical item ID,\n * and no dataKey, because keyboard interaction is always\n * with the whole chart, not with a specific graphical item.\n */\nexport type KeyboardTooltipActionPayload = {\n  /**\n   * If true, means user is actively interacting with the chart using keyboard.\n   * If false, means user has stopped interacting with the chart using keyboard - perhaps focus has moved away, or ESC key was pressed.\n   */\n  active: boolean;\n  /**\n   * Keyboard interaction index. The middleware is responsible for computing this index based on\n   * current index, key pressed, chart direction, etc.\n   * Each chart type may have different index types (string or number) and different idea on how to iterate them.\n   */\n  activeIndex: TooltipIndex | undefined;\n  /**\n   This is the coordinate where Recharts think the tooltip should appear.\n\n   * Keyboard coordinate follows the same rules as defaultIndex coordinate.\n   * In an absence of mouse coordinates, the chart must compute where to render the tooltip\n   * based on the activeIndex and domain and range.\n   */\n  activeCoordinate: Coordinate | undefined;\n};\n\nconst tooltipSlice = createSlice({\n  name: 'tooltip',\n  initialState,\n  reducers: {\n    addTooltipEntrySettings: {\n      reducer(state, action: PayloadAction<TooltipPayloadConfiguration>) {\n        state.tooltipItemPayloads.push(castDraft(action.payload));\n      },\n      prepare: prepareAutoBatched<TooltipPayloadConfiguration>(),\n    },\n    replaceTooltipEntrySettings: {\n      reducer(state, action: PayloadAction<{ prev: TooltipPayloadConfiguration; next: TooltipPayloadConfiguration }>) {\n        const { prev, next } = action.payload;\n        const index = current(state).tooltipItemPayloads.indexOf(castDraft(prev));\n        if (index > -1) {\n          state.tooltipItemPayloads[index] = castDraft(next);\n        }\n      },\n      prepare: prepareAutoBatched<{ prev: TooltipPayloadConfiguration; next: TooltipPayloadConfiguration }>(),\n    },\n    removeTooltipEntrySettings: {\n      reducer(state, action: PayloadAction<TooltipPayloadConfiguration>) {\n        const index = current(state).tooltipItemPayloads.indexOf(castDraft(action.payload));\n        if (index > -1) {\n          state.tooltipItemPayloads.splice(index, 1);\n        }\n      },\n      prepare: prepareAutoBatched<TooltipPayloadConfiguration>(),\n    },\n    setTooltipSettingsState(state, action: PayloadAction<TooltipSettingsState>) {\n      state.settings = action.payload;\n    },\n    setActiveMouseOverItemIndex(state, action: PayloadAction<GraphicalItemTooltipActionPayload>) {\n      state.syncInteraction.active = false;\n      state.syncInteraction.sourceViewBox = undefined;\n      state.keyboardInteraction.active = false;\n      state.itemInteraction.hover.active = true;\n      state.itemInteraction.hover.index = action.payload.activeIndex;\n      state.itemInteraction.hover.dataKey = action.payload.activeDataKey;\n      state.itemInteraction.hover.graphicalItemId = action.payload.activeGraphicalItemId;\n      state.itemInteraction.hover.coordinate = action.payload.activeCoordinate;\n    },\n    mouseLeaveChart(state) {\n      /*\n       * Clear only the active flags. Why?\n       * 1. Keep Coordinate to preserve animation - next time the Tooltip appears, we want to render it from\n       * the last place where it was when it disappeared.\n       * 2. We want to keep all the properties anyway just in case the tooltip has `active=true` prop\n       * and continues being visible even after the mouse has left the chart.\n       */\n      state.itemInteraction.hover.active = false;\n      state.axisInteraction.hover.active = false;\n    },\n    mouseLeaveItem(state) {\n      state.itemInteraction.hover.active = false;\n    },\n    setActiveClickItemIndex(state, action: PayloadAction<GraphicalItemTooltipActionPayload>) {\n      state.syncInteraction.active = false;\n      state.syncInteraction.sourceViewBox = undefined;\n      state.itemInteraction.click.active = true;\n      state.keyboardInteraction.active = false;\n      state.itemInteraction.click.index = action.payload.activeIndex;\n      state.itemInteraction.click.dataKey = action.payload.activeDataKey;\n      state.itemInteraction.click.graphicalItemId = action.payload.activeGraphicalItemId;\n      state.itemInteraction.click.coordinate = action.payload.activeCoordinate;\n    },\n    setMouseOverAxisIndex(state, action: PayloadAction<AxisTooltipActionPayload>) {\n      state.syncInteraction.active = false;\n      state.syncInteraction.sourceViewBox = undefined;\n      state.axisInteraction.hover.active = true;\n      state.keyboardInteraction.active = false;\n      state.axisInteraction.hover.index = action.payload.activeIndex;\n      state.axisInteraction.hover.dataKey = action.payload.activeDataKey;\n      state.axisInteraction.hover.coordinate = action.payload.activeCoordinate;\n    },\n    setMouseClickAxisIndex(state, action: PayloadAction<AxisTooltipActionPayload>) {\n      state.syncInteraction.active = false;\n      state.syncInteraction.sourceViewBox = undefined;\n      state.keyboardInteraction.active = false;\n      state.axisInteraction.click.active = true;\n      state.axisInteraction.click.index = action.payload.activeIndex;\n      state.axisInteraction.click.dataKey = action.payload.activeDataKey;\n      state.axisInteraction.click.coordinate = action.payload.activeCoordinate;\n    },\n    setSyncInteraction(state, action: PayloadAction<TooltipSyncState>) {\n      state.syncInteraction = action.payload;\n    },\n    setKeyboardInteraction(state, action: PayloadAction<KeyboardTooltipActionPayload>) {\n      state.keyboardInteraction.active = action.payload.active;\n      state.keyboardInteraction.index = action.payload.activeIndex;\n      state.keyboardInteraction.coordinate = action.payload.activeCoordinate;\n    },\n  },\n});\n\nexport const {\n  addTooltipEntrySettings,\n  replaceTooltipEntrySettings,\n  removeTooltipEntrySettings,\n  setTooltipSettingsState,\n  setActiveMouseOverItemIndex,\n  mouseLeaveItem,\n  mouseLeaveChart,\n  setActiveClickItemIndex,\n  setMouseOverAxisIndex,\n  setMouseClickAxisIndex,\n  setSyncInteraction,\n  setKeyboardInteraction,\n} = tooltipSlice.actions;\n\nexport const tooltipReducer = tooltipSlice.reducer;\n","import { noInteraction, TooltipIndex, TooltipInteractionState, TooltipState } from '../../tooltipSlice';\nimport { TooltipEventType } from '../../../util/types';\nimport { TooltipTrigger } from '../../../chart/types';\n\nfunction chooseAppropriateMouseInteraction(\n  tooltipState: TooltipState,\n  tooltipEventType: TooltipEventType,\n  trigger: TooltipTrigger,\n): TooltipInteractionState | undefined {\n  if (tooltipEventType === 'axis') {\n    if (trigger === 'click') {\n      return tooltipState.axisInteraction.click;\n    }\n    return tooltipState.axisInteraction.hover;\n  }\n  if (trigger === 'click') {\n    return tooltipState.itemInteraction.click;\n  }\n  return tooltipState.itemInteraction.hover;\n}\n\nfunction hasBeenActivePreviously(tooltipInteractionState: TooltipInteractionState): boolean {\n  return tooltipInteractionState.index != null;\n}\n\nexport const combineTooltipInteractionState = (\n  tooltipState: TooltipState,\n  tooltipEventType: TooltipEventType | undefined,\n  trigger: TooltipTrigger,\n  defaultIndex: TooltipIndex | undefined,\n): TooltipInteractionState => {\n  if (tooltipEventType == null) {\n    return noInteraction;\n  }\n  const appropriateMouseInteraction = chooseAppropriateMouseInteraction(tooltipState, tooltipEventType, trigger);\n\n  if (appropriateMouseInteraction == null) {\n    return noInteraction;\n  }\n\n  if (appropriateMouseInteraction.active) {\n    return appropriateMouseInteraction;\n  }\n\n  if (tooltipState.keyboardInteraction.active) {\n    return tooltipState.keyboardInteraction;\n  }\n\n  if (tooltipState.syncInteraction.active && tooltipState.syncInteraction.index != null) {\n    return tooltipState.syncInteraction;\n  }\n\n  const activeFromProps = tooltipState.settings.active === true;\n\n  if (hasBeenActivePreviously(appropriateMouseInteraction)) {\n    if (activeFromProps) {\n      return {\n        ...appropriateMouseInteraction,\n        active: true,\n      };\n    }\n  } else if (defaultIndex != null) {\n    return {\n      active: true,\n      coordinate: undefined,\n      dataKey: undefined,\n      index: defaultIndex,\n      graphicalItemId: undefined,\n    };\n  }\n\n  return {\n    ...noInteraction,\n    coordinate: appropriateMouseInteraction.coordinate,\n  };\n};\n","import { TooltipIndex, TooltipInteractionState } from '../../tooltipSlice';\nimport { ChartData } from '../../chartDataSlice';\nimport { isWellBehavedNumber } from '../../../util/isWellBehavedNumber';\nimport { DataKey, CategoricalDomain, NumberDomain } from '../../../util/types';\nimport { getValueByDataKey } from '../../../util/ChartUtils';\nimport { isWellFormedNumberDomain } from '../../../util/isDomainSpecifiedByUser';\n\nfunction toFiniteNumber(value: unknown): number | undefined {\n  if (typeof value === 'number') {\n    return Number.isFinite(value) ? value : undefined;\n  }\n  if (value instanceof Date) {\n    const numericValue = value.valueOf();\n    return Number.isFinite(numericValue) ? numericValue : undefined;\n  }\n  const parsed = Number(value);\n  return Number.isFinite(parsed) ? parsed : undefined;\n}\n\nfunction isValueWithinNumberDomain(value: unknown, domain: NumberDomain): boolean {\n  const numericValue = toFiniteNumber(value);\n  const lowerBound = domain[0];\n  const upperBound = domain[1];\n\n  if (numericValue === undefined) {\n    return false;\n  }\n\n  const min = Math.min(lowerBound, upperBound);\n  const max = Math.max(lowerBound, upperBound);\n  return numericValue >= min && numericValue <= max;\n}\n\nfunction isValueWithinDomain(\n  entry: unknown,\n  axisDataKey: DataKey<unknown> | undefined,\n  domain: NumberDomain | CategoricalDomain | undefined,\n): boolean {\n  if (domain == null || axisDataKey == null) {\n    return true;\n  }\n\n  const value = getValueByDataKey(entry, axisDataKey);\n  if (value == null) {\n    return true;\n  }\n\n  if (!isWellFormedNumberDomain(domain)) {\n    return true;\n  }\n\n  return isValueWithinNumberDomain(value, domain);\n}\n\nexport const combineActiveTooltipIndex = (\n  tooltipInteraction: TooltipInteractionState | undefined,\n  chartData: ChartData,\n  axisDataKey?: DataKey<unknown>,\n  domain?: NumberDomain | CategoricalDomain,\n): TooltipIndex | null => {\n  const desiredIndex: TooltipIndex | undefined = tooltipInteraction?.index;\n  if (desiredIndex == null) {\n    return null;\n  }\n\n  const indexAsNumber = Number(desiredIndex);\n  if (!isWellBehavedNumber(indexAsNumber)) {\n    // this is for charts like Sankey and Treemap that do not support numerical indexes. We need a proper solution for this before we can start supporting keyboard events on these charts.\n    return desiredIndex;\n  }\n\n  /*\n   * Zero is a trivial limit for single-dimensional charts like Line and Area,\n   * but this also needs a support for multidimensional charts like Sankey and Treemap! TODO\n   */\n  const lowerLimit = 0;\n  let upperLimit: number = +Infinity;\n\n  if (chartData.length > 0) {\n    upperLimit = chartData.length - 1;\n  }\n\n  // now let's clamp the desiredIndex between the limits\n  const clampedIndex = Math.max(lowerLimit, Math.min(indexAsNumber, upperLimit));\n  const entry = chartData[clampedIndex];\n\n  if (entry == null) {\n    return String(clampedIndex);\n  }\n\n  if (!isValueWithinDomain(entry, axisDataKey, domain)) {\n    return null;\n  }\n\n  return String(clampedIndex);\n};\n","import { ChartOffsetInternal, Coordinate, LayoutType, TickItem } from '../../../util/types';\nimport { TooltipIndex, TooltipPayloadConfiguration } from '../../tooltipSlice';\n\nexport const combineCoordinateForDefaultIndex = (\n  width: number,\n  height: number,\n  layout: LayoutType,\n  offset: ChartOffsetInternal,\n  tooltipTicks: ReadonlyArray<TickItem> | undefined,\n  defaultIndex: TooltipIndex | undefined,\n  tooltipConfigurations: ReadonlyArray<TooltipPayloadConfiguration>,\n): Coordinate | undefined => {\n  if (defaultIndex == null) {\n    return undefined;\n  }\n  /*\n   * With defaultIndex alone, we don't have enough information to decide _which_ of the multiple tooltips to display.\n   * Maybe one day we could add new prop `activeGraphicalItemId` to the chart to help with that.\n   * Until then, we choose the first one.\n   */\n  const firstConfiguration = tooltipConfigurations[0];\n  const maybePosition: Coordinate | undefined = firstConfiguration?.getPosition(defaultIndex);\n  if (maybePosition != null) {\n    return maybePosition;\n  }\n  const tick = tooltipTicks?.[Number(defaultIndex)];\n  if (!tick) {\n    return undefined;\n  }\n  switch (layout) {\n    case 'horizontal': {\n      return {\n        x: tick.coordinate,\n        y: (offset.top + height) / 2,\n      };\n    }\n    default: {\n      // This logic is not super sound - it conflates vertical, radial, centric layouts into just one. TODO improve!\n      return {\n        x: (offset.left + width) / 2,\n        y: tick.coordinate,\n      };\n    }\n  }\n};\n","import { TooltipIndex, TooltipPayloadConfiguration, TooltipState } from '../../tooltipSlice';\nimport { TooltipEventType } from '../../../util/types';\nimport { TooltipTrigger } from '../../../chart/types';\nimport { GraphicalItemId } from '../../graphicalItemsSlice';\n\nexport const combineTooltipPayloadConfigurations = (\n  tooltipState: TooltipState,\n  tooltipEventType: TooltipEventType | undefined,\n  trigger: TooltipTrigger,\n  defaultIndex: TooltipIndex | undefined,\n): ReadonlyArray<TooltipPayloadConfiguration> => {\n  // if tooltip reacts to axis interaction, then we display all items at the same time.\n  if (tooltipEventType === 'axis') {\n    return tooltipState.tooltipItemPayloads;\n  }\n  /*\n   * By now we already know that tooltipEventType is 'item', so we can only search in itemInteractions.\n   * item means that only the hovered or clicked item will be present in the tooltip.\n   */\n  if (tooltipState.tooltipItemPayloads.length === 0) {\n    // No point filtering if the payload is empty\n    return [];\n  }\n  let filterByGraphicalItemId: GraphicalItemId | undefined;\n  if (trigger === 'hover') {\n    filterByGraphicalItemId = tooltipState.itemInteraction.hover.graphicalItemId;\n  } else {\n    filterByGraphicalItemId = tooltipState.itemInteraction.click.graphicalItemId;\n  }\n  if (tooltipState.syncInteraction.active && filterByGraphicalItemId == null) {\n    /*\n     * When a tooltip is synchronised from another chart, the local itemInteraction\n     * has no graphicalItemId because the user hasn't hovered over this chart.\n     * In that case we show all tooltip items so the receiving chart can display\n     * its own data at the synced index — matching the behaviour of axis-type tooltips.\n     */\n    return tooltipState.tooltipItemPayloads;\n  }\n  if (filterByGraphicalItemId == null && (defaultIndex != null || tooltipState.keyboardInteraction.active)) {\n    /*\n     * So when we use `defaultIndex` - we don't have a dataKey to filter by because user did not hover over anything yet.\n     * In that case let's display the first item in the tooltip; after all, this is `item` interaction case,\n     * so we should display only one item at a time instead of all.\n     */\n    const firstItemPayload = tooltipState.tooltipItemPayloads[0];\n    if (firstItemPayload != null) {\n      return [firstItemPayload];\n    }\n    return [];\n  }\n  return tooltipState.tooltipItemPayloads.filter(tpc => tpc.settings?.graphicalItemId === filterByGraphicalItemId);\n};\n","import { RechartsRootState } from '../store';\nimport { TooltipPayloadSearcher } from '../tooltipSlice';\n\nexport const selectTooltipPayloadSearcher = (state: RechartsRootState): TooltipPayloadSearcher =>\n  state.options.tooltipPayloadSearcher;\n","import { RechartsRootState } from '../store';\nimport { TooltipState } from '../tooltipSlice';\n\nexport const selectTooltipState = (state: RechartsRootState): TooltipState => state.tooltip;\n","import {\n  TooltipEntrySettings,\n  TooltipIndex,\n  TooltipPayload,\n  TooltipPayloadConfiguration,\n  TooltipPayloadEntry,\n  TooltipPayloadSearcher,\n} from '../../tooltipSlice';\nimport { ChartData, ChartDataState } from '../../chartDataSlice';\nimport { DataKey, TooltipEventType } from '../../../util/types';\nimport { findEntryInArray } from '../../../util/DataUtils';\nimport { getTooltipEntry, getValueByDataKey } from '../../../util/ChartUtils';\nimport { getSliced } from '../../../util/getSliced';\nimport { ActiveLabel } from '../../../synchronisation/types';\n\ntype TooltipPayloadItemLike = {\n  name: TooltipEntrySettings['name'];\n  unit: TooltipEntrySettings['unit'];\n  dataKey: DataKey<any> | undefined;\n  payload: unknown;\n  color: string | undefined;\n  fill: string | undefined;\n};\n\nfunction parseName(value: unknown): TooltipEntrySettings['name'] {\n  if (typeof value === 'string' || typeof value === 'number') {\n    return value;\n  }\n  return undefined;\n}\n\nfunction parseUnit(value: unknown): TooltipEntrySettings['unit'] {\n  if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') {\n    return value;\n  }\n  return undefined;\n}\n\nfunction parseDataKey(value: unknown): DataKey<any> | undefined {\n  if (typeof value === 'string' || typeof value === 'number') {\n    return value;\n  }\n  if (typeof value === 'function') {\n    return obj => value(obj);\n  }\n  return undefined;\n}\n\nfunction parseColor(value: unknown): string | undefined {\n  if (typeof value === 'string') {\n    return value;\n  }\n  return undefined;\n}\n\nfunction parseTooltipPayloadItem(item: unknown): TooltipPayloadItemLike | undefined {\n  if (item == null || typeof item !== 'object') {\n    return undefined;\n  }\n\n  const name = 'name' in item ? parseName(item.name) : undefined;\n  const unit = 'unit' in item ? parseUnit(item.unit) : undefined;\n  const dataKey = 'dataKey' in item ? parseDataKey(item.dataKey) : undefined;\n  const payload = 'payload' in item ? item.payload : undefined;\n  const color = 'color' in item ? parseColor(item.color) : undefined;\n  const fill = 'fill' in item ? parseColor(item.fill) : undefined;\n\n  return {\n    name,\n    unit,\n    dataKey,\n    payload,\n    color,\n    fill,\n  };\n}\n\nfunction selectFinalData(dataDefinedOnItem: unknown, dataDefinedOnChart: ChartData | undefined): unknown {\n  /*\n   * If a payload has data specified directly from the graphical item, prefer that.\n   * Otherwise, fill in data from the chart level, using the same index.\n   */\n  if (dataDefinedOnItem != null) {\n    return dataDefinedOnItem;\n  }\n  return dataDefinedOnChart;\n}\n\nexport const combineTooltipPayload = (\n  tooltipPayloadConfigurations: ReadonlyArray<TooltipPayloadConfiguration>,\n  activeIndex: TooltipIndex,\n  chartDataState: ChartDataState,\n  tooltipAxisDataKey: DataKey<any> | undefined,\n  activeLabel: ActiveLabel,\n  tooltipPayloadSearcher: TooltipPayloadSearcher | undefined,\n  tooltipEventType: TooltipEventType | undefined,\n): TooltipPayload | undefined => {\n  if (activeIndex == null || tooltipPayloadSearcher == null) {\n    return undefined;\n  }\n  const { chartData, computedData, dataStartIndex, dataEndIndex } = chartDataState;\n\n  const init: Array<TooltipPayloadEntry> = [];\n\n  return tooltipPayloadConfigurations.reduce((agg, { dataDefinedOnItem, settings }): Array<TooltipPayloadEntry> => {\n    const finalData = selectFinalData(dataDefinedOnItem, chartData);\n\n    const sliced = Array.isArray(finalData) ? getSliced(finalData, dataStartIndex, dataEndIndex) : finalData;\n\n    const finalDataKey: DataKey<any> | undefined = settings?.dataKey ?? tooltipAxisDataKey;\n    // BaseAxisProps does not support nameKey but it could!\n    const finalNameKey: DataKey<any> | undefined = settings?.nameKey; // ?? tooltipAxis?.nameKey;\n    let tooltipPayload: unknown;\n    if (\n      tooltipAxisDataKey &&\n      Array.isArray(sliced) &&\n      /*\n       * findEntryInArray won't work for Scatter because Scatter provides an array of arrays\n       * as tooltip payloads and findEntryInArray is not prepared to handle that.\n       * Sad but also ScatterChart only allows 'item' tooltipEventType\n       * and also this is only a problem if there are multiple Scatters and each has its own data array\n       * so let's fix that some other time.\n       */\n      !Array.isArray(sliced[0]) &&\n      /*\n       * If the tooltipEventType is 'axis', we should search for the dataKey in the sliced data\n       * because thanks to allowDuplicatedCategory=false, the order of elements in the array\n       * no longer matches the order of elements in the original data\n       * and so we need to search by the active dataKey + label rather than by index.\n       *\n       * The same happens if multiple graphical items are present in the chart\n       * and each of them has its own data array. Those arrays get concatenated\n       * and again the tooltip index no longer matches the original data.\n       *\n       * On the other hand the tooltipEventType 'item' should always search by index\n       * because we get the index from interacting over the individual elements\n       * which is always accurate, irrespective of the allowDuplicatedCategory setting.\n       */\n      tooltipEventType === 'axis'\n    ) {\n      tooltipPayload = findEntryInArray(sliced, tooltipAxisDataKey, activeLabel);\n    } else {\n      /*\n       * This is a problem because it assumes that the index is pointing to the displayed data\n       * which it isn't because the index is pointing to the tooltip ticks array.\n       * The above approach (with findEntryInArray) is the correct one, but it only works\n       * if the axis dataKey is defined explicitly, and if the data is an array of objects.\n       */\n      tooltipPayload = tooltipPayloadSearcher(sliced, activeIndex, computedData, finalNameKey);\n    }\n\n    if (Array.isArray(tooltipPayload)) {\n      tooltipPayload.forEach(item => {\n        const parsedItem = parseTooltipPayloadItem(item);\n        const itemName = parsedItem?.name;\n        const itemDataKey = parsedItem?.dataKey;\n        const itemPayload = parsedItem?.payload;\n        const newSettings: TooltipEntrySettings = {\n          ...settings,\n          name: itemName,\n          unit: parsedItem?.unit,\n          // Preserve item-level color/fill from graphical items.\n          color: parsedItem?.color ?? settings?.color,\n          fill: parsedItem?.fill ?? settings?.fill,\n        };\n        agg.push(\n          getTooltipEntry({\n            tooltipEntrySettings: newSettings,\n            dataKey: itemDataKey,\n            payload: itemPayload,\n            value: getValueByDataKey(itemPayload, itemDataKey),\n            name: itemName == null ? undefined : String(itemName),\n          }),\n        );\n      });\n    } else {\n      // I am not quite sure why these two branches (Array vs Array of Arrays) have to behave differently - I imagine we should unify these. 3.x breaking change?\n      agg.push(\n        getTooltipEntry({\n          tooltipEntrySettings: settings,\n          dataKey: finalDataKey,\n          payload: tooltipPayload,\n          // getValueByDataKey does not validate the output type\n          value: getValueByDataKey(tooltipPayload, finalDataKey),\n          // getValueByDataKey does not validate the output type\n          name: getValueByDataKey(tooltipPayload, finalNameKey) ?? settings?.name,\n        }),\n      );\n    }\n    return agg;\n  }, init);\n};\n","import { createSelector } from 'reselect';\nimport { RechartsRootState } from '../store';\nimport {\n  AxisRange,\n  combineAllAppliedValues,\n  combineAreasDomain,\n  combineAxisDomain,\n  combineAxisDomainWithNiceTicks,\n  combineCategoricalDomain,\n  combineDisplayedData,\n  combineDomainOfAllAppliedNumericalValuesIncludingErrorValues,\n  combineDomainOfStackGroups,\n  combineDotsDomain,\n  combineDuplicateDomain,\n  combineGraphicalItemsData,\n  combineGraphicalItemsSettings,\n  combineLinesDomain,\n  combineNiceTicks,\n  combineNumericalDomain,\n  combineStackGroups,\n  filterGraphicalNotStackedItems,\n  filterReferenceElements,\n  getDomainDefinition,\n  itemAxisPredicate,\n  mergeDomains,\n  RenderableAxisSettings,\n  selectAllErrorBarSettings,\n  selectAxisRange,\n  selectHasBar,\n  selectReferenceAreas,\n  selectReferenceDots,\n  selectReferenceLines,\n  selectTooltipAxis,\n  selectTooltipAxisDataKey,\n} from './axisSelectors';\nimport { selectChartLayout } from '../../context/chartLayoutContext';\nimport { isCategoricalAxis, StackId } from '../../util/ChartUtils';\nimport {\n  AxisDomain,\n  CategoricalDomain,\n  CategoricalDomainItem,\n  Coordinate,\n  RechartsScaleType,\n  DataKey,\n  LayoutType,\n  NumberDomain,\n  TickItem,\n  TooltipEventType,\n} from '../../util/types';\nimport { AppliedChartData, ChartData } from '../chartDataSlice';\nimport { selectChartDataWithIndexes, selectChartDataSliceWithIndexes } from './dataSelectors';\nimport {\n  CartesianGraphicalItemSettings,\n  GraphicalItemSettings,\n  PolarGraphicalItemSettings,\n} from '../graphicalItemsSlice';\nimport { ReferenceAreaSettings, ReferenceDotSettings, ReferenceLineSettings } from '../referenceElementsSlice';\nimport { selectChartName, selectReverseStackOrder, selectStackOffsetType } from './rootPropsSelectors';\nimport { isNotNil, mathSign } from '../../util/DataUtils';\nimport { combineAxisRangeWithReverse } from './combiners/combineAxisRangeWithReverse';\nimport { TooltipIndex, TooltipInteractionState, TooltipPayload, TooltipSettingsState } from '../tooltipSlice';\n\nimport {\n  combineTooltipEventType,\n  selectDefaultTooltipEventType,\n  selectValidateTooltipEventTypes,\n} from './selectTooltipEventType';\n\nimport { combineActiveLabel } from './combiners/combineActiveLabel';\n\nimport { selectTooltipSettings } from './selectTooltipSettings';\n\nimport { combineTooltipInteractionState } from './combiners/combineTooltipInteractionState';\nimport { combineActiveTooltipIndex } from './combiners/combineActiveTooltipIndex';\nimport { combineCoordinateForDefaultIndex } from './combiners/combineCoordinateForDefaultIndex';\nimport { selectChartHeight, selectChartWidth } from './containerSelectors';\nimport { selectChartOffsetInternal } from './selectChartOffsetInternal';\nimport { combineTooltipPayloadConfigurations } from './combiners/combineTooltipPayloadConfigurations';\nimport { selectTooltipPayloadSearcher } from './selectTooltipPayloadSearcher';\nimport { selectTooltipState } from './selectTooltipState';\n\nimport { combineTooltipPayload } from './combiners/combineTooltipPayload';\nimport { StackGroup } from '../../util/stacks/stackTypes';\nimport { selectTooltipAxisId } from './selectTooltipAxisId';\nimport { RenderableAxisType, selectTooltipAxisType } from './selectTooltipAxisType';\nimport { combineDisplayedStackedData, DisplayedStackedData } from './combiners/combineDisplayedStackedData';\nimport { DefinitelyStackedGraphicalItem, isStacked } from '../types/StackedGraphicalItem';\nimport { numericalDomainSpecifiedWithoutRequiringData } from '../../util/isDomainSpecifiedByUser';\nimport { numberDomainEqualityCheck } from './numberDomainEqualityCheck';\nimport { emptyArraysAreEqualCheck } from './arrayEqualityCheck';\nimport { ActiveLabel } from '../../synchronisation/types';\nimport { RechartsScale, rechartsScaleFactory } from '../../util/scale/RechartsScale';\nimport { isWellBehavedNumber } from '../../util/isWellBehavedNumber';\nimport { combineRealScaleType } from './combiners/combineRealScaleType';\nimport { combineConfiguredScale } from './combiners/combineConfiguredScale';\nimport { CustomScaleDefinition } from '../../util/scale/CustomScaleDefinition';\n\nexport const selectTooltipAxisRealScaleType: (state: RechartsRootState) => RechartsScaleType | undefined =\n  createSelector([selectTooltipAxis, selectHasBar, selectChartName], combineRealScaleType);\n\nexport const selectAllUnfilteredGraphicalItems: (\n  state: RechartsRootState,\n) => ReadonlyArray<CartesianGraphicalItemSettings | PolarGraphicalItemSettings> = createSelector(\n  [\n    (state: RechartsRootState) => state.graphicalItems.cartesianItems,\n    (state: RechartsRootState) => state.graphicalItems.polarItems,\n  ],\n  (cartesianItems, polarItems) => [...cartesianItems, ...polarItems],\n);\n\nconst selectTooltipAxisPredicate = createSelector([selectTooltipAxisType, selectTooltipAxisId], itemAxisPredicate);\n\nexport const selectAllGraphicalItemsSettings: (state: RechartsRootState) => ReadonlyArray<GraphicalItemSettings> =\n  createSelector(\n    [selectAllUnfilteredGraphicalItems, selectTooltipAxis, selectTooltipAxisPredicate],\n    combineGraphicalItemsSettings,\n    {\n      memoizeOptions: {\n        resultEqualityCheck: emptyArraysAreEqualCheck,\n      },\n    },\n  );\n\nconst selectAllStackedGraphicalItemsSettings: (\n  state: RechartsRootState,\n) => ReadonlyArray<DefinitelyStackedGraphicalItem> = createSelector(\n  [selectAllGraphicalItemsSettings],\n  (graphicalItems: ReadonlyArray<GraphicalItemSettings>): ReadonlyArray<DefinitelyStackedGraphicalItem> =>\n    graphicalItems.filter(isStacked),\n);\n\nexport const selectTooltipGraphicalItemsData = createSelector(\n  [selectAllGraphicalItemsSettings],\n  combineGraphicalItemsData,\n  {\n    memoizeOptions: {\n      resultEqualityCheck: emptyArraysAreEqualCheck,\n    },\n  },\n);\n\nconst selectAnyTooltipItemUsesChartData: (state: RechartsRootState) => boolean = createSelector(\n  [selectAllGraphicalItemsSettings],\n  items => items.some(item => !item.data),\n);\n\n/**\n * Data for tooltip always use the data with indexes set by a Brush,\n * and never accept the isPanorama flag:\n * because Tooltip never displays inside the panorama anyway\n * so we don't need to worry what would happen there.\n */\nexport const selectTooltipDisplayedData: (state: RechartsRootState) => ChartData = createSelector(\n  [selectTooltipGraphicalItemsData, selectChartDataWithIndexes],\n  combineDisplayedData,\n);\n\nconst selectTooltipStackedData: (state: RechartsRootState) => DisplayedStackedData = createSelector(\n  [selectAllStackedGraphicalItemsSettings, selectChartDataWithIndexes, selectTooltipAxis],\n  combineDisplayedStackedData,\n);\n\nconst selectAllTooltipAppliedValues: (state: RechartsRootState) => AppliedChartData = createSelector(\n  [\n    selectTooltipDisplayedData,\n    selectTooltipAxis,\n    selectAllGraphicalItemsSettings,\n    selectChartDataWithIndexes,\n    selectAnyTooltipItemUsesChartData,\n    selectTooltipGraphicalItemsData,\n  ],\n  combineAllAppliedValues,\n);\n\nconst selectTooltipAxisDomainDefinition: (state: RechartsRootState) => AxisDomain | undefined = createSelector(\n  [selectTooltipAxis],\n  getDomainDefinition,\n);\n\nconst selectTooltipDataOverflow: (state: RechartsRootState) => boolean = createSelector(\n  [selectTooltipAxis],\n  axisSettings => axisSettings.allowDataOverflow,\n);\n\nconst selectTooltipDomainFromUserPreferences: (state: RechartsRootState) => NumberDomain | undefined = createSelector(\n  [selectTooltipAxisDomainDefinition, selectTooltipDataOverflow],\n  numericalDomainSpecifiedWithoutRequiringData,\n);\n\nconst selectAllStackedGraphicalItems: (state: RechartsRootState) => ReadonlyArray<DefinitelyStackedGraphicalItem> =\n  createSelector([selectAllGraphicalItemsSettings], (graphicalItems: ReadonlyArray<GraphicalItemSettings>) =>\n    graphicalItems.filter(isStacked),\n  );\n\nconst selectTooltipStackGroups: (state: RechartsRootState) => Record<StackId, StackGroup> = createSelector(\n  [selectTooltipStackedData, selectAllStackedGraphicalItems, selectStackOffsetType, selectReverseStackOrder],\n  combineStackGroups,\n);\n\nconst selectTooltipDomainOfStackGroups: (state: RechartsRootState) => NumberDomain | undefined = createSelector(\n  [selectTooltipStackGroups, selectChartDataWithIndexes, selectTooltipAxisType, selectTooltipDomainFromUserPreferences],\n  combineDomainOfStackGroups,\n);\n\nconst selectTooltipItemsSettingsExceptStacked: (state: RechartsRootState) => ReadonlyArray<GraphicalItemSettings> =\n  createSelector([selectAllGraphicalItemsSettings], filterGraphicalNotStackedItems);\n\nconst selectDomainOfAllAppliedNumericalValuesIncludingErrorValues: (\n  state: RechartsRootState,\n) => NumberDomain | undefined = createSelector(\n  [\n    selectTooltipDisplayedData,\n    selectTooltipAxis,\n    selectTooltipItemsSettingsExceptStacked,\n    selectAllErrorBarSettings,\n    selectTooltipAxisType,\n    selectChartDataSliceWithIndexes,\n  ],\n  combineDomainOfAllAppliedNumericalValuesIncludingErrorValues,\n  {\n    memoizeOptions: {\n      resultEqualityCheck: numberDomainEqualityCheck,\n    },\n  },\n);\n\nconst selectReferenceDotsByTooltipAxis: (state: RechartsRootState) => ReadonlyArray<ReferenceDotSettings> | undefined =\n  createSelector([selectReferenceDots, selectTooltipAxisType, selectTooltipAxisId], filterReferenceElements);\n\nconst selectTooltipReferenceDotsDomain: (state: RechartsRootState) => NumberDomain | undefined = createSelector(\n  [selectReferenceDotsByTooltipAxis, selectTooltipAxisType],\n  combineDotsDomain,\n);\n\nconst selectReferenceAreasByTooltipAxis: (\n  state: RechartsRootState,\n) => ReadonlyArray<ReferenceAreaSettings> | undefined = createSelector(\n  [selectReferenceAreas, selectTooltipAxisType, selectTooltipAxisId],\n  filterReferenceElements,\n);\n\nconst selectTooltipReferenceAreasDomain: (state: RechartsRootState) => NumberDomain | undefined = createSelector(\n  [selectReferenceAreasByTooltipAxis, selectTooltipAxisType],\n  combineAreasDomain,\n);\n\nconst selectReferenceLinesByTooltipAxis: (\n  state: RechartsRootState,\n) => ReadonlyArray<ReferenceLineSettings> | undefined = createSelector(\n  [selectReferenceLines, selectTooltipAxisType, selectTooltipAxisId],\n  filterReferenceElements,\n);\n\nconst selectTooltipReferenceLinesDomain: (state: RechartsRootState) => NumberDomain | undefined = createSelector(\n  [selectReferenceLinesByTooltipAxis, selectTooltipAxisType],\n  combineLinesDomain,\n);\n\nconst selectTooltipReferenceElementsDomain: (state: RechartsRootState) => NumberDomain | undefined = createSelector(\n  [selectTooltipReferenceDotsDomain, selectTooltipReferenceLinesDomain, selectTooltipReferenceAreasDomain],\n  mergeDomains,\n);\n\nconst selectTooltipNumericalDomain: (state: RechartsRootState) => NumberDomain | undefined = createSelector(\n  [\n    selectTooltipAxis,\n    selectTooltipAxisDomainDefinition,\n    selectTooltipDomainFromUserPreferences,\n    selectTooltipDomainOfStackGroups,\n    selectDomainOfAllAppliedNumericalValuesIncludingErrorValues,\n    selectTooltipReferenceElementsDomain,\n    selectChartLayout,\n    selectTooltipAxisType,\n  ],\n  combineNumericalDomain,\n);\n\nexport const selectTooltipAxisDomain: (state: RechartsRootState) => NumberDomain | CategoricalDomain | undefined =\n  createSelector(\n    [\n      selectTooltipAxis,\n      selectChartLayout,\n      selectTooltipDisplayedData,\n      selectAllTooltipAppliedValues,\n      selectStackOffsetType,\n      selectTooltipAxisType,\n      selectTooltipNumericalDomain,\n    ],\n    combineAxisDomain,\n  );\n\nconst selectTooltipNiceTicks: (state: RechartsRootState) => ReadonlyArray<number> | undefined = createSelector(\n  [selectTooltipAxisDomain, selectTooltipAxis, selectTooltipAxisRealScaleType],\n  combineNiceTicks,\n);\n\nexport const selectTooltipAxisDomainIncludingNiceTicks: (\n  state: RechartsRootState,\n) => NumberDomain | CategoricalDomain | undefined = createSelector(\n  [selectTooltipAxis, selectTooltipAxisDomain, selectTooltipNiceTicks, selectTooltipAxisType],\n  combineAxisDomainWithNiceTicks,\n);\n\nconst selectTooltipAxisRange = (state: RechartsRootState): AxisRange | undefined => {\n  const axisType = selectTooltipAxisType(state);\n  const axisId = selectTooltipAxisId(state);\n  const isPanorama = false; // Tooltip never displays in panorama so this is safe to assume\n  return selectAxisRange(state, axisType, axisId, isPanorama);\n};\n\nexport const selectTooltipAxisRangeWithReverse: (state: RechartsRootState) => AxisRange | undefined = createSelector(\n  [selectTooltipAxis, selectTooltipAxisRange],\n  combineAxisRangeWithReverse,\n);\n\nconst selectTooltipConfiguredScale: (state: RechartsRootState) => CustomScaleDefinition | undefined = createSelector(\n  [\n    selectTooltipAxis,\n    selectTooltipAxisRealScaleType,\n    selectTooltipAxisDomainIncludingNiceTicks,\n    selectTooltipAxisRangeWithReverse,\n  ],\n  combineConfiguredScale,\n);\n\nexport const selectTooltipAxisScale: (state: RechartsRootState) => RechartsScale | undefined = createSelector(\n  [selectTooltipConfiguredScale],\n  rechartsScaleFactory,\n);\n\nconst selectTooltipDuplicateDomain: (state: RechartsRootState) => ReadonlyArray<unknown> | undefined = createSelector(\n  [selectChartLayout, selectAllTooltipAppliedValues, selectTooltipAxis, selectTooltipAxisType],\n  combineDuplicateDomain,\n);\n\nexport const selectTooltipCategoricalDomain: (state: RechartsRootState) => ReadonlyArray<unknown> | undefined =\n  createSelector(\n    [selectChartLayout, selectAllTooltipAppliedValues, selectTooltipAxis, selectTooltipAxisType],\n    combineCategoricalDomain,\n  );\n\nconst combineTicksOfTooltipAxis = (\n  layout: LayoutType,\n  axis: RenderableAxisSettings,\n  realScaleType: string | undefined,\n  scale: RechartsScale | undefined,\n  range: AxisRange | undefined,\n  duplicateDomain: ReadonlyArray<unknown> | undefined,\n  categoricalDomain: ReadonlyArray<unknown> | undefined,\n  axisType: RenderableAxisType,\n): ReadonlyArray<TickItem> | undefined => {\n  if (!axis) {\n    return undefined;\n  }\n  const { type } = axis;\n\n  const isCategorical = isCategoricalAxis(layout, axisType);\n\n  if (!scale) {\n    return undefined;\n  }\n\n  const offsetForBand = realScaleType === 'scaleBand' && scale.bandwidth ? scale.bandwidth() / 2 : 2;\n  let offset = type === 'category' && scale.bandwidth ? scale.bandwidth() / offsetForBand : 0;\n\n  offset =\n    axisType === 'angleAxis' && range != null && range?.length >= 2\n      ? mathSign(range[0] - range[1]) * 2 * offset\n      : offset;\n\n  // When axis is a categorical axis, but the type of axis is number or the scale of axis is not \"auto\"\n  if (isCategorical && categoricalDomain) {\n    return categoricalDomain\n      .map((entry: unknown, index: number): TickItem | null => {\n        const scaled = scale.map(entry);\n        if (!isWellBehavedNumber(scaled)) {\n          return null;\n        }\n        return {\n          coordinate: scaled + offset,\n          value: entry,\n          index,\n          offset,\n        };\n      })\n      .filter(isNotNil);\n  }\n\n  // When axis has duplicated text, serial numbers are used to generate scale\n  return scale\n    .domain()\n    .map((entry: CategoricalDomainItem, index: number): TickItem | null => {\n      const scaled = scale.map(entry);\n      if (!isWellBehavedNumber(scaled)) {\n        return null;\n      }\n      return {\n        coordinate: scaled + offset,\n        // @ts-expect-error can't use Date as an index\n        value: duplicateDomain ? duplicateDomain[entry] : entry,\n        index,\n        offset,\n      };\n    })\n    .filter(isNotNil);\n};\n\n/**\n * Of on four almost identical implementations of tick generation.\n * The four horsemen of tick generation are:\n * - {@link selectTooltipAxisTicks}\n * - {@link combineAxisTicks}\n * - {@link getTicksOfAxis}.\n * - {@link combineGraphicalItemTicks}\n */\nexport const selectTooltipAxisTicks: (state: RechartsRootState) => ReadonlyArray<TickItem> | undefined = createSelector(\n  [\n    selectChartLayout,\n    selectTooltipAxis,\n    selectTooltipAxisRealScaleType,\n    selectTooltipAxisScale,\n    selectTooltipAxisRange,\n    selectTooltipDuplicateDomain,\n    selectTooltipCategoricalDomain,\n    selectTooltipAxisType,\n  ],\n  combineTicksOfTooltipAxis,\n);\n\nconst selectTooltipEventType: (state: RechartsRootState) => TooltipEventType | undefined = createSelector(\n  [selectDefaultTooltipEventType, selectValidateTooltipEventTypes, selectTooltipSettings],\n  (defaultTooltipEventType, validateTooltipEventType, settings: TooltipSettingsState) =>\n    combineTooltipEventType(settings.shared, defaultTooltipEventType, validateTooltipEventType),\n);\n\nconst selectTooltipTrigger = (state: RechartsRootState) => state.tooltip.settings.trigger;\n\nconst selectDefaultIndex: (state: RechartsRootState) => TooltipIndex | undefined = state =>\n  state.tooltip.settings.defaultIndex;\n\nconst selectTooltipInteractionState: (state: RechartsRootState) => TooltipInteractionState | undefined = createSelector(\n  [selectTooltipState, selectTooltipEventType, selectTooltipTrigger, selectDefaultIndex],\n  combineTooltipInteractionState,\n);\n\nexport const selectActiveTooltipIndex: (state: RechartsRootState) => TooltipIndex | null = createSelector(\n  [selectTooltipInteractionState, selectTooltipDisplayedData, selectTooltipAxisDataKey, selectTooltipAxisDomain],\n  combineActiveTooltipIndex,\n);\n\nexport const selectActiveLabel: (state: RechartsRootState) => ActiveLabel = createSelector(\n  [selectTooltipAxisTicks, selectActiveTooltipIndex],\n  combineActiveLabel,\n);\n\nexport const selectActiveTooltipDataKey: (state: RechartsRootState) => DataKey<any> | undefined = createSelector(\n  [selectTooltipInteractionState],\n  (tooltipInteraction: TooltipInteractionState | undefined): DataKey<any> | undefined => {\n    if (!tooltipInteraction) {\n      return undefined;\n    }\n\n    return tooltipInteraction.dataKey;\n  },\n);\n\nexport const selectActiveTooltipGraphicalItemId: (state: RechartsRootState) => string | undefined = createSelector(\n  [selectTooltipInteractionState],\n  (tooltipInteraction: TooltipInteractionState | undefined): string | undefined => {\n    if (!tooltipInteraction) {\n      return undefined;\n    }\n\n    return tooltipInteraction.graphicalItemId;\n  },\n);\n\nconst selectTooltipPayloadConfigurations = createSelector(\n  [selectTooltipState, selectTooltipEventType, selectTooltipTrigger, selectDefaultIndex],\n  combineTooltipPayloadConfigurations,\n);\n\nconst selectTooltipCoordinateForDefaultIndex: (state: RechartsRootState) => Coordinate | undefined = createSelector(\n  [\n    selectChartWidth,\n    selectChartHeight,\n    selectChartLayout,\n    selectChartOffsetInternal,\n    selectTooltipAxisTicks,\n    selectDefaultIndex,\n    selectTooltipPayloadConfigurations,\n  ],\n  combineCoordinateForDefaultIndex,\n);\n\nexport const selectActiveTooltipCoordinate: (state: RechartsRootState) => Coordinate | undefined = createSelector(\n  [selectTooltipInteractionState, selectTooltipCoordinateForDefaultIndex],\n  (\n    tooltipInteractionState: TooltipInteractionState | undefined,\n    defaultIndexCoordinate: Coordinate | undefined,\n  ): Coordinate | undefined => {\n    if (tooltipInteractionState?.coordinate) {\n      return tooltipInteractionState.coordinate;\n    }\n\n    return defaultIndexCoordinate;\n  },\n);\n\nexport const selectIsTooltipActive: (state: RechartsRootState) => boolean = createSelector(\n  [selectTooltipInteractionState],\n  (tooltipInteractionState: TooltipInteractionState | undefined): boolean => tooltipInteractionState?.active ?? false,\n);\n\nexport const selectActiveTooltipPayload: (state: RechartsRootState) => TooltipPayload | undefined = createSelector(\n  [\n    selectTooltipPayloadConfigurations,\n    selectActiveTooltipIndex,\n    selectChartDataWithIndexes,\n    selectTooltipAxisDataKey,\n    selectActiveLabel,\n    selectTooltipPayloadSearcher,\n    selectTooltipEventType,\n  ],\n  combineTooltipPayload,\n);\n\nexport const selectActiveTooltipDataPoints = createSelector([selectActiveTooltipPayload], payload => {\n  if (payload == null) {\n    return undefined;\n  }\n  const dataPoints = payload.map(p => p.payload).filter(p => p != null);\n  return Array.from(new Set(dataPoints));\n});\n","import { RechartsRootState } from '../store';\nimport { TooltipSettingsState } from '../tooltipSlice';\n\nexport const selectTooltipSettings = (state: RechartsRootState): TooltipSettingsState => state.tooltip.settings;\n","import { useAppSelector } from '../state/hooks';\nimport { getBandSizeOfAxis } from '../util/ChartUtils';\nimport { RenderableAxisSettings, selectTooltipAxis } from '../state/selectors/axisSelectors';\nimport { selectTooltipAxisScale, selectTooltipAxisTicks } from '../state/selectors/tooltipSelectors';\n\nexport const useTooltipAxis = (): RenderableAxisSettings | undefined => useAppSelector(selectTooltipAxis);\n\nexport const useTooltipAxisBandSize = (): number | undefined => {\n  const tooltipAxis = useTooltipAxis();\n  const tooltipTicks = useAppSelector(selectTooltipAxisTicks);\n  const tooltipAxisScale = useAppSelector(selectTooltipAxisScale);\n  if (!tooltipAxis || !tooltipAxisScale) {\n    return getBandSizeOfAxis(undefined, tooltipTicks);\n  }\n  return getBandSizeOfAxis({ ...tooltipAxis, scale: tooltipAxisScale }, tooltipTicks);\n};\n","import {\n  AxisType,\n  CartesianLayout,\n  ChartOffsetInternal,\n  RelativePointer,\n  Coordinate,\n  PolarCoordinate,\n  PolarLayout,\n  RangeObj,\n  TickItem,\n} from './types';\nimport { polarToCartesian } from './PolarUtils';\nimport { AxisRange } from '../state/selectors/axisSelectors';\nimport { mathSign } from './DataUtils';\n\nexport const getActiveCartesianCoordinate = (\n  layout: CartesianLayout,\n  tooltipTicks: readonly TickItem[],\n  activeIndex: number | undefined,\n  pointer: RelativePointer,\n): Coordinate => {\n  const entry = tooltipTicks.find(tick => tick && tick.index === activeIndex);\n\n  if (entry) {\n    if (layout === 'horizontal') {\n      return { x: entry.coordinate, y: pointer.relativeY };\n    }\n    if (layout === 'vertical') {\n      return { x: pointer.relativeX, y: entry.coordinate };\n    }\n  }\n\n  return { x: 0, y: 0 };\n};\n\n/**\n * Get the active coordinate in polar coordinate system.\n * Internally we only really use x and y, but this returned object is part of public API\n * (because it goes straight to the tooltip content) so we keep all the other properties\n * for backwards compatibility.\n *\n * @param layout - The polar layout type ('centric' or 'radial').\n * @param tooltipTicks - Array of tick items used for tooltips.\n * @param activeIndex - The index of the active tick.\n * @param rangeObj - The range object containing polar chart properties.\n * @returns The active coordinate object with polar properties.\n */\nexport const getActivePolarCoordinate = (\n  layout: PolarLayout,\n  tooltipTicks: readonly TickItem[],\n  activeIndex: number | undefined,\n  rangeObj: RangeObj,\n): PolarCoordinate => {\n  const entry = tooltipTicks.find(tick => tick && tick.index === activeIndex);\n\n  if (entry) {\n    if (layout === 'centric') {\n      const angle = entry.coordinate;\n      const { radius } = rangeObj;\n\n      return {\n        ...rangeObj,\n        ...polarToCartesian(rangeObj.cx, rangeObj.cy, radius, angle),\n        angle,\n        radius,\n      };\n    }\n\n    const radius = entry.coordinate;\n    const { angle } = rangeObj;\n\n    return {\n      ...rangeObj,\n      ...polarToCartesian(rangeObj.cx, rangeObj.cy, radius, angle),\n      angle,\n      radius,\n    };\n  }\n\n  return {\n    angle: 0,\n    clockWise: false,\n    cx: 0,\n    cy: 0,\n    endAngle: 0,\n    innerRadius: 0,\n    outerRadius: 0,\n    radius: 0,\n    startAngle: 0,\n    x: 0,\n    y: 0,\n  };\n};\n\nexport function isInCartesianRange(pointer: RelativePointer, offset: ChartOffsetInternal): boolean {\n  const { relativeX: x, relativeY: y } = pointer;\n  return x >= offset.left && x <= offset.left + offset.width && y >= offset.top && y <= offset.top + offset.height;\n}\n\nexport const calculateActiveTickIndex = (\n  /**\n   * For different layouts, `coordinate` is different:\n   * In horizontal layout, this is expected to be the `x` coordinate\n   * vertical -> y\n   * centric -> angle\n   * radial -> radius\n   */\n  coordinate: number | undefined,\n  ticks: ReadonlyArray<TickItem> | undefined,\n  unsortedTicks: ReadonlyArray<TickItem>,\n  axisType: AxisType | undefined,\n  range: AxisRange | undefined,\n): number | undefined => {\n  const len = ticks?.length ?? 0;\n\n  // if there are 1 or fewer ticks or if there is no coordinate then the active tick is at index 0\n  if (len <= 1 || coordinate == null) {\n    return 0;\n  }\n\n  if (axisType === 'angleAxis' && range != null && Math.abs(Math.abs(range[1] - range[0]) - 360) <= 1e-6) {\n    // ticks are distributed in a circle\n    for (let i = 0; i < len; i++) {\n      const before = i > 0 ? unsortedTicks[i - 1]?.coordinate : unsortedTicks[len - 1]?.coordinate;\n      const cur = unsortedTicks[i]?.coordinate;\n      const after = i >= len - 1 ? unsortedTicks[0]?.coordinate : unsortedTicks[i + 1]?.coordinate;\n      let sameDirectionCoord;\n\n      if (before == null || cur == null || after == null) {\n        continue;\n      }\n\n      if (mathSign(cur - before) !== mathSign(after - cur)) {\n        const diffInterval = [];\n        if (mathSign(after - cur) === mathSign(range[1] - range[0])) {\n          sameDirectionCoord = after;\n\n          const curInRange = cur + range[1] - range[0];\n          diffInterval[0] = Math.min(curInRange, (curInRange + before) / 2);\n          diffInterval[1] = Math.max(curInRange, (curInRange + before) / 2);\n        } else {\n          sameDirectionCoord = before;\n\n          const afterInRange = after + range[1] - range[0];\n          diffInterval[0] = Math.min(cur, (afterInRange + cur) / 2);\n          diffInterval[1] = Math.max(cur, (afterInRange + cur) / 2);\n        }\n        const sameInterval: [number, number] = [\n          Math.min(cur, (sameDirectionCoord + cur) / 2),\n          Math.max(cur, (sameDirectionCoord + cur) / 2),\n        ];\n\n        if (\n          (coordinate > sameInterval[0] && coordinate <= sameInterval[1]) ||\n          (coordinate >= diffInterval[0] && coordinate <= diffInterval[1])\n        ) {\n          return unsortedTicks[i]?.index;\n        }\n      } else {\n        const minValue = Math.min(before, after);\n        const maxValue = Math.max(before, after);\n\n        if (coordinate > (minValue + cur) / 2 && coordinate <= (maxValue + cur) / 2) {\n          return unsortedTicks[i]?.index;\n        }\n      }\n    }\n  } else if (ticks) {\n    // ticks are distributed in a single direction\n    for (let i = 0; i < len; i++) {\n      const curr = ticks[i];\n      if (curr == null) {\n        continue;\n      }\n      const next = ticks[i + 1];\n      const prev = ticks[i - 1];\n\n      if (i === 0 && next != null && coordinate <= (curr.coordinate + next.coordinate) / 2) {\n        return curr.index;\n      }\n\n      if (i === len - 1 && prev != null && coordinate > (curr.coordinate + prev.coordinate) / 2) {\n        return curr.index;\n      }\n\n      if (\n        i > 0 &&\n        i < len - 1 &&\n        prev != null &&\n        next != null &&\n        coordinate > (curr.coordinate + prev.coordinate) / 2 &&\n        coordinate <= (curr.coordinate + next.coordinate) / 2\n      ) {\n        return curr.index;\n      }\n    }\n  }\n\n  return -1;\n};\n","import { createSelector } from 'reselect';\nimport sortBy from 'es-toolkit/compat/sortBy';\nimport { useAppSelector } from '../hooks';\nimport { RechartsRootState } from '../store';\nimport {\n  ActiveTooltipProps,\n  TooltipIndex,\n  TooltipInteractionState,\n  TooltipPayload,\n  TooltipPayloadConfiguration,\n} from '../tooltipSlice';\nimport { calculateCartesianTooltipPos, calculatePolarTooltipPos } from '../../util/ChartUtils';\nimport {\n  AxisType,\n  CartesianLayout,\n  ChartOffsetInternal,\n  RelativePointer,\n  Coordinate,\n  DataKey,\n  PolarCoordinate,\n  PolarLayout,\n  PolarViewBoxRequired,\n  TickItem,\n  TooltipEventType,\n} from '../../util/types';\nimport { TooltipTrigger } from '../../chart/types';\nimport { selectChartDataWithIndexes } from './dataSelectors';\nimport { selectTooltipAxisDomain, selectTooltipAxisTicks, selectTooltipDisplayedData } from './tooltipSelectors';\nimport { AxisRange, selectTooltipAxisDataKey } from './axisSelectors';\nimport { selectChartName } from './rootPropsSelectors';\nimport { selectChartLayout } from '../../context/chartLayoutContext';\nimport { selectChartOffsetInternal } from './selectChartOffsetInternal';\nimport { selectChartHeight, selectChartWidth } from './containerSelectors';\nimport { combineActiveLabel } from './combiners/combineActiveLabel';\nimport { combineTooltipInteractionState } from './combiners/combineTooltipInteractionState';\nimport { combineActiveTooltipIndex } from './combiners/combineActiveTooltipIndex';\nimport { combineCoordinateForDefaultIndex } from './combiners/combineCoordinateForDefaultIndex';\nimport { combineTooltipPayloadConfigurations } from './combiners/combineTooltipPayloadConfigurations';\nimport { selectTooltipPayloadSearcher } from './selectTooltipPayloadSearcher';\nimport { selectTooltipState } from './selectTooltipState';\nimport { combineTooltipPayload } from './combiners/combineTooltipPayload';\nimport {\n  calculateActiveTickIndex,\n  getActiveCartesianCoordinate,\n  getActivePolarCoordinate,\n  isInCartesianRange,\n} from '../../util/getActiveCoordinate';\nimport { inRangeOfSector } from '../../util/PolarUtils';\n\nexport const useChartName = (): string | undefined => {\n  return useAppSelector(selectChartName);\n};\n\nconst pickTooltipEventType = (\n  _state: RechartsRootState,\n  tooltipEventType: TooltipEventType | undefined,\n): TooltipEventType | undefined => tooltipEventType;\n\nconst pickTrigger = (\n  _state: RechartsRootState,\n  _tooltipEventType: TooltipEventType | undefined,\n  trigger: TooltipTrigger,\n): TooltipTrigger => trigger;\n\nconst pickDefaultIndex = (\n  _state: RechartsRootState,\n  _tooltipEventType: TooltipEventType | undefined,\n  _trigger: TooltipTrigger,\n  defaultIndex?: TooltipIndex | undefined,\n): TooltipIndex | undefined => defaultIndex;\n\nexport const selectOrderedTooltipTicks = createSelector(\n  selectTooltipAxisTicks,\n  (ticks: ReadonlyArray<TickItem> | undefined) => sortBy(ticks, o => o.coordinate),\n);\n\nexport const selectTooltipInteractionState: (\n  state: RechartsRootState,\n  tooltipEventType: TooltipEventType | undefined,\n  trigger: TooltipTrigger,\n  defaultIndex: TooltipIndex | undefined,\n) => TooltipInteractionState = createSelector(\n  [selectTooltipState, pickTooltipEventType, pickTrigger, pickDefaultIndex],\n  combineTooltipInteractionState,\