ody.appendChild(measurementSpan);\n    }\n\n    // Apply styles directly without unnecessary object creation\n    Object.assign(measurementSpan.style, SPAN_STYLE, style);\n    measurementSpan.textContent = `${text}`;\n\n    const rect = measurementSpan.getBoundingClientRect();\n    return { width: rect.width, height: rect.height };\n  } catch {\n    return { width: 0, height: 0 };\n  }\n};\n\nexport const getStringSize = (text: string | number, style: CSSProperties = {}): Size => {\n  if (text === undefined || text === null || Global.isSsr) {\n    return { width: 0, height: 0 };\n  }\n\n  // If caching is disabled, measure directly\n  if (!currentConfig.enableCache) {\n    return measureTextWithDOM(text, style);\n  }\n\n  const cacheKey = createCacheKey(text, style);\n  const cachedResult = stringCache.get(cacheKey);\n\n  if (cachedResult) {\n    return cachedResult;\n  }\n\n  // Measure using DOM\n  const result = measureTextWithDOM(text, style);\n\n  // Store in LRU cache\n  stringCache.set(cacheKey, result);\n\n  return result;\n};\n\n/**\n * Configure text measurement behavior\n * @param config - Partial configuration to apply\n * @returns void\n */\nexport const configureTextMeasurement = (config: Partial<TextMeasurementConfig>): void => {\n  const newConfig = { ...currentConfig, ...config };\n\n  if (newConfig.cacheSize !== currentConfig.cacheSize) {\n    stringCache = new LRUCache<string, Size>(newConfig.cacheSize);\n  }\n\n  currentConfig = newConfig;\n};\n\n/**\n * Get current text measurement configuration\n * @returns Current configuration\n */\nexport const getTextMeasurementConfig = (): TextMeasurementConfig => ({ ...currentConfig });\n\n/**\n * Clear the string size cache. Useful for testing or memory management.\n * @returns void\n */\nexport const clearStringCache = (): void => {\n  stringCache.clear();\n};\n\n/**\n * Get cache statistics for debugging purposes.\n * @returns Cache statistics including size and max size\n */\nexport const getStringCacheStats = () => ({\n  size: stringCache.size(),\n  maxSize: currentConfig.cacheSize,\n});\n","/**\n * Simple LRU (Least Recently Used) cache implementation\n */\nexport class LRUCache<K, V> {\n  private cache = new Map<K, V>();\n\n  private maxSize: number;\n\n  constructor(maxSize: number) {\n    this.maxSize = maxSize;\n  }\n\n  get(key: K): V | undefined {\n    const value = this.cache.get(key);\n    if (value !== undefined) {\n      this.cache.delete(key);\n      this.cache.set(key, value);\n    }\n    return value;\n  }\n\n  set(key: K, value: V): void {\n    if (this.cache.has(key)) {\n      this.cache.delete(key);\n    } else if (this.cache.size >= this.maxSize) {\n      const firstKey = this.cache.keys().next().value;\n      if (firstKey != null) {\n        this.cache.delete(firstKey);\n      }\n    }\n    this.cache.set(key, value);\n  }\n\n  clear(): void {\n    this.cache.clear();\n  }\n\n  size(): number {\n    return this.cache.size;\n  }\n}\n","import { isNan } from './DataUtils';\n\nconst MULTIPLY_OR_DIVIDE_REGEX = /(-?\\d+(?:\\.\\d+)?[a-zA-Z%]*)([*/])(-?\\d+(?:\\.\\d+)?[a-zA-Z%]*)/;\nconst ADD_OR_SUBTRACT_REGEX = /(-?\\d+(?:\\.\\d+)?[a-zA-Z%]*)([+-])(-?\\d+(?:\\.\\d+)?[a-zA-Z%]*)/;\nconst CSS_LENGTH_UNIT_REGEX = /^(px|cm|vh|vw|em|rem|%|mm|in|pt|pc|ex|ch|vmin|vmax|Q)$/;\nconst NUM_SPLIT_REGEX = /(-?\\d+(?:\\.\\d+)?)([a-zA-Z%]+)?/;\n\ntype SupportedUnits = 'cm' | 'mm' | 'pt' | 'pc' | 'in' | 'Q' | 'px';\n\nconst CONVERSION_RATES: Record<SupportedUnits, number> = {\n  cm: 96 / 2.54,\n  mm: 96 / 25.4,\n  pt: 96 / 72,\n  pc: 96 / 6,\n  in: 96,\n  Q: 96 / (2.54 * 40),\n  px: 1,\n};\n\nconst FIXED_CSS_LENGTH_UNITS: ReadonlyArray<SupportedUnits> = ['cm', 'mm', 'pt', 'pc', 'in', 'Q', 'px'];\n\nfunction isSupportedUnit(unit: string): unit is SupportedUnits {\n  return FIXED_CSS_LENGTH_UNITS.includes(unit as SupportedUnits);\n}\n\nconst STR_NAN = 'NaN';\n\nfunction convertToPx(value: number, unit: SupportedUnits): number {\n  return value * CONVERSION_RATES[unit];\n}\n\nclass DecimalCSS {\n  static parse(str: string) {\n    const [, numStr, unit] = NUM_SPLIT_REGEX.exec(str) ?? [];\n\n    if (numStr == null) {\n      return DecimalCSS.NaN;\n    }\n\n    return new DecimalCSS(parseFloat(numStr), unit ?? '');\n  }\n\n  static NaN = new DecimalCSS(NaN, '');\n\n  constructor(\n    public num: number,\n    public unit: string,\n  ) {\n    this.num = num;\n    this.unit = unit;\n\n    if (isNan(num)) {\n      this.unit = '';\n    }\n\n    if (unit !== '' && !CSS_LENGTH_UNIT_REGEX.test(unit)) {\n      this.num = NaN;\n      this.unit = '';\n    }\n\n    if (isSupportedUnit(unit)) {\n      this.num = convertToPx(num, unit);\n      this.unit = 'px';\n    }\n  }\n\n  add(other: DecimalCSS) {\n    if (this.unit !== other.unit) {\n      return new DecimalCSS(NaN, '');\n    }\n\n    return new DecimalCSS(this.num + other.num, this.unit);\n  }\n\n  subtract(other: DecimalCSS) {\n    if (this.unit !== other.unit) {\n      return new DecimalCSS(NaN, '');\n    }\n\n    return new DecimalCSS(this.num - other.num, this.unit);\n  }\n\n  multiply(other: DecimalCSS) {\n    if (this.unit !== '' && other.unit !== '' && this.unit !== other.unit) {\n      return new DecimalCSS(NaN, '');\n    }\n\n    return new DecimalCSS(this.num * other.num, this.unit || other.unit);\n  }\n\n  divide(other: DecimalCSS) {\n    if (this.unit !== '' && other.unit !== '' && this.unit !== other.unit) {\n      return new DecimalCSS(NaN, '');\n    }\n\n    return new DecimalCSS(this.num / other.num, this.unit || other.unit);\n  }\n\n  toString() {\n    return `${this.num}${this.unit}`;\n  }\n\n  isNaN() {\n    return isNan(this.num);\n  }\n}\n\nfunction calculateArithmetic(expr: string | undefined): string {\n  if (expr == null || expr.includes(STR_NAN)) {\n    return STR_NAN;\n  }\n\n  let newExpr = expr;\n  while (newExpr.includes('*') || newExpr.includes('/')) {\n    const [, leftOperand, operator, rightOperand] = MULTIPLY_OR_DIVIDE_REGEX.exec(newExpr) ?? [];\n    const lTs = DecimalCSS.parse(leftOperand ?? '');\n    const rTs = DecimalCSS.parse(rightOperand ?? '');\n    const result = operator === '*' ? lTs.multiply(rTs) : lTs.divide(rTs);\n    if (result.isNaN()) {\n      return STR_NAN;\n    }\n    newExpr = newExpr.replace(MULTIPLY_OR_DIVIDE_REGEX, result.toString());\n  }\n\n  while (newExpr.includes('+') || /.-\\d+(?:\\.\\d+)?/.test(newExpr)) {\n    const [, leftOperand, operator, rightOperand] = ADD_OR_SUBTRACT_REGEX.exec(newExpr) ?? [];\n    const lTs = DecimalCSS.parse(leftOperand ?? '');\n    const rTs = DecimalCSS.parse(rightOperand ?? '');\n    const result = operator === '+' ? lTs.add(rTs) : lTs.subtract(rTs);\n    if (result.isNaN()) {\n      return STR_NAN;\n    }\n    newExpr = newExpr.replace(ADD_OR_SUBTRACT_REGEX, result.toString());\n  }\n\n  return newExpr;\n}\n\nconst PARENTHESES_REGEX = /\\(([^()]*)\\)/;\n\nfunction calculateParentheses(expr: string): string {\n  let newExpr = expr;\n  let match: ReturnType<typeof RegExp.prototype.exec> | null;\n  // eslint-disable-next-line no-cond-assign\n  while ((match = PARENTHESES_REGEX.exec(newExpr)) != null) {\n    const [, parentheticalExpression] = match;\n    newExpr = newExpr.replace(PARENTHESES_REGEX, calculateArithmetic(parentheticalExpression));\n  }\n\n  return newExpr;\n}\n\nfunction evaluateExpression(expression: string): string {\n  let newExpr = expression.replace(/\\s+/g, '');\n  newExpr = calculateParentheses(newExpr);\n  newExpr = calculateArithmetic(newExpr);\n\n  return newExpr;\n}\n\nexport function safeEvaluateExpression(expression: string): string {\n  try {\n    return evaluateExpression(expression);\n  } catch {\n    return STR_NAN;\n  }\n}\n\nexport function reduceCSSCalc(expression: string): string {\n  const result = safeEvaluateExpression(expression.slice(5, -1));\n\n  if (result === STR_NAN) {\n    return '';\n  }\n\n  return result;\n}\n","import * as React from 'react';\nimport { CSSProperties, SVGProps, useMemo, forwardRef } from 'react