RenderableText = string | number | boolean | null | undefined;\n\nexport function isRenderableText(val: unknown): val is RenderableText {\n  return isNullish(val) || typeof val === 'string' || typeof val === 'number' || typeof val === 'boolean';\n}\n\ninterface TextProps {\n  /**\n   * When true, scales the text to fit within the specified width.\n   * The text will be scaled down proportionally to fit the available space.\n   *\n   * **Important interactions:**\n   * - Requires `width` to be defined to have any effect. If width is undefined, scaleToFit does nothing.\n   * - When enabled, `maxLines` restrictions are bypassed and ellipsis truncation is disabled.\n   * - Uses the first line's width to calculate the scale factor.\n   * - The scaling transform is applied as `scale(width / lineWidth)`.\n   *\n   * @defaultValue false\n   */\n  scaleToFit?: boolean;\n\n  /**\n   * Text rotation angle in degrees.\n   * Positive values rotate clockwise, negative values rotate counterclockwise.\n   *\n   * @defaultValue 0\n   */\n  angle?: number;\n\n  /**\n   * Horizontal text alignment within the text element.\n   * - 'start': Text starts at the x coordinate (left-aligned for LTR text)\n   * - 'middle': Text is centered on the x coordinate\n   * - 'end': Text ends at the x coordinate (right-aligned for LTR text)\n   * - 'inherit': Inherits the text-anchor from parent element\n   *\n   * **Note:** This controls horizontal alignment only and does not affect RTL text behavior.\n   * @defaultValue 'start'\n   */\n  textAnchor?: TextAnchor;\n\n  /**\n   * Vertical text alignment relative to the y coordinate.\n   * - 'start': Text baseline starts at y coordinate (text appears below the y position)\n   * - 'middle': Text is vertically centered on the y coordinate\n   * - 'end': Text baseline ends at y coordinate (text appears above the y position)\n   *\n   * **Note:** This controls vertical positioning only and does not affect RTL (right-to-left) text behavior.\n   * The alignment calculation uses capHeight and lineHeight to determine the starting dy offset.\n   *\n   * @defaultValue 'end'\n   */\n  verticalAnchor?: TextVerticalAnchor;\n\n  /**\n   * CSS styles to apply to the text element.\n   * These styles are used for text measurement calculations when width constraints or scaleToFit are used.\n   * Font-related properties (fontSize, fontFamily, fontWeight, etc.) are particularly important for accurate measurements.\n   */\n  style?: CSSProperties;\n\n  /**\n   * Line height for multi-line text.\n   * Can be a number (height in pixels) or a string with CSS units.\n   * Used to calculate spacing between lines when text wraps to multiple lines.\n   * Also used in verticalAnchor calculations for positioning the text block.\n   * @defaultValue '1em'\n   */\n  lineHeight?: number | string;\n\n  /**\n   * When true, enables character-level breaking instead of word-level breaking.\n   * - false: Text breaks at word boundaries (spaces, tabs, etc.)\n   * - true: Text can break between any characters, useful for languages without spaces\n   *\n   * **Note:** Only effective when `width` is defined to enable line breaking.\n   * @defaultValue false\n   */\n  breakAll?: boolean;\n\n  /**\n   * The text content to render.\n   * Can be a string or number. Numbers will be converted to strings.\n   * undefined or null values will result in no text being rendered.\n   */\n  children?: RenderableText;\n\n  /**\n   * Maximum number of lines to display when text wrapping is enabled.\n   * When text exceeds this limit, it will be truncated with an ellipsis (…).\n   *\n   * **Important requirements for ellipsis truncation:**\n   * - `width` must be defined (no effect when width is undefined)\n   * - `scaleToFit` must be false (when scaleToFit is true, maxLines is bypassed)\n   * - Text must actually overflow the specified maxLines or width constraints\n   *\n   * **Truncation behavior:**\n   * - Uses binary search to find the optimal truncation point\n   * - Adds ellipsis (…) at the end of the truncated text\n   * - Ensures the truncated text + ellipsis fits within the constraints\n   *\n   * **Interaction with other props:**\n   * - When `scaleToFit` is true, this property is ignored\n   * - Requires `width` to be set for line breaking to occur\n   */\n  maxLines?: number;\n  /**\n   * When width is specified, the text will automatically wrap by calculating the width of text.\n   */\n  width?: number | string;\n}\n\nexport type Props = Omit<SVGProps<SVGTextElement>, 'textAnchor' | 'verticalAnchor'> & TextProps;\n\ntype CalculateWordsByLinesProps = Pick<Props, 'maxLines' | 'children' | 'style' | 'breakAll'>;\n\nconst calculate = (\n  words: ReadonlyArray<WordWithComputedWidth>,\n  lineWidth: number | string | undefined,\n  spaceWidth: number,\n  scaleToFit: boolean,\n): ReadonlyArray<WordsWithWidth> =>\n  words.reduce((result: Array<WordsWithWidth>, { word, width }) => {\n    const currentLine = result[result.length - 1];\n\n    if (\n      currentLine &&\n      width != null &&\n      (lineWidth == null || scaleToFit || currentLine.width + width + spaceWidth < Number(lineWidth))\n    ) {\n      // Word can be added to an existing line\n      currentLine.words.push(word);\n      currentLine.width += width + spaceWidth;\n    } else {\n      // Add first word to line or word is too long to scaleToFit on existing line\n      const newLine: WordsWithWidth = { words: [word], width };\n      result.push(newLine);\n    }\n\n    return result;\n  }, []);\n\nconst findLongestLine = (words: ReadonlyArray<WordsWithWidth>): WordsWithWidth =>\n  words.reduce((a: WordsWithWidth, b: WordsWithWidth) => (a.width > b.width ? a : b));\n\nconst suffix = '…';\n\nconst checkOverflow = (\n  text: string,\n  index: number,\n  breakAll: TextProps['breakAll'],\n  style: TextProps['style'],\n  maxLines: number,\n  lineWidth: number | string | undefined,\n  spaceWidth: number,\n  scaleToFit: boolean,\n): [boolean, ReadonlyArray<Words>] => {\n  const tempText = text.slice(0, index);\n\n  const words = calculateWordWidths({\n    breakAll,\n    style,\n    children: tempText + suffix,\n  });\n\n  if (!words) {\n    return [false, []];\n  }\n\n  const result: ReadonlyArray<WordsWithWidth> = calculate(\n    words.wordsWithComputedWidth,\n    lineWidth,\n    spaceWidth,\n    scaleToFit,\n  );\n\n  const doesOverflow = result.length > maxLines || findLongestLine(result).width > Number(lineWidth);\n\n  return [doesOverflow, result];\n};\n\nconst calculateWordsByLines = (\n  { maxLines, children, style, breakAll }: CalculateWordsByLinesProps,\n  initialWordsWithComputedWith: ReadonlyArray<WordWithComputedWidth>,\n  spaceWidth: number,\n  lineWidth: number | string | undefined,\n  scaleToFit: boolean,\n): ReadonlyArray<Words> => {\n  const shouldLimitLines = isNumber(maxLines);\n  const text = String(children);\n\n  const originalResult: ReadonlyArray<WordsWithWidth> = calculate(\n    initialWordsWithComputedWith,\n    lineWidth,\n    spaceWidth,\n    scaleToFit,\n  );\n\n  if (!shouldLimitLines || scaleToFit) {\n    return originalResult;\n  }\n\n  const overflows = originalResult.length > maxLines || findLongestLine(originalResult).width > Number(lineWidth);\n  if (!overflows) {\n    return originalResult;\n  }\n\n  let start = 0;\n  let end = text.length - 1;\n\n  let iterations = 0;\n  let trimmedResult;\n\n  while (start <= end && iterations <= text.length - 1) {\n    const middle = Math.floor((start + end) / 2);\n    const prev = middle - 1;\n\n    const [doesPrevOverflow, result] = checkOverflow(\n      text,\n      prev,\n      breakAll,\n      style,\n      maxLines,\n      lineWidth,\n      spaceWidth,\n      scaleToFit,\n    );\n    const [doesMiddleOverflow] = checkOverflow(\n      text,\n      middle,\n      breakAll,\n      style,\n      maxLines,\n      lineWidth,\n      spaceWidth,\n      scaleToFit,\n    );\n\n    if (!doesPrevOverflow && !doesMiddleOverflow) {\n      start = middle + 1;\n    }\n\n    if (doesPrevOverflow && doesMiddleOverflow) {\n      end = middle - 1;\n    }\n\n    if (!doesPrevOverflow && doesMiddleOverflow) {\n      trimmedResult = result;\n      break;\n    }\n\n    iterations++;\n  }\n\n  // Fallback to originalResult (result without trimming) if we cannot find the\n  // where to trim.  This should not happen :tm:\n  return trimmedResult || originalResult;\n};\n\nconst getWordsWithoutCalculate = (children: React.ReactNode): Array<Words> => {\n  const words = !isNullish(children) ? children.toString().split(BREAKING_SPACES) : [];\n  return [{ words, width: undefined }];\n};\n\ntype GetWordsByLinesProps = Pick<Props, 'width' | 'scaleToFit' | 'children' | 'style' | 'breakAll' | 'maxLines'>;\n\nexport const getWordsByLines = ({ width, scaleToFit, children, style, breakAll, maxLines }: GetWordsByLinesProps) => {\n  // Only perform calculations if using features that require them (multiline, scaleToFit)\n  if ((width || scaleToFit) && !Global.isSsr) {\n    let wordsWithComputedWidth: ReadonlyArray<WordWithComputedWidth>, spaceWidth: number;\n\n    const wordWidths = calculateWordWidths({ breakAll, children, style });\n\n    if (wordWidths) {\n      const { wordsWithComputedWidth: wcw, spaceWidth: sw } = wordWidths;\n\n      wordsWithComputedWidth = wcw;\n      spaceWidth = sw;\n    } else {\n      return getWordsWithoutCalculate(children);\n    }\n\n    return calculateWordsByLines(\n      { breakAll, children, maxLines, style },\n      wordsWithComputedWidth,\n      spaceWidth,\n      width,\n      Boolean(scaleToFit),\n    );\n  }\n  return getWordsWithoutCalculate(children);\n};\n\nconst DEFAULT_FILL = '#808080';\n\nexport const textDefaultProps = {\n  angle: 0,\n  breakAll: false,\n  // Magic number from d3\n  capHeight: '0.71em',\n  fill: DEFAULT_FILL,\n  lineHeight: '1em',\n  scaleToFit: false,\n  textAnchor: 'start',\n  // Maintain compat with existing charts / default SVG behavior\n  verticalAnchor: 'end',\n  x: 0,\n  y: 0,\n} as const satisfies Partial<Props>;\n\nexport const Text = forwardRef<SVGTextElement, Props>((outsideProps, ref) => {\n  const {\n    x: propsX,\n    y: propsY,\n    lineHeight,\n    capHeight,\n    fill,\n    scaleToFit,\n    textAnchor,\n    verticalAnchor,\n    ...props\n  } = resolveDefaultProps(outsideProps, textDefaultProps);\n  const wordsByLines: ReadonlyArray<Words> = useMemo(() => {\n    return getWordsByLines({\n      breakAll: props.breakAll,\n      children: props.children,\n      maxLines: props.maxLines,\n      scaleToFit,\n      style: props.style,\n      width: props.width,\n    });\n  }, [props.breakAll, props.children, props.maxLines, scaleToFit, props.style, props.width]);\n\n  const { dx, dy, angle, className, breakAll, ...textProps } = props;\n\n  if (!isNumOrStr(propsX) || !isNumOrStr(propsY) || wordsByLines.length === 0) {\n    return null;\n  }\n  const x = Number(propsX) + (isNumber(dx) ? dx : 0);\n  const y = Number(propsY) + (isNumber(dy) ? dy : 0);\n\n  if (!isWellBehavedNumber(x) || !isWellBehavedNumber(y)) {\n    return null;\n  }\n\n  let startDy: string;\n  switch (verticalAnchor) {\n    case 'start':\n      startDy = reduceCSSCalc(`calc(${capHeight})`);\n      break;\n    case 'middle':\n      startDy = reduceCSSCalc(`calc(${(wordsByLines.length - 1) / 2} * -${lineHeight} + (${capHeight} / 2))`);\n      break;\n    default:\n      startDy = reduceCSSCalc(`calc(${wordsByLines.length - 1} * -${lineHeight})`);\n      break;\n  }\n\n  const transforms = [];\n  const firstLine = wordsByLines[0];\n  if (scaleToFit && firstLine != null) {\n    const lineWidth = firstLine.width;\n    const { width } = props;\n    transforms.push(`scale(${isNumber(width) && isNumber(lineWidth) ? width / lineWidth : 1})`);\n  }\n  if (angle) {\n    transforms.push(`rotate(${angle}, ${x}, ${y})`);\n  }\n  if (transforms.length) {\n    textProps.transform = transforms.join(' ');\n  }\n\n  return (\n    <text\n      {...svgPropertiesAndEvents(textProps)}\n      ref={ref}\n      x={x}\n      y={y}\n      className={clsx('recharts-text', className)}\n      textAnchor={textAnchor}\n      fill={fill.includes('url') ? DEFAULT_FILL : fill}\n    >\n      {wordsByLines.map((line, index) => {\n        const words = line.words.join(breakAll ? '' : ' ');\n        return (\n          // duplicate words will cause duplicate keys which is why we add the array index here\n          <tspan x={x} dy={index === 0 ? startDy : lineHeight} key={`${words}-${index}`}>\n            {words}\n          </tspan>\n        );\n      })}\n    </text>\n  );\n});\n\nText.displayName = 'Text';\n","import { getPercentValue, isNumber, isPercent } from '../util/DataUtils';\nimport { CartesianViewBoxRequired, TrapezoidViewBox } from '../util/types';\nimport { TextAnchor, TextVerticalAnchor } from '../component/Text';\nimport { cartesianViewBoxToTrapezoid } from '../context/chartLayoutContext';\n\nexport type CartesianLabelPosition =\n  | 'top'\n  | 'left'\n  | 'right'\n  | 'bottom'\n  | 'inside'\n  | 'outside'\n  | 'insideLeft'\n  | 'insideRight'\n  | 'insideTop'\n  | 'insideBottom'\n  | 'insideTopLeft'\n  | 'insideBottomLeft'\n  | 'insideTopRight'\n  | 'insideBottomRight'\n  | 'insideStart'\n  | 'insideEnd'\n  | 'end'\n  | 'center'\n  | 'centerTop'\n  | 'centerBottom'\n  | 'middle'\n  | {\n      x?: number | string;\n      y?: number | string;\n    };\n\nexport type GetCartesianPositionOptions = {\n  viewBox: TrapezoidViewBox | CartesianViewBoxRequired;\n  parentViewBox?: CartesianViewBoxRequired;\n  /**\n   * The offset to the specified \"position\". Direction of the offset depends on the position.\n   */\n  offset?: number;\n  /**\n   * The position of the element relative to the view box.\n   */\n  position?: CartesianLabelPosition;\n  /**\n   * If true, the returned width and height will be clamped to keep the element within the parentViewBox.\n   * This is useful for preventing labels from overflowing the chart area.\n   */\n  clamp?: boolean;\n};\n\nexport type CartesianPosition = {\n  x: number;\n  y: number;\n  horizontalAnchor: TextAnchor;\n  verticalAnchor: TextVerticalAnchor;\n  width?: number;\n  height?: number;\n};\n\n/**\n * Calculates the position and alignment for a generic element in a Cartesian coordinate system.\n *\n * @param options - The options including viewBox, position, and offset.\n * @returns The calculated x, y, alignment and size.\n */\nexport const getCartesianPosition = (options: GetCartesianPositionOptions): CartesianPosition => {\n  const { viewBox, position, offset = 0, parentViewBox: parentViewBoxFromOptions, clamp } = options;\n\n  const { x, y, height, upperWidth, lowerWidth } = cartesianViewBoxToTrapezoid(viewBox);\n\n  // Funnel.tsx provides a viewBox where `x` is the top-left of the trapezoid shape.\n  const upperX = x;\n  // The trapezoid is centered, so we can calculate the other corners from the top-left.\n  const lowerX = x + (upperWidth - lowerWidth) / 2;\n  // middleX is the x-coordinate of the left edge at the vertical midpoint of the trapezoid.\n  const middleX = (upperX + lowerX) / 2;\n  // The width of the trapezoid at its vertical midpoint.\n  const midHeightWidth = (upperWidth + lowerWidth) / 2;\n  // The center x-coordinate is constant for the entire height of the trapezoid.\n  const centerX = upperX + upperWidth / 2;\n\n  // Define vertical offsets and position inverts based on the value being positive or negative.\n  // This allows labels to be positioned correctly for bars with negative height.\n  const verticalSign = height >= 0 ? 1 : -1;\n  const verticalOffset = verticalSign * offset;\n  const verticalEnd = verticalSign > 0 ? 'end' : 'start';\n  const verticalStart = verticalSign > 0 ? 'start' : 'end';\n\n  // Define horizontal offsets and position inverts based on the value being positive or negative.\n  // This allows labels to be positioned correctly for bars with negative width.\n  const horizontalSign = upperWidth >= 0 ? 1 : -1;\n  const horizontalOffset = horizontalSign * offset;\n  const horizontalEnd = horizontalSign > 0 ? 'end' : 'start';\n  const horizontalStart = horizontalSign > 0 ? 'start' : 'end';\n\n  // We assume parentViewBox is generic if provided.\n  // The user has asserted that parentViewBox will be CartesianViewBoxRequired if present.\n  const parentViewBox = parentViewBoxFromOptions;\n\n  if (position === 'top') {\n    const result: CartesianPosition = {\n      x: upperX + upperWidth / 2,\n      y: y - verticalOffset,\n      horizontalAnchor: 'middle',\n      verticalAnchor: verticalEnd,\n    };\n\n    if (clamp && parentViewBox) {\n      result.height = Math.max(y - parentViewBox.y, 0);\n      result.width = upperWidth;\n    }\n    return result;\n  }\n\n  if (position === 'bottom') {\n    const result: CartesianPosition = {\n      x: lowerX + lowerWidth / 2,\n      y: y + height + verticalOffset,\n      horizontalAnchor: 'middle',\n      verticalAnchor: verticalStart,\n    };\n    if (clamp && parentViewBox) {\n      result.height = Math.max(parentViewBox.y + parentViewBox.height - (y + height), 0);\n      result.width = lowerWidth;\n    }\n    return result;\n  }\n\n  if (position === 'left') {\n    const result: CartesianPosition = {\n      x: middleX - horizontalOffset,\n      y: y + height / 2,\n      horizontalAnchor: horizontalEnd,\n      verticalAnchor: 'middle',\n    };\n    if (clamp && parentViewBox) {\n      result.width = Math.max(result.x - parentViewBox.x, 0);\n      result.height = height;\n    }\n    return result;\n  }\n\n  if (position === 'right') {\n    const result: CartesianPosition = {\n      x: middleX + midHeightWidth + horizontalOffset,\n      y: y + height / 2,\n      horizontalAnchor: horizontalStart,\n      verticalAnchor: 'middle',\n    };\n    if (clamp && parentViewBox) {\n      result.width = Math.max(parentViewBox.x + parentViewBox.width - result.x, 0);\n      result.height = height;\n    }\n    return result;\n  }\n\n  const sizeAttrs = clamp && parentViewBox ? { width: midHeightWidth, height } : {};\n\n  if (position === 'insideLeft') {\n    return {\n      x: middleX + horizontalOffset,\n      y: y + height / 2,\n      horizontalAnchor: horizontalStart,\n      verticalAnchor: 'middle',\n      ...sizeAttrs,\n    };\n  }\n\n  if (position === 'insideRight') {\n    return {\n      x: middleX + midHeightWidth - horizontalOffset,\n      y: y + height / 2,\n      horizontalAnchor: horizontalEnd,\n      verticalAnchor: 'middle',\n      ...sizeAttrs,\n    };\n  }\n\n  if (position === 'insideTop') {\n    return {\n      x: upperX + upperWidth / 2,\n      y: y + verticalOffset,\n      horizontalAnchor: 'middle',\n      verticalAnchor: verticalStart,\n      ...sizeAttrs,\n    };\n  }\n\n  if (position === 'insideBottom') {\n    return {\n      x: lowerX + lowerWidth / 2,\n      y: y + height - verticalOffset,\n      horizontalAnchor: 'middle',\n      verticalAnchor: verticalEnd,\n      ...sizeAttrs,\n    };\n  }\n\n  if (position === 'insideTopLeft') {\n    return {\n      x: upperX + horizontalOffset,\n      y: y + verticalOffset,\n      horizontalAnchor: horizontalStart,\n      verticalAnchor: verticalStart,\n      ...sizeAttrs,\n    };\n  }\n\n  if (position === 'insideTopRight') {\n    return {\n      x: upperX + upperWidth - horizontalOffset,\n      y: y + verticalOffset,\n      horizontalAnchor: horizontalEnd,\n      verticalAnchor: verticalStart,\n      ...sizeAttrs,\n    };\n  }\n\n  if (position === 'insideBottomLeft') {\n    return {\n      x: lowerX + horizontalOffset,\n      y: y + height - verticalOffset,\n      horizontalAnchor: horizontalStart,\n      verticalAnchor: verticalEnd,\n      ...sizeAttrs,\n    };\n  }\n\n  if (position === 'insideBottomRight') {\n    return {\n      x: lowerX + lowerWidth - horizontalOffset,\n      y: y + height - verticalOffset,\n      horizontalAnchor: horizontalEnd,\n      verticalAnchor: verticalEnd,\n      ...sizeAttrs,\n    };\n  }\n\n  if (\n    !!position &&\n    typeof position === 'object' &&\n    (isNumber(position.x) || isPercent(position.x)) &&\n    (isNumber(position.y) || isPercent(position.y))\n  ) {\n    // TODO: This is not quite right. The width of the trapezoid changes with y.\n    // A percentage-based x should be relative to the width at that y.\n    // For now, we use the mid-height width as a reasonable approximation.\n    return {\n      x: x + getPercentValue(position.x, midHeightWidth),\n      y: y + getPercentValue(position.y, height),\n      horizontalAnchor: 'end',\n      verticalAnchor: 'end',\n      ...sizeAttrs,\n    };\n  }\n\n  return {\n    x: centerX,\n    y: y + height / 2,\n    horizontalAnchor: 'middle',\n    verticalAnchor: 'middle',\n    ...sizeAttrs,\n  };\n};\n","import * as React from 'react';\nimport {\n  cloneElement,\n  createContext,\n  createElement,\n  isValidElement,\n  ReactElement,\n  ReactNode,\n  SVGProps,\n  useContext,\n  useMemo,\n} from 'react';\nimport { clsx } from 'clsx';\nimport { isValidTextAnchor, RenderableText, Text, TextAnchor, TextVerticalAnchor } from './Text';\nimport { isNullish, isNumber, isNumOrStr, mathSign, uniqueId } from '../util/DataUtils';\nimport { polarToCartesian } from '../util/PolarUtils';\nimport { CartesianViewBoxRequired, DataKey, PolarViewBoxRequired, TrapezoidViewBox, ViewBox } from '../util/types';\nimport { cartesianViewBoxToTrapezoid, useViewBox } from '../context/chartLayoutContext';\nimport { useAppSelector } from '../state/hooks';\nimport { selectPolarViewBox } from '../state/selectors/polarAxisSelectors';\nimport { resolveDefaultProps } from '../util/resolveDefaultProps';\nimport { svgPropertiesAndEvents } from '../util/svgPropertiesAndEvents';\nimport { ZIndexable, ZIndexLayer } from '../zIndex/ZIndexLayer';\nimport { DefaultZIndexes } from '../zIndex/DefaultZIndexes';\n\nimport { CartesianLabelPosition, getCartesianPosition } from '../cartesian/getCartesianPosition';\n\n/**\n * @inline\n */\nexport type LabelContentType = ReactElement | ((props: Props) => RenderableText | ReactElement);\n\ntype PolarLabelPosition = 'insideStart' | 'insideEnd' | 'end';\n\n/**\n * @inline\n */\nexport type LabelPosition = CartesianLabelPosition | PolarLabelPosition;\n\n/**\n * @inline\n */\nexport type LabelFormatter = (label: RenderableText) => RenderableText;\n\ninterface LabelProps extends ZIndexable {\n  /**\n   * The box of viewing area. Used for positioning.\n   * If undefined, viewBox will be calculated based on surrounding context.\n   */\n  viewBox?: ViewBox;\n  parentViewBox?: ViewBox;\n  /**\n   * Function to customize how content is serialized before rendering.\n   *\n   * This should return a renderable text - something that the {@link Text} component can render.\n   * Typically, a string or number.\n   * Custom components are not supported here - use the `content` prop instead.\n   */\n  formatter?: LabelFormatter;\n  /**\n   * The value of label can be set as children or as the `value` prop\n   *\n   * @example <Label value=\"foo\" />\n   */\n  value?: RenderableText;\n  /**\n   * The offset to the specified \"position\". Direction of the offset depends on the position.\n   *\n   * @defaultValue 5\n   */\n  offset?: number;\n  /**\n   * The position of label relative to the view box.\n   *\n   * @defaultValue middle\n   */\n  position?: LabelPosition;\n  /**\n   * The value of label can be set as children or as the `value` prop\n   *\n   * @example <Label>foo</Label>\n   */\n  children?: RenderableText;\n  className?: string;\n  /**\n   * If set a React element, the option is the custom react element of rendering label.\n   * If set a function, the function will be called to render label content.\n   *\n   * @example <Label content={CustomizedLabel} />\n   * @example\n   * const renderCustomLabel = (props) => <text {...props}>Custom Label</text>;\n   * <Label content={renderCustomLabel} />\n   */\n  content?: LabelContentType;\n  /**\n   * @defaultValue false\n   */\n  textBreakAll?: boolean;\n  /**\n   * Text rotation angle in degrees.\n   * Positive values rotate clockwise, negative values rotate counterclockwise.\n   *\n   * @defaultValue 0\n   */\n  angle?: number;\n  index?: number;\n  labelRef?: React.RefObject<SVGTextElement> | null;\n  /**\n   * Z-Index of this component and its children. The higher the value,\n   * the more on top it will be rendered.\n   * Components with higher zIndex will appear in front of components with lower zIndex.\n   * If undefined or 0, the content is rendered in the default layer without portals.\n   *\n   * @since 3.4\n   * @defaultValue 2000\n   * @see {@link https://recharts.github.io/en-US/guide/zIndex/ Z-Index and layers guide}\n   */\n  zIndex?: number;\n  /**\n   * Unique identifier of this component.\n   * Used as an HTML attribute `id`.\n   */\n  id?: string;\n}\n\nexport type Props = Omit<SVGProps<SVGTextElement>, 'viewBox'> & LabelProps;\n\ntype PropsWithDefaults = Props & {\n  offset: number;\n};\n\nexport type ImplicitLabelType =\n  | boolean\n  | string\n  | number\n  | ReactElement<SVGElement>\n  | ((props: any) => RenderableText | ReactElement)\n  // dataKey is only applicable when label is used implicitly from graphical element props\n  | (Props & { dataKey?: DataKey<any> });\n\nconst CartesianLabelContext = createContext<TrapezoidViewBox | null>(null);\n\nexport const CartesianLabelContextProvider = ({\n  x,\n  y,\n  upperWidth,\n  lowerWidth,\n  width,\n  height,\n  children,\n}: TrapezoidViewBox & {\n  children: ReactNode;\n}) => {\n  const viewBox: TrapezoidViewBox = useMemo(\n    () => ({\n      x,\n      y,\n      upperWidth,\n      lowerWidth,\n      width,\n      height,\n    }),\n    [x, y, upperWidth, lowerWidth, width, height],\n  );\n  return <CartesianLabelContext.Provider value={viewBox}>{children}</CartesianLabelContext.Provider>;\n};\n\nconst useCartesianLabelContext = (): TrapezoidViewBox | undefined => {\n  const labelChildContext = useContext(CartesianLabelContext);\n  const chartContext = useViewBox();\n  return labelChildContext || (chartContext ? cartesianViewBoxToTrapezoid(chartContext) : undefined);\n};\n\nconst PolarLabelContext = createContext<PolarViewBoxRequired | null>(null);\n\nexport const PolarLabelContextProvider = ({\n  cx,\n  cy,\n  innerRadius,\n  outerRadius,\n  startAngle,\n  endAngle,\n  clockWise,\n  children,\n}: PolarViewBoxRequired & {\n  children: ReactNode;\n}) => {\n  const viewBox: PolarViewBoxRequired = useMemo(\n    () => ({\n      cx,\n      cy,\n      innerRadius,\n      outerRadius,\n      startAngle,\n      endAngle,\n      clockWise,\n    }),\n    [cx, cy, innerRadius, outerRadius, startAngle, endAngle, clockWise],\n  );\n  return <PolarLabelContext.Provider value={viewBox}>{children}</PolarLabelContext.Provider>;\n};\n\nexport const usePolarLabelContext = (): PolarViewBoxRequired | undefined => {\n  const labelChildContext = useContext(PolarLabelContext);\n  const chartContext = useAppSelector(selectPolarViewBox);\n  return labelChildContext || chartContext;\n};\n\nconst getLabel = (props: Props): RenderableText => {\n  const { value, formatter } = props;\n  const label: RenderableText = isNullish(props.children) ? value : props.children;\n\n  if (typeof formatter === 'function') {\n    return formatter(label);\n  }\n\n  return label;\n};\n\nexport const isLabelContentAFunction = (content: unknown): content is (props: Props) => React.ReactNode => {\n  return content != null && typeof content === 'function';\n};\n\nconst getDeltaAngle = (startAngle: number, endAngle: number) => {\n  const sign = mathSign(endAngle - startAngle);\n  const deltaAngle = Math.min(Math.abs(endAngle - startAngle), 360);\n\n  return sign * deltaAngle;\n};\n\nconst renderRadialLabel = (\n  labelProps: PropsWithDefaults,\n  position: PolarLabelPosition,\n  label: ReactNode,\n  attrs: SVGProps<SVGTextElement>,\n  viewBox: PolarViewBoxRequired,\n) => {\n  const { offset, className } = labelProps;\n  const { cx, cy, innerRadius, outerRadius, startAngle, endAngle, clockWise } = viewBox;\n  const radius = (innerRadius + outerRadius) / 2;\n  const deltaAngle = getDeltaAngle(startAngle, endAngle);\n  const sign = deltaAngle >= 0 ? 1 : -1;\n  let labelAngle, direction;\n\n  switch (position) {\n    case 'insideStart':\n      labelAngle = startAngle + sign * offset;\n      direction = clockWise;\n      break;\n    case 'insideEnd':\n      labelAngle = endAngle - sign * offset;\n      direction = !clockWise;\n      break;\n    case 'end':\n      labelAngle = endAngle + sign * offset;\n      direction = clockWise;\n      break;\n    default:\n      throw new Error(`Unsupported position ${position}`);\n  }\n\n  direction = deltaAngle <= 0 ? direction : !direction;\n\n  const startPoint = polarToCartesian(cx, cy, radius, labelAngle);\n  const endPoint = polarToCartesian(cx, cy, radius, labelAngle + (direction ? 1 : -1) * 359);\n  const path = `M${startPoint.x},${startPoint.y}\n    A${radius},${radius},0,1,${direction ? 0 : 1},\n    ${endPoint.x},${endPoint.y}`;\n  const id = isNullish(labelProps.id) ? uniqueId('recharts-radial-line-') : labelProps.id;\n\n  return (\n    <text {...attrs} dominantBaseline=\"central\" className={clsx('recharts-radial-bar-label', className)}>\n      <defs>\n        <path id={id} d={path} />\n      </defs>\n      <textPath xlinkHref={`#${id}`}>{label}</textPath>\n    </text>\n  );\n};\n\nconst getAttrsOfPolarLabel = (\n  viewBox: PolarViewBoxRequired,\n  offset: number,\n  position: LabelPosition | undefined,\n): LabelPositionAttributes => {\n  const { cx, cy, innerRadius, outerRadius, startAngle, endAngle } = viewBox;\n  const midAngle = (startAngle + endAngle) / 2;\n\n  if (position === 'outside') {\n    const { x, y } = polarToCartesian(cx, cy, outerRadius + offset, midAngle);\n\n    return {\n      x,\n      y,\n      textAnchor: x >= cx ? 'start' : 'end',\n      verticalAnchor: 'middle',\n    };\n  }\n\n  if (position === 'center') {\n    return {\n      x: cx,\n      y: cy,\n      textAnchor: 'middle',\n      verticalAnchor: 'middle',\n    };\n  }\n\n  if (position === 'centerTop') {\n    return {\n      x: cx,\n      y: cy,\n      textAnchor: 'middle',\n      verticalAnchor: 'start',\n    };\n  }\n\n  if (position === 'centerBottom') {\n    return {\n      x: cx,\n      y: cy,\n      textAnchor: 'middle',\n      verticalAnchor: 'end',\n    };\n  }\n\n  const r = (innerRadius + outerRadius) / 2;\n  const { x, y } = polarToCartesian(cx, cy, r, midAngle);\n\n  return {\n    x,\n    y,\n    textAnchor: 'middle',\n    verticalAnchor: 'middle',\n  };\n};\n\nconst isPolar = (\n  viewBox: CartesianViewBoxRequired | TrapezoidViewBox | PolarViewBoxRequired | undefined,\n): viewBox is PolarViewBoxRequired => viewBox != null && 'cx' in viewBox && isNumber(viewBox.cx);\n\nexport type LabelPositionAttributes = {\n  x: number;\n  y: number;\n  textAnchor: TextAnchor;\n  verticalAnchor: TextVerticalAnchor;\n  width?: number;\n  height?: number;\n};\n\nexport const defaultLabelProps = {\n  angle: 0,\n  offset: 5,\n  zIndex: DefaultZIndexes.label,\n  position: 'middle',\n  textBreakAll: false,\n} as const satisfies Partial<Props>;\n\nfunction polarViewBoxToTrapezoid(\n  viewBox: PolarViewBoxRequired | TrapezoidViewBox | undefined,\n): TrapezoidViewBox | undefined {\n  if (!isPolar(viewBox)) {\n    return viewBox;\n  }\n  const { cx, cy, outerRadius } = viewBox;\n  const diameter = outerRadius * 2;\n  return {\n    x: cx - outerRadius,\n    y: cy - outerRadius,\n    width: diameter,\n    upperWidth: diameter,\n    lowerWidth: diameter,\n    height: diameter,\n  };\n}\n\n/**\n * @consumes CartesianViewBoxContext\n * @consumes PolarViewBoxContext\n * @consumes CartesianLabelContext\n * @consumes PolarLabelContext\n */\nexport function Label(outerProps: Props) {\n  const props: PropsWithDefaults = resolveDefaultProps(outerProps, defaultLabelProps);\n  const {\n    viewBox: viewBoxFromProps,\n    parentViewBox,\n    position,\n    value,\n    children,\n    content,\n    className = '',\n    textBreakAll,\n    labelRef,\n  } = props;\n  const polarViewBox = usePolarLabelContext();\n  const cartesianViewBox = useCartesianLabelContext();\n\n  /*\n   * I am not proud about this solution, but it's a quick fix for https://github.com/recharts/recharts/issues/6030#issuecomment-3155352460.\n   * What we should really do is split Label into two components: CartesianLabel and PolarLabel and then handle their respective viewBoxes separately.\n   * Also other components should set its own viewBox in a context so that we can fix https://github.com/recharts/recharts/issues/6156\n   */\n  const resolvedViewBox = position === 'center' ? cartesianViewBox : (polarViewBox ?? cartesianViewBox);\n\n  let viewBox: PolarViewBoxRequired | TrapezoidViewBox | undefined,\n    label: RenderableText,\n    positionAttrs: LabelPositionAttributes;\n  if (viewBoxFromProps == null) {\n    viewBox = resolvedViewBox;\n  } else if (isPolar(viewBoxFromProps)) {\n    viewBox = viewBoxFromProps;\n  } else {\n    viewBox = cartesianViewBoxToTrapezoid(viewBoxFromProps);\n  }\n\n  const cartesianBox = polarViewBoxToTrapezoid(viewBox);\n\n  if (\n    !viewBox ||\n    (isNullish(value) && isNullish(children) && !isValidElement(content) && typeof content !== 'function')\n  ) {\n    return null;\n  }\n\n  const propsWithViewBox = {\n    ...props,\n    viewBox,\n  };\n\n  if (isValidElement(content)) {\n    const { labelRef: _, ...propsWithoutLabelRef } = propsWithViewBox;\n    return cloneElement(content, propsWithoutLabelRef);\n  }\n\n  if (typeof content === 'function') {\n    const { content: _, ...propsForContent } = propsWithViewBox;\n    // @ts-expect-error we're not checking if the content component returns something that Text is able to render\n    label = createElement(content, propsForContent);\n\n    if (isValidElement(label)) {\n      return label;\n    }\n  } else {\n    label = getLabel(props);\n  }\n\n  const attrs = svgPropertiesAndEvents(props);\n\n  if (isPolar(viewBox)) {\n    // TODO: Generic Polar Hook\n    if (position === 'insideStart' || position === 'insideEnd' || position === 'end') {\n      return renderRadialLabel(props, position, label, attrs, viewBox);\n    }\n    positionAttrs = getAttrsOfPolarLabel(viewBox, props.offset, props.position);\n  } else {\n    if (!cartesianBox) {\n      return null;\n    }\n    const cartesianResult = getCartesianPosition({\n      viewBox: cartesianBox,\n      position,\n      offset: props.offset,\n      parentViewBox: isPolar(parentViewBox) ? undefined : parentViewBox,\n      clamp: true,\n    });\n\n    positionAttrs = {\n      x: cartesianResult.x,\n      y: cartesianResult.y,\n      textAnchor: cartesianResult.horizontalAnchor,\n      verticalAnchor: cartesianResult.verticalAnchor,\n      ...(cartesianResult.width !== undefined ? { width: cartesianResult.width } : {}),\n      ...(cartesianResult.height !== undefined ? { height: cartesianResult.height } : {}),\n    };\n  }\n\n  return (\n    <ZIndexLayer zIndex={props.zIndex}>\n      <Text\n        ref={labelRef}\n        className={clsx('recharts-label', className)}\n        {...attrs}\n        {...positionAttrs}\n        /*\n         * textAnchor is decided by default based on the `position`\n         * but we allow overriding via props for precise control.\n         */\n        textAnchor={isValidTextAnchor(attrs.textAnchor) ? attrs.textAnchor : positionAttrs.textAnchor}\n        breakAll={textBreakAll}\n      >\n        {label}\n      </Text>\n    </ZIndexLayer>\n  );\n}\n\nLabel.displayName = 'Label';\n\nconst parseLabel = (\n  label: ImplicitLabelType | undefined,\n  viewBox: ViewBox | undefined,\n  labelRef?: React.RefObject<SVGTextElement> | null,\n) => {\n  if (!label) {\n    return null;\n  }\n\n  const commonProps = { viewBox, labelRef };\n\n  if (label === true) {\n    return <Label key=\"label-implicit\" {...commonProps} />;\n  }\n\n  if (isNumOrStr(label)) {\n    return <Label key=\"label-implicit\" value={label} {...commonProps} />;\n  }\n\n  if (isValidElement(label)) {\n    if (label.type === Label) {\n      return cloneElement<SVGElement>(label, { key: 'label-implicit', ...commonProps });\n    }\n\n    return <Label key=\"label-implicit\" content={label} {...commonProps} />;\n  }\n\n  if (isLabelContentAFunction(label)) {\n    return <Label key=\"label-implicit\" content={label} {...commonProps} />;\n  }\n\n  if (label && typeof label === 'object') {\n    return <Label {...label} key=\"label-implicit\" {...commonProps} />;\n  }\n\n  return null;\n};\n\nexport function CartesianLabelFromLabelProp({\n  label,\n  labelRef,\n}: {\n  label: ImplicitLabelType | undefined;\n  labelRef?: React.RefObject<SVGTextElement> | null;\n}) {\n  const viewBox = useCartesianLabelContext();\n\n  return parseLabel(label, viewBox, labelRef) || null;\n}\n\nexport function PolarLabelFromLabelProp({ label }: { label: ImplicitLabelType | undefined }) {\n  const viewBox = usePolarLabelContext();\n\n  return parseLabel(label, viewBox) || null;\n}\n","import * as React from 'react';\nimport { createContext, PropsWithoutRef, SVGProps, useContext } from 'react';\nimport { LabelContentType, isLabelContentAFunction, Label, LabelPosition, LabelFormatter } from './Label';\nimport { Layer } from '../container/Layer';\nimport { getValueByDataKey } from '../util/ChartUtils';\nimport { CartesianViewBoxRequired, DataKey, PolarViewBoxRequired, TrapezoidViewBox } from '../util/types';\nimport { isNullish } from '../util/DataUtils';\nimport { LabelProps } from '../index';\nimport { svgPropertiesAndEvents } from '../util/svgPropertiesAndEvents';\nimport { ZIndexable, ZIndexLayer } from '../zIndex/ZIndexLayer';\nimport { DefaultZIndexes } from '../zIndex/DefaultZIndexes';\nimport { isRenderableText, RenderableText } from './Text';\n\nexport interface LabelListEntry<DataPointItem = any> {\n  /**\n   * Value is what renders in the UI as the label content.\n   * If undefined, then the LabelList will pull it from the payload using the dataKey.\n   */\n  value: unknown;\n  /**\n   * Payload is the source data object for this entry. The shape of this depends on what the user has passed\n   * as the data prop to the chart.\n   */\n  payload: DataPointItem;\n  fill: string | undefined;\n}\n\n/**\n * This is public API because we expose it as the valueAccessor parameter.\n *\n * The properties of \"viewBox\" are repeated as the root props of the entry object.\n * So it doesn't matter if you read entry.x or entry.viewBox.x, they are the same.\n *\n * It's not necessary to pass redundant data, but we keep it for backward compatibility.\n */\nexport interface CartesianLabelListEntry extends LabelListEntry, TrapezoidViewBox {\n  /**\n   * The bounding box of the graphical element that this label is attached to.\n   * This will be an individual Bar for example.\n   */\n  viewBox: TrapezoidViewBox;\n  parentViewBox?: CartesianViewBoxRequired;\n}\n\nexport interface PolarLabelListEntry extends LabelListEntry {\n  viewBox: PolarViewBoxRequired;\n  parentViewBox?: PolarViewBoxRequired;\n  clockWise?: boolean;\n}\n\ninterface LabelListProps extends ZIndexable {\n  /**\n   * Unique identifier of this component.\n   * Used as an HTML attribute `id`.\n   */\n  id?: string;\n  /**\n   * The accessor function to get the value of each label. Is ignored if dataKey is specified.\n   * @param entry\n   * @param index\n   */\n  valueAccessor?: (entry: CartesianLabelListEntry | PolarLabelListEntry, index: number) => RenderableText;\n  /**\n   * The parameter to calculate the view box of label in radial charts.\n   */\n  clockWise?: boolean;\n  /**\n   *\n   * Decides how to extract the value of each label from the data:\n   * - `string`: the name of the field in the data object;\n   * - `number`: the index of the field in the data;\n   * - `function`: a function that receives the data object and returns the value of each label.\n   *\n   * If set, then valueAccessor will be ignored.\n   *\n   * Scatter requires this prop to be set.\n   * Other graphical components will show the same value as the dataKey of the component by default.\n   */\n  dataKey?: DataKey<any>;\n  /**\n   * If set a React element, the option is the customized React element of rendering each label.\n   * If set to a function, the function is called once for each item\n   *\n   * @example <LabelList content={CustomizedLabel} />\n   *\n   * @see {@link https://recharts.github.io/en-US/examples/BarChartWithMinHeight/ Customized content of LabelList in a BarChart}\n   */\n  content?: LabelContentType;\n  textBreakAll?: boolean;\n  /**\n   * The position of label relative to the view box.\n   */\n  position?: LabelPosition;\n  /**\n   * The offset to the specified \"position\".\n   * Direction of the offset depends on the position.\n   */\n  offset?: LabelProps['offset'];\n  /**\n   * Text rotation angle in degrees.\n   * Positive values rotate clockwise, negative values rotate counterclockwise.\n   *\n   * @defaultValue 0\n   */\n  angle?: number;\n  /**\n   * Function to customize how content is serialized before rendering.\n   *\n   * This should return a renderable text - something that the {@link Text} component can render.\n   * Typically, a string or number.\n   * Custom components are not supported here - use the `content` prop instead.\n   */\n  formatter?: LabelFormatter;\n  /**\n   * Z-Index of this component and its children. The higher the value,\n   * the more on top it will be rendered.\n   * Components with higher zIndex will appear in front of components with lower zIndex.\n   * If undefined or 0, the content is rendered in the default layer without portals.\n   *\n   * @since 3.4\n   * @defaultValue 2000\n   * @see {@link https://recharts.github.io/en-US/guide/zIndex/ Z-Index and layers guide}\n   */\n  zIndex?: number;\n}\n\n/**\n * LabelList props do not allow refs because the same props are reused in multiple elements so we don't have a good single place to ref to.\n */\ntype SvgTextProps = PropsWithoutRef<SVGProps<SVGTextElement>>;\nexport type Props = Omit<SvgTextProps, 'children'> & LabelListProps;\n\n/**\n * This is the type accepted for the `label` prop on various graphical items.\n * It accepts:\n *\n * boolean:\n *    true = labels show,\n *    false = labels don't show\n * React element:\n *    will be cloned with extra props\n * function:\n *    is used as <Label content={function} />, so this will be called once for each individual label (so typically once for each data point)\n * object:\n *    the props to be passed to a LabelList component\n *\n * @inline\n */\nexport type ImplicitLabelListType = boolean | LabelContentType | Props;\n\nconst defaultAccessor = (entry: LabelListEntry): RenderableText => {\n  const val = Array.isArray(entry.value) ? entry.value[entry.value.length - 1] : entry.value;\n  if (isRenderableText(val)) {\n    return val;\n  }\n  return undefined;\n};\n\nconst CartesianLabelListContext = createContext<ReadonlyArray<CartesianLabelListEntry> | undefined>(undefined);\n\nexport const CartesianLabelListContextProvider = CartesianLabelListContext.Provider;\n\nconst PolarLabelListContext = createContext<ReadonlyArray<PolarLabelListEntry> | undefined>(undefined);\n\nexport const PolarLabelListContextProvider = PolarLabelListContext.Provider;\n\nfunction useCartesianLabelListContext(): ReadonlyArray<CartesianLabelListEntry> | undefined {\n  return useContext(CartesianLabelListContext);\n}\n\nfunction usePolarLabelListContext(): ReadonlyArray<PolarLabelListEntry> | undefined {\n  return useContext(PolarLabelListContext);\n}\n\n/**\n * @consumes LabelListContext\n */\nexport function LabelList({ valueAccessor = defaultAccessor, ...restProps }: Props) {\n  const { dataKey, clockWise, id, textBreakAll, zIndex, ...others } = restProps;\n  const cartesianData = useCartesianLabelListContext();\n  const polarData = usePolarLabelListContext();\n  const data = cartesianData || polarData;\n  if (!data || !data.length) {\n    return null;\n  }\n\n  return (\n    <ZIndexLayer zIndex={zIndex ?? DefaultZIndexes.label}>\n      <Layer className=\"recharts-label-list\">\n        {data.map((entry, index) => {\n          const value = isNullish(dataKey)\n            ? valueAccessor(entry, index)\n            : (getValueByDataKey(entry.payload, dataKey) as string | number);\n\n          const idProps = isNullish(id) ? {} : { id: `${id}-${index}` };\n\n          return (\n            <Label\n              key={`label-${index}`}\n              {...svgPropertiesAndEvents(entry)}\n              {...others}\n              {...idProps}\n              /*\n               * Prefer to use the explicit fill from LabelList props.\n               * Only in an absence of that, fall back to the fill of the entry.\n               * The entry fill can be quite difficult to see especially in Bar, Pie, RadialBar in inside positions.\n               * On the other hand it's quite convenient in Scatter, Line, or when the position is outside the Bar, Pie filled shapes.\n               */\n              fill={restProps.fill ?? entry.fill}\n              parentViewBox={entry.parentViewBox}\n              value={value}\n              textBreakAll={textBreakAll}\n              viewBox={entry.viewBox}\n              index={index}\n              /*\n               * Here we don't want to use the default Label zIndex,\n               * we want it to inherit the zIndex of the LabelList itself\n               * which means just rendering as a regular child, without portaling anywhere.\n               */\n              zIndex={0}\n            />\n          );\n        })}\n      </Layer>\n    </ZIndexLayer>\n  );\n}\n\nLabelList.displayName = 'LabelList';\n\nexport function LabelListFromLabelProp({ label }: { label?: ImplicitLabelListType }) {\n  if (!label) {\n    return null;\n  }\n\n  if (label === true) {\n    return <LabelList key=\"labelList-implicit\" />;\n  }\n\n  if (React.isValidElement(label) || isLabelContentAFunction(label)) {\n    return <LabelList key=\"labelList-implicit\" content={label} />;\n  }\n\n  if (typeof label === 'object') {\n    return <LabelList key=\"labelList-implicit\" {...label} type={String(label.type)} />;\n  }\n\n  return null;\n}\n","/**\n * @fileOverview Customized\n */\nimport * as React from 'react';\nimport { isValidElement, cloneElement, createElement, Component, FunctionComponent, ReactElement } from 'react';\n\nimport { Layer } from '../container/Layer';\nimport { warn } from '../util/LogUtils';\n\ntype Comp<P> = FunctionComponent<P> | Component<P> | ReactElement<P>;\nexport type Props<P, C extends Comp<P>> = P & {\n  /**\n   * Render your components directly, without Customized wrapper. Will be removed in 4.0\n   * @deprecated\n   * @example Before: `<Customized component={<MyCustomComponent />} />`\n   * @example After: `<MyCustomComponent />`\n   */\n  component: C;\n};\n\n/**\n * Customized component used to be necessary to render custom elements in Recharts 2.x.\n * Starting from Recharts 3.x, all charts are able to render arbitrary elements anywhere,\n * and Customized is no longer needed.\n *\n * @example Before: `<Customized component={<MyCustomComponent />} />`\n * @example After: `<MyCustomComponent />`\n *\n * @deprecated Just render your components directly. Will be removed in 4.0\n */\nexport function Customized<P, C extends Comp<P>>({ component, ...props }: Props<P, C>) {\n  let child;\n  if (isValidElement(component)) {\n    child = cloneElement(component, props);\n  } else if (typeof component === 'function') {\n    // @ts-expect-error TS cannot verify that C is FunctionComponent<P> here\n    child = createElement(component, props as any);\n  } else {\n    warn(false, \"Customized's props `component` must be React.element or Function, but got %s.\", typeof component);\n  }\n  return <Layer className=\"recharts-customized-wrapper\">{child}</Layer>;\n}\n\nCustomized.displayName = 'Customized';\n","/**\n * @fileOverview Polygon\n */\nimport * as React from 'react';\nimport { SVGProps } from 'react';\nimport { clsx } from 'clsx';\nimport { Coordinate } from '../util/types';\nimport { svgPropertiesAndEvents } from '../util/svgPropertiesAndEvents';\nimport { roundTemplateLiteral } from '../util/round';\n\nconst isValidatePoint = (point: Coordinate | undefined): point is Coordinate => {\n  return point != null && point.x === +point.x && point.y === +point.y;\n};\n\nconst getParsedPoints = (points: ReadonlyArray<Coordinate> = []) => {\n  let segmentPoints: Coordinate[][] = [[]];\n\n  points.forEach(entry => {\n    const lastLink = segmentPoints[segmentPoints.length - 1];\n    if (isValidatePoint(entry)) {\n      if (lastLink) {\n        lastLink.push(entry);\n      }\n    } else if (lastLink && lastLink.length > 0) {\n      // add another path\n      segmentPoints.push([]);\n    }\n  });\n\n  const firstPoint = points[0];\n  const lastLink = segmentPoints[segmentPoints.length - 1];\n  if (isValidatePoint(firstPoint) && lastLink) {\n    lastLink.push(firstPoint);\n  }\n\n  const finalLink = segmentPoints[segmentPoints.length - 1];\n  if (finalLink && finalLink.length <= 0) {\n    segmentPoints = segmentPoints.slice(0, -1);\n  }\n\n  return segmentPoints;\n};\n\nconst getSinglePolygonPath = (points: ReadonlyArray<Coordinate>, connectNulls?: boolean) => {\n  let segmentPoints = getParsedPoints(points);\n\n  if (connectNulls) {\n    segmentPoints = [\n      segmentPoints.reduce((res: Coordinate[], segPoints: Coordinate[]) => {\n        return [...res, ...segPoints];\n      }, []),\n    ];\n  }\n\n  const polygonPath = segmentPoints\n    .map(segPoints => {\n      return segPoints.reduce((path: string, point: Coordinate, index: number) => {\n        return roundTemplateLiteral`${path}${index === 0 ? 'M' : 'L'}${point.x},${point.y}`;\n      }, '');\n    })\n    .join('');\n\n  return segmentPoints.length === 1 ? `${polygonPath}Z` : polygonPath;\n};\n\nconst getRanglePath = (\n  points: ReadonlyArray<Coordinate>,\n  baseLinePoints: ReadonlyArray<Coordinate>,\n  connectNulls?: boolean,\n) => {\n  const outerPath = getSinglePolygonPath(points, connectNulls);\n\n  return `${outerPath.slice(-1) === 'Z' ? outerPath.slice(0, -1) : outerPath}L${getSinglePolygonPath(\n    Array.from(baseLinePoints).reverse(),\n    connectNulls,\n  ).slice(1)}`;\n};\n\ninterface PolygonProps {\n  className?: string;\n  /**\n   * The coordinates of all the vertexes of the polygon, like an array of objects with x and y coordinates.\n   */\n  points?: ReadonlyArray<Coordinate>;\n  baseLinePoints?: ReadonlyArray<Coordinate>;\n  connectNulls?: boolean;\n\n  /**\n   * The customized event handler of click on the polygon\n   */\n  onClick?: (e: React.MouseEvent<SVGPolygonElement, MouseEvent>) => void;\n  /**\n   * The customized event handler of mousedown on the polygon\n   */\n  onMouseDown?: (e: React.MouseEvent<SVGPolygonElement, MouseEvent>) => void;\n  /**\n   * The customized event handler of mouseup on the polygon\n   */\n  onMouseUp?: (e: React.MouseEvent<SVGPolygonElement, MouseEvent>) => void;\n  /**\n   * The customized event handler of mousemove on the polygon\n   */\n  onMouseMove?: (e: React.MouseEvent<SVGPolygonElement, MouseEvent>) => void;\n  /**\n   * The customized event handler of mouseover on the polygon\n   */\n  onMouseOver?: (e: React.MouseEvent<SVGPolygonElement, MouseEvent>) => void;\n  /**\n   * The customized event handler of mouseout on the polygon\n   */\n  onMouseOut?: (e: React.MouseEvent<SVGPolygonElement, MouseEvent>) => void;\n  /**\n   * The customized event handler of mouseenter on the polygon\n   */\n  onMouseEnter?: (e: React.MouseEvent<SVGPolygonElement, MouseEvent>) => void;\n  /**\n   * The customized event handler of mouseleave on the polygon\n   */\n  onMouseLeave?: (e: React.MouseEvent<SVGPolygonElement, MouseEvent>) => void;\n}\n\nexport type Props = Omit<SVGProps<SVGPolygonElement>, 'points'> & PolygonProps;\n\nexport const Polygon: React.FC<Props> = props => {\n  const { points, className, baseLinePoints, connectNulls, ...others } = props;\n\n  if (!points || !points.length) {\n    return null;\n  }\n\n  const layerClass = clsx('recharts-polygon', className);\n\n  if (baseLinePoints && baseLinePoints.length) {\n    const hasStroke = others.stroke && others.stroke !== 'none';\n    const rangePath = getRanglePath(points, baseLinePoints, connectNulls);\n\n    return (\n      <g className={layerClass}>\n        <path\n          {...svgPropertiesAndEvents(others)}\n          fill={rangePath.slice(-1) === 'Z' ? others.fill : 'none'}\n          stroke=\"none\"\n          d={rangePath}\n        />\n        {hasStroke ? (\n          <path {...svgPropertiesAndEvents(others)} fill=\"none\" d={getSinglePolygonPath(points, connectNulls)} />\n        ) : null}\n        {hasStroke ? (\n          <path\n            {...svgPropertiesAndEvents(others)}\n            fill=\"none\"\n            d={getSinglePolygonPath(baseLinePoints, connectNulls)}\n          />\n        ) : null}\n      </g>\n    );\n  }\n\n  const singlePath = getSinglePolygonPath(points, connectNulls);\n\n  return (\n    <path\n      {...svgPropertiesAndEvents(others)}\n      fill={singlePath.slice(-1) === 'Z' ? others.fill : 'none'}\n      className={layerClass}\n      d={singlePath}\n    />\n  );\n};\n","import * as React from 'react';\nimport { clsx } from 'clsx';\nimport { PresentationAttributesWithProps, adaptEventHandlers } from '../util/types';\n\nimport { svgPropertiesNoEvents } from '../util/svgPropertiesNoEvents';\nimport { isNumber } from '../util/DataUtils';\n\ninterface DotProps {\n  className?: string;\n  /**\n   * The x-coordinate of center in pixels.\n   */\n  cx?: number;\n  /**\n   * The y-coordinate of center in pixels.\n   */\n  cy?: number;\n  /**\n   * The radius of dot.\n   */\n  r?: number | string;\n  clipDot?: boolean;\n}\n\nexport type Props = PresentationAttributesWithProps<DotProps, SVGCircleElement> & DotProps;\n\n/**\n * Renders a dot in the chart.\n *\n * This component accepts X and Y coordinates in pixels.\n * If you need to position the rectangle based on your chart's data,\n * consider using the {@link ReferenceDot} component instead.\n *\n * @param props\n * @constructor\n */\nexport const Dot: React.FC<Props> = props => {\n  const { cx, cy, r, className } = props;\n  const layerClass = clsx('recharts-dot', className);\n\n  if (isNumber(cx) && isNumber(cy) && isNumber(r)) {\n    return (\n      <circle\n        {...svgPropertiesNoEvents(props)}\n        {...adaptEventHandlers(props)}\n        className={layerClass}\n        cx={cx}\n        cy={cy}\n        r={r}\n      />\n    );\n  }\n\n  return null;\n};\n","import { createSelector } from 'reselect';\nimport { AppliedChartData, ChartData } from '../chartDataSlice';\nimport { RechartsRootState } from '../store';\nimport { AxisId, BaseCartesianAxis } from '../cartesianAxisSlice';\nimport { selectChartDataAndAlwaysIgnoreIndexes, selectChartDataSliceIgnoringIndexes } from './dataSelectors';\nimport {\n  AppliedChartDataWithErrorDomain,\n  combineAppliedValues,\n  combineAxisDomain,\n  combineAxisDomainWithNiceTicks,\n  combineDisplayedData,\n  combineDomainOfAllAppliedNumericalValuesIncludingErrorValues,\n  combineGraphicalItemsData,\n  combineGraphicalItemsSettings,\n  combineNiceTicks,\n  combineNumericalDomain,\n  itemAxisPredicate,\n  selectAllErrorBarSettings,\n  selectBaseAxis,\n  selectDomainDefinition,\n  selectDomainFromUserPreference,\n  selectRealScaleType,\n  selectRenderableAxisSettings,\n} from './axisSelectors';\nimport { PolarGraphicalItemSettings } from '../graphicalItemsSlice';\nimport { CategoricalDomain, NumberDomain } from '../../util/types';\nimport { selectChartLayout } from '../../context/chartLayoutContext';\nimport { getValueByDataKey } from '../../util/ChartUtils';\nimport { pickAxisType } from './pickAxisType';\nimport { pickAxisId } from './pickAxisId';\nimport { selectStackOffsetType } from './rootPropsSelectors';\nimport { combineCheckedDomain } from './combiners/combineCheckedDomain';\n\nexport type PolarAxisType = 'angleAxis' | 'radiusAxis';\n\nexport const selectUnfilteredPolarItems = (state: RechartsRootState) => state.graphicalItems.polarItems;\n\nconst selectAxisPredicate: (\n  _state: RechartsRootState,\n  axisType: PolarAxisType,\n  axisId: AxisId,\n) => (item: PolarGraphicalItemSettings) => boolean = createSelector([pickAxisType, pickAxisId], itemAxisPredicate);\n\nexport const selectPolarItemsSettings: (\n  state: RechartsRootState,\n  axisType: PolarAxisType,\n  polarAxisId: AxisId,\n) => ReadonlyArray<PolarGraphicalItemSettings> = createSelector(\n  [selectUnfilteredPolarItems, selectBaseAxis, selectAxisPredicate],\n  combineGraphicalItemsSettings,\n);\n\nconst selectPolarGraphicalItemsData: (\n  state: RechartsRootState,\n  axisType: PolarAxisType,\n  polarAxisId: AxisId,\n) => ChartData = createSelector([selectPolarItemsSettings], combineGraphicalItemsData);\n\nexport const selectPolarDisplayedData: (\n  state: RechartsRootState,\n  axisType: PolarAxisType,\n  polarAxisId: AxisId,\n) => ChartData = createSelector(\n  [selectPolarGraphicalItemsData, selectChartDataAndAlwaysIgnoreIndexes],\n  combineDisplayedData,\n);\n\nexport const selectPolarAppliedValues: (\n  state: RechartsRootState,\n  axisType: PolarAxisType,\n  axisId: AxisId,\n) => AppliedChartData = createSelector(\n  [selectPolarDisplayedData, selectBaseAxis, selectPolarItemsSettings],\n  combineAppliedValues,\n);\n\nexport const selectAllPolarAppliedNumericalValues: (\n  state: RechartsRootState,\n  axisType: PolarAxisType,\n  axisId: AxisId,\n) => ReadonlyArray<AppliedChartDataWithErrorDomain> = createSelector(\n  [selectPolarDisplayedData, selectBaseAxis, selectPolarItemsSettings],\n  (\n    data: ChartData,\n    axisSettings: BaseCartesianAxis,\n    items: ReadonlyArray<PolarGraphicalItemSettings>,\n  ): ReadonlyArray<AppliedChartDataWithErrorDomain> => {\n    if (items.length > 0) {\n      return data\n        .flatMap(entry => {\n          return items.flatMap((item): AppliedChartDataWithErrorDomain | undefined => {\n            const valueByDataKey: unknown = getValueByDataKey(entry, axisSettings.dataKey ?? item.dataKey);\n            return {\n              value: valueByDataKey,\n              errorDomain: [], // polar charts do not have error bars\n            };\n          });\n        })\n        .filter(Boolean);\n    }\n    if (axisSettings?.dataKey != null) {\n      return data.map(\n        (item): AppliedChartDataWithErrorDomain => ({\n          value: getValueByDataKey(item, axisSettings.dataKey),\n          errorDomain: [],\n        }),\n      );\n    }\n    return data.map((entry): AppliedChartDataWithErrorDomain => ({ value: entry, errorDomain: [] }));\n  },\n);\n\nconst unsupportedInPolarChart = (): undefined => undefined;\n\nconst selectDomainOfAllPolarAppliedNumericalValues: (\n  state: RechartsRootState,\n  axisType: PolarAxisType,\n  axisId: AxisId,\n) => NumberDomain | undefined = createSelector(\n  [\n    selectPolarDisplayedData,\n    selectBaseAxis,\n    selectPolarItemsSettings,\n    selectAllErrorBarSettings,\n    pickAxisType,\n    selectChartDataSliceIgnoringIndexes,\n  ],\n  combineDomainOfAllAppliedNumericalValuesIncludingErrorValues,\n);\n\nconst selectPolarNumericalDomain: (\n  state: RechartsRootState,\n  axisType: PolarAxisType,\n  axisId: AxisId,\n) => NumberDomain | undefined = createSelector(\n  [\n    selectBaseAxis,\n    selectDomainDefinition,\n    selectDomainFromUserPreference,\n    unsupportedInPolarChart,\n    selectDomainOfAllPolarAppliedNumericalValues,\n    unsupportedInPolarChart,\n    selectChartLayout,\n    pickAxisType,\n  ],\n  combineNumericalDomain,\n);\n\nexport const selectPolarAxisDomain: (\n  state: RechartsRootState,\n  axisType: PolarAxisType,\n  polarAxisId: AxisId,\n) => NumberDomain | CategoricalDomain | undefined = createSelector(\n  [\n    selectBaseAxis,\n    selectChartLayout,\n    selectPolarDisplayedData,\n    selectPolarAppliedValues,\n    selectStackOffsetType,\n    pickAxisType,\n    selectPolarNumericalDomain,\n  ],\n  combineAxisDomain,\n);\n\nexport const selectPolarNiceTicks = createSelector(\n  [selectPolarAxisDomain, selectRenderableAxisSettings, selectRealScaleType],\n  combineNiceTicks,\n);\n\nexport const selectPolarAxisDomainIncludingNiceTicks: (\n  state: RechartsRootState,\n  axisType: PolarAxisType,\n  polarAxisId: AxisId,\n) => NumberDomain | CategoricalDomain | undefined = createSelector(\n  [selectBaseAxis, selectPolarAxisDomain, selectPolarNiceTicks, pickAxisType],\n  combineAxisDomainWithNiceTicks,\n);\n\nexport const selectPolarAxisCheckedDomain: (\n  state: RechartsRootState,\n  axisType: PolarAxisType,\n  polarAxisId: AxisId,\n) => NumberDomain | CategoricalDomain | undefined = createSelector(\n  [selectRealScaleType, selectPolarAxisDomainIncludingNiceTicks],\n  combineCheckedDomain,\n);\n","import { createSelector } from 'reselect';\nimport { RechartsRootState } from '../store';\nimport { AxisId } from '../cartesianAxisSlice';\nimport {\n  combineAxisTicks,\n  combineCategoricalDomain,\n  combineGraphicalItemTicks,\n  selectDuplicateDomain,\n  selectRealScaleType,\n  selectRenderableAxisSettings,\n} from './axisSelectors';\nimport {\n  selectAngleAxis,\n  selectAngleAxisRangeWithReversed,\n  selectRadiusAxis,\n  selectRadiusAxisRangeWithReversed,\n} from './polarAxisSelectors';\nimport { CartesianTickItem } from '../../util/types';\nimport { selectChartLayout } from '../../context/chartLayoutContext';\nimport { selectPolarAppliedValues, selectPolarAxisCheckedDomain, selectPolarNiceTicks } from './polarSelectors';\nimport { pickAxisType } from './pickAxisType';\nimport { RechartsScale, rechartsScaleFactory } from '../../util/scale/RechartsScale';\nimport { CustomScaleDefinition } from '../../util/scale/CustomScaleDefinition';\nimport { combineConfiguredScale } from './combiners/combineConfiguredScale';\n\nexport const selectPolarAxis = (state: RechartsRootState, axisType: 'angleAxis' | 'radiusAxis', axisId: AxisId) => {\n  switch (axisType) {\n    case 'angleAxis': {\n      return selectAngleAxis(state, axisId);\n    }\n    case 'radiusAxis': {\n      return selectRadiusAxis(state, axisId);\n    }\n    default: {\n      throw new Error(`Unexpected axis type: ${axisType}`);\n    }\n  }\n};\n\nconst selectPolarAxisRangeWithReversed = (\n  state: RechartsRootState,\n  axisType: 'angleAxis' | 'radiusAxis',\n  axisId: AxisId,\n) => {\n  switch (axisType) {\n    case 'angleAxis': {\n      return selectAngleAxisRangeWithReversed(state, axisId);\n    }\n    case 'radiusAxis': {\n      return selectRadiusAxisRangeWithReversed(state, axisId);\n    }\n    default: {\n      throw new Error(`Unexpected axis type: ${axisType}`);\n    }\n  }\n};\n\nconst selectPolarConfiguredScale: (\n  state: RechartsRootState,\n  axisType: 'angleAxis' | 'radiusAxis',\n  polarAxisId: AxisId,\n) => CustomScaleDefinition | undefined = createSelector(\n  [selectPolarAxis, selectRealScaleType, selectPolarAxisCheckedDomain, selectPolarAxisRangeWithReversed],\n  combineConfiguredScale,\n);\n\nexport const selectPolarAxisScale: (\n  state: RechartsRootState,\n  axisType: 'angleAxis' | 'radiusAxis',\n  polarAxisId: AxisId,\n) => RechartsScale | undefined = createSelector([selectPolarConfiguredScale], rechartsScaleFactory);\n\nexport const selectPolarCategoricalDomain: (\n  state: RechartsRootState,\n  axisType: 'angleAxis' | 'radiusAxis',\n  polarAxisId: AxisId,\n) => ReadonlyArray<unknown> | undefined = createSelector(\n  [selectChartLayout, selectPolarAppliedValues, selectRenderableAxisSettings, pickAxisType],\n  combineCategoricalDomain,\n);\n\nexport const selectPolarAxisTicks: (\n  state: RechartsRootState,\n  axisType: 'angleAxis' | 'radiusAxis',\n  polarAxisId: AxisId,\n  isPanorama: boolean,\n) => ReadonlyArray<CartesianTickItem> | undefined = createSelector(\n  [\n    selectChartLayout,\n    selectPolarAxis,\n    selectRealScaleType,\n    selectPolarAxisScale,\n    selectPolarNiceTicks,\n    selectPolarAxisRangeWithReversed,\n    selectDuplicateDomain,\n    selectPolarCategoricalDomain,\n    pickAxisType,\n  ],\n  combineAxisTicks,\n);\n\nexport const selectPolarAngleAxisTicks: (\n  state: RechartsRootState,\n  axisType: 'angleAxis',\n  polarAxisId: AxisId,\n  isPanorama: boolean,\n) => ReadonlyArray<CartesianTickItem> | undefined = createSelector([selectPolarAxisTicks], ticks => {\n  /*\n   * Angle axis is circular; so here we need to look for ticks that overlap (i.e., 0 and 360 degrees)\n   * and remove the duplicate tick to avoid rendering issues.\n   */\n  if (!ticks) {\n    return undefined;\n  }\n\n  const uniqueTicksMap = new Map<number, CartesianTickItem>();\n  ticks.forEach(tick => {\n    const normalizedCoordinate = (tick.coordinate + 360) % 360;\n    if (!uniqueTicksMap.has(normalizedCoordinate)) {\n      uniqueTicksMap.set(normalizedCoordinate, tick);\n    }\n  });\n\n  return Array.from(uniqueTicksMap.values());\n});\n\nexport const selectPolarGraphicalItemAxisTicks: (\n  state: RechartsRootState,\n  axisType: 'angleAxis' | 'radiusAxis',\n  polarAxisId: AxisId,\n  isPanorama: boolean,\n) => ReadonlyArray<CartesianTickItem> | undefined = createSelector(\n  [\n    selectChartLayout,\n    selectPolarAxis,\n    selectPolarAxisScale,\n    selectPolarAxisRangeWithReversed,\n    selectDuplicateDomain,\n    selectPolarCategoricalDomain,\n    pickAxisType,\n  ],\n  combineGraphicalItemTicks,\n);\n","import { createSelector } from 'reselect';\nimport { RechartsRootState } from '../store';\nimport { AxisId } from '../cartesianAxisSlice';\nimport { selectPolarAxisTicks } from './polarScaleSelectors';\nimport { CartesianTickItem } from '../../util/types';\n\nexport type PolarAngles = Array<number>;\n\nexport type PolarRadius = Array<number>;\n\nconst selectAngleAxisTicks = (state: RechartsRootState, anglexisId: AxisId) =>\n  selectPolarAxisTicks(state, 'angleAxis', anglexisId, false);\n\nexport const selectPolarGridAngles: (state: RechartsRootState, angleAxisId: AxisId) => PolarAngles | undefined =\n  createSelector(\n    [selectAngleAxisTicks],\n    (ticks: ReadonlyArray<CartesianTickItem> | undefined): PolarAngles | undefined => {\n      if (!ticks) {\n        return undefined;\n      }\n\n      return ticks.map(tick => tick.coordinate);\n    },\n  );\n\nconst selectRadiusAxisTicks = (state: RechartsRootState, radiusAxisId: AxisId) =>\n  selectPolarAxisTicks(state, 'radiusAxis', radiusAxisId, false);\n\nexport const selectPolarGridRadii: (state: RechartsRootState, radiusAxisId: AxisId) => PolarRadius | undefined =\n  createSelector(\n    [selectRadiusAxisTicks],\n    (ticks: ReadonlyArray<CartesianTickItem> | undefined): PolarRadius | undefined => {\n      if (!ticks) {\n        return undefined;\n      }\n\n      return ticks.map(tick => tick.coordinate);\n    },\n  );\n","import { clsx } from 'clsx';\nimport * as React from 'react';\nimport { SVGProps } from 'react';\nimport { polarToCartesian } from '../util/PolarUtils';\nimport { AxisId } from '../state/cartesianAxisSlice';\nimport { useAppSelector } from '../state/hooks';\nimport { selectPolarGridAngles, selectPolarGridRadii } from '../state/selectors/polarGridSelectors';\nimport { selectPolarViewBox } from '../state/selectors/polarAxisSelectors';\nimport { PolarViewBoxRequired } from '../util/types';\nimport { svgPropertiesNoEvents } from '../util/svgPropertiesNoEvents';\nimport { ZIndexable, ZIndexLayer } from '../zIndex/ZIndexLayer';\nimport { DefaultZIndexes } from '../zIndex/DefaultZIndexes';\nimport { resolveDefaultProps } from '../util/resolveDefaultProps';\n\ninterface PolarGridProps extends ZIndexable {\n  /**\n   * The x-coordinate of center.\n   * When used inside a chart context, this prop is calculated based on the chart's dimensions,\n   * and this prop is ignored.\n   *\n   * This is only used when rendered outside a chart context.\n   */\n  cx?: number;\n  /**\n   * The y-coordinate of center.\n   * When used inside a chart context, this prop is calculated based on the chart's dimensions,\n   * and this prop is ignored.\n   *\n   * This is only used when rendered outside a chart context.\n   */\n  cy?: number;\n  /**\n   * The radius of the inner polar grid.\n   * When used inside a chart context, this prop is calculated based on the chart's dimensions,\n   * and this prop is ignored.\n   *\n   * This is only used when rendered outside a chart context.\n   */\n  innerRadius?: number;\n  /**\n   * The radius of the outer polar grid.\n   * When used inside a chart context, this prop is calculated based on the chart's dimensions,\n   * and this prop is ignored.\n   *\n   * This is only used when rendered outside a chart context.\n   */\n  outerRadius?: number;\n  /**\n   * The array of every line grid's angle.\n   */\n  polarAngles?: ReadonlyArray<number>;\n  /**\n   * The array of every circle grid's radius.\n   */\n  polarRadius?: ReadonlyArray<number>;\n  /**\n   * The type of polar grids.\n   * @defaultValue polygon\n   */\n  gridType?: 'polygon' | 'circle';\n  /**\n   * @defaultValue true\n   */\n  radialLines?: boolean;\n  /**\n   * @defaultValue 0\n   */\n  angleAxisId?: AxisId;\n  /**\n   * @defaultValue 0\n   */\n  radiusAxisId?: AxisId;\n  /**\n   * Z-Index of this component and its children. The higher the value,\n   * the more on top it will be rendered.\n   * Components with higher zIndex will appear in front of components with lower zIndex.\n   * If undefined or 0, the content is rendered in the default layer without portals.\n   *\n   * @since 3.4\n   * @defaultValue -100\n   * @see {@link https://recharts.github.io/en-US/guide/zIndex/ Z-Index and layers guide}\n   */\n  zIndex?: number;\n  /**\n   * The stroke color. If \"none\", no line will be drawn.\n   * @defaultValue #ccc\n   */\n  stroke?: string;\n  /**\n   * The width of the stroke.\n   * @defaultValue 1\n   */\n  strokeWidth?: number | string;\n  /**\n   * The pattern of dashes and gaps used to paint the lines of the grid.\n   * @see {@link https://developer.mozilla.org/en-US/docs/Web/SVG/Attribute/stroke-dasharray stroke-dasharray on MDN}\n   */\n  strokeDasharray?: string | number;\n  /**\n   * The background color used to fill the space between grid lines.\n   * @defaultValue none\n   */\n  fill?: string;\n  /**\n   * The opacity of the background used to fill the space between grid lines.\n   */\n  fillOpacity?: number | string;\n}\n\nexport type Props = SVGProps<SVGLineElement> & PolarGridProps;\n\ntype PropsWithDefaults = Props & {\n  cx: number;\n  cy: number;\n  innerRadius: number;\n  outerRadius: number;\n  polarAngles: ReadonlyArray<number>;\n  polarRadius: ReadonlyArray<number>;\n};\n\ntype ConcentricProps = PropsWithDefaults & {\n  // The radius of circle\n  radius: number;\n};\n\nconst getPolygonPath = (radius: number, cx: number, cy: number, polarAngles: ReadonlyArray<number>) => {\n  let path = '';\n\n  polarAngles.forEach((angle: number, i: number) => {\n    const point = polarToCartesian(cx, cy, radius, angle);\n\n    if (i) {\n      path += `L ${point.x},${point.y}`;\n    } else {\n      path += `M ${point.x},${point.y}`;\n    }\n  });\n  path += 'Z';\n\n  return path;\n};\n\n// Draw axis of radial line\nconst PolarAngles: React.FC<PropsWithDefaults> = (props: PropsWithDefaults) => {\n  const { cx, cy, innerRadius, outerRadius, polarAngles, radialLines } = props;\n\n  if (!polarAngles || !polarAngles.length || !radialLines) {\n    return null;\n  }\n  const polarAnglesProps = {\n    ...svgPropertiesNoEvents(props),\n  };\n\n  return (\n    <g className=\"recharts-polar-grid-angle\">\n      {polarAngles.map(entry => {\n        const start = polarToCartesian(cx, cy, innerRadius, entry);\n        const end = polarToCartesian(cx, cy, outerRadius, entry);\n\n        return <line key={`line-${entry}`} {...polarAnglesProps} x1={start.x} y1={start.y} x2={end.x} y2={end.y} />;\n      })}\n    </g>\n  );\n};\n\n// Draw concentric circles\nconst ConcentricCircle: React.FC<ConcentricProps> = props => {\n  const { cx, cy, radius } = props;\n  const concentricCircleProps = {\n    ...svgPropertiesNoEvents(props),\n  };\n\n  return (\n    // @ts-expect-error wrong SVG element type\n    <circle\n      {...concentricCircleProps}\n      className={clsx('recharts-polar-grid-concentric-circle', props.className)}\n      cx={cx}\n      cy={cy}\n      r={radius}\n    />\n  );\n};\n\n// Draw concentric polygons\nconst ConcentricPolygon: React.FC<ConcentricProps> = (props: ConcentricProps) => {\n  const { radius } = props;\n  const concentricPolygonProps = {\n    ...svgPropertiesNoEvents(props),\n  };\n\n  return (\n    <path\n      {...concentricPolygonProps}\n      className={clsx('recharts-polar-grid-concentric-polygon', props.className)}\n      d={getPolygonPath(radius, props.cx, props.cy, props.polarAngles)}\n    />\n  );\n};\n\n// Draw concentric axis\nconst ConcentricGridPath = (props: PropsWithDefaults) => {\n  const { polarRadius, gridType } = props;\n\n  if (!polarRadius || !polarRadius.length) {\n    return null;\n  }\n\n  const maxPolarRadius: number = Math.max(...polarRadius);\n  const renderBackground = props.fill && props.fill !== 'none';\n\n  return (\n    <g className=\"recharts-polar-grid-concentric\">\n      {/* Render background as separate first child to do not cover strokes of smaller figures */}\n      {renderBackground && gridType === 'circle' && <ConcentricCircle {...props} radius={maxPolarRadius} />}\n      {renderBackground && gridType !== 'circle' && <ConcentricPolygon {...props} radius={maxPolarRadius} />}\n\n      {polarRadius.map((entry: number, i: number) => {\n        const key = i;\n\n        if (gridType === 'circle') {\n          return <ConcentricCircle key={key} {...props} fill=\"none\" radius={entry} />;\n        }\n\n        return <ConcentricPolygon key={key} {...props} fill=\"none\" radius={entry} />;\n      })}\n    </g>\n  );\n};\n\nexport const defaultPolarGridProps = {\n  angleAxisId: 0,\n  radiusAxisId: 0,\n  gridType: 'polygon',\n  radialLines: true,\n  zIndex: DefaultZIndexes.grid,\n  stroke: '#ccc',\n  strokeWidth: 1,\n  fill: 'none',\n} as const satisfies Partial<Props>;\n\n/**\n * @consumes PolarViewBoxContext\n */\nexport const PolarGrid = (outsideProps: Props) => {\n  const {\n    gridType,\n    radialLines,\n    angleAxisId,\n    radiusAxisId,\n    cx: cxFromOutside,\n    cy: cyFromOutside,\n    innerRadius: innerRadiusFromOutside,\n    outerRadius: outerRadiusFromOutside,\n    polarAngles: polarAnglesInput,\n    polarRadius: polarRadiusInput,\n    zIndex,\n    ...inputs\n  } = resolveDefaultProps(outsideProps, defaultPolarGridProps);\n  const polarViewBox: PolarViewBoxRequired | undefined = useAppSelector(selectPolarViewBox);\n\n  const polarAnglesFromRedux = useAppSelector(state => selectPolarGridAngles(state, angleAxisId));\n  const polarRadiiFromRedux = useAppSelector(state => selectPolarGridRadii(state, radiusAxisId));\n\n  const polarAngles = Array.isArray(polarAnglesInput) ? polarAnglesInput : polarAnglesFromRedux;\n  const polarRadius = Array.isArray(polarRadiusInput) ? polarRadiusInput : polarRadiiFromRedux;\n\n  if (polarAngles == null || polarRadius == null) {\n    return null;\n  }\n\n  const props: PropsWithDefaults = {\n    cx: polarViewBox?.cx ?? cxFromOutside ?? 0,\n    cy: polarViewBox?.cy ?? cyFromOutside ?? 0,\n    innerRadius: polarViewBox?.innerRadius ?? innerRadiusFromOutside ?? 0,\n    outerRadius: polarViewBox?.outerRadius ?? outerRadiusFromOutside ?? 0,\n    polarAngles,\n    polarRadius,\n    zIndex,\n    ...inputs,\n  };\n\n  const { outerRadius } = props;\n\n  if (outerRadius <= 0) {\n    return null;\n  }\n\n  return (\n    <ZIndexLayer zIndex={props.zIndex}>\n      <g className=\"recharts-polar-grid\">\n        <ConcentricGridPath\n          gridType={gridType}\n          radialLines={radialLines}\n          {...props}\n          polarAngles={polarAngles}\n          polarRadius={polarRadius}\n        />\n        <PolarAngles\n          gridType={gridType}\n          radialLines={radialLines}\n          {...props}\n          polarAngles={polarAngles}\n          polarRadius={polarRadius}\n        />\n      </g>\n    </ZIndexLayer>\n  );\n};\n\nPolarGrid.displayName = 'PolarGrid';\n","import { createSlice, PayloadAction } from '@reduxjs/toolkit';\nimport { castDraft } from 'immer';\nimport { AxisId, BaseCartesianAxis, TicksSettings } from './cartesianAxisSlice';\n\nexport type RadiusAxisSettings = BaseCartesianAxis & TicksSettings;\n\nexport type AngleAxisSettings = BaseCartesianAxis & TicksSettings;\n\ntype PolarAxisState = {\n  radiusAxis: Record<AxisId, RadiusAxisSettings>;\n  angleAxis: Record<AxisId, AngleAxisSettings>;\n};\n\nconst initialState: PolarAxisState = {\n  radiusAxis: {},\n  angleAxis: {},\n};\n\nconst polarAxisSlice = createSlice({\n  name: 'polarAxis',\n  initialState,\n  reducers: {\n    addRadiusAxis(state, action: PayloadAction<RadiusAxisSettings>) {\n      state.radiusAxis[action.payload.id] = castDraft(action.payload);\n    },\n    removeRadiusAxis(state, action: PayloadAction<RadiusAxisSettings>) {\n      delete state.radiusAxis[action.payload.id];\n    },\n    addAngleAxis(state, action: PayloadAction<AngleAxisSettings>) {\n      state.angleAxis[action.payload.id] = castDraft(action.payload);\n    },\n    removeAngleAxis(state, action: PayloadAction<AngleAxisSettings>) {\n      delete state.angleAxis[action.payload.id];\n    },\n  },\n});\n\nexport const { addRadiusAxis, removeRadiusAxis, addAngleAxis, removeAngleAxis } = polarAxisSlice.actions;\n\nexport const polarAxisReducer = polarAxisSlice.reducer;\n","export function getClassNameFromUnknown(u: unknown): string {\n  if (u && typeof u === 'object' && 'className' in u && typeof u.className === 'string') {\n    return u.className;\n  }\n  return '';\n}\n","import * as React from 'react';\nimport { FunctionComponent, ReactElement, ReactNode, SVGProps, useEffect, useMemo } from 'react';\nimport maxBy from 'es-toolkit/compat/maxBy';\nimport minBy from 'es-toolkit/compat/minBy';\n\nimport { clsx } from 'clsx';\nimport { Text } from '../component/Text';\nimport { PolarLabelContextProvider, PolarLabelFromLabelProp } from '../component/Label';\nimport { Layer } from '../container/Layer';\nimport { polarToCartesian } from '../util/PolarUtils';\nimport {\n  adaptEventsOfChild,\n  RenderableAxisProps,\n  Coordinate,\n  PolarViewBoxRequired,\n  PresentationAttributesAdaptChildEvent,\n  TickItem,\n  AxisDomain,\n  ScaleType,\n  AxisDomainTypeInput,\n  EvaluatedAxisDomainType,\n  TickProp,\n  BaseTickContentProps,\n  AxisTick,\n} from '../util/types';\nimport { addRadiusAxis, RadiusAxisSettings, removeRadiusAxis } from '../state/polarAxisSlice';\nimport { NiceTicksAlgorithm } from '../state/cartesianAxisSlice';\nimport { useAppDispatch, useAppSelector } from '../state/hooks';\nimport { selectPolarAxisScale, selectPolarAxisTicks } from '../state/selectors/polarScaleSelectors';\nimport { selectPolarViewBox } from '../state/selectors/polarAxisSelectors';\nimport { defaultPolarRadiusAxisProps } from './defaultPolarRadiusAxisProps';\nimport { svgPropertiesNoEvents, svgPropertiesNoEventsFromUnknown } from '../util/svgPropertiesNoEvents';\nimport { RequiresDefaultProps, resolveDefaultProps } from '../util/resolveDefaultProps';\nimport { ZIndexable, ZIndexLayer } from '../zIndex/ZIndexLayer';\nimport { RechartsScale } from '../util/scale/RechartsScale';\nimport { CustomScaleDefinition } from '../util/scale/CustomScaleDefinition';\nimport { usePolarChartLayout } from '../context/chartLayoutContext';\nimport { noop } from '../util/DataUtils';\nimport { getAxisTypeBasedOnLayout } from '../util/getAxisTypeBasedOnLayout';\nimport { getClassNameFromUnknown } from '../util/getClassNameFromUnknown';\n\ntype TickOrientation = 'left' | 'right' | 'middle';\n\nexport interface PolarRadiusAxisProps<DataPointType = any, DataValueType = any>\n  extends\n    Omit<\n      RenderableAxisProps<DataPointType, DataValueType>,\n      'axisLine' | 'angle' | 'type' | 'tickSize' | 'domain' | 'scale' | 'tick'\n    >,\n    ZIndexable {\n  /**\n   * Determines how the axis line is drawn. Options:\n   * - `true`: the axis line is drawn with default props;\n   * - `false`: the axis line is not visible;\n   * - `object`: passed as props to SVG `<line>` element representing the axis line.\n   *\n   * @example <PolarRadiusAxis axisLine={false} />\n   * @example <PolarRadiusAxis axisLine={{ stroke: 'red', strokeWidth: 2 }} />\n   * @defaultValue true\n   */\n  axisLine?: boolean | SVGProps<SVGLineElement>;\n  /**\n   * The angle of the whole axis: the line, ticks and labels, everything.\n   *\n   * This is different from other graphical elements where angle usually means\n   * the angle of text. Here, it means the angle of everything.\n   *\n   * @defaultValue 0\n   */\n  angle?: number;\n  /**\n   * The type of axis.\n   *\n   * `category`: Treats data as distinct values.\n   * Each value is in the same distance from its neighbors, regardless of their actual numeric difference.\n   *\n   * `number`: Treats data as continuous range.\n   * Values that are numerically closer are placed closer together on the axis.\n   *\n   * `auto`: the type is inferred based on the chart layout.\n   *\n   * @defaultValue auto\n   */\n  type?: AxisDomainTypeInput;\n  /**\n   * The orientation of axis text.\n   * @defaultValue right\n   */\n  orientation?: TickOrientation;\n  /**\n   * Specify the domain of axis when the axis is a number axis.\n   *\n   * If undefined, then the domain is calculated based on the data and dataKeys.\n   *\n   * The length of domain should be 2, and we will validate the values in domain.\n   *\n   * Each element in the array can be a number, 'auto', 'dataMin', 'dataMax', a string like 'dataMin - 20', 'dataMax + 100',\n   * or a function that accepts a single argument and returns a number.\n   *\n   * If any element of domain is set to be 'auto', comprehensible scale ticks will be calculated, and the final domain of axis is generated by the ticks.\n   * If a function, receives '[dataMin, dataMax]', and must return a computed domain as '[min, max]'.\n   *\n   * @example <PolarRadiusAxis type=\"number\" domain={['dataMin', 'dataMax']} />\n   * @example <PolarRadiusAxis type=\"number\" domain={[0, 'dataMax']} />\n   * @example <PolarRadiusAxis type=\"number\" domain={['auto', 'auto']} />\n   * @example <PolarRadiusAxis type=\"number\" domain={[0, 'dataMax + 1000']} />\n   * @example <PolarRadiusAxis type=\"number\" domain={['dataMin - 100', 'dataMax + 100']} />\n   * @example <PolarRadiusAxis type=\"number\" domain={[dataMin => (0 - Math.abs(dataMin)), dataMax => (dataMax * 2)]} />\n   * @example <PolarRadiusAxis type=\"number\" domain={([dataMin, dataMax]) => { const absMax = Math.max(Math.abs(dataMin), Math.abs(dataMax)); return [-absMax, absMax]; }} />\n   * @example <PolarRadiusAxis type=\"number\" domain={[0, 100]} allowDataOverflow />\n   */\n  domain?: AxisDomain;\n  /**\n   * Scale function determines how data values are mapped to visual values.\n   * In other words, decided the mapping between data domain and coordinate range.\n   *\n   * If undefined, or 'auto', the scale function is created internally according to the type of axis and data.\n   *\n   * You can define a custom scale, either as a string shortcut to a d3 scale, or as a complete scale definition object.\n   *\n   * @defaultValue auto\n   * @example <PolarRadiusAxis scale=\"log\" />\n   * @example\n   * import { scaleLog } from 'd3-scale';\n   * const scale = scaleLog().base(Math.E);\n   * <PolarRadiusAxis scale={scale} />\n   */\n  scale?:\n    | ScaleType\n    | CustomScaleDefinition\n    | CustomScaleDefinition<string>\n    | CustomScaleDefinition<number>\n    | CustomScaleDefinition<Date>;\n  /**\n   * The customized event handler of click on the ticks of this axis\n   */\n  onClick?: (data: any, index: num