n  /**\n   * The formatter function of ticks.\n   */\n  tickFormatter?: (value: any, index: number) => string;\n  /**\n   * The length of tick line.\n   * @defaultValue 8\n   */\n  tickSize?: number;\n  /**\n   * The array of every tick's value and angle.\n   */\n  ticks?: ReadonlyArray<TickItem>;\n  /**\n   * The type of axis.\n   *\n   * `category`: Treats data as distinct values.\n   * Each value is in the same distance from its neighbors, regardless of their actual numeric difference.\n   *\n   * `number`: Treats data as continuous range.\n   * Values that are numerically closer are placed closer together on the axis.\n   *\n   * `auto`: the type is inferred based on the chart layout.\n   *\n   * @defaultValue auto\n   */\n  type?: AxisDomainTypeInput;\n  /**\n   * Z-Index of this component and its children. The higher the value,\n   * the more on top it will be rendered.\n   * Components with higher zIndex will appear in front of components with lower zIndex.\n   * If undefined or 0, the content is rendered in the default layer without portals.\n   *\n   * @since 3.4\n   * @defaultValue 500\n   * @see {@link https://recharts.github.io/en-US/guide/zIndex/ Z-Index and layers guide}\n   */\n  zIndex?: number;\n}\n\ntype PolarAngleAxisEvents = {\n  /**\n   * The customized event handler of click on the ticks of this axis\n   */\n  onClick?: (data: TickItem, index: number, e: React.MouseEvent<SVGTextElement>) => void;\n  /**\n   * The customized event handler of mousedown on the ticks of this axis\n   */\n  onMouseDown?: (data: TickItem, index: number, e: React.MouseEvent<SVGTextElement>) => void;\n  /**\n   * The customized event handler of mouseup on the ticks of this axis\n   */\n  onMouseUp?: (data: TickItem, index: number, e: React.MouseEvent<SVGTextElement>) => void;\n  /**\n   * The customized event handler of mousemove on the ticks of this axis\n   */\n  onMouseMove?: (data: TickItem, index: number, e: React.MouseEvent<SVGTextElement>) => void;\n  /**\n   * The customized event handler of mouseover on the ticks of this axis\n   */\n  onMouseOver?: (data: TickItem, index: number, e: React.MouseEvent<SVGTextElement>) => void;\n  /**\n   * The customized event handler of mouseout on the ticks of this axis\n   */\n  onMouseOut?: (data: TickItem, index: number, e: React.MouseEvent<SVGTextElement>) => void;\n  /**\n   * The customized event handler of mouseenter on the ticks of this axis\n   */\n  onMouseEnter?: (data: TickItem, index: number, e: React.MouseEvent<SVGTextElement>) => void;\n  /**\n   * The customized event handler of mouseleave on the ticks of this axis\n   */\n  onMouseLeave?: (data: TickItem, index: number, e: React.MouseEvent<SVGTextElement>) => void;\n  onTouchStart?: (data: TickItem, index: number, e: React.TouchEvent<SVGTextElement>) => void;\n  onTouchMove?: (data: TickItem, index: number, e: React.TouchEvent<SVGTextElement>) => void;\n  onTouchEnd?: (data: TickItem, index: number, e: React.TouchEvent<SVGTextElement>) => void;\n};\n\ntype AxisSvgProps = Omit<\n  PresentationAttributesAdaptChildEvent<TickItem, SVGTextElement>,\n  'scale' | 'type' | 'dangerouslySetInnerHTML'\n>;\n\nexport type Props<DataPointType = any, DataValueType = any> = AxisSvgProps &\n  PolarAngleAxisProps<DataPointType, DataValueType>;\n\ntype PropsWithDefaults<DataPointType = any, DataValueType = any> = RequiresDefaultProps<\n  Props<DataPointType, DataValueType>,\n  typeof defaultPolarAngleAxisProps\n>;\n\ntype InternalPolarAngleAxisProps = Omit<PropsWithDefaults, 'scale'> & {\n  cx: number;\n  cy: number;\n  radius: number;\n  ticks: ReadonlyArray<TickItem>;\n  scale: RechartsScale;\n} & PolarAngleAxisEvents;\n\nconst AXIS_TYPE = 'angleAxis';\n\ntype AngleAxisSettingsReporter = Omit<AngleAxisSettings, 'type'> & {\n  children: ReactNode;\n  type: AxisDomainTypeInput;\n};\n\nfunction SetAngleAxisSettings(props: AngleAxisSettingsReporter): ReactNode {\n  const dispatch = useAppDispatch();\n  const layout = usePolarChartLayout();\n  const settings: AngleAxisSettings | undefined = useMemo(() => {\n    const { children, type: typeFromProps, ...rest } = props;\n    const evaluatedType: EvaluatedAxisDomainType | undefined = getAxisTypeBasedOnLayout(\n      layout,\n      'angleAxis',\n      typeFromProps,\n    );\n    if (evaluatedType == null) {\n      return undefined;\n    }\n    return { ...rest, type: evaluatedType };\n  }, [props, layout]);\n  const synchronizedSettings = useAppSelector(state => selectAngleAxis(state, settings?.id));\n  const settingsAreSynchronized = settings === synchronizedSettings;\n  useEffect(() => {\n    if (settings == null) {\n      return noop;\n    }\n    dispatch(addAngleAxis(settings));\n    return () => {\n      dispatch(removeAngleAxis(settings));\n    };\n  }, [dispatch, settings]);\n\n  if (settingsAreSynchronized) {\n    return props.children;\n  }\n  return null;\n}\n\n/**\n * Calculate the coordinate of line endpoint\n * @param data The data if there are ticks\n * @param props axis settings\n * @return (x1, y1): The point close to text,\n *         (x2, y2): The point close to axis\n */\nconst getTickLineCoord = (\n  data: TickItem,\n  props: InternalPolarAngleAxisProps,\n): {\n  x1: number;\n  y1: number;\n  x2: number;\n  y2: number;\n} => {\n  const { cx, cy, radius, orientation, tickSize } = props;\n  const tickLineSize = tickSize || 8;\n  const p1 = polarToCartesian(cx, cy, radius, data.coordinate);\n  const p2 = polarToCartesian(cx, cy, radius + (orientation === 'inner' ? -1 : 1) * tickLineSize, data.coordinate);\n\n  return { x1: p1.x, y1: p1.y, x2: p2.x, y2: p2.y };\n};\n\n/**\n * Get the text-anchor of each tick\n * @param data Data of ticks\n * @param orientation of the axis ticks\n * @return text-anchor\n */\nconst getTickTextAnchor = (data: TickItem, orientation: Props['orientation']): TextAnchor => {\n  const cos = Math.cos(degreeToRadian(-data.coordinate));\n\n  if (cos > eps) {\n    return orientation === 'outer' ? 'start' : 'end';\n  }\n  if (cos < -eps) {\n    return orientation === 'outer' ? 'end' : 'start';\n  }\n  return 'middle';\n};\n\n/**\n * Get the text vertical anchor of each tick\n * @param data Data of a tick\n * @return text vertical anchor\n */\nconst getTickTextVerticalAnchor = (data: TickItem): TextVerticalAnchor => {\n  const cos = Math.cos(degreeToRadian(-data.coordinate));\n  const sin = Math.sin(degreeToRadian(-data.coordinate));\n\n  // handle top and bottom sectors: 90±45deg and 270±45deg\n  if (Math.abs(cos) <= COS_45) {\n    // sin > 0: top sector, sin < 0: bottom sector\n    return sin > 0 ? 'start' : 'end';\n  }\n\n  return 'middle';\n};\n\nconst AxisLine = (props: InternalPolarAngleAxisProps) => {\n  const { cx, cy, radius, axisLineType, axisLine, ticks } = props;\n  if (!axisLine) {\n    return null;\n  }\n  const axisLineProps = {\n    ...svgPropertiesNoEvents(props),\n    fill: 'none',\n    ...svgPropertiesNoEvents(axisLine),\n  };\n\n  if (axisLineType === 'circle') {\n    // @ts-expect-error wrong SVG element type\n    return <Dot className=\"recharts-polar-angle-axis-line\" {...axisLineProps} cx={cx} cy={cy} r={radius} />;\n  }\n  const points = ticks.map(entry => polarToCartesian(cx, cy, radius, entry.coordinate));\n\n  // @ts-expect-error wrong SVG element type\n  return <Polygon className=\"recharts-polar-angle-axis-line\" {...axisLineProps} points={points} />;\n};\n\ntype TickItemProps = {\n  tick: TickProp<BaseTickContentProps>;\n  tickProps: BaseTickContentProps;\n  value: string | number;\n};\n\nconst TickItemText = ({ tick, tickProps, value }: TickItemProps): ReactNode => {\n  if (!tick) {\n    return null;\n  }\n  if (React.isValidElement(tick)) {\n    return React.cloneElement(tick, tickProps);\n  }\n  if (typeof tick === 'function') {\n    return tick(tickProps);\n  }\n  return (\n    <Text {...tickProps} className=\"recharts-polar-angle-axis-tick-value\">\n      {value}\n    </Text>\n  );\n};\n\nconst Ticks = (props: InternalPolarAngleAxisProps) => {\n  const { tick, tickLine, tickFormatter, stroke, ticks } = props;\n  const { ref, ...axisProps } = svgPropertiesNoEvents(props);\n  const customTickProps = svgPropertiesNoEventsFromUnknown(tick);\n  const tickLineProps = {\n    ...axisProps,\n    fill: 'none',\n    ...svgPropertiesNoEvents(tickLine),\n  };\n\n  const items = ticks.map((entry, i) => {\n    const lineCoord = getTickLineCoord(entry, props);\n    const textAnchor: TextAnchor = getTickTextAnchor(entry, props.orientation);\n    const verticalAnchor: TextVerticalAnchor = getTickTextVerticalAnchor(entry);\n    const tickProps: BaseTickContentProps = {\n      ...axisProps,\n      // @ts-expect-error customTickProps is contributing unknown props\n      textAnchor,\n      verticalAnchor,\n      // @ts-expect-error customTickProps is contributing unknown props\n      stroke: 'none',\n      // @ts-expect-error customTickProps is contributing unknown props\n      fill: stroke,\n      ...customTickProps,\n      index: i,\n      payload: entry,\n      x: lineCoord.x2,\n      y: lineCoord.y2,\n    };\n\n    return (\n      <Layer\n        className={clsx('recharts-polar-angle-axis-tick', getClassNameFromUnknown(tick))}\n        key={`tick-${entry.coordinate}`}\n        {...adaptEventsOfChild(props, entry, i)}\n      >\n        {tickLine && <line className=\"recharts-polar-angle-axis-tick-line\" {...tickLineProps} {...lineCoord} />}\n        <TickItemText\n          tick={tick}\n          tickProps={tickProps}\n          value={tickFormatter ? tickFormatter(entry.value, i) : entry.value}\n        />\n      </Layer>\n    );\n  });\n\n  return <Layer className=\"recharts-polar-angle-axis-ticks\">{items}</Layer>;\n};\n\nexport const PolarAngleAxisWrapper: FunctionComponent<PropsWithDefaults> = (defaultsAndInputs: PropsWithDefaults) => {\n  const { angleAxisId } = defaultsAndInputs;\n\n  const viewBox = useAppSelector(selectPolarViewBox);\n  const scale = useAppSelector(state => selectPolarAxisScale(state, 'angleAxis', angleAxisId));\n  const isPanorama = useIsPanorama();\n  const ticks = useAppSelector(state => selectPolarAngleAxisTicks(state, 'angleAxis', angleAxisId, isPanorama));\n\n  if (viewBox == null || !ticks || !ticks.length || scale == null) {\n    return null;\n  }\n\n  const props: InternalPolarAngleAxisProps = {\n    ...defaultsAndInputs,\n    scale,\n    ...viewBox,\n    radius: viewBox.outerRadius,\n    ticks,\n  };\n\n  return (\n    <ZIndexLayer zIndex={props.zIndex}>\n      <Layer className={clsx('recharts-polar-angle-axis', AXIS_TYPE, props.className)}>\n        <AxisLine {...props} />\n        <Ticks {...props} />\n      </Layer>\n    </ZIndexLayer>\n  );\n};\n\n/**\n * @provides PolarLabelContext\n * @consumes PolarViewBoxContext\n */\nexport function PolarAngleAxis<DataPointType = any, DataValueType = any>(\n  outsideProps: Props<DataPointType, DataValueType>,\n): React.ReactNode {\n  const props: PropsWithDefaults<DataPointType, DataValueType> = resolveDefaultProps(\n    outsideProps,\n    defaultPolarAngleAxisProps,\n  );\n\n  return (\n    <SetAngleAxisSettings\n      id={props.angleAxisId}\n      scale={props.scale}\n      type={props.type}\n      dataKey={props.dataKey}\n      unit={undefined}\n      name={props.name}\n      allowDuplicatedCategory={false} // Ignoring the prop on purpose because axis calculation behaves as if it was false and Tooltip requires it to be true.\n      allowDataOverflow={false}\n      reversed={props.reversed}\n      includeHidden={false}\n      allowDecimals={props.allowDecimals}\n      tickCount={props.tickCount}\n      niceTicks={props.niceTicks ?? 'auto'}\n      // @ts-expect-error the type does not match. Is RadiusAxis really expecting what it says?\n      ticks={props.ticks}\n      tick={props.tick}\n      domain={props.domain}\n    >\n      <PolarAngleAxisWrapper {...props} />\n    </SetAngleAxisSettings>\n  );\n}\n\nPolarAngleAxis.displayName = 'PolarAngleAxis';\n","import { createSelector } from 'reselect';\nimport { ReactElement } from 'react';\nimport { CellProps } from '../..';\nimport { computePieSectors, PieSectorDataItem } from '../../polar/Pie';\nimport { RechartsRootState } from '../store';\nimport { selectChartDataAndAlwaysIgnoreIndexes } from './dataSelectors';\nimport { ChartData, ChartDataState } from '../chartDataSlice';\nimport { ChartOffsetInternal } from '../../util/types';\nimport { selectChartOffsetInternal } from './selectChartOffsetInternal';\nimport type { LegendPayload } from '../../component/DefaultLegendContent';\nimport { getTooltipNameProp, getValueByDataKey } from '../../util/ChartUtils';\nimport { selectUnfilteredPolarItems } from './polarSelectors';\nimport { PieSettings } from '../types/PieSettings';\nimport { GraphicalItemId } from '../graphicalItemsSlice';\n\nconst pickId = (_state: RechartsRootState, id: GraphicalItemId): GraphicalItemId => id;\n\nconst selectSynchronisedPieSettings: (state: RechartsRootState, id: GraphicalItemId) => PieSettings | undefined =\n  createSelector([selectUnfilteredPolarItems, pickId], (graphicalItems, id) =>\n    graphicalItems.filter(item => item.type === 'pie').find(item => item.id === id),\n  );\n\n// Keep stable reference to an empty array to prevent re-renders\nconst emptyArray: ReadonlyArray<ReactElement> = [];\nconst pickCells = (\n  _state: RechartsRootState,\n  _id: GraphicalItemId,\n  cells: ReadonlyArray<ReactElement> | undefined,\n): ReadonlyArray<ReactElement> | undefined => {\n  if (cells?.length === 0) {\n    return emptyArray;\n  }\n  return cells;\n};\n\nexport const selectDisplayedData: (\n  state: RechartsRootState,\n  id: GraphicalItemId,\n  cells: ReadonlyArray<ReactElement> | undefined,\n) => ChartData | undefined = createSelector(\n  [selectChartDataAndAlwaysIgnoreIndexes, selectSynchronisedPieSettings, pickCells],\n  ({ chartData }: ChartDataState, pieSettings: PieSettings | undefined, cells): ChartData | undefined => {\n    if (pieSettings == null) {\n      return undefined;\n    }\n    let displayedData: ChartData | undefined;\n    if (pieSettings?.data != null && pieSettings.data.length > 0) {\n      displayedData = pieSettings.data;\n    } else {\n      displayedData = chartData;\n    }\n\n    if ((!displayedData || !displayedData.length) && cells != null) {\n      displayedData = cells.map((cell: ReactElement<CellProps>) => ({\n        ...pieSettings.presentationProps,\n        ...cell.props,\n      }));\n    }\n\n    if (displayedData == null) {\n      return undefined;\n    }\n\n    return displayedData;\n  },\n);\n\nexport const selectPieLegend: (\n  state: RechartsRootState,\n  id: GraphicalItemId,\n  cells: ReadonlyArray<ReactElement> | undefined,\n) => ReadonlyArray<LegendPayload> | undefined = createSelector(\n  [selectDisplayedData, selectSynchronisedPieSettings, pickCells],\n  (\n    displayedData: ChartData | undefined,\n    pieSettings: PieSettings | undefined,\n    cells: ReadonlyArray<ReactElement> | undefined,\n  ): ReadonlyArray<LegendPayload> | undefined => {\n    if (displayedData == null || pieSettings == null) {\n      return undefined;\n    }\n    return displayedData.map((entry, i): LegendPayload => {\n      const name = getValueByDataKey(entry, pieSettings.nameKey, pieSettings.name);\n      let color;\n      if (cells?.[i]?.props?.fill) {\n        color = cells[i].props.fill;\n      } else if (typeof entry === 'object' && entry != null && 'fill' in entry) {\n        color = entry.fill;\n      } else {\n        color = pieSettings.fill;\n      }\n      return {\n        value: getTooltipNameProp(name, pieSettings.dataKey),\n        color,\n        // @ts-expect-error Legend payload.payload says it wants objects but our data can be unknown\n        payload: entry,\n        type: pieSettings.legendType,\n      };\n    });\n  },\n);\n\nexport const selectPieSectors: (\n  state: RechartsRootState,\n  id: GraphicalItemId,\n  cells: ReadonlyArray<ReactElement> | undefined,\n) => ReadonlyArray<PieSectorDataItem> | undefined = createSelector(\n  [selectDisplayedData, selectSynchronisedPieSettings, pickCells, selectChartOffsetInternal],\n  (\n    displayedData: ChartData | undefined,\n    pieSettings: PieSettings | undefined,\n    cells,\n    offset: ChartOffsetInternal,\n  ): ReadonlyArray<PieSectorDataItem> | undefined => {\n    if (pieSettings == null || displayedData == null) {\n      return undefined;\n    }\n    return computePieSectors({\n      offset,\n      pieSettings,\n      displayedData,\n      cells,\n    });\n  },\n);\n","import * as React from 'react';\nimport { MutableRefObject, ReactElement, ReactNode, SVGProps, useCallback, useMemo, useRef, useState } from 'react';\nimport get from 'es-toolkit/compat/get';\n\nimport { clsx } from 'clsx';\nimport { selectPieLegend, selectPieSectors } from '../state/selectors/pieSelectors';\nimport { useAppSelector } from '../state/hooks';\nimport { Layer } from '../container/Layer';\nimport { Curve, Props as CurveProps } from '../shape/Curve';\nimport { Text } from '../component/Text';\nimport { Cell } from '../component/Cell';\nimport { findAllByType } from '../util/ReactUtils';\nimport { getMaxRadius, polarToCartesian } from '../util/PolarUtils';\nimport { getPercentValue, interpolate, isNumber, mathSign } from '../util/DataUtils';\nimport { getTooltipNameProp, getValueByDataKey } from '../util/ChartUtils';\nimport {\n  ActiveShape,\n  adaptEventsOfChild,\n  AnimationDuration,\n  AnimationTiming,\n  ChartOffsetInternal,\n  Coordinate,\n  DataConsumer,\n  DataKey,\n  DataProvider,\n  GeometrySector,\n  LegendType,\n  PresentationAttributesAdaptChildEvent,\n  TooltipType,\n} from '../util/types';\nimport { Shape } from '../util/ActiveShapeUtils';\nimport {\n  TooltipTriggerInfo,\n  useMouseClickItemDispatch,\n  useMouseEnterItemDispatch,\n  useMouseLeaveItemDispatch,\n} from '../context/tooltipContext';\nimport { TooltipPayload, TooltipPayloadConfiguration } from '../state/tooltipSlice';\nimport { SetTooltipEntrySettings } from '../state/SetTooltipEntrySettings';\nimport {\n  selectActiveTooltipDataKey,\n  selectActiveTooltipGraphicalItemId,\n  selectActiveTooltipIndex,\n} from '../state/selectors/tooltipSelectors';\nimport { SetPolarLegendPayload } from '../state/SetLegendPayload';\nimport { DATA_ITEM_GRAPHICAL_ITEM_ID_ATTRIBUTE_NAME, DATA_ITEM_INDEX_ATTRIBUTE_NAME } from '../util/Constants';\nimport { useAnimationId } from '../util/useAnimationId';\nimport { RequiresDefaultProps, resolveDefaultProps } from '../util/resolveDefaultProps';\nimport { RegisterGraphicalItemId } from '../context/RegisterGraphicalItemId';\nimport { SetPolarGraphicalItem } from '../state/SetGraphicalItem';\nimport { PiePresentationProps, PieSettings } from '../state/types/PieSettings';\nimport {\n  svgPropertiesNoEvents,\n  svgPropertiesNoEventsFromUnknown,\n  SVGPropsNoEvents,\n} from '../util/svgPropertiesNoEvents';\nimport { JavascriptAnimate } from '../animation/JavascriptAnimate';\nimport {\n  LabelListFromLabelProp,\n  PolarLabelListContextProvider,\n  PolarLabelListEntry,\n  Props as LabelListProps,\n} from '../component/LabelList';\nimport { GraphicalItemId } from '../state/graphicalItemsSlice';\nimport { ZIndexable, ZIndexLayer } from '../zIndex/ZIndexLayer';\nimport { DefaultZIndexes } from '../zIndex/DefaultZIndexes';\nimport { ChartData } from '../state/chartDataSlice';\nimport { getClassNameFromUnknown } from '../util/getClassNameFromUnknown';\n\ninterface PieDef {\n  /**\n   * The x-coordinate of center. If set a percentage, the final value is obtained by multiplying the percentage of container width.\n   */\n  cx?: number | string;\n  /**\n   * The y-coordinate of center. If set a percentage, the final value is obtained by multiplying the percentage of container height.\n   */\n  cy?: number | string;\n  /**\n   * Angle in degrees from which the chart should start.\n   */\n  startAngle?: number;\n  /**\n   * Angle, in degrees, at which the chart should end.\n   */\n  endAngle?: number;\n  /**\n   * The angle between two sectors.\n   *\n   * @example <Pie paddingAngle={5} />\n   * @example https://recharts.github.io/examples/PieChartWithPaddingAngle\n   */\n  paddingAngle?: number;\n  /**\n   * The inner radius of the sectors.\n   * If set a percentage, the final value is obtained by multiplying the percentage of maxRadius which is calculated by the width, height, cx, cy.\n   */\n  innerRadius?: number | string;\n  /**\n   * The outer radius of the sectors.\n   * If set a percentage, the final value is obtained by multiplying the percentage of maxRadius which is calculated by the width, height, cx, cy.\n   * Function should return a string percentage or number.\n   */\n  outerRadius?: number | string | ((dataPoint: any) => number | string);\n  cornerRadius?: number | string;\n}\n\ntype PieLabelLine =\n  | ReactElement<SVGElement>\n  | ((props: any) => ReactElement<SVGElement>)\n  | SVGProps<SVGPathElement>\n  | boolean;\n\ninterface PieLabelExtraProps {\n  stroke: string;\n  index: number;\n  textAnchor: string;\n}\n\nexport type PieLabelRenderProps = Omit<SVGPropsNoEvents<PieSvgAttributes>, 'offset'> &\n  Omit<PieSectorDataItem, 'offset'> &\n  PieLabelExtraProps &\n  Coordinate;\n\nexport type LabelListPropsWithPosition = LabelListProps & { position: LabelListProps['position'] };\n\n/**\n * The `label` prop in Pie accepts a variety of alternatives.\n */\nexport type PieLabel =\n  /*\n   * If label prop is false, labels don't show.\n   * If label prop is true, labels will be rendered with default props.\n   */\n  | boolean\n  /*\n   * If label prop is an object, and it contains a `position` prop,\n   * the object will become props to a <LabelList /> component.\n   */\n  | LabelListPropsWithPosition\n  /*\n   * If label prop is an object, and it does not have a `position` prop,\n   * this renders a special Pie label that is similar to <Label position=\"outside\"> and supports an optional labelLine.\n   * labelLine is a small line connecting the sector to the label.\n   */\n  | Partial<PieLabelRenderProps>\n  /*\n   * If label prop is a function, or a React component, it will be called once for each label.\n   * The result of each call will be rendered.\n   */\n  | ((props: PieLabelRenderProps) => ReactNode | ReactElement<SVGElement>)\n  /*\n   * If label prop is a ReactElement, it will get cloned and receive brand-new surprise props.\n   * I do not recommend this variant\n   */\n  | ReactElement<SVGElement>;\n\nexport type PieSectorData = GeometrySector &\n  TooltipTriggerInfo & {\n    dataKey?: DataKey<any>;\n    midAngle?: number;\n    middleRadius?: number;\n    name?: string | number;\n    paddingAngle?: number;\n    payload?: any;\n    percent?: number;\n    value: number;\n  };\n\n/**\n * We spread the data object into the sector data item,\n * so we can't really know what is going to be inside.\n *\n * This type represents our best effort, but it all depends on the input data\n * and what is inside of it.\n *\n * https://github.com/recharts/recharts/issues/6380\n * https://github.com/recharts/recharts/discussions/6375\n */\nexport type PieSectorDataItem = PiePresentationProps &\n  PieCoordinate &\n  PieSectorData & {\n    cornerRadius: number | undefined;\n  };\n\nexport type PieSectorShapeProps = PieSectorDataItem & { isActive: boolean; index: number };\nexport type PieShape = ReactNode | ((props: PieSectorShapeProps, index: number) => React.ReactElement);\n\ninterface PieEvents {\n  /**\n   * The customized event handler of click on the sectors in this group.\n   */\n  onClick?: (data: PieSectorDataItem, index: number, e: React.MouseEvent<SVGGraphicsElement>) => void;\n  /**\n   * The customized event handler of mousedown on the sectors in this group.\n   */\n  onMouseDown?: (data: PieSectorDataItem, index: number, e: React.MouseEvent<SVGGraphicsElement>) => void;\n  /**\n   * The customized event handler of mouseup on the sectors in this group.\n   */\n  onMouseUp?: (data: PieSectorDataItem, index: number, e: React.MouseEvent<SVGGraphicsElement>) => void;\n  /**\n   * The customized event handler of mousemove on the sectors in this group.\n   */\n  onMouseMove?: (data: PieSectorDataItem, index: number, e: React.MouseEvent<SVGGraphicsElement>) => void;\n  /**\n   * The customized event handler of mouseover on the sectors in this group.\n   */\n  onMouseOver?: (data: PieSectorDataItem, index: number, e: React.MouseEvent<SVGGraphicsElement>) => void;\n  /**\n   * The customized event handler of mouseout on the sectors in this group.\n   */\n  onMouseOut?: (data: PieSectorDataItem, index: number, e: React.MouseEvent<SVGGraphicsElement>) => void;\n  /**\n   * The customized event handler of mouseenter on the sectors in this group.\n   */\n  onMouseEnter?: (data: PieSectorDataItem, index: number, e: React.MouseEvent<SVGGraphicsElement>) => void;\n  /**\n   * The customized event handler of mouseleave on the sectors in this group.\n   */\n  onMouseLeave?: (data: PieSectorDataItem, index: number, e: React.MouseEvent<SVGGraphicsElement>) => void;\n  onTouchStart?: (data: PieSectorDataItem, index: number, e: React.TouchEvent<SVGGraphicsElement>) => void;\n  onTouchMove?: (data: PieSectorDataItem, index: number, e: React.TouchEvent<SVGGraphicsElement>) => void;\n  onTouchEnd?: (data: PieSectorDataItem, index: number, e: React.TouchEvent<SVGGraphicsElement>) => void;\n}\n\n/**\n * Internal props, combination of external props + defaultProps + private Recharts state\n */\ninterface InternalPieProps<DataPointType = unknown> extends DataProvider<DataPointType>, PieDef, ZIndexable, PieEvents {\n  id: GraphicalItemId;\n  className?: string;\n  // We actually spread the whole PieSectorDataItem into the keys.\n  dataKey: DataKey<DataPointType, unknown>;\n  // We actually spread the whole PieSectorDataItem into the keys.\n  nameKey?: DataKey<DataPointType, string>;\n  /** The minimum angle for no-zero element */\n  minAngle?: number;\n  legendType?: LegendType;\n  tooltipType?: TooltipType;\n  /** the max radius