nst sectors = useAppSelector(state => selectPieSectors(state, id, cells));\n\n  const previousSectorsRef = useRef<ReadonlyArray<PieSectorDataItem> | null>(null);\n\n  const layerClass = clsx('recharts-pie', className);\n\n  if (hide || sectors == null) {\n    previousSectorsRef.current = null;\n    return <Layer tabIndex={rootTabIndex} className={layerClass} />;\n  }\n\n  return (\n    <ZIndexLayer zIndex={props.zIndex}>\n      <SetPieTooltipEntrySettings\n        dataKey={props.dataKey}\n        nameKey={props.nameKey}\n        sectors={sectors}\n        stroke={props.stroke}\n        strokeWidth={props.strokeWidth}\n        fill={props.fill}\n        name={props.name}\n        hide={props.hide}\n        tooltipType={props.tooltipType}\n        id={id}\n        activeShape={props.activeShape}\n      />\n      <Layer tabIndex={rootTabIndex} className={layerClass}>\n        <SectorsWithAnimation props={{ ...propsWithoutId, sectors }} previousSectorsRef={previousSectorsRef} id={id} />\n      </Layer>\n    </ZIndexLayer>\n  );\n}\n\ntype PropsWithResolvedDefaults = RequiresDefaultProps<Props, typeof defaultPieProps>;\n\n/**\n * @consumes PolarChartContext\n * @provides LabelListContext\n * @provides CellReader\n */\nfunction PieFn(outsideProps: Props) {\n  const props: PropsWithResolvedDefaults = resolveDefaultProps(outsideProps, defaultPieProps);\n  const { id: externalId, ...propsWithoutId } = props;\n  const presentationProps: PiePresentationProps | null = svgPropertiesNoEvents(propsWithoutId);\n\n  return (\n    <RegisterGraphicalItemId id={externalId} type=\"pie\">\n      {id => (\n        <>\n          <SetPolarGraphicalItem\n            type=\"pie\"\n            id={id}\n            data={propsWithoutId.data}\n            dataKey={propsWithoutId.dataKey}\n            hide={propsWithoutId.hide}\n            angleAxisId={0}\n            radiusAxisId={0}\n            name={propsWithoutId.name}\n            nameKey={propsWithoutId.nameKey}\n            tooltipType={propsWithoutId.tooltipType}\n            legendType={propsWithoutId.legendType}\n            fill={propsWithoutId.fill}\n            cx={propsWithoutId.cx}\n            cy={propsWithoutId.cy}\n            startAngle={propsWithoutId.startAngle}\n            endAngle={propsWithoutId.endAngle}\n            paddingAngle={propsWithoutId.paddingAngle}\n            minAngle={propsWithoutId.minAngle}\n            innerRadius={propsWithoutId.innerRadius}\n            outerRadius={propsWithoutId.outerRadius}\n            cornerRadius={propsWithoutId.cornerRadius}\n            presentationProps={presentationProps}\n            maxRadius={props.maxRadius}\n          />\n          <SetPiePayloadLegend {...propsWithoutId} id={id} />\n          <PieImpl {...propsWithoutId} id={id} />\n        </>\n      )}\n    </RegisterGraphicalItemId>\n  );\n}\nexport const Pie = PieFn as {\n  <DataPointType = any, DataValueType = any>(outsideProps: Props<DataPointType, DataValueType>): ReactElement;\n  (outsideProps: Props<any, any>): ReactElement;\n};\n// @ts-expect-error we need to set the displayName for debugging purposes\nPie.displayName = 'Pie';\n","import get from 'es-toolkit/compat/get';\n\nimport * as React from 'react';\nimport { Children, ReactNode } from 'react';\nimport { isFragment } from 'react-is';\nimport { isNullish } from './DataUtils';\nimport { ActiveDotType, DotType } from './types';\n\nexport const SCALE_TYPES = [\n  'auto',\n  'linear',\n  'pow',\n  'sqrt',\n  'log',\n  'identity',\n  'time',\n  'band',\n  'point',\n  'ordinal',\n  'quantile',\n  'quantize',\n  'utc',\n  'sequential',\n  'threshold',\n];\n\n/**\n * @deprecated instead find another approach that does not depend on displayName.\n * Get the display name of a component\n * @param  {Object} Comp Specified Component\n * @return {String}      Display name of Component\n */\nexport const getDisplayName = (Comp: React.ComponentType | string) => {\n  if (typeof Comp === 'string') {\n    return Comp;\n  }\n  if (!Comp) {\n    return '';\n  }\n  return Comp.displayName || Comp.name || 'Component';\n};\n\n// `toArray` gets called multiple times during the render\n// so we can memoize last invocation (since reference to `children` is the same)\nlet lastChildren: ReactNode | null = null;\nlet lastResult: ReactNode[] | null = null;\n\n/**\n * @deprecated instead find another approach that does not require reading React Elements from DOM.\n *\n * @param children do not use\n * @return deprecated do not use\n */\nexport const toArray = <T extends ReactNode>(children: T | T[]): T[] => {\n  if (children === lastChildren && Array.isArray(lastResult)) {\n    return lastResult as T[];\n  }\n  let result: T[] = [];\n  Children.forEach(children, child => {\n    if (isNullish(child)) return;\n    if (isFragment(child)) {\n      result = result.concat(toArray(child.props.children));\n    } else {\n      // @ts-expect-error this could still be Iterable<ReactNode> and TS does not like that\n      result.push(child);\n    }\n  });\n  lastResult = result;\n  lastChildren = children;\n  return result;\n};\n\n/**\n * @deprecated instead find another approach that does not require reading React Elements from DOM.\n *\n * Find and return all matched children by type.\n * `type` must be a React.ComponentType\n *\n * @param children do not use\n * @param type do not use\n * @return deprecated do not use\n */\nexport function findAllByType<\n  ComponentType extends React.ComponentType,\n  DetailedElement = React.DetailedReactHTMLElement<React.ComponentProps<ComponentType>, HTMLElement>,\n>(children: ReactNode, type: ComponentType | ComponentType[]): DetailedElement[] {\n  const result: DetailedElement[] = [];\n  let types: string[] = [];\n\n  if (Array.isArray(type)) {\n    types = type.map(t => getDisplayName(t));\n  } else {\n    types = [getDisplayName(type)];\n  }\n\n  toArray(children).forEach(child => {\n    // @ts-expect-error toArray and lodash.get are not compatible. Let's get rid of the whole findAllByType function\n    const childType: string = get(child, 'type.displayName') || get(child, 'type.name');\n    if (childType && types.indexOf(childType) !== -1) {\n      result.push(child as DetailedElement);\n    }\n  });\n\n  return result;\n}\n\nexport const isClipDot = (dot: ActiveDotType | DotType): boolean => {\n  if (dot && typeof dot === 'object' && 'clipDot' in dot) {\n    return Boolean(dot.clipDot);\n  }\n  return true;\n};\n","/**\n * @fileOverview Rectangle\n */\nimport * as React from 'react';\nimport { SVGProps, useEffect, useRef, useState } from 'react';\nimport { clsx } from 'clsx';\nimport { AnimationDuration, AnimationTiming } from '../util/types';\nimport { resolveDefaultProps } from '../util/resolveDefaultProps';\nimport { JavascriptAnimate } from '../animation/JavascriptAnimate';\nimport { useAnimationId } from '../util/useAnimationId';\nimport { interpolate } from '../util/DataUtils';\nimport { getTransitionVal } from '../animation/util';\nimport { svgPropertiesAndEvents } from '../util/svgPropertiesAndEvents';\nimport { roundTemplateLiteral } from '../util/round';\n\nconst getTrapezoidPath = (x: number, y: number, upperWidth: number, lowerWidth: number, height: number): string => {\n  const widthGap = upperWidth - lowerWidth;\n  let path;\n  path = roundTemplateLiteral`M ${x},${y}`;\n  path += roundTemplateLiteral`L ${x + upperWidth},${y}`;\n  path += roundTemplateLiteral`L ${x + upperWidth - widthGap / 2},${y + height}`;\n  path += roundTemplateLiteral`L ${x + upperWidth - widthGap / 2 - lowerWidth},${y + height}`;\n  path += roundTemplateLiteral`L ${x},${y} Z`;\n  return path;\n};\n\ninterface TrapezoidProps {\n  className?: string;\n  /**\n   * The x-coordinate of top left point of the trapezoid.\n   * @default 0\n   */\n  x?: number;\n  /**\n   * The y-coordinate of top left point of the trapezoid.\n   * @default 0\n   */\n  y?: number;\n  /**\n   * Width of the upper horizontal side of the trapezoid in pixels.\n   * @default 0\n   */\n  upperWidth?: number;\n  /**\n   * Width of the lower horizontal side of the trapezoid in pixels.\n   * @default 0\n   */\n  lowerWidth?: number;\n  /**\n   * Height of the trapezoid in pixels.\n   * @default 0\n   */\n  height?: number;\n\n  /**\n   * If set to true, trapezoid will update and render with a gradual fade-in animation from left to right.\n   * @default false\n   */\n  isUpdateAnimationActive?: boolean;\n  animationBegin?: number;\n  animationDuration?: AnimationDuration;\n  animationEasing?: AnimationTiming;\n\n  /**\n   * The customized event handler of click on the trapezoid\n   */\n  onClick?: (e: React.MouseEvent<SVGPathElement>) => void;\n  /**\n   * The customized event handler of mousedown on the trapezoid\n   */\n  onMouseDown?: (e: React.MouseEvent<SVGPathElement>) => void;\n  /**\n   * The customized event handler of mouseup on the trapezoid\n   */\n  onMouseUp?: (e: React.MouseEvent<SVGPathElement>) => void;\n  /**\n   * The customized event handler of mousemove on the trapezoid\n   */\n  onMouseMove?: (e: React.MouseEvent<SVGPathElement>) => void;\n  /**\n   * The customized event handler of mouseover on the trapezoid\n   */\n  onMouseOver?: (e: React.MouseEvent<SVGPathElement>) => void;\n  /**\n   * The customized event handler of mouseout on the trapezoid\n   */\n  onMouseOut?: (e: React.MouseEvent<SVGPathElement>) => void;\n  /**\n   * The customized event handler of mouseenter on the trapezoid\n   */\n  onMouseEnter?: (e: React.MouseEvent<SVGPathElement>) => void;\n  /**\n   * The customized event handler of mouseleave on the trapezoid\n   */\n  onMouseLeave?: (e: React.MouseEvent<SVGPathElement>) => void;\n}\n\nexport type Props = SVGProps<SVGPathElement> & TrapezoidProps;\n\nexport const defaultTrapezoidProps = {\n  x: 0,\n  y: 0,\n  upperWidth: 0,\n  lowerWidth: 0,\n  height: 0,\n  isUpdateAnimationActive: false,\n  animationBegin: 0,\n  animationDuration: 1500,\n  animationEasing: 'ease',\n} as const satisfies Partial<Props