lLength}px`;\n  const transition = getTransitionVal(['strokeDasharray'], animationDuration, animationEasing);\n\n  return (\n    <JavascriptAnimate\n      animationId={animationId}\n      key={animationId}\n      canBegin={totalLength > 0}\n      duration={animationDuration}\n      easing={animationEasing}\n      isActive={isUpdateAnimationActive}\n      begin={animationBegin}\n    >\n      {(t: number) => {\n        const currUpperWidth = interpolate(prevUpperWidth, upperWidth, t);\n        const currLowerWidth = interpolate(prevLowerWidth, lowerWidth, t);\n        const currHeight = interpolate(prevHeight, height, t);\n        const currX = interpolate(prevX, x, t);\n        const currY = interpolate(prevY, y, t);\n\n        if (pathRef.current) {\n          prevUpperWidthRef.current = currUpperWidth;\n          prevLowerWidthRef.current = currLowerWidth;\n          prevHeightRef.current = currHeight;\n          prevXRef.current = currX;\n          prevYRef.current = currY;\n        }\n        const animationStyle = t > 0 ? { transition, strokeDasharray: to } : { strokeDasharray: from };\n        return (\n          <path\n            {...svgPropertiesAndEvents(trapezoidProps)}\n            className={layerClass}\n            d={getTrapezoidPath(currX, currY, currUpperWidth, currLowerWidth, currHeight)}\n            ref={pathRef}\n            style={{\n              ...animationStyle,\n              ...trapezoidProps.style,\n            }}\n          />\n        );\n      }}\n    </JavascriptAnimate>\n  );\n};\n","import * as React from 'react';\nimport { cloneElement, isValidElement, ReactElement } from 'react';\nimport isPlainObject from 'es-toolkit/compat/isPlainObject';\n\nimport { Rectangle } from '../shape/Rectangle';\nimport { Trapezoid } from '../shape/Trapezoid';\nimport { Sector } from '../shape/Sector';\nimport { Layer } from '../container/Layer';\nimport { Symbols, SymbolsProps } from '../shape/Symbols';\nimport { Curve } from '../shape/Curve';\n\n/**\n * This is an abstraction for rendering a user defined prop for a customized shape in several forms.\n *\n * <Shape /> is the root and will handle taking in:\n *  - an object of svg properties\n *  - a boolean\n *  - a render prop(inline function that returns jsx)\n *  - a React element\n *\n * <ShapeSelector /> is a subcomponent of <Shape /> and used to match a component\n * to the value of props.shapeType that is passed to the root.\n *\n */\ntype ShapeType = 'trapezoid' | 'rectangle' | 'sector' | 'symbols' | 'curve';\n\nexport type ShapeProps<OptionType, ExtraProps> = {\n  shapeType: ShapeType;\n  option: OptionType;\n  isActive?: boolean;\n  index?: string | number;\n  activeClassName?: string;\n  inActiveClassName?: string;\n} & ExtraProps;\n\nfunction defaultPropTransformer<OptionType, ExtraProps, ShapePropsType>(\n  option: OptionType,\n  props: ExtraProps,\n): ShapePropsType {\n  return {\n    ...props,\n    ...option,\n  } as unknown as ShapePropsType;\n}\n\nfunction isSymbolsProps(shapeType: ShapeType, _elementProps: unknown): _elementProps is SymbolsProps {\n  return shapeType === 'symbols';\n}\n\nfunction ShapeSelector<ShapePropsType extends React.JSX.IntrinsicAttributes>({\n  shapeType,\n  elementProps,\n}: {\n  shapeType: ShapeType;\n  elementProps: ShapePropsType;\n}): React.ReactNode {\n  switch (shapeType) {\n    case 'rectangle':\n      return <Rectangle {...elementProps} />;\n    case 'trapezoid':\n      return <Trapezoid {...elementProps} />;\n    case 'sector':\n      return <Sector {...elementProps} />;\n    case 'symbols':\n      if (isSymbolsProps(shapeType, elementProps)) {\n        return <Symbols {...elementProps} />;\n      }\n      break;\n    case 'curve':\n      return <Curve {...elementProps} />;\n    default:\n      return null;\n  }\n}\n\nexport function getPropsFromShapeOption<T>(option: ReactElement<T> | T): T {\n  if (isValidElement(option)) {\n    return option.props;\n  }\n\n  return option;\n}\n\nexport function Shape<OptionType, ExtraProps, ShapePropsType extends React.JSX.IntrinsicAttributes>({\n  option,\n  shapeType,\n  activeClassName = 'recharts-active-shape',\n  inActiveClassName = 'recharts-shape',\n  ...props\n}: ShapeProps<OptionType, ExtraProps>) {\n  let shape: React.JSX.Element;\n  if (isValidElement(option)) {\n    // @ts-expect-error we can't know the type of cloned element props\n    shape = cloneElement(option, { ...props, ...getPropsFromShapeOption(option) });\n  } else if (typeof option === 'function') {\n    shape = option(props, props.index);\n  } else if (isPlainObject(option) && typeof option !== 'boolean') {\n    const nextProps: ShapePropsType = defaultPropTransformer(option, props);\n    shape = <ShapeSelector<ShapePropsType> shapeType={shapeType} elementProps={nextProps} />;\n  } else {\n    const elementProps = props as unknown as ShapePropsType;\n    shape = <ShapeSelector<ShapePropsType> shapeType={shapeType} elementProps={elementProps} />;\n  }\n\n  if (props.isActive) {\n    return <Layer className={activeClassName}>{shape}</Layer>;\n  }\n\n  return <Layer className={inActiveClassName}>{shape}</Layer>;\n}\n","import * as React from 'react';\nimport { Coordinate, DataKey } from '../util/types';\nimport { useAppDispatch } from '../state/hooks';\nimport {\n  mouseLeaveItem,\n  setActiveClickItemIndex,\n  setActiveMouseOverItemIndex,\n  TooltipPayload,\n} from '../state/tooltipSlice';\n\n/**\n * Some graphical items choose to provide more information to the tooltip\n * and some do not.\n */\nexport type TooltipTriggerInfo = {\n  tooltipPayload?: TooltipPayload;\n  tooltipPosition?: Coordinate;\n};\n\nexport type MouseEnterLeaveEvent<T, E extends SVGElement = SVGElement> = (\n  data: T,\n  index: number,\n  event: React.MouseEvent<E>,\n) => void;\n\nexport const useMouseEnterItemDispatch = <T extends TooltipTriggerInfo, E extends SVGElement = SVGElement>(\n  onMouseEnterFromProps: MouseEnterLeaveEvent<T, E> | undefined,\n  dataKey: DataKey<any> | undefined,\n  graphicalItemId: string,\n) => {\n  const dispatch = useAppDispatch();\n  return (data: T, index: number) => (event: React.MouseEvent<E>) => {\n    onMouseEnterFromProps?.(data, index, event);\n    dispatch(\n      setActiveMouseOverItemIndex({\n        activeIndex: String(index),\n        activeDataKey: dataKey,\n        activeCoordinate: data.tooltipPosition,\n        activeGraphicalItemId: graphicalItemId,\n      }),\n    );\n  };\n};\n\nexport const useMouseLeaveItemDispatch = <T extends TooltipTriggerInfo, E extends SVGElement = SVGElement>(\n  onMouseLeaveFromProps: undefined | MouseEnterLeaveEvent<T, E>,\n) => {\n  const dispatch = useAppDispatch();\n  return (data: T, index: number) => (event: React.MouseEvent<E>) => {\n    onMouseLeaveFromProps?.(data, index, event);\n    dispatch(mouseLeaveItem());\n  };\n};\n\nexport const useMouseClickItemDispatch = <T extends TooltipTriggerInfo, E extends SVGElement = SVGElement>(\n  onMouseClickFromProps: MouseEnterLeaveEvent<T, E> | undefined,\n  dataKey: DataKey<any> | undefined,\n  graphicalItemId: string,\n) => {\n  const dispatch = useAppDispatch();\n  return (data: T, index: number) => (event: React.MouseEvent<E>) => {\n    onMouseClickFromProps?.(data, index, event);\n    dispatch(\n      setActiveClickItemIndex({\n        activeIndex: String(index),\n        activeDataKey: dataKey,\n        activeCoordinate: data.tooltipPosition,\n        activeGraphicalItemId: graphicalItemId,\n      }),\n    );\n  };\n};\n","import { useLayoutEffect, useRef } from 'react';\nimport { useAppDispatch } from './hooks';\nimport {\n  addTooltipEntrySettings,\n  removeTooltipEntrySettings,\n  replaceTooltipEntrySettings,\n  TooltipPayloadConfiguration,\n} from './tooltipSlice';\nimport { useIsPanorama } from '../context/PanoramaContext';\n\nexport function SetTooltipEntrySettings({\n  tooltipEntrySettings,\n}: {\n  tooltipEntrySettings: TooltipPayloadConfiguration;\n}): null {\n  const dispatch = useAppDispatch();\n  const isPanorama = useIsPanorama();\n  const prevSettingsRef = useRef<TooltipPayloadConfiguration | null>(null);\n\n  useLayoutEffect(() => {\n    if (isPanorama) {\n      // Panorama graphical items should never contribute to Tooltip payload.\n      return;\n    }\n    if (prevSettingsRef.current === null) {\n      dispatch(addTooltipEntrySettings(tooltipEntrySettings));\n    } else if (prevSettingsRef.current !== tooltipEntrySettings) {\n      dispatch(replaceTooltipEntrySettings({ prev: prevSettingsRef.current, next: tooltipEntrySettings }));\n    }\n    prevSettingsRef.current = tooltipEntrySettings;\n  }, [tooltipEntrySettings, dispatch, isPanorama]);\n\n  useLayoutEffect(() => {\n    return () => {\n      if (prevSettingsRef.current) {\n        dispatch(removeTooltipEntrySettings(prevSettingsRef.current));\n        prevSettingsRef.current = null;\n      }\n    };\n  }, [dispatch]);\n\n  return null;\n}\n","import { useLayoutEffect, useRef } from 'react';\nimport type { LegendPayload } from '../component/DefaultLegendContent';\nimport { useIsPanorama } from '../context/PanoramaContext';\nimport { selectChartLayout } from '../context/chartLayoutContext';\nimport { useAppDispatch, useAppSelector } from './hooks';\nimport { addLegendPayload, replaceLegendPayload, removeLegendPayload } from './legendSlice';\n\nexport function SetLegendPayload({ legendPayload }: { legendPayload: ReadonlyArray<LegendPayload> }): null {\n  const dispatch = useAppDispatch();\n  const isPanorama = useIsPanorama();\n  const prevPayloadRef = useRef<ReadonlyArray<LegendPayload> | null>(null);\n\n  useLayoutEffect(() => {\n    if (isPanorama) {\n      return;\n    }\n    if (prevPayloadRef.current === null) {\n      dispatch(addLegendPayload(legendPayload));\n    } else if (prevPayloadRef.current !== legendPayload) {\n      dispatch(replaceLegendPayload({ prev: prevPayloadRef.current, next: legendPayload }));\n    }\n    prevPayloadRef.current = legendPayload;\n  }, [dispatch, isPanorama, legendPayload]);\n\n  useLayoutEffect(() => {\n    return () => {\n      if (prevPayloadRef.current) {\n        dispatch(removeLegendPayload(prevPayloadRef.current));\n        prevPayloadRef.current = null;\n      }\n    };\n  }, [dispatch]);\n\n  return null;\n}\n\nexport function SetPolarLegendPayload({ legendPayload }: { legendPayload: ReadonlyArray<LegendPayload> }): null {\n  const dispatch = useAppDispatch();\n  const layout = useAppSelector(selectChartLayout);\n  const prevPayloadRef = useRef<ReadonlyArray<LegendPayload> | null>(null);\n\n  useLayoutEffect(() => {\n    if (layout !== 'centric' && layout !== 'radial') {\n      return;\n    }\n    if (prevPayloadRef.current === null) {\n      dispatch(addLegendPayload(legendPayload));\n    } else if (prevPayloadRef.current !== legendPayload) {\n      dispatch(replaceLegendPayload({ prev: prevPayloadRef.current, next: legendPayload }));\n    }\n    prevPayloadRef.current = legendPayload;\n  }, [dispatch, layout, legendPayload]);\n\n  useLayoutEffect(() => {\n    return () => {\n      if (prevPayloadRef.current) {\n        dispatch(removeLegendPayload(prevPayloadRef.current));\n        prevPayloadRef.current = null;\n      }\n    };\n  }, [dispatch]);\n\n  return null;\n}\n","import * as React from 'react';\nimport { uniqueId } from './DataUtils';\n\n/**\n * Fallback for React.useId() for versions prior to React 18.\n * Generates a unique ID using a simple counter and a prefix.\n *\n * @returns A unique ID that remains consistent across renders.\n */\nexport const useIdFallback = (): string => {\n  const [id] = React.useState(() => uniqueId('uid-'));\n  return id;\n};\n\n/*\n * This weird syntax is used to avoid a build-time error in React 17 and earlier when building with Webpack.\n * See https://github.com/webpack/webpack/issues/14814\n */\nexport const useId: () => string = ((React as any)['useId'.toString()] as () => string) ?? useIdFallback;\n","import { useId } from './useId';\n\n/**\n * A hook that generates a unique ID. It uses React.useId() in React 18+ for SSR safety\n * and falls back to a client-side-only unique ID generator for older versions.\n *\n * The ID will stay the same across renders, and you can optionally provide a prefix.\n *\n * @param [prefix] - An optional prefix for the generated ID.\n * @param [customId] - An optional custom ID to override the generated one.\n * @returns The unique ID.\n */\nexport function useUniqueId(prefix?: string, customId?: string): string {\n  /*\n   * We have to call this hook here even if we don't use the result because\n   * rules of hooks demand that hooks are never called conditionally.\n   */\n  const generatedId = useId();\n\n  // If a custom ID is provided, it always takes precedence.\n  if (customId) {\n    return customId;\n  }\n\n  // Apply the prefix if one was provided.\n  return prefix ? `${prefix}-${generatedId}` : generatedId;\n}\n\n/**\n * The useUniqueId hook returns a unique ID that is either reused from external props or generated internally.\n * Either way the ID is now guaranteed to be present so no more nulls or undefined.\n */\nexport type WithIdRequired<T> = T & {\n  id: string;\n};\n\nexport type WithoutId<T> = Omit<T, 'id'>;\n","import * as React from 'react';\nimport { createContext, useContext } from 'react';\nimport { useUniqueId } from '../util/useUniqueId';\nimport { GraphicalItemId } from '../state/graphicalItemsSlice';\n\nexport type IdSetter = {\n  id?: string;\n  type: string;\n  /**\n   * Children must be a function that receives the resolved ID of the graphical item.\n   * This ID will either be the one provided via props.id or generated automatically.\n   */\n  children: (id: GraphicalItemId) => React.ReactNode;\n};\n\nconst GraphicalItemIdContext = createContext<GraphicalItemId | undefined>(undefined);\n\nexport const RegisterGraphicalItemId = ({ id, type, children }: IdSetter) => {\n  const resolvedId = useUniqueId(`recharts-${type}`, id);\n  return <GraphicalItemIdContext.Provider value={resolvedId}>{children(resolvedId)}</GraphicalItemIdContext.Provider>;\n};\n\nexport function useGraphicalItemId(): GraphicalItemId | undefined {\n  return useContext(GraphicalItemIdContext);\n}\n","import { createSlice, current, PayloadAction, prepareAutoBatched } from '@reduxjs/toolkit';\nimport { castDraft } from 'immer';\nimport { ChartData } from './chartDataSlice';\nimport { AxisId } from './cartesianAxisSlice';\nimport { DataKey } from '../util/types';\nimport { LineSettings } from './types/LineSettings';\nimport { ScatterSettings } from './types/ScatterSettings';\nimport { AreaSettings } from './types/AreaSettings';\nimport { BarSettings } from './types/BarSettings';\nimport { RadialBarSettings } from './types/RadialBarSettings';\nimport { PieSettings } from './types/PieSettings';\nimport { RadarSettings } from './types/RadarSettings';\n\n/**\n * Unique ID of the graphical item.\n * This is used to identify the graphical item in the state and in the React tree.\n * This is required for every graphical item - it's either provided by the user or generated automatically.\n */\nexport type GraphicalItemId = string;\n\nexport interface GraphicalItemSettings {\n  /**\n   * Unique ID of the graphical item.\n   * This is used to identify the graphical item in the state and in the React tree.\n   * This is required for every graphical item - it's either provided by the user or generated automatically.\n   */\n  id: GraphicalItemId;\n  /**\n   * If the given graphical item has its own data array, it will appear here.\n   * If this is undefined, the data will be taken from the chart root prop.\n   */\n  data: ChartData | undefined;\n  dataKey: DataKey<any> | undefined;\n  /**\n   * Why not just stop pushing the graphical items to state when they are hidden?\n   * Well some components decide to continue showing them anyway.\n   * Legend for example will keep showing a record for hidden graphical items.\n   * Stacks for example will ignore them.\n   */\n  hide: boolean;\n}\n\nexport interface BaseCartesianGraphicalItemSettings extends GraphicalItemSettings {\n  /**\n   * Each of the graphical items explicitly says which axis it uses;\n   * this property is optional for users but every graphical item must have a default,\n   * and it is required here.\n   */\n  xAxisId: AxisId;\n  yAxisId: AxisId;\n  zAxisId: AxisId;\n  /**\n   * Graphical items that are inside Brush panorama should not interact with the main area graphical items\n   * and vice versa.\n   */\n  isPanorama: boolean;\n}\n\nexport type CartesianGraphicalItemSettings = AreaSettings | BarSettings | LineSettings | ScatterSettings;\n\nexport interface BasePolarGraphicalItemSettings extends GraphicalItemSettings {\n  angleAxisId: AxisId;\n  radiusAxisId: AxisId;\n}\n\nexport type PolarGraphicalItemSettings = PieSettings | RadarSettings | RadialBarSettings;\n\nexport type GraphicalItemsState = {\n  /**\n   * This is an array of all cartesian graphical items and their settings.\n   * Graphical item is a visual representation of data on the chart.\n   * Some examples are: Line, Bar.\n   *\n   * The order is arbitrary; do not expect that indexes here will be the same as indexes elsewhere.\n   */\n  cartesianItems: ReadonlyArray<CartesianGraphicalItemSettings>;\n  /**\n   * This is an array of all polar graphical items and their settings.\n   * Graphical item is a visual representation of data on the chart.\n   * Some examples are: Pie, Radar, RadialBar\n   *\n   * The order is arbitrary; do not expect that indexes here will be the same as indexes elsewhere.\n   */\n  polarItems: ReadonlyArray<PolarGraphicalItemSettings>;\n};\n\nconst initialState: GraphicalItemsState = {\n  cartesianItems: [],\n  polarItems: [],\n};\n\ntype ReplacePayload<T> = {\n  prev: T;\n  next: T;\n};\n\nconst graphicalItemsSlice = createSlice({\n  name: 'graphicalItems',\n  initialState,\n  reducers: {\n    addCartesianGraphicalItem: {\n      reducer(state, action: PayloadAction<CartesianGraphicalItemSettings>) {\n        state.cartesianItems.push(castDraft(action.payload));\n      },\n      prepare: prepareAutoBatched<CartesianGraphicalItemSettings>(),\n    },\n    replaceCartesianGraphicalItem: {\n      reducer(state, action: PayloadAction<ReplacePayload<CartesianGraphicalItemSettings>>) {\n        const { prev, next } = action.payload;\n        const index = current(state).cartesianItems.indexOf(castDraft(prev));\n        if (index > -1) {\n          state.cartesianItems[index] = castDraft(next);\n        }\n      },\n      prepare: prepareAutoBatched<ReplacePayload<CartesianGraphicalItemSettings>>(),\n    },\n    removeCartesianGraphicalItem: {\n      reducer(state, action: PayloadAction<CartesianGraphicalItemSettings>) {\n        const index = current(state).cartesianItems.indexOf(castDraft(action.payload));\n        if (index > -1) {\n          state.cartesianItems.splice(index, 1);\n        }\n      },\n      prepare: prepareAutoBatched<CartesianGraphicalItemSettings>(),\n    },\n    addPolarGraphicalItem: {\n      reducer(state, action: PayloadAction<PolarGraphicalItemSettings>) {\n        state.polarItems.push(castDraft(action.payload));\n      },\n      prepare: prepareAutoBatched<PolarGraphicalItemSettings>(),\n    },\n    removePolarGraphicalItem: {\n      reducer(state, action: PayloadAction<PolarGraphicalItemSettings>) {\n        const index = current(state).polarItems.indexOf(castDraft(action.payload));\n        if (index > -1) {\n          state.polarItems.splice(index, 1);\n        }\n      },\n      prepare: prepareAutoBatched<PolarGraphicalItemSettings>(),\n    },\n    replacePolarGraphicalItem: {\n      reducer(state, action: PayloadAction<ReplacePayload<PolarGraphicalItemSettings>>) {\n        const { prev, next } = action.payload;\n        const index = current(state).polarItems.indexOf(castDraft(prev));\n        if (index > -1) {\n          state.polarItems[index] = castDraft(next);\n        }\n      },\n      prepare: prepareAutoBatched<ReplacePayload<PolarGraphicalItemSettings>>(),\n    },\n  },\n});\n\nexport const {\n  addCartesianGraphicalItem,\n  replaceCartesianGraphicalItem,\n  removeCartesianGraphicalItem,\n  addPolarGraphicalItem,\n  removePolarGraphicalItem,\n  replacePolarGraphicalItem,\n} = graphicalItemsSlice.actions;\n\nexport const graphicalItemsReducer = graphicalItemsSlice.reducer;\n","import { memo, useLayoutEffect, useRef } from 'react';\nimport { useAppDispatch } from './hooks';\nimport {\n  addCartesianGraphicalItem,\n  addPolarGraphicalItem,\n  CartesianGraphicalItemSettings,\n  PolarGraphicalItemSettings,\n  removeCartesianGraphicalItem,\n  removePolarGraphicalItem,\n  replaceCartesianGraphicalItem,\n  replacePolarGraphicalItem,\n} from './graphicalItemsSlice';\n\nconst SetCartesianGraphicalItemImpl = <T extends CartesianGraphicalItemSettings>(props: T): null => {\n  const dispatch = useAppDispatch();\n  const prevPropsRef = useRef<T | null>(null);\n\n  useLayoutEffect(() => {\n    if (prevPropsRef.current === null) {\n      dispatch(addCartesianGraphicalItem(props));\n    } else if (prevPropsRef.current !== props) {\n      dispatch(replaceCartesianGraphicalItem({ prev: prevPropsRef.current, next: props }));\n    }\n    prevPropsRef.current = props;\n  }, [dispatch, props]);\n\n  useLayoutEffect(() => {\n    return () => {\n      if (prevPropsRef.current) {\n        dispatch(removeCartesianGraphicalItem(prevPropsRef.current));\n        /*\n         * Here we have to reset the ref to null because in StrictMode, the effect will run twice,\n         * but it will keep the same ref value from the first render.\n         *\n         * In browser, React will clear the ref after the first effect cleanup,\n         * so that wouldn't be an issue.\n         *\n         * In StrictMode, however, the ref is kept,\n         * and in the hook above the code checks for `prevPropsRef.current === null`\n         * which would be false so it would not dispatch the `addCartesianGraphicalItem` action again.\n         *\n         * https://github.com/recharts/recharts/issues/6022\n         */\n        prevPropsRef.current = null;\n      }\n    };\n  }, [dispatch]);\n\n  return null;\n};\n\nexport const SetCartesianGraphicalItem = memo(SetCartesianGraphicalItemImpl);\n\nconst SetPolarGraphicalItemImpl = (props: PolarGraphicalItemSettings): null => {\n  const dispatch = useAppDispatch();\n  const prevPropsRef = useRef<PolarGraphicalItemSettings | null>(null);\n\n  useLayoutEffect(() => {\n    if (prevPropsRef.current === null) {\n      dispatch(addPolarGraphicalItem(props));\n    } else if (prevPropsRef.current !== props) {\n      dispatch(replacePolarGraphicalItem({ prev: prevPropsRef.current, next: props }));\n    }\n    prevPropsRef.current = props;\n  }, [dispatch, props]);\n\n  useLayoutEffect(() => {\n    return () => {\n      if (prevPropsRef.current) {\n        dispatch(removePolarGraphicalItem(prevPropsRef.current));\n        prevPropsRef.current = null;\n      }\n    };\n  }, [dispatch]);\n\n  return null;\n};\n\nexport const SetPolarGraphicalItem = memo(SetPolarGraphicalItemImpl);\n","import * as React from 'react';\nimport { cloneElement, isValidElement } from 'react';\nimport { clsx } from 'clsx';\nimport { Dot, type Props as DotProps } from '../shape/Dot';\nimport { Layer } from '../container/Layer';\nimport { DataKey, DotItemDotProps, DotType } from '../util/types';\nimport { isClipDot } from '../util/ReactUtils';\nimport { svgPropertiesAndEventsFromUnknown } from '../util/svgPropertiesAndEvents';\nimport { ZIndexable, ZIndexLayer } from '../zIndex/ZIndexLayer';\nimport { DefaultZIndexes } from '../zIndex/DefaultZIndexes';\n\nexport interface DotPoint {\n  readonly x: number | null;\n  readonly y: number | null;\n  readonly value?: any;\n  readonly payload?: any;\n}\n\ntype DotItemProps = {\n  option: DotType;\n  dotProps: DotItemDotProps;\n  className: string;\n};\n\nfunction DotItem({ option, dotProps, className }: DotItemProps) {\n  if (isValidElement(option)) {\n    // @ts-expect-error we can't type check element cloning properly\n    return cloneElement(option, dotProps);\n  }\n\n  if (typeof option === 'function') {\n    return option(dotProps);\n  }\n\n  const finalClassName = clsx(className, typeof option !== 'boolean' ? option.className : '');\n  const { points, ...props } = dotProps ?? {};\n  return <Dot {...props} className={finalClassName} />;\n}\n\nfunction shouldRenderDots(points: ReadonlyArray<DotPoint> | undefined, dot: DotType): boolean {\n  if (points == null) {\n    return false;\n  }\n  if (dot) {\n    return true;\n  }\n  return points.length === 1;\n}\n\nexport type DotsDotProps = Omit<DotProps, 'cx' | 'cy' | 'key' | 'index' | 'dataKey' | 'value' | 'payload'>;\n\ninterface DotsProps extends ZIndexable {\n  /**\n   * Points to render dots for\n   */\n  points: ReadonlyArray<DotPoint>;\n  /**\n   * Dot configuration - boolean, ReactElement, function, or props object\n   */\n  dot: DotType;\n  /**\n   * Base class name for the dots layer (e.g., 'recharts-area-dots')\n   */\n  className: string;\n  /**\n   * Base class name for individual dot (e.g., 'recharts-area-dot')\n   */\n  dotClassName: string;\n  /**\n   * DataKey for the data\n   */\n  dataKey: DataKey<any> | undefined;\n  /**\n   * Base props to spread onto each dot (from parent component).\n   * Except some properties that the Dots component manages itself.\n   */\n  baseProps: DotsDotProps;\n  /**\n   * Whether clipping is needed (cartesian only)\n   */\n  needClip?: boolean;\n  /**\n   * Clip path ID (cartesian only)\n   */\n  clipPathId?: string;\n}\n\nexport function Dots({\n  points,\n  dot,\n  className,\n  dotClassName,\n  dataKey,\n  baseProps,\n  needClip,\n  clipPathId,\n  zIndex = DefaultZIndexes.scatter,\n}: DotsProps) {\n  if (!shouldRenderDots(points, dot)) {\n    return null;\n  }\n\n  const clipDot = isClipDot(dot);\n  const customDotProps = svgPropertiesAndEventsFromUnknown(dot);\n\n  const dots = points.map((entry, i) => {\n    const dotProps: DotItemDotProps = {\n      r: 3,\n      ...baseProps,\n      ...customDotProps,\n      index: i,\n      cx: entry.x ?? undefined,\n      cy: entry.y ?? undefined,\n      dataKey,\n      value: entry.value,\n      payload: entry.payload,\n      points,\n    };\n\n    return <DotItem key={`dot-${i}`} option={dot} dotProps={dotProps} className={dotClassName} />;\n  });\n\n  const layerProps: { clipPath?: string } = {};\n  if (needClip && clipPathId != null) {\n    layerProps.clipPath = `url(#clipPath-${clipDot ? '' : 'dots-'}${clipPathId})`;\n  }\n\n  return (\n    <ZIndexLayer zIndex={zIndex}>\n      <Layer className={className} {...layerProps}>\n        {dots}\n      </Layer>\n    </ZIndexLayer>\n  );\n}\n","import { createSlice, PayloadAction, prepareAutoBatched } from '@reduxjs/toolkit';\nimport { castDraft } from 'immer';\nimport {\n  AxisDomain,\n  AxisInterval,\n  AxisTick,\n  DataKey,\n  EvaluatedAxisDomainType,\n  ScaleType,\n  TickProp,\n} from '../util/types';\nimport { TickFormatter } from '../cartesian/CartesianAxis';\nimport type { AxisRange } from './selectors/axisSelectors';\nimport { CustomScaleDefinition } from '../util/scale/CustomScaleDefinition';\n\n/**\n * @inline\n */\nexport type AxisId = string | number;\nexport const defaultAxisId: AxisId = 0;\nexport type XAxisPadding = { left?: number; right?: number } | 'gap' | 'no-gap';\nexport type YAxisPadding = { top?: number; bottom?: number } | 'gap' | 'no-gap';\n\nexport type XAxisOrientation = 'top' | 'bottom';\nexport type YAxisOrientation = 'left' | 'right';\n\n/**\n * Properties shared in X, Y, and Z axes.\n * User defined axis settings, coming from props.\n */\nexport type BaseCartesianAxis = {\n  id: AxisId;\n  scale:\n    | ScaleType\n    | CustomScaleDefinition\n    | CustomScaleDefinition<string>\n    | CustomScaleDefinition<number>\n    | CustomScaleDefinition<Date>;\n  /**\n   * Before creating this object, evaluate the domain type based on the chart layout so that we have the 'auto' resolved.\n   */\n  type: EvaluatedAxisDomainType;\n  /**\n   * The axis functionality is severely restricted without a dataKey\n   * - but there is still something left, and the prop is optional\n   * so this can also be undefined even in real charts.\n   * There are no defaults.\n   */\n  dataKey: DataKey<any> | undefined;\n  unit: string | undefined;\n  name: string | undefined;\n  allowDuplicatedCategory: boolean;\n  allowDataOverflow: boolean;\n  reversed: boolean;\n  includeHidden: boolean;\n  domain: AxisDomain | undefined;\n};\n\n/**\n * Controls how Recharts calculates \"nice\" tick values for numerical axes.\n *\n * - `'none'`: Recharts does not apply any tick-rounding algorithm; tick positions are\n *   determined entirely by d3, evenly spaced but not rounded to human-friendly numbers.\n *   There is no domain-extension logic applied in this mode.\n *\n * - `'auto'` *(default)*: Recharts automatically decides whether and how to apply tick\n *   niceties based on the domain definition. When the domain contains an `'auto'` keyword,\n *   Recharts uses the `'adaptive'` algorithm and may extend the domain slightly to\n *   produce clean tick labels. Otherwise, it applies the same algorithm while keeping\n *   ticks within the fixed domain. This mirrors the default behavior from Recharts v2.\n *\n * - `'adaptive'`: Always applies the space-efficient algorithm (`getAdaptiveStep`),\n *   which fills the available range as densely as possible while still rounding steps\n *   to reasonable numbers (e.g. 10, 20, 25). May produce less \"round-looking\" labels\n *   than `'snap125'`, but wastes less space. The domain-extension logic still applies\n *   when the domain contains an `'auto'` keyword.\n *\n * - `'snap125'`: Always applies the round-numbers algorithm (`getSnap125Step`), which\n *   snaps step sizes to values from the set {1, 2, 2.5, 5} × 10ⁿ. Produces very\n *   human-friendly labels (e.g. 0, 5, 10, 15, 20) but may leave blank space at the\n *   edges of the chart. The domain-extension logic still applies when the domain\n *   contains an `'auto'` keyword.\n *\n * @see {@link https://recharts.github.io/guide/axisTicks/}\n * @inline\n */\nexport type NiceTicksAlgorithm = 'none' | 'auto' | 'adaptive' | 'snap125';\n\nexport type TicksSettings = {\n  allowDecimals: boolean;\n  /**\n   * We pass the suggested number of ticks to d3 https://d3js.org/d3-scale/linear#linear_ticks\n   * This number is a suggestion. d3 tries to accommodate it, but it might return more or less ticks than requested:\n   * > The specified count is only a hint; the scale may return more or fewer values depending on the domain.\n   *\n   * If undefined, then d3 decides the number of ticks on its own. The default in d3 is 10,\n   * but it can vary based on the domain size and other factors.\n   */\n  tickCount: number | undefined;\n  /**\n   * Ticks can be any type when the axis is the type of category\n   * Ticks must be numbers when the axis is the type of number\n   */\n  ticks: ReadonlyArray<AxisTick> | undefined;\n  tick: TickProp<any>;\n  /**\n   * Controls how Recharts calculates \"nice\" tick values for this axis.\n   * See {@link NiceTicksAlgorithm} for a full description of each option.\n   *\n   * @defaultValue 'auto'\n   */\n  niceTicks: NiceTicksAlgorithm;\n};\n\n/**\n * These are the external props, visible for users as they set them using our public API.\n * There is all sorts of internal computed things based on these, but they will come through selectors.\n *\n * Properties shared between X and Y axes\n */\nexport type CartesianAxisSettings = BaseCartesianAxis &\n  TicksSettings & {\n    interval: AxisInterval;\n    mirror: boolean;\n    minTickGap: number;\n    angle: number;\n    hide: boolean;\n    tickFormatter: TickFormatter | undefined;\n  };\n\nexport type XAxisSettings = CartesianAxisSettings & {\n  padding: XAxisPadding;\n  height: number;\n  orientation: XAxisOrientation;\n};\n\nexport type YAxisWidth = number | 'auto';\n\nexport type YAxisSettings = CartesianAxisSettings & {\n  padding: YAxisPadding;\n  width: YAxisWidth;\n  orientation: YAxisOrientation;\n  widthHistory?: number[];\n};\n\n/**\n * Z axis is special because it's never displayed. It controls the size of Scatter dots,\n * but it never displays ticks anywhere.\n */\nexport type ZAxisSettings = BaseCartesianAxis & {\n  range: AxisRange;\n};\n\ntype AxisMapState = {\n  xAxis: Record<AxisId, XAxisSettings>;\n  yAxis: Record<AxisId, YAxisSettings>;\n  zAxis: Record<AxisId, ZAxisSettings>;\n};\n\nconst initialState: AxisMapState = {\n  xAxis: {},\n  yAxis: {},\n  zAxis: {},\n};\n\n/**\n * This is the slice where each individual Axis element pushes its own configuration.\n * Prefer to use this one instead of axisSlice.\n */\nconst cartesianAxisSlice = createSlice({\n  name: 'cartesianAxis',\n  initialState,\n  reducers: {\n    addXAxis: {\n      reducer(state, action: PayloadAction<XAxisSettings>) {\n        state.xAxis[action.payload.id] = castDraft(action.payload);\n      },\n      prepare: prepareAutoBatched<XAxisSettings>(),\n    },\n    replaceXAxis: {\n      reducer(state, action: PayloadAction<{ prev: XAxisSettings; next: XAxisSettings }>) {\n        const { prev, next } = action.payload;\n        if (state.xAxis[prev.id] !== undefined) {\n          if (prev.id !== next.id) {\n            delete state.xAxis[prev.id];\n          }\n          state.xAxis[next.id] = castDraft(next);\n        }\n      },\n      prepare: prepareAutoBatched<{ prev: XAxisSettings; next: XAxisSettings }>(),\n    },\n    removeXAxis: {\n      reducer(state, action: PayloadAction<XAxisSettings>) {\n        delete state.xAxis[action.payload.id];\n      },\n      prepare: prepareAutoBatched<XAxisSettings>(),\n    },\n    addYAxis: {\n      reducer(state, action: PayloadAction<YAxisSettings>) {\n        state.yAxis[action.payload.id] = castDraft(action.payload);\n      },\n      prepare: prepareAutoBatched<YAxisSettings>(),\n    },\n    replaceYAxis: {\n      reducer(state, action: PayloadAction<{ prev: YAxisSettings; next: YAxisSettings }>) {\n        const { prev, next } = action.payload;\n        if (state.yAxis[prev.id] !== undefined) {\n          if (prev.id !== next.id) {\n            delete state.yAxis[prev.id];\n          }\n          state.yAxis[next.id] = castDraft(next);\n        }\n      },\n      prepare: prepareAutoBatched<{ prev: YAxisSettings; next: YAxisSettings }>(),\n    },\n    removeYAxis: {\n      reducer(state, action: PayloadAction<YAxisSettings>) {\n        delete state.yAxis[action.payload.id];\n      },\n      prepare: prepareAutoBatched<YAxisSettings>(),\n    },\n    addZAxis: {\n      reducer(state, action: PayloadAction<ZAxisSettings>) {\n        state.zAxis[action.payload.id] = castDraft(action.payload);\n      },\n      prepare: prepareAutoBatched<ZAxisSettings>(),\n    },\n    replaceZAxis: {\n      reducer(state, action: PayloadAction<{ prev: ZAxisSettings; next: ZAxisSettings }>) {\n        const { prev, next } = action.payload;\n        if (state.zAxis[prev.id] !== undefined) {\n          if (prev.id !== next.id) {\n            delete state.zAxis[prev.id];\n          }\n          state.zAxis[next.id] = castDraft(next);\n        }\n      },\n      prepare: prepareAutoBatched<{ prev: ZAxisSettings; next: ZAxisSettings }>(),\n    },\n    removeZAxis: {\n      reducer(state, action: PayloadAction<ZAxisSettings>) {\n        delete state.zAxis[action.payload.id];\n      },\n      prepare: prepareAutoBatched<ZAxisSettings>(),\n    },\n    updateYAxisWidth(state, action: PayloadAction<{ id: AxisId; width: number }>) {\n      const { id, width } = action.payload;\n      const axis = state.yAxis[id];\n      if (axis) {\n        const history = axis.widthHistory || [];\n        // An oscillation is detected when the new width is the same as the width before the last one.\n        // This is a simple A -> B -> A pattern. If the next width is B, and the difference is less than 1 pixel, we ignore it.\n        if (\n          history.length === 3 &&\n          history[0] === history[2] &&\n          width === history[1] &&\n          width !== axis.width &&\n          Math.abs(width - (history[0] ?? 0)) <= 1\n        ) {\n          return;\n        }\n        const newHistory = [...history, width].slice(-3);\n        state.yAxis[id] = {\n          ...axis,\n          width,\n          widthHistory: newHistory,\n        };\n      }\n    },\n  },\n});\n\nexport const {\n  addXAxis,\n  replaceXAxis,\n  removeXAxis,\n  addYAxis,\n  replaceYAxis,\n  removeYAxis,\n  addZAxis,\n  replaceZAxis,\n  removeZAxis,\n  updateYAxisWidth,\n} = cartesianAxisSlice.actions;\n\nexport const cartesianAxisReducer = cartesianAxisSlice.reducer;\n","import { createSelector } from 'reselect';\nimport { selectChartOffsetInternal } from './selectChartOffsetInternal';\nimport { ChartOffsetInternal } from '../../util/types';\nimport { ChartOffset } from '../../types';\n\nexport const selectChartOffset = createSelector(\n  [selectChartOffsetInternal],\n  (offsetInternal: ChartOffsetInternal): ChartOffset => {\n    return {\n      top: offsetInternal.top,\n      bottom: offsetInternal.bottom,\n      left: offsetInternal.left,\n      right: offsetInternal.right,\n    };\n  },\n);\n","import { createSelector } from 'reselect';\nimport { selectChartOffset } from './selectChartOffset';\nimport { selectChartHeight, selectChartWidth } from './containerSelectors';\n\nexport const selectPlotArea = createSelector(\n  [selectChartOffset, selectChartWidth, selectChartHeight],\n  (offset, chartWidth, chartHeight) => {\n    if (!offset || chartWidth == null || chartHeight == null) {\n      return undefined;\n    }\n\n    return {\n      x: offset.left,\n      y: offset.top,\n      width: Math.max(0, chartWidth - offset.left - offset.right),\n      height: Math.max(0, chartHeight - offset.top - offset.bottom),\n    };\n  },\n);\n","import { AxisId, defaultAxisId } from './state/cartesianAxisSlice';\nimport {\n  BaseAxisWithScale,\n  selectAxisDomain,\n  selectAxisInverseScale,\n  selectAxisInverseDataSnapScale,\n  selectAxisInverseTickSnapScale,\n  selectAxisScale,\n  selectAxisWithScale,\n  selectRenderedTicksOfAxis,\n} from './state/selectors/axisSelectors';\nimport { useAppSelector } from './state/hooks';\nimport { useIsPanorama } from './context/PanoramaContext';\nimport {\n  selectActiveLabel,\n  selectActiveTooltipCoordinate,\n  selectActiveTooltipDataPoints,\n  selectIsTooltipActive,\n} from './state/selectors/tooltipSelectors';\nimport { ChartOffset, PlotArea } from './types';\nimport { selectChartOffset } from './state/selectors/selectChartOffset';\nimport { selectPlotArea } from './state/selectors/selectPlotArea';\nimport { CategoricalDomain, Coordinate, NumberDomain, TickItem } from './util/types';\nimport { ActiveLabel } from './synchronisation/types';\nimport { BandPosition } from './util/scale/RechartsScale';\n\nexport const useXAxis = (xAxisId: AxisId): BaseAxisWithScale | undefined => {\n  const isPanorama = useIsPanorama();\n  return useAppSelector(state => selectAxisWithScale(state, 'xAxis', xAxisId, isPanorama));\n};\n\nexport const useYAxis = (yAxisId: AxisId): BaseAxisWithScale | undefined => {\n  const isPanorama = useIsPanorama();\n  return useAppSelector(state => selectAxisWithScale(state, 'yAxis', yAxisId, isPanorama));\n};\n\n/**\n * A function that converts data values to pixel coordinates.\n * @param value - The data value to convert (number, string, or category).\n * @param options - Optional configuration for banded scales.\n * @param options.position - Position within a band: 'start', 'middle', or 'end'.\n * @returns The pixel coordinate, or `undefined` if the value is not in the domain.\n */\nexport type ScaleFunction = (value: unknown, options?: { position?: BandPosition }) => number | undefined;\n\n/**\n * A function that converts pixel coordinates back to data values.\n * @param pixelValue - The pixel coordinate to convert.\n * @returns The closest data value in the domain.\n */\nexport type InverseScaleFunction = (pixelValue: number) => unknown;\n\n/**\n * Returns a function to convert data values to pixel coordinates for an {@link XAxis}.\n *\n * This is useful for positioning annotations, custom shapes, or other elements\n * at specific data points on the chart.\n *\n * This hook must be used within a chart context (inside a {@link LineChart}, {@link BarChart}, etc.).\n * Returns `undefined` if used outside a chart context, or if the axes don't exist.\n *\n * @example\n * ```tsx\n * const xScale = useXAxisScale();\n * if (xScale) {\n *   const pixelX = xScale('Page A'); // Returns the pixel x-coordinate for 'Page A'\n * }\n * ```\n *\n * @param xAxisId The `xAxisId` of the XAxis. Defaults to `0` if not provided.\n * @returns A scale function that maps data values to pixel coordinates, or `undefined`.\n * @since 3.8\n */\nexport const useXAxisScale = (xAxisId: AxisId = defaultAxisId): ScaleFunction | undefined => {\n  const isPanorama = useIsPanorama();\n  const scale = useAppSelector(state => selectAxisScale(state, 'xAxis', xAxisId, isPanorama));\n  return scale?.map;\n};\n\n/**\n * Returns a function to convert data values to pixel coordinates for a {@link YAxis}.\n *\n * This is useful for positioning annotations, custom shapes, or other elements\n * at specific data points on the chart.\n *\n * This hook must be used within a chart context (inside a {@link LineChart}, {@link BarChart}, etc.).\n * Returns `undefined` if used outside a chart context, or if the axes don't exist.\n *\n * @example\n * ```tsx\n * const yScale = useYAxisScale();\n * if (yScale) {\n *   const pixelY = yScale(1500); // Returns the pixel y-coordinate for value 1500\n * }\n * ```\n *\n * @param yAxisId The `yAxisId` of the YAxis. Defaults to `0` if not provided.\n * @returns A scale function that maps data values to pixel coordinates, or `undefined`.\n * @since 3.8\n */\nexport const useYAxisScale = (yAxisId: AxisId = defaultAxisId): ScaleFunction | undefined => {\n  const isPanorama = useIsPanorama();\n  const scale = useAppSelector(state => selectAxisScale(state, 'yAxis', yAxisId, isPanorama));\n  return scale?.map;\n};\n\n/**\n * Returns a function to convert pixel coordinates back to data values for an {@link XAxis}.\n *\n * This is useful for implementing interactions like click-to-add-annotation,\n * drag interactions, or tooltips that need to determine what data point\n * corresponds to a mouse position.\n *\n * For continuous (numerical) scales, returns an interpolated value.\n * For categorical scales, returns the closest category in the domain - which is the same behaviour as {@link useXAxisInverseDataSnapScale}.\n *\n * This hook must be used within a chart context (inside a {@link LineChart}, {@link BarChart}, etc.).\n * Returns `undefined` if used outside a chart context, or if the axes don't exist.\n *\n * @example\n * ```tsx\n * const xInverseScale = useXAxisInverseScale();\n * if (xInverseScale) {\n *   const dataValue = xInverseScale(150); // Returns the data value at pixel x=150\n * }\n * ```\n *\n * @param xAxisId The `xAxisId` of the XAxis. Defaults to `0` if not provided.\n * @returns An inverse scale function that maps pixel coordinates to data values, or `undefined`.\n * @since 3.8\n */\nexport const useXAxisInverseScale = (xAxisId: AxisId = defaultAxisId): InverseScaleFunction | undefined => {\n  const isPanorama = useIsPanorama();\n  return useAppSelector(state => selectAxisInverseScale(state, 'xAxis', xAxisId, isPanorama));\n};\n\n/**\n * Returns a function to convert pixel coordinates back to data values for an {@link XAxis},\n * but snapping to the closest data point.\n *\n * This is similar to {@link useXAxisInverseScale}, but instead of returning the exact data value\n * at the pixel position (interpolation), it returns the value of the closest data point.\n *\n * This is useful for implementing interactions where you want to select the closest data point\n * rather than an exact value or a tick.\n *\n * This hook must be used within a chart context (inside a {@link LineChart}, {@link BarChart}, etc.).\n * Returns `undefined` if used outside a chart context, or if the axes don't exist.\n *\n * @param xAxisId The `xAxisId` of the XAxis. Defaults to `0` if not provided.\n * @returns An inverse scale function that maps pixel coordinates to the closest data value, or `undefined`.\n * @since 3.8\n */\nexport const useXAxisInverseDataSnapScale = (xAxisId: AxisId = defaultAxisId): InverseScaleFunction | undefined => {\n  const isPanorama = useIsPanorama();\n  return useAppSelector(state => selectAxisInverseDataSnapScale(state, 'xAxis', xAxisId, isPanorama));\n};\n\n/**\n * Returns a function to convert pixel coordinates back to data values for an {@link XAxis},\n * but snapping to the closest axis tick.\n *\n * This is similar to {@link useXAxisInverseScale}, but instead of returning the exact data value\n * at the pixel position (interpolation), it returns the value of the closest tick.\n *\n * This is useful for implementing interactions where you want to select the closest tick\n * rather than an exact value or a data point.\n *\n * This hook must be used within a chart context (inside a {@link LineChart}, {@link BarChart}, etc.).\n * Returns `undefined` if used outside a chart context, or if the axes don't exist.\n *\n * @param xAxisId The `xAxisId` of the XAxis. Defaults to `0` if not provided.\n * @returns An inverse scale function that maps pixel coordinates to the closest tick value, or `undefined`.\n * @since 3.8\n */\nexport const useXAxisInverseTickSnapScale = (xAxisId: AxisId = defaultAxisId): InverseScaleFunction | undefined => {\n  return useAppSelector(state => selectAxisInverseTickSnapScale(state, 'xAxis', xAxisId));\n};\n\n/**\n * Returns a function to convert pixel coordinates back to data values for a {@link YAxis}.\n *\n * This is useful for implementing interactions like click-to-add-annotation,\n * drag interactions, or tooltips that need to determine what data point\n * corresponds to a mouse position.\n *\n * For continuous (numerical) scales, returns an interpolated value.\n * For categorical scales, returns the closest category in the domain - which is the same behaviour as {@link useYAxisInverseDataSnapScale}.\n *\n * This hook must be used within a chart context (inside a {@link LineChart}, {@link BarChart}, etc.).\n * Returns `undefined` if used outside a chart context, or if the axes don't exist.\n *\n * @example\n * ```tsx\n * const yInverseScale = useYAxisInverseScale();\n * if (yInverseScale) {\n *   const dataValue = yInverseScale(200); // Returns the data value at pixel y=200\n * }\n * ```\n *\n * @param yAxisId The `yAxisId` of the YAxis. Defaults to `0` if not provided.\n * @returns An inverse scale function that maps pixel coordinates to data values, or `undefined`.\n * @since 3.8\n */\nexport const useYAxisInverseScale = (yAxisId: AxisId = defaultAxisId): InverseScaleFunction | undefined => {\n  const isPanorama = useIsPanorama();\n  return useAppSelector(state => selectAxisInverseScale(state, 'yAxis', yAxisId, isPanorama));\n};\n\n/**\n * Returns a function to convert pixel coordinates back to data values for a {@link YAxis},\n * but snapping to the closest data point.\n *\n * This is similar to {@link useYAxisInverseScale}, but instead of returning the exact data value\n * at the pixel position (interpolation), it returns the value of the closest data point.\n *\n * This is useful for implementing interactions where you want to select the closest data point\n * rather than an exact value or a tick.\n *\n * This hook must be used within a chart context (inside a {@link LineChart}, {@link BarChart}, etc.).\n * Returns `undefined` if used outside a chart context, or if the axes don't exist.\n *\n * @param yAxisId The `yAxisId` of the YAxis. Defaults to `0` if not provided.\n * @returns An inverse scale function that maps pixel coordinates to the closest data value, or `undefined`.\n * @since 3.8\n */\nexport const useYAxisInverseDataSnapScale = (yAxisId: AxisId = defaultAxisId): InverseScaleFunction | undefined => {\n  const isPanorama = useIsPanorama();\n  return useAppSelector(state => selectAxisInverseDataSnapScale(state, 'yAxis', yAxisId, isPanorama));\n};\n\n/**\n * Returns a function to convert pixel coordinates back to data values for a {@link YAxis},\n * but snapping to the closest axis tick.\n *\n * This is similar to {@link useYAxisInverseScale}, but instead of returning the exact data value\n * at the pixel position (interpolation), it returns the value of the closest tick.\n *\n * This is useful for implementing interactions where you want to select the closest tick\n * rather than an exact value or a data point.\n *\n * This hook must be used within a chart context (inside a {@link LineChart}, {@link BarChart}, etc.).\n * Returns `undefined` if used outside a chart context, or if the axes don't exist.\n *\n * @param yAxisId The `yAxisId` of the YAxis. Defaults to `0` if not provided.\n * @returns An inverse scale function that maps pixel coordinates to the closest tick value, or `undefined`.\n * @since 3.8\n */\nexport const useYAxisInverseTickSnapScale = (yAxisId: AxisId = defaultAxisId): InverseScaleFunction | undefined => {\n  return useAppSelector(state => selectAxisInverseTickSnapScale(state, 'yAxis', yAxisId));\n};\n\n/**\n * Returns the ticks of an {@link XAxis}.\n *\n * This hook is useful for accessing the calculated ticks of an XAxis.\n * The ticks are the same as the ones rendered by the XAxis component.\n *\n * @param xAxisId The `xAxisId` of the XAxis. Defaults to `0` if not provided.\n * @returns An array of ticks, or `undefined` if the axis doesn't exist or hasn't been calculated yet.\n * @since 3.8\n */\nexport const useXAxisTicks = (xAxisId: AxisId = defaultAxisId): ReadonlyArray<TickItem> | undefined => {\n  return useAppSelector(state => selectRenderedTicksOfAxis(state, 'xAxis', xAxisId));\n};\n\n/**\n * Returns the ticks of a {@link YAxis}.\n *\n * This hook is useful for accessing the calculated ticks of a YAxis.\n * The ticks are the same as the ones rendered by the YAxis component.\n *\n * @param yAxisId The `yAxisId` of the YAxis. Defaults to `0` if not provided.\n * @returns An array of ticks, or `undefined` if the axis doesn't exist or hasn't been calculated yet.\n * @since 3.8\n */\nexport const useYAxisTicks = (yAxisId: AxisId = defaultAxisId): ReadonlyArray<TickItem> | undefined => {\n  return useAppSelector(state => selectRenderedTicksOfAxis(state, 'yAxis', yAxisId));\n};\n\n/**\n * Data point with x and y values that can be converted to pixel coordinates.\n * The x and y values should be in the same format as your chart data.\n */\nexport type CartesianDataPoint = {\n  x: number | string;\n  y: number | string;\n};\n\n/**\n * Converts a data point (in data coordinates) to pixel coordinates.\n *\n * This hook is useful for positioning annotations, custom shapes, or other elements\n * at specific data points on the chart. It uses the axis scales to convert\n * data values to their corresponding pixel positions within the chart area.\n *\n * This hook must be used within a chart context (inside a {@link LineChart}, {@link BarChart}, etc.).\n * Returns `undefined` if used outside a chart context, or if the axes don't exist, or if the data point\n * cannot be converted (e.g., if the data values are outside the axis domains).\n *\n * This is a convenience hook that combines {@link useXAxisScale} and {@link useYAxisScale} together in a single call.\n *\n * @example\n * ```tsx\n * // Position a marker at data point { x: 'Page C', y: 2500 }\n * const pixelCoords = useCartesianScale({ x: 'Page C', y: 2500 });\n * if (pixelCoords) {\n *   return <circle cx={pixelCoords.x} cy={pixelCoords.y} r={5} fill=\"red\" />;\n * }\n * ```\n *\n * @param dataPoint The data point with x and y values in data coordinates.\n * @param xAxisId The `xAxisId` of the X-axis. Defaults to `0` if not provided.\n * @param yAxisId The `yAxisId` of the Y-axis. Defaults to `0` if not provided.\n * @returns The pixel x,y coordinates, or `undefined` if conversion is not possible.\n * @since 3.8\n */\nexport const useCartesianScale = (\n  dataPoint: CartesianDataPoint,\n  xAxisId: AxisId = defaultAxisId,\n  yAxisId: AxisId = defaultAxisId,\n): Coordinate | undefined => {\n  const xScale = useXAxisScale(xAxisId);\n  const yScale = useYAxisScale(yAxisId);\n\n  if (xScale == null || yScale == null) {\n    return undefined;\n  }\n\n  const pixelX = xScale(dataPoint.x);\n  const pixelY = yScale(dataPoint.y);\n\n  if (pixelX == null || pixelY == null) {\n    return undefined;\n  }\n\n  return { x: pixelX, y: pixelY };\n};\n\n/**\n * Returns the active tooltip label. The label is one of the values from the chart data,\n * and is used to display in the tooltip content.\n *\n * Returns undefined if there is no active user interaction or if used outside a chart context\n *\n * @returns ActiveLabel\n * @since 3.0\n */\nexport const useActiveTooltipLabel = (): ActiveLabel => {\n  return useAppSelector(selectActiveLabel);\n};\n\n/**\n * Returns the offset of the chart in pixels.\n *\n * Offset defines the blank space between the chart and the plot area.\n * This blank space is occupied by supporting elements like axes, legends, and brushes.\n *\n * The offset includes:\n *\n * - Margins\n * - Width and height of the axes\n * - Width and height of the legend\n * - Brush height\n *\n * If you are interested in the margin alone, use {@link useMargin} instead.\n *\n * The offset is independent of charts position on the page, meaning it does not change as the chart is scrolled or resized.\n *\n * It is also independent of the scale and zoom, meaning that as the user zooms in and out,\n * the numbers will not change as the chart gets visually larger or smaller.\n *\n * This hook must be used within a chart context (inside a `<LineChart>`, `<BarChart>`, etc.).\n * This hook returns `undefined` if used outside a chart context.\n *\n * @returns Offset of the chart in pixels, or undefined if used outside a chart context.\n * @since 3.1\n */\nexport const useOffset = (): ChartOffset | undefined => {\n  return useAppSelector(selectChartOffset);\n};\n\n/**\n * Plot area is the area where the actual chart data is rendered.\n * This means: bars, lines, scatter points, etc.\n *\n * The plot area is calculated based on the chart dimensions and the offset.\n *\n * Plot area `width` and `height` are the dimensions in pixels;\n * `x` and `y` are the coordinates of the top-left corner of the plot area relative to the chart container.\n *\n * They are also independent of the scale and zoom, meaning that as the user zooms in and out,\n * the plot area dimensions will not change as the chart gets visually larger or smaller.\n *\n * This hook must be used within a chart context (inside a `<LineChart>`, `<BarChart>`, etc.).\n * This hook returns `undefined` if used outside a chart context.\n *\n * @returns Plot area of the chart in pixels, or undefined if used outside a chart context.\n * @since 3.1\n */\nexport const usePlotArea = (): PlotArea | undefined => {\n  return useAppSelector(selectPlotArea);\n};\n\n/**\n * Returns the currently active data points being displayed in the Tooltip.\n * Active means that it is currently visible; this hook will return `undefined` if there is no current interaction.\n *\n * This follows the `<Tooltip />` props, if the Tooltip element is present in the chart.\n * If there is no `<Tooltip />` then this hook will follow the default Tooltip props.\n *\n * Data point is whatever you pass as an input to the chart using the `data={}` prop.\n *\n * This returns an array because a chart can have multiple graphical items in it (multiple Lines for example)\n * and tooltip with `shared={true}` will display all items at the same time.\n *\n * Returns undefined when used outside a chart context.\n *\n * @returns Data points that are currently visible in a Tooltip\n */\nexport const useActiveTooltipDataPoints = <T = unknown>(): ReadonlyArray<T> | undefined => {\n  return useAppSelector(selectActiveTooltipDataPoints);\n};\n\n/**\n * Returns the calculated domain of an X-axis.\n *\n * The domain can be numerical: `[min, max]`, or categorical: `['a', 'b', 'c']`.\n *\n * The type of the domain is defined by the `type` prop of the XAxis.\n *\n * The values of the domain are calculated based on the data and the `dataKey` of the axis.\n *\n * If the chart has a Brush, the domain will be filtered to the brushed indexes if the hook is used outside a Brush context,\n * and the full domain will be returned if the hook is used inside a Brush context.\n *\n * @param xAxisId The `xAxisId` of the X-axis. Defaults to `0` if not provided.\n * @returns The domain of the X-axis, or `undefined` if it cannot be calculated or if used outside a chart context.\n * @since 3.2\n */\nexport const useXAxisDomain = (xAxisId: AxisId = defaultAxisId): NumberDomain | CategoricalDomain | undefined => {\n  const isPanorama = useIsPanorama();\n  return useAppSelector(state => selectAxisDomain(state, 'xAxis', xAxisId, isPanorama));\n};\n\n/**\n * Returns the calculated domain of a Y-axis.\n *\n * The domain can be numerical: `[min, max]`, or categorical: `['a', 'b', 'c']`.\n *\n * The type of the domain is defined by the `type` prop of the YAxis.\n *\n * The values of the domain are calculated based on the data and the `dataKey` of the axis.\n *\n * Does not interact with Brushes, as Y-axes do not support brushing.\n *\n * @param yAxisId The `yAxisId` of the Y-axis. Defaults to `0` if not provided.\n * @returns The domain of the Y-axis, or `undefined` if it cannot be calculated or if used outside a chart context.\n * @since 3.2\n */\nexport const useYAxisDomain = (yAxisId: AxisId = defaultAxisId): NumberDomain | CategoricalDomain | undefined => {\n  const isPanorama = useIsPanorama();\n  return useAppSelector(state => selectAxisDomain(state, 'yAxis', yAxisId, isPanorama));\n};\n\n/**\n * Returns true if the {@link Tooltip} is currently active (visible).\n *\n * Returns false if the Tooltip is not active or if used outside a chart context.\n *\n * Recharts only allows one Tooltip per chart, so this hook does not take any parameters.\n * Weird things may happen if you have multiple Tooltip components in the same chart so please don't do that.\n *\n * @returns {boolean} True if the Tooltip is active, false otherwise.\n * @since 3.7\n */\nexport const useIsTooltipActive = (): boolean => {\n  return useAppSelector(selectIsTooltipActive) ?? false;\n};\n\n/**\n * Returns the Cartesian `x` + `y` coordinates of the active {@link Tooltip}.\n *\n * Returns undefined if there is no active user interaction or if used outside a chart context.\n *\n * Recharts only allows one Tooltip per chart, so this hook does not take any parameters.\n * Weird things may happen if you have multiple Tooltip components in the same chart so please don't do that.\n *\n * @returns {Coordinate | undefined} The coordinate of the active Tooltip, or undefined.\n * @since 3.7\n */\nexport const useActiveTooltipCoordinate = (): Coordinate | undefined => {\n  const coordinate = useAppSelector(selectActiveTooltipCoordinate);\n  if (coordinate == null) {\n    return undefined;\n  }\n  return {\n    x: coordinate.x,\n    y: coordinate.y,\n  };\n};\n","import * as React from 'react';\nimport { cloneElement, isValidElement } from 'react';\nimport { ActiveDotProps, ActiveDotType, adaptEventHandlers, DataKey } from '../util/types';\nimport { Dot } from '../shape/Dot';\nimport { Layer } from '../container/Layer';\nimport { useAppSelector } from '../state/hooks';\nimport { selectActiveTooltipIndex } from '../state/selectors/tooltipSelectors';\nimport { useActiveTooltipDataPoints } from '../hooks';\nimport { isNullish } from '../util/DataUtils';\nimport { svgPropertiesNoEventsFromUnknown } from '../util/svgPropertiesNoEvents';\nimport { ZIndexable, ZIndexLayer } from '../zIndex/ZIndexLayer';\nimport { DefaultZIndexes } from '../zIndex/DefaultZIndexes';\n\nexport interface PointType {\n  readonly x: number | null;\n  readonly y: number | null;\n  readonly value?: any;\n  readonly payload?: any;\n}\n\nconst ActivePoint = ({\n  point,\n  childIndex,\n  mainColor,\n  activeDot,\n  dataKey,\n  clipPath,\n}: {\n  point: PointType;\n  activeDot: ActiveDotType;\n  childIndex: number;\n  dataKey: DataKey<any> | undefined;\n  /**\n   * Different graphical elements have different opinion on what is their main color.\n   * Sometimes stroke, sometimes fill, sometimes combination.\n   */\n  mainColor: string | undefined;\n  clipPath?: string;\n}) => {\n  if (activeDot === false || point.x == null || point.y == null) {\n    return null;\n  }\n  const dotPropsTyped: ActiveDotProps = {\n    index: childIndex,\n    dataKey,\n    cx: point.x,\n    cy: point.y,\n    r: 4,\n    fill: mainColor ?? 'none',\n    strokeWidth: 2,\n    stroke: '#fff',\n    payload: point.payload,\n    value: point.value,\n  };\n\n  // @ts-expect-error svgPropertiesNoEventsFromUnknown(activeDot) is contributing unknown props\n  const dotProps: ActiveDotProps = {\n    ...dotPropsTyped,\n    ...svgPropertiesNoEventsFromUnknown(activeDot),\n    ...adaptEventHandlers(activeDot),\n  };\n\n  let dot;\n\n  if (isValidElement(activeDot)) {\n    // @ts-expect-error we're improperly typing events\n    dot = cloneElement(activeDot, dotProps);\n  } else if (typeof activeDot === 'function') {\n    dot = activeDot(dotProps);\n  } else {\n    dot = <Dot {...dotProps} />;\n  }\n\n  return (\n    <Layer className=\"recharts-active-dot\" clipPath={clipPath}>\n      {dot}\n    </Layer>\n  );\n};\n\ninterface ActivePointsProps extends ZIndexable {\n  points: ReadonlyArray<PointType>;\n  /**\n   * Different graphical elements have different opinion on what is their main color.\n   * Sometimes stroke, sometimes fill, sometimes combination.\n   * `undefined` means that the color is not set, and the point will be transparent.\n   */\n  mainColor: string | undefined;\n  itemDataKey: DataKey<any> | undefined;\n  activeDot: ActiveDotType;\n  clipPath?: string;\n}\n\nexport function ActivePoints({\n  points,\n  mainColor,\n  activeDot,\n  itemDataKey,\n  clipPath,\n  zIndex = DefaultZIndexes.activeDot,\n}: ActivePointsProps) {\n  const activeTooltipIndex = useAppSelector(selectActiveTooltipIndex);\n  const activeDataPoints = useActiveTooltipDataPoints();\n  if (points == null || activeDataPoints == null) {\n    return null;\n  }\n\n  const activePoint: PointType | undefined = points.find(p => activeDataPoints.includes(p.payload));\n\n  if (isNullish(activePoint)) {\n    return null;\n  }\n\n  return (\n    <ZIndexLayer zIndex={zIndex}>\n      <ActivePoint\n        point={activePoint}\n        childIndex={Number(activeTooltipIndex)}\n        mainColor={mainColor}\n        dataKey={itemDataKey}\n        activeDot={activeDot}\n        clipPath={clipPath}\n      />\n    </ZIndexLayer>\n  );\n}\n","import { createSelector } from 'reselect';\nimport { RechartsRootState } from '../store';\nimport { AngleAxisForRadar, computeRadarPoints, RadarComposedData, RadiusAxisForRadar } from '../../polar/Radar';\nimport { BaseAxisWithScale } from './axisSelectors';\nimport { selectPolarAxisScale, selectPolarAxisTicks } from './polarScaleSelectors';\nimport { selectAngleAxis, selectPolarViewBox, selectRadiusAxis } from './polarAxisSelectors';\nimport { AxisId } from '../cartesianAxisSlice';\nimport { selectChartDataAndAlwaysIgnoreIndexes } from './dataSelectors';\nimport { ChartDataState } from '../chartDataSlice';\nimport { DataKey, LayoutType, PolarViewBoxRequired, TickItem } from '../../util/types';\nimport { selectChartLayout } from '../../context/chartLayoutContext';\nimport { getBandSizeOfAxis, isCategoricalAxis } from '../../util/ChartUtils';\nimport { AngleAxisSettings, RadiusAxisSettings } from '../polarAxisSlice';\nimport { selectUnfilteredPolarItems } from './polarSelectors';\nimport { GraphicalItemId } from '../graphicalItemsSlice';\nimport { RechartsScale } from '../../util/scale/RechartsScale';\n\nconst selectRadiusAxisScale = (state: RechartsRootState, radiusAxisId: AxisId): RechartsScale | undefined =>\n  selectPolarAxisScale(state, 'radiusAxis', radiusAxisId);\n\nconst selectRadiusAxisForRadar: (state: RechartsRootState, radiusAxisId: AxisId) => RadiusAxisForRadar | undefined =\n  createSelector([selectRadiusAxisScale], (scale: RechartsScale | undefined): RadiusAxisForRadar | undefined => {\n    if (scale == null) {\n      return undefined;\n    }\n    return { scale };\n  });\n\nexport const selectRadiusAxisForBandSize: (\n  state: RechartsRootState,\n  radiusAxisId: AxisId,\n) => BaseAxisWithScale | undefined = createSelector(\n  [selectRadiusAxis, selectRadiusAxisScale],\n  (axisSettings: RadiusAxisSettings | undefined, scale: RechartsScale | undefined): BaseAxisWithScale | undefined => {\n    if (axisSettings == null || scale == null) {\n      return undefined;\n    }\n    return {\n      ...axisSettings,\n      scale,\n    };\n  },\n);\n\nconst selectRadiusAxisTicks = (\n  state: RechartsRootState,\n  radiusAxisId: AxisId,\n  _angleAxisId: AxisId,\n  isPanorama: boolean,\n): ReadonlyArray<TickItem> | undefined => {\n  return selectPolarAxisTicks(state, 'radiusAxis', radiusAxisId, isPanorama);\n};\n\nconst selectAngleAxisForRadar = (\n  state: RechartsRootState,\n  _radiusAxisId: AxisId,\n  angleAxisId: AxisId,\n): AngleAxisSettings => selectAngleAxis(state, angleAxisId);\n\nconst selectPolarAxisScaleForRadar = (\n  state: RechartsRootState,\n  _radiusAxisId: AxisId,\n  angleAxisId: AxisId,\n): RechartsScale | undefined => selectPolarAxisScale(state, 'angleAxis', angleAxisId);\n\nexport const selectAngleAxisForBandSize: (\n  state: RechartsRootState,\n  _radiusAxisId: AxisId,\n  angleAxisId: AxisId,\n) => BaseAxisWithScale | undefined = createSelector(\n  [selectAngleAxisForRadar, selectPolarAxisScaleForRadar],\n  (axisSettings: AngleAxisSettings, scale: RechartsScale | undefined): BaseAxisWithScale | undefined => {\n    if (axisSettings == null || scale == null) {\n      return undefined;\n    }\n    return {\n      ...axisSettings,\n      scale,\n    };\n  },\n);\n\nconst selectAngleAxisTicks = (\n  state: RechartsRootState,\n  _radiusAxisId: AxisId,\n  angleAxisId: AxisId,\n  isPanorama: boolean,\n): ReadonlyArray<TickItem> | undefined => {\n  return selectPolarAxisTicks(state, 'angleAxis', angleAxisId, isPanorama);\n};\n\nexport const selectAngleAxisWithScaleAndViewport: (\n  state: RechartsRootState,\n  _radiusAxisId: AxisId,\n  angleAxisId: AxisId,\n) => AngleAxisForRadar | undefined = createSelector(\n  [selectAngleAxisForRadar, selectPolarAxisScaleForRadar, selectPolarViewBox],\n  (\n    axisOptions: AngleAxisSettings,\n    scale: RechartsScale | undefined,\n    polarViewBox: PolarViewBoxRequired | undefined,\n  ): AngleAxisForRadar | undefined => {\n    if (polarViewBox == null || scale == null) {\n      return undefined;\n    }\n    return {\n      scale,\n      type: axisOptions.type,\n      dataKey: axisOptions.dataKey,\n      cx: polarViewBox.cx,\n      cy: polarViewBox.cy,\n    };\n  },\n);\n\nconst pickId = (\n  _state: RechartsRootState,\n  _radiusAxisId: AxisId,\n  _angleAxisId: AxisId,\n  _isPanorama: boolean,\n  radarId: GraphicalItemId,\n): GraphicalItemId => radarId;\n\nconst selectBandSizeOfAxis: (\n  state: RechartsRootState,\n  radiusAxisId: AxisId,\n  angleAxisId: AxisId,\n  isPanorama: boolean,\n  radarId: GraphicalItemId,\n) => number | undefined = createSelector(\n  [\n    selectChartLayout,\n    selectRadiusAxisForBandSize,\n    selectRadiusAxisTicks,\n    selectAngleAxisForBandSize,\n    selectAngleAxisTicks,\n  ],\n  (\n    layout: LayoutType,\n    radiusAxis: BaseAxisWithScale | undefined,\n    radiusAxisTicks: ReadonlyArray<TickItem> | undefined,\n    angleAxis: BaseAxisWithScale | undefined,\n    angleAxisTicks: ReadonlyArray<TickItem> | undefined,\n  ) => {\n    if (isCategoricalAxis(layout, 'radiusAxis')) {\n      return getBandSizeOfAxis(radiusAxis, radiusAxisTicks, false);\n    }\n    return getBandSizeOfAxis(angleAxis, angleAxisTicks, false);\n  },\n);\n\nconst selectSynchronisedRadarDataKey: (\n  state: RechartsRootState,\n  _radiusAxisId: AxisId,\n  _angleAxisId: AxisId,\n  _isPanorama: boolean,\n  radarId: GraphicalItemId,\n) => DataKey<any> | undefined = createSelector([selectUnfilteredPolarItems, pickId], (graphicalItems, radarId) => {\n  if (graphicalItems == null) {\n    return undefined;\n  }\n  // Find the radar item with the given radarId\n  const pgis = graphicalItems.find(item => item.type === 'radar' && radarId === item.id);\n  // If found, return its dataKey\n  return pgis?.dataKey;\n});\n\nexport const selectRadarPoints: (\n  state: RechartsRootState,\n  radiusAxisId: AxisId,\n  angleAxisId: AxisId,\n  isPanorama: boolean,\n  radarId: GraphicalItemId,\n) => RadarComposedData | undefined = createSelector(\n  [\n    selectRadiusAxisForRadar,\n    selectAngleAxisWithScaleAndViewport,\n    selectChartDataAndAlwaysIgnoreIndexes,\n    selectSynchronisedRadarDataKey,\n    selectBandSizeOfAxis,\n  ],\n  (\n    radiusAxis: RadiusAxisForRadar | undefined,\n    angleAxis: AngleAxisForRadar | undefined,\n    { chartData, dataStartIndex, dataEndIndex }: ChartDataState,\n    dataKey: DataKey<any> | undefined,\n    bandSize: number | undefined,\n  ): RadarComposedData | undefined => {\n    if (radiusAxis == null || angleAxis == null || chartData == null || bandSize == null || dataKey == null) {\n      return undefined;\n    }\n    const displayedData = chartData.slice(dataStartIndex, dataEndIndex + 1);\n    return computeRadarPoints({\n      radiusAxis,\n      angleAxis,\n      displayedData,\n      dataKey,\n      bandSize,\n    });\n  },\n);\n","import * as React from 'react';\nimport { MouseEvent, MutableRefObject, ReactElement, ReactNode, SVGProps, useCallback, useRef, useState } from 'react';\nimport last from 'es-toolkit/compat/last';\n\nimport { clsx } from 'clsx';\nimport { interpolate, isNullish, noop } from '../util/DataUtils';\nimport { polarToCartesian } from '../util/PolarUtils';\nimport { getTooltipNameProp, getValueByDataKey } from '../util/ChartUtils';\nimport { Polygon } from '../shape/Polygon';\nimport { Layer } from '../container/Layer';\nimport {\n  CartesianLabelListContextProvider,\n  CartesianLabelListEntry,\n  ImplicitLabelListType,\n  LabelListFromLabelProp,\n} from '../component/LabelList';\nimport { Dots } from '../component/Dots';\nimport {\n  ActiveDotType,\n  AnimationDuration,\n  AnimationTiming,\n  DataConsumer,\n  DataKey,\n  DotType,\n  LegendType,\n  TooltipType,\n  TrapezoidViewBox,\n} from '../util/types';\nimport type { LegendPayload } from '../component/DefaultLegendContent';\nimport { ActivePoints } from '../component/ActivePoints';\nimport { TooltipPayloadConfiguration } from '../state/tooltipSlice';\nimport { SetTooltipEntrySettings } from '../state/SetTooltipEntrySettings';\nimport { selectRadarPoints } from '../state/selectors/radarSelectors';\nimport { useAppSelector } from '../state/hooks';\nimport { useIsPanorama } from '../context/PanoramaContext';\nimport { SetPolarLegendPayload } from '../state/SetLegendPayload';\nimport { useAnimationId } from '../util/useAnimationId';\nimport { RegisterGraphicalItemId } from '../context/RegisterGraphicalItemId';\nimport { SetPolarGraphicalItem } from '../state/SetGraphicalItem';\nimport { svgPropertiesNoEvents } from '../util/svgPropertiesNoEvents';\nimport { JavascriptAnimate } from '../animation/JavascriptAnimate';\nimport { svgPropertiesAndEvents } from '../util/svgPropertiesAndEvents';\nimport { RequiresDefaultProps, resolveDefaultProps } from '../util/resolveDefaultProps';\nimport { WithIdRequired } from '../util/useUniqueId';\nimport { ZIndexable, ZIndexLayer } from '../zIndex/ZIndexLayer';\nimport { DefaultZIndexes } from '../zIndex/DefaultZIndexes';\nimport { RechartsScale } from '../util/scale/RechartsScale';\n\nexport interface RadarPoint {\n  x: number;\n  y: number;\n  cx?: number;\n  cy?: number;\n  angle: number;\n  radius?: number;\n  value?: number;\n  payload?: any;\n  name?: string | number;\n}\n\ninterface RadarProps<DataPointType = any, DataValueType = any>\n  extends ZIndexable, DataConsumer<DataPointType, DataValueType> {\n  /**\n   * @defaultValue true\n   */\n  activeDot?: ActiveDotType;\n  /**\n   * @defaultValue 0\n   */\n  angleAxisId?: string | number;\n  /**\n   * Specifies when the animation should begin, the unit of this option is ms.\n   * @defaultValue 0\n   */\n  animationBegin?: number;\n  /**\n   * Specifies the duration of animation, the unit of this option is ms.\n   * @defaultValue 1500\n   */\n  animationDuration?: AnimationDuration;\n  /**\n   * The type of easing function.\n   * @defaultValue ease\n   */\n  animationEasing?: AnimationTiming;\n  baseLinePoints?: RadarPoint[];\n  className?: string;\n  connectNulls?: boolean;\n  /**\n   * Renders a circle element at each data point. Options:\n   *\n   * - `false`: no dots are drawn;\n   * - `true`: renders the dots with default settings;\n   * - `object`: the props of the dot. This will be merged with the internal calculated props of each dot;\n   * - `ReactElement`: the custom dot element;\n   * - `function`: a render function of the custom dot.\n   *\n   * @defaultValue false\n   */\n  dot?: DotType;\n  /**\n   * @defaultValue false\n   */\n  hide?: boolean;\n  /**\n   * If set false, animation of polygon will be disabled.\n   * If set \"auto\", the animation will be disabled in SSR and will respect the user's prefers-reduced-motion system preference for accessibility.\n   * @defaultValue auto\n   */\n  isAnimationActive?: boolean | 'auto';\n  isRange?: boolean;\n  /**\n   * Renders one label for each point. Options:\n   * - `true`: renders default labels;\n   * - `false`: no labels are rendered;\n   * - `object`: the props of LabelList component;\n   * - `ReactElement`: a custom label element;\n   * - `function`: a render function of custom label.\n   *\n   * @defaultValue false\n   */\n  label?: ImplicitLabelListType;\n  /**\n   * The type of icon in legend.  If set to 'none', no legend item will be rendered.\n   * @defaultValue rect\n   */\n  legendType?: LegendType;\n  /**\n   * The customized event handler of animation end\n   */\n  onAnimationEnd?: () => void;\n  /**\n   * The customized event handler of animation start\n   */\n  onAnimationStart?: () => void;\n  onMouseEnter?: (props: InternalRadarProps, e: MouseEvent<SVGPolygonElement>) => void;\n  onMouseLeave?: (props: InternalRadarProps, e: MouseEvent<SVGPolygonElement>) => void;\n  /**\n   * @defaultValue 0\n   */\n  radiusAxisId?: string | number;\n\n  /**\n   * If set a ReactElement, the shape of radar can be customized.\n   * If set a function, the function will be called to render customized shape.\n   */\n  shape?: ReactElement<SVGElement> | ((props: any) => ReactElement<SVGElement>);\n  tooltipType?: TooltipType;\n  /**\n   * @defaultValue 100\n   */\n  zIndex?: number;\n}\n\nexport type RadiusAxisForRadar = { scale: RechartsScale };\nexport type AngleAxisForRadar = {\n  scale: RechartsScale;\n  type: 'number' | 'category';\n  dataKey: DataKey<any> | undefined;\n  cx: number;\n  cy: number;\n};\n\nexport type Props<DataPointType = any, DataValueType = any> = Omit<\n  SVGProps<SVGGraphicsElement>,\n  'onMouseEnter' | 'onMouseLeave' | 'points' | 'ref'\n> &\n  RadarProps<DataPointType, DataValueType>;\n\nexport type RadarComposedData = {\n  points: RadarPoint[];\n  baseLinePoints: RadarPoint[];\n  isRange: boolean;\n};\n\nfunction getLegendItemColor(stroke: string | undefined, fill: string | undefined): string | undefined {\n  return stroke && stroke !== 'none' ? stroke : fill;\n}\n\nconst computeLegendPayloadFromRadarSectors = (props: PropsWithDefaults): ReadonlyArray<LegendPayload> => {\n  const { dataKey, name, stroke, fill, legendType, hide } = props;\n  return [\n    {\n      inactive: hide,\n      dataKey,\n      type: legendType,\n      color: getLegendItemColor(stroke, fill),\n      value: getTooltipNameProp(name, dataKey),\n      payload: props,\n    },\n  ];\n};\n\nconst SetRadarTooltipEntrySettings = React.memo(\n  ({\n    dataKey,\n    stroke,\n    strokeWidth,\n    fill,\n    name,\n    hide,\n    tooltipType,\n    id,\n  }: Pick<\n    WithIdRequired<PropsWithDefaults>,\n    'dataKey' | 'stroke' | 'strokeWidth' | 'fill' | 'name' | 'hide' | 'tooltipType' | 'id'\n  >) => {\n    const tooltipEntrySettings: TooltipPayloadConfiguration = {\n      /*\n       * I suppose this here _could_ return props.points\n       * because while Radar does not support item tooltip mode, it _could_ support it.\n       * But when I actually do return the points here, a defaultIndex test starts failing.\n       * So, undefined it is.\n       */\n      dataDefinedOnItem: undefined,\n      getPosition: noop,\n      settings: {\n        stroke,\n        strokeWidth,\n        fill,\n        nameKey: undefined, // RadarChart does not have nameKey unfortunately\n        dataKey,\n        name: getTooltipNameProp(name, dataKey),\n        hide,\n        type: tooltipType,\n        color: getLegendItemColor(stroke, fill),\n        unit: '', // why doesn't Radar support unit?\n        graphicalItemId: id,\n      },\n    };\n    return <SetTooltipEntrySettings tooltipEntrySettings={tooltipEntrySettings} />;\n  },\n);\n\nfunction RadarDotsWrapper({ points, props }: { points: ReadonlyArray<RadarPoint>; props: PropsWithDefaults }) {\n  const { dot, dataKey } = props;\n  const { id, ...propsWithoutId } = props;\n\n  const baseProps = svgPropertiesNoEvents(propsWithoutId);\n\n  return (\n    <Dots\n      points={points}\n      dot={dot}\n      className=\"recharts-radar-dots\"\n      dotClassName=\"recharts-radar-dot\"\n      dataKey={dataKey}\n      baseProps={baseProps}\n    />\n  );\n}\n\nexport function computeRadarPoints({\n  radiusAxis,\n  angleAxis,\n  displayedData,\n  dataKey,\n  bandSize,\n}: {\n  radiusAxis: RadiusAxisForRadar;\n  angleAxis: AngleAxisForRadar;\n  displayedData: any[];\n  dataKey: RadarProps['dataKey'];\n  bandSize: number;\n}): RadarComposedData {\n  const { cx, cy } = angleAxis;\n  let isRange = false;\n  const points: RadarPoint[] = [];\n  const angleBandSize = angleAxis.type !== 'number' ? (bandSize ?? 0) : 0;\n\n  displayedData.forEach((entry, i) => {\n    const name = getValueByDataKey(entry, angleAxis.dataKey, i);\n    const value = getValueByDataKey(entry, dataKey);\n    const angle: number = (angleAxis.scale.map(name) ?? 0) + angleBandSize;\n    const pointValue = Array.isArray(value) ? last(value) : value;\n    const radius: number = isNullish(pointValue) ? 0 : (radiusAxis.scale.map(pointValue) ?? 0);\n\n    if (Array.isArray(value) && value.length >= 2) {\n      isRange = true;\n    }\n\n    points.push({\n      ...polarToCartesian(cx, cy, radius, angle),\n      // getValueByDataKey does not validate the output type\n      name,\n      // getValueByDataKey does not validate the output type\n      value,\n      cx,\n      cy,\n      radius,\n      angle,\n      payload: entry,\n    });\n  });\n  const baseLinePoints: RadarPoint[] = [];\n\n  if (isRange) {\n    points.forEach((point: RadarPoint) => {\n      if (Array.isArray(point.value)) {\n        const baseValue = point.value[0];\n        const radius: number = isNullish(baseValue) ? 0 : (radiusAxis.scale.map(baseValue) ?? 0);\n\n        baseLinePoints.push({\n          ...point,\n          radius,\n          ...polarToCartesian(cx, cy, radius, point.angle),\n        });\n      } else {\n        baseLinePoints.push(point);\n      }\n    });\n  }\n\n  return { points, isRange, baseLinePoints };\n}\n\nfunction RadarLabelListProvider({\n  showLabels,\n  points,\n  children,\n}: {\n  showLabels: boolean;\n  points: ReadonlyArray<RadarPoint>;\n  children: ReactNode;\n}) {\n  /*\n   * Radar provides a Cartesian label list context. Do we want to also provide a polar label list context?\n   * That way, users can choose to use polar positions for the Radar labels.\n   */\n  // const labelListEntries: ReadonlyArray<PolarLabelListEntry> = points.map(\n  //   (point): PolarLabelListEntry => ({\n  //     value: point.value,\n  //     payload: point.payload,\n  //     parentViewBox: undefined,\n  //     clockWise: false,\n  //     viewBox: {\n  //       cx: point.cx,\n  //       cy: point.cy,\n  //       innerRadius: point.radius,\n  //       outerRadius: point.radius,\n  //       startAngle: point.angle,\n  //       endAngle: point.angle,\n  //       clockWise: false,\n  //     },\n  //   }),\n  // );\n\n  const labelListEntries: ReadonlyArray<CartesianLabelListEntry> = points.map((point): CartesianLabelListEntry => {\n    const viewBox: TrapezoidViewBox = {\n      x: point.x,\n      y: point.y,\n      width: 0,\n      lowerWidth: 0,\n      upperWidth: 0,\n      height: 0,\n    };\n    return {\n      ...viewBox,\n      value: point.value ?? '',\n      payload: point.payload,\n      parentViewBox: undefined,\n      viewBox,\n      fill: undefined,\n    };\n  });\n\n  return (\n    <CartesianLabelListContextProvider value={showLabels ? labelListEntries : undefined}>\n      {children}\n    </CartesianLabelListContextProvider>\n  );\n}\n\nfunction StaticPolygon({\n  points,\n  baseLinePoints,\n  props,\n}: {\n  points: ReadonlyArray<RadarPoint>;\n  baseLinePoints: ReadonlyArray<RadarPoint>;\n  props: InternalRadarProps;\n}) {\n  if (points == null) {\n    return null;\n  }\n\n  const { shape, isRange, connectNulls } = props;\n\n  const handleMouseEnter = (e: MouseEvent<SVGPolygonElement>) => {\n    const { onMouseEnter } = props;\n\n    if (onMouseEnter) {\n      onMouseEnter(props, e);\n    }\n  };\n\n  const handleMouseLeave = (e: MouseEvent<SVGPolygonElement>) => {\n    const { onMouseLeave } = props;\n\n    if (onMouseLeave) {\n      onMouseLeave(props, e);\n    }\n  };\n\n  let radar;\n  if (React.isValidElement(shape)) {\n    radar = React.cloneElement(shape, { ...props, points } as any);\n  } else if (typeof shape === 'function') {\n    radar = shape({ ...props, points });\n  } else {\n    radar = (\n      <Polygon\n        {...svgPropertiesAndEvents(props)}\n        onMouseEnter={handleMouseEnter}\n        onMouseLeave={handleMouseLeave}\n        points={points}\n        baseLinePoints={isRange ? baseLinePoints : undefined}\n        connectNulls={connectNulls}\n      />\n    );\n  }\n\n  return (\n    <Layer className=\"recharts-radar-polygon\">\n      {radar}\n      <RadarDotsWrapper props={props} points={points} />\n    </Layer>\n  );\n}\n\nconst interpolatePolarPoint =\n  (prevPoints: ReadonlyArray<RadarPoint> | undefined, prevPointsDiffFactor: number, t: number) =>\n  (entry: RadarPoint, index: number) => {\n    const prev = prevPoints && prevPoints[Math.floor(index * prevPointsDiffFactor)];\n\n    if (prev) {\n      return {\n        ...entry,\n        x: interpolate(prev.x, entry.x, t),\n        y: interpolate(prev.y, entry.y, t),\n      };\n    }\n\n    return {\n      ...entry,\n      x: interpolate(entry.cx, entry.x, t),\n      y: interpolate(entry.cy, entry.y, t),\n    };\n  };\n\nfunction PolygonWithAnimation({\n  props,\n  previousPointsRef,\n  previousBaseLinePointsRef,\n}: {\n  props: InternalRadarProps;\n  previousPointsRef: MutableRefObject<ReadonlyArray<RadarPoint> | undefined>;\n  previousBaseLinePointsRef: MutableRefObject<ReadonlyArray<RadarPoint> | undefined>;\n}) {\n  const {\n    points,\n    baseLinePoints,\n    isAnimationActive,\n    animationBegin,\n    animationDuration,\n    animationEasing,\n    onAnimationEnd,\n    onAnimationStart,\n  } = props;\n  const prevPoints = previousPointsRef.current;\n  const prevBaseLinePoints = previousBaseLinePointsRef.current;\n\n  const prevPointsDiffFactor: number = prevPoints ? prevPoints.length / points.length : 1;\n  const prevBaseLinePointsDiffFactor: number = prevBaseLinePoints\n    ? prevBaseLinePoints.length / baseLinePoints.length\n    : 1;\n\n  const animationId = useAnimationId(props, 'recharts-radar-');\n  const [isAnimating, setIsAnimating] = useState(false);\n  const showLabels = !isAnimating;\n\n  const handleAnimationEnd = useCallback(() => {\n    if (typeof onAnimationEnd === 'function') {\n      onAnimationEnd();\n    }\n    setIsAnimating(false);\n  }, [onAnimationEnd]);\n\n  const handleAnimationStart = useCallback(() => {\n    if (typeof onAnimationStart === 'function') {\n      onAnimationStart();\n    }\n    setIsAnimating(true);\n  }, [onAnimationStart]);\n\n  return (\n    <RadarLabelListProvider showLabels={showLabels} points={points}>\n      <JavascriptAnimate\n        animationId={animationId}\n        begin={animationBegin}\n        duration={animationDuration}\n        isActive={isAnimationActive}\n        easing={animationEasing}\n        key={`radar-${animationId}`}\n        onAnimationEnd={handleAnimationEnd}\n        onAnimationStart={handleAnimationStart}\n      >\n        {(t: number) => {\n          const stepData = t === 1 ? points : points.map(interpolatePolarPoint(prevPoints, prevPointsDiffFactor, t));\n\n          const stepBaseLinePoints =\n            t === 1\n              ? baseLinePoints\n              : baseLinePoints?.map(interpolatePolarPoint(prevBaseLinePoints, prevBaseLinePointsDiffFactor, t));\n\n          if (t > 0) {\n            // eslint-disable-next-line no-param-reassign\n            previousPointsRef.current = stepData;\n            // eslint-disable-next-line no-param-reassign\n            previousBaseLinePointsRef.current = stepBaseLinePoints;\n          }\n          return <StaticPolygon points={stepData} baseLinePoints={stepBaseLinePoints} props={props} />;\n        }}\n      </JavascriptAnimate>\n      <LabelListFromLabelProp label={props.label} />\n      {props.children}\n    </RadarLabelListProvider>\n  );\n}\n\nfunction RenderPolygon(props: InternalRadarProps) {\n  const previousPointsRef = useRef<ReadonlyArray<RadarPoint> | undefined>(undefined);\n  const previousBaseLinePointsRef = useRef<ReadonlyArray<RadarPoint> | undefined>(undefined);\n\n  return (\n    <PolygonWithAnimation\n      props={props}\n      previousPointsRef={previousPointsRef}\n      previousBaseLinePointsRef={previousBaseLinePointsRef}\n    />\n  );\n}\n\nexport const defaultRadarProps = {\n  activeDot: true,\n  angleAxisId: 0,\n  animationBegin: 0,\n  animationDuration: 1500,\n  animationEasing: 'ease',\n  dot: false,\n  hide: false,\n  isAnimationActive: 'auto',\n  label: false,\n  legendType: 'rect',\n  radiusAxisId: 0,\n  zIndex: DefaultZIndexes.area,\n} as const satisfies Partial<Props>;\n\ntype PropsWithDefaults = RequiresDefaultProps<Props, typeof defaultRadarProps>;\n\nexport type InternalRadarProps = WithIdRequired<PropsWithDefaults> & RadarComposedData;\n\nfunction RadarWithState(props: InternalRadarProps) {\n  const { hide, className, points } = props;\n\n  if (hide) {\n    return null;\n  }\n\n  const layerClass = clsx('recharts-radar', className);\n\n  return (\n    <ZIndexLayer zIndex={props.zIndex}>\n      <Layer className={layerClass}>\n        <RenderPolygon {...props} />\n      </Layer>\n      <ActivePoints\n        points={points}\n        mainColor={getLegendItemColor(props.stroke, props.fill)}\n        itemDataKey={props.dataKey}\n        activeDot={props.activeDot}\n      />\n    </ZIndexLayer>\n  );\n}\n\nfunction RadarImpl(props: WithIdRequired<PropsWithDefaults>) {\n  const isPanorama = useIsPanorama();\n  const radarPoints = useAppSelector(state =>\n    selectRadarPoints(state, props.radiusAxisId, props.angleAxisId, isPanorama, props.id),\n  );\n\n  if (radarPoints?.points == null) {\n    return null;\n  }\n\n  return (\n    <RadarWithState\n      {...props}\n      points={radarPoints?.points}\n      baseLinePoints={radarPoints?.baseLinePoints}\n      isRange={radarPoints?.isRange}\n    />\n  );\n}\n\n/**\n * @consumes PolarChartContext\n * @provides LabelListContext\n */\nexport function Radar<DataPointType = any, DataValueType = any>(outsideProps: Props<DataPointType, DataValueType>) {\n  const props: PropsWithDefaults = resolveDefaultProps(outsideProps, defaultRadarProps);\n  return (\n    <RegisterGraphicalItemId id={props.id} type=\"radar\">\n      {id => (\n        <>\n          <SetPolarGraphicalItem\n            type=\"radar\"\n            id={id}\n            data={undefined} // Radar does not have data prop, why?\n            dataKey={props.dataKey}\n            hide={props.hide}\n            angleAxisId={props.angleAxisId}\n            radiusAxisId={props.radiusAxisId}\n          />\n          <SetPolarLegendPayload legendPayload={computeLegendPayloadFromRadarSectors(props)} />\n          <SetRadarTooltipEntrySettings\n            dataKey={props.dataKey}\n            stroke={props.stroke}\n            strokeWidth={props.strokeWidth}\n            fill={props.fill}\n            name={props.name}\n            hide={props.hide}\n            tooltipType={props.tooltipType}\n            id={id}\n          />\n          <RadarImpl {...props} id={id} />\n        </>\n      )}\n    </RegisterGraphicalItemId>\n  );\n}\n\nRadar.displayName = 'Radar';\n","import * as React from 'react';\nimport { RadialBarDataItem, RadialBarProps } from '../polar/RadialBar';\nimport { Shape } from './ActiveShapeUtils';\n\nexport function parseCornerRadius(cornerRadius: string | number | undefined): number | undefined {\n  if (typeof cornerRadius === 'string') {\n    return parseInt(cornerRadius, 10);\n  }\n\n  return cornerRadius;\n}\n\nexport interface RadialBarSectorProps extends RadialBarDataItem {\n  index: number;\n  option: RadialBarProps['activeShape'];\n  isActive: boolean;\n}\n\nexport function RadialBarSector(props: RadialBarSectorProps) {\n  return <Shape shapeType=\"sector\" {...props} />;\n}\n","import { DefinitelyStackedGraphicalItem, isStacked, MaybeStackedGraphicalItem } from '../../types/StackedGraphicalItem';\nimport { StackId } from '../../../util/ChartUtils';\nimport { SizeList } from '../barSelectors';\nimport { getPercentValue, isNullish } from '../../../util/DataUtils';\nimport { DataKey } from '../../../util/types';\n\nconst getBarSize = (\n  globalSize: string | number | undefined,\n  totalSize: number | undefined,\n  selfSize: number | string | undefined,\n): number | undefined => {\n  const barSize: string | number | undefined = selfSize ?? globalSize;\n\n  if (isNullish(barSize)) {\n    return undefined;\n  }\n  return getPercentValue(barSize, totalSize, 0);\n};\n\nexport const combineBarSizeList = (\n  allBars: ReadonlyArray<MaybeStackedGraphicalItem>,\n  globalSize: string | number | undefined,\n  totalSize: number | undefined,\n): SizeList => {\n  const initialValue: Record<StackId, Array<DefinitelyStackedGraphicalItem>> = {};\n\n  const stackedBars: ReadonlyArray<DefinitelyStackedGraphicalItem> = allBars.filter(isStacked);\n  const unstackedBars = allBars.filter(b => b.stackId == null);\n\n  const groupByStack: Record<StackId, Array<DefinitelyStackedGraphicalItem>> = stackedBars.reduce((acc, bar) => {\n    let s = acc[bar.stackId];\n    if (s == null) {\n      s = [];\n    }\n    s.push(bar);\n    acc[bar.stackId] = s;\n    return acc;\n  }, initialValue);\n\n  const stackedSizeList: SizeList = Object.entries(groupByStack).map(([stackId, bars]): BarCategory => {\n    const dataKeys = bars.map(b => b.dataKey);\n    const barSize: number | undefined = getBarSize(globalSize, totalSize, bars[0]?.barSize);\n    return { stackId, dataKeys, barSize };\n  });\n\n  const unstackedSizeList: SizeList = unstackedBars.map((b): BarCategory => {\n    const dataKeys = [b.dataKey].filter(dk => dk != null);\n    const barSize: number | undefined = getBarSize(globalSize, totalSize, b.barSize);\n    return { stackId: undefined, dataKeys, barSize };\n  });\n\n  return [...stackedSizeList, ...unstackedSizeList];\n};\nexport type BarCategory = {\n  stackId: StackId | undefined;\n  /**\n   * List of dataKeys of items stacked at this position.\n   * All of these Bars are either sharing the same stackId,\n   * or this is an array with one Bar because it has no stackId defined.\n   *\n   * This structure limits us to having one dataKey only once per stack which I think is reasonable.\n   * People who want to have the same data twice can duplicate their data to have two distinct dataKeys.\n   */\n  dataKeys: ReadonlyArray<DataKey<any>>;\n  /**\n   * Width (in horizontal chart) or height (in vertical chart) of this stack of items\n   */\n  barSize: number | undefined;\n};\n","import { getPercentValue, isNullish } from '../../../util/DataUtils';\nimport { BarWithPosition, SizeList } from '../barSelectors';\nimport { isWellBehavedNumber } from '../../../util/isWellBehavedNumber';\nimport { BarPositionPosition } from '../../../util/ChartUtils';\nimport { BarCategory } from './combineBarSizeList';\n\nfunction getBarPositions(\n  barGap: string | number,\n  barCategoryGap: string | number,\n  bandSize: number,\n  sizeList: SizeList,\n  maxBarSize: number | undefined,\n): ReadonlyArray<BarWithPosition> | undefined {\n  const len = sizeList.length;\n  if (len < 1) {\n    return undefined;\n  }\n\n  let realBarGap = getPercentValue(barGap, bandSize, 0, true);\n\n  let result: ReadonlyArray<BarWithPosition>;\n  const initialValue: ReadonlyArray<BarWithPosition> = [];\n\n  // whether is barSize set by user\n  // Okay but why does it check only for the first element? What if the first element is set but others are not?\n  if (isWellBehavedNumber(sizeList[0]?.barSize)) {\n    let useFull = false;\n    let fullBarSize: number = bandSize / len;\n    let sum = sizeList.reduce((res, entry) => res + (entry.barSize || 0), 0);\n    sum += (len - 1) * realBarGap;\n\n    if (sum >= bandSize) {\n      sum -= (len - 1) * realBarGap;\n      realBarGap = 0;\n    }\n    if (sum >= bandSize && fullBarSize > 0) {\n      useFull = true;\n      fullBarSize *= 0.9;\n      sum = len * fullBarSize;\n    }\n\n    const offset = ((bandSize - sum) / 2) >> 0;\n    let prev: BarPositionPosition = { offset: offset - realBarGap, size: 0 };\n\n    result = sizeList.reduce(\n      (res: ReadonlyArray<BarWithPosition>, entry: BarCategory): ReadonlyArray<BarWithPosition> => {\n        const newPosition: BarWithPosition = {\n          stackId: entry.stackId,\n          dataKeys: entry.dataKeys,\n          position: {\n            offset: prev.offset + prev.size + realBarGap,\n            size: useFull ? fullBarSize : (entry.barSize ?? 0),\n          },\n        };\n        const newRes: Array<BarWithPosition> = [...res, newPosition];\n\n        prev = newPosition.position;\n\n        return newRes;\n      },\n      initialValue,\n    );\n  } else {\n    const offset = getPercentValue(barCategoryGap, bandSize, 0, true);\n\n    if (bandSize - 2 * offset - (len - 1) * realBarGap <= 0) {\n      realBarGap = 0;\n    }\n\n    let originalSize = (bandSize - 2 * offset - (len - 1) * realBarGap) / len;\n    if (originalSize > 1) {\n      originalSize >>= 0;\n    }\n    const size = isWellBehavedNumber(maxBarSize) ? Math.min(originalSize, maxBarSize) : originalSize;\n    result = sizeList.reduce(\n      (res: ReadonlyArray<BarWithPosition>, entry: BarCategory, i): ReadonlyArray<BarWithPosition> => [\n        ...res,\n        {\n          stackId: entry.stackId,\n          dataKeys: entry.dataKeys,\n          position: {\n            offset: offset + (originalSize + realBarGap) * i + (originalSize - size) / 2,\n            size,\n          },\n        },\n      ],\n      initialValue,\n    );\n  }\n\n  return result;\n}\n\nexport const combineAllBarPositions = (\n  sizeList: SizeList,\n  globalMaxBarSize: number | undefined,\n  barGap: string | number,\n  barCategoryGap: string | number,\n  barBandSize: number,\n  bandSize: number | undefined,\n  childMaxBarSize: number | undefined,\n): ReadonlyArray<BarWithPosition> | undefined => {\n  const maxBarSize: number | undefined = isNullish(childMaxBarSize) ? globalMaxBarSize : childMaxBarSize;\n\n  let allBarPositions: ReadonlyArray<BarWithPosition> | undefined = getBarPositions(\n    barGap,\n    barCategoryGap,\n    barBandSize !== bandSize ? barBandSize : bandSize,\n    sizeList,\n    maxBarSize,\n  );\n\n  if (barBandSize !== bandSize && allBarPositions != null) {\n    allBarPositions = allBarPositions.map(pos => ({\n      ...pos,\n      position: { ...pos.position, offset: pos.position.offset - barBandSize / 2 },\n    }));\n  }\n\n  return allBarPositions;\n};\n","import { AllStackGroups, StackGroup, StackSeries } from '../../../util/stacks/stackTypes';\nimport { MaybeStackedGraphicalItem } from '../../types/StackedGraphicalItem';\nimport { getStackSeriesIdentifier } from '../../../util/stacks/getStackSeriesIdentifier';\n\nexport const combineStackedData = (\n  stackGroups: AllStackGroups | undefined,\n  barSettings: MaybeStackedGraphicalItem | undefined,\n): StackSeries | undefined => {\n  const stackSeriesIdentifier = getStackSeriesIdentifier(barSettings);\n  if (!stackGroups || stackSeriesIdentifier == null || barSettings == null) {\n    return undefined;\n  }\n  const { stackId } = barSettings;\n  if (stackId == null) {\n    return undefined;\n  }\n  const stackGroup: StackGroup | undefined = stackGroups[stackId];\n  if (!stackGroup) {\n    return undefined;\n  }\n  const { stackedData }: StackGroup = stackGroup;\n  if (!stackedData) {\n    return undefined;\n  }\n  return stackedData.find(sd => sd.key === stackSeriesIdentifier);\n};\n","import { MaybeStackedGraphicalItem } from '../../types/StackedGraphicalItem';\nimport { BarPositionPosition } from '../../../util/ChartUtils';\nimport { BarWithPosition } from '../barSelectors';\n\nexport const combineBarPosition = (\n  allBarPositions: ReadonlyArray<BarWithPosition> | undefined,\n  barSettings: MaybeStackedGraphicalItem | undefined,\n): BarPositionPosition | undefined => {\n  if (allBarPositions == null || barSettings == null) {\n    return undefined;\n  }\n  const position = allBarPositions.find(\n    (p: BarWithPosition) =>\n      p.stackId === barSettings.stackId && barSettings.dataKey != null && p.dataKeys.includes(barSettings.dataKey),\n  );\n  if (position == null) {\n    return undefined;\n  }\n  return position.position;\n};\n","import { createSelector } from 'reselect';\nimport { ReactElement } from 'react';\nimport { Series } from 'victory-vendor/d3-shape';\nimport { computeRadialBarDataItems, RadialBarDataItem } from '../../polar/RadialBar';\nimport { selectChartDataAndAlwaysIgnoreIndexes, selectChartDataWithIndexes } from './dataSelectors';\nimport { RechartsRootState } from '../store';\nimport { ChartDataState } from '../chartDataSlice';\nimport { AxisId } from '../cartesianAxisSlice';\nimport { LayoutType, LegendType, PolarViewBoxRequired, TickItem } from '../../util/types';\nimport { selectPolarAxisScale, selectPolarAxisTicks, selectPolarGraphicalItemAxisTicks } from './polarScaleSelectors';\nimport { BaseAxisWithScale, combineStackGroups, selectTooltipAxis } from './axisSelectors';\nimport { selectAngleAxis, selectPolarViewBox, selectRadiusAxis } from './polarAxisSelectors';\nimport { selectChartLayout } from '../../context/chartLayoutContext';\nimport { BarPositionPosition, getBandSizeOfAxis, getBaseValueOfBar, isCategoricalAxis } from '../../util/ChartUtils';\nimport { BarWithPosition, SizeList } from './barSelectors';\nimport {\n  selectBarCategoryGap,\n  selectBarGap,\n  selectReverseStackOrder,\n  selectRootBarSize,\n  selectRootMaxBarSize,\n  selectStackOffsetType,\n} from './rootPropsSelectors';\nimport { PolarGraphicalItemSettings } from '../graphicalItemsSlice';\nimport { PolarAxisType, selectPolarItemsSettings, selectUnfilteredPolarItems } from './polarSelectors';\nimport { AngleAxisSettings, RadiusAxisSettings } from '../polarAxisSlice';\nimport { LegendPayload } from '../../component/DefaultLegendContent';\nimport { isNullish } from '../../util/DataUtils';\n\nimport { AllStackGroups, StackDataPoint, StackSeries, StackSeriesIdentifier } from '../../util/stacks/stackTypes';\nimport { combineDisplayedStackedData, DisplayedStackedData } from './combiners/combineDisplayedStackedData';\nimport { RadialBarSettings } from '../types/RadialBarSettings';\nimport { DefinitelyStackedGraphicalItem, isStacked } from '../types/StackedGraphicalItem';\nimport { combineBarSizeList } from './combiners/combineBarSizeList';\nimport { combineAllBarPositions } from './combiners/combineAllBarPositions';\nimport { combineStackedData } from './combiners/combineStackedData';\nimport { RechartsScale } from '../../util/scale/RechartsScale';\nimport { combineBarPosition } from './combiners/combineBarPosition';\n\nconst selectRadiusAxisForRadialBar = (state: RechartsRootState, radiusAxisId: AxisId): RadiusAxisSettings =>\n  selectRadiusAxis(state, radiusAxisId);\n\nconst selectRadiusAxisScaleForRadar = (state: RechartsRootState, radiusAxisId: AxisId): RechartsScale | undefined =>\n  selectPolarAxisScale(state, 'radiusAxis', radiusAxisId);\n\nexport const selectRadiusAxisWithScale: (\n  state: RechartsRootState,\n  radiusAxisId: AxisId,\n) => BaseAxisWithScale | undefined = createSelector(\n  [selectRadiusAxisForRadialBar, selectRadiusAxisScaleForRadar],\n  (axis: RadiusAxisSettings, scale: RechartsScale | undefined): BaseAxisWithScale | undefined => {\n    if (axis == null || scale == null) {\n      return undefined;\n    }\n    return { ...axis, scale };\n  },\n);\n\nexport const selectRadiusAxisTicks = (\n  state: RechartsRootState,\n  radiusAxisId: AxisId,\n): ReadonlyArray<TickItem> | undefined => {\n  return selectPolarGraphicalItemAxisTicks(state, 'radiusAxis', radiusAxisId, false);\n};\n\nconst selectAngleAxisForRadialBar = (\n  state: RechartsRootState,\n  _radiusAxisId: AxisId,\n  angleAxisId: AxisId,\n): AngleAxisSettings => selectAngleAxis(state, angleAxisId);\n\nconst selectAngleAxisScaleForRadialBar = (\n  state: RechartsRootState,\n  _radiusAxisId: AxisId,\n  angleAxisId: AxisId,\n): RechartsScale | undefined => selectPolarAxisScale(state, 'angleAxis', angleAxisId);\n\nexport const selectAngleAxisWithScale: (\n  state: RechartsRootState,\n  _radiusAxisId: AxisId,\n  angleAxisId: AxisId,\n) => BaseAxisWithScale | undefined = createSelector(\n  [selectAngleAxisForRadialBar, selectAngleAxisScaleForRadialBar],\n  (axis: AngleAxisSettings, scale: RechartsScale | undefined): BaseAxisWithScale | undefined => {\n    if (axis == null || scale == null) {\n      return undefined;\n    }\n    return { ...axis, scale };\n  },\n);\n\nconst selectAngleAxisTicks = (\n  state: RechartsRootState,\n  _radiusAxisId: AxisId,\n  angleAxisId: AxisId,\n): ReadonlyArray<TickItem> | undefined => {\n  // here we can hardcode isPanorama to false because radialBar does not support panorama mode\n  return selectPolarAxisTicks(state, 'angleAxis', angleAxisId, false);\n};\n\nconst pickRadialBarSettings = (\n  _state: RechartsRootState,\n  _radiusAxisId: AxisId,\n  _angleAxisId: AxisId,\n  radialBarSettings: RadialBarSettings,\n): RadialBarSettings => radialBarSettings;\n\nconst selectSynchronisedRadialBarSettings: (\n  state: RechartsRootState,\n  _radiusAxisId: AxisId,\n  _angleAxisId: AxisId,\n  radialBarSettings: RadialBarSettings,\n) => RadialBarSettings | undefined = createSelector(\n  [selectUnfilteredPolarItems, pickRadialBarSettings],\n  (graphicalItems, radialBarSettingsFromProps) => {\n    if (\n      graphicalItems.some(\n        pgis =>\n          pgis.type === 'radialBar' &&\n          radialBarSettingsFromProps.dataKey === pgis.dataKey &&\n          radialBarSettingsFromProps.stackId === pgis.stackId,\n      )\n    ) {\n      return radialBarSettingsFromProps;\n    }\n    return undefined;\n  },\n);\n\nexport const selectBandSizeOfPolarAxis: (\n  state: RechartsRootState,\n  radiusAxisId: AxisId,\n  angleAxisId: AxisId,\n) => number | undefined = createSelector(\n  [selectChartLayout, selectRadiusAxisWithScale, selectRadiusAxisTicks, selectAngleAxisWithScale, selectAngleAxisTicks],\n  (\n    layout: LayoutType,\n    radiusAxis: BaseAxisWithScale | undefined,\n    radiusAxisTicks: ReadonlyArray<TickItem> | undefined,\n    angleAxis: BaseAxisWithScale | undefined,\n    angleAxisTicks: ReadonlyArray<TickItem> | undefined,\n  ) => {\n    if (isCategoricalAxis(layout, 'radiusAxis')) {\n      return getBandSizeOfAxis(radiusAxis, radiusAxisTicks, false);\n    }\n    return getBandSizeOfAxis(angleAxis, angleAxisTicks, false);\n  },\n);\n\nexport const selectBaseValue: (\n  state: RechartsRootState,\n  radiusAxisId: AxisId,\n  angleAxisId: AxisId,\n) => number | unknown = createSelector(\n  [selectAngleAxisWithScale, selectRadiusAxisWithScale, selectChartLayout],\n  (angleAxis, radiusAxis, layout) => {\n    const numericAxis = layout === 'radial' ? angleAxis : radiusAxis;\n    if (numericAxis == null || numericAxis.scale == null) {\n      return undefined;\n    }\n    return getBaseValueOfBar({ numericAxis });\n  },\n);\n\nconst pickCells = (\n  _state: RechartsRootState,\n  _radiusAxisId: AxisId,\n  _angleAxisId: AxisId,\n  _radialBarSettings: RadialBarSettings,\n  cells: ReadonlyArray<ReactElement> | undefined,\n) => cells;\n\nconst pickAngleAxisId = (\n  _state: RechartsRootState,\n  _radiusAxisId: AxisId,\n  angleAxisId: AxisId,\n  _radialBarSettings: RadialBarSettings,\n  _cells: ReadonlyArray<ReactElement> | undefined,\n): AxisId => angleAxisId;\n\nconst pickRadiusAxisId = (\n  _state: RechartsRootState,\n  radiusAxisId: AxisId,\n  _angleAxisId: AxisId,\n  _radialBarSettings: RadialBarSettings,\n  _cells: ReadonlyArray<ReactElement> | undefined,\n): AxisId => radiusAxisId;\n\nexport const pickMaxBarSize = (\n  _state: RechartsRootState,\n  _radiusAxisId: AxisId,\n  _angleAxisId: AxisId,\n  radialBarSettings: RadialBarSettings,\n  _cells: ReadonlyArray<ReactElement> | undefined,\n): number | undefined => radialBarSettings.maxBarSize;\n\nconst isRadialBar = (item: PolarGraphicalItemSettings): item is RadialBarSettings => item.type === 'radialBar';\n\nconst selectAllVisibleRadialBars: (\n  state: RechartsRootState,\n  radiusAxisId: AxisId,\n  angleAxisId: AxisId,\n  radialBarSettings: RadialBarSettings,\n  cells: ReadonlyArray<ReactElement> | undefined,\n) => ReadonlyArray<RadialBarSettings> = createSelector(\n  [selectChartLayout, selectUnfilteredPolarItems, pickAngleAxisId, pickRadiusAxisId],\n  (\n    layout: LayoutType,\n    allItems: ReadonlyArray<PolarGraphicalItemSettings>,\n    angleAxisId: AxisId,\n    radiusAxisId: AxisId,\n  ): ReadonlyArray<RadialBarSettings> => {\n    return allItems\n      .filter(i => {\n        if (layout === 'centric') {\n          return i.angleAxisId === angleAxisId;\n        }\n        return i.radiusAxisId === radiusAxisId;\n      })\n      .filter(i => i.hide === false)\n      .filter(isRadialBar);\n  },\n);\n\n/**\n * The generator never returned the totalSize which means that barSize in polar chart can not support percent values.\n * We can add that if we want to I suppose.\n * @returns undefined - but it should be a total size of numerical axis in polar chart\n */\nconst selectPolarBarAxisSize = (): undefined => undefined;\n\nexport const selectPolarBarSizeList: (\n  state: RechartsRootState,\n  radiusAxisId: AxisId,\n  angleAxisId: AxisId,\n  radialBarSettings: RadialBarSettings,\n  cells: ReadonlyArray<ReactElement> | undefined,\n) => SizeList = createSelector(\n  [selectAllVisibleRadialBars, selectRootBarSize, selectPolarBarAxisSize],\n  combineBarSizeList,\n);\n\nexport const selectPolarBarBandSize: (\n  state: RechartsRootState,\n  radiusAxisId: AxisId,\n  angleAxisId: AxisId,\n  radialBarSettings: RadialBarSettings,\n  cells: ReadonlyArray<ReactElement> | undefined,\n) => number = createSelector(\n  [\n    selectChartLayout,\n    selectRootMaxBarSize,\n    selectAngleAxisWithScale,\n    selectAngleAxisTicks,\n    selectRadiusAxisWithScale,\n    selectRadiusAxisTicks,\n    pickMaxBarSize,\n  ],\n  (\n    layout: LayoutType,\n    globalMaxBarSize: number | undefined,\n    angleAxis: BaseAxisWithScale | undefined,\n    angleAxisTicks: ReadonlyArray<TickItem> | undefined,\n    radiusAxis: BaseAxisWithScale | undefined,\n    radiusAxisTicks: ReadonlyArray<TickItem> | undefined,\n    childMaxBarSize: number | undefined,\n  ): number => {\n    const maxBarSize: number | undefined = isNullish(childMaxBarSize) ? globalMaxBarSize : childMaxBarSize;\n    if (layout === 'centric') {\n      return getBandSizeOfAxis(angleAxis, angleAxisTicks, true) ?? maxBarSize ?? 0;\n    }\n    return getBandSizeOfAxis(radiusAxis, radiusAxisTicks, true) ?? maxBarSize ?? 0;\n  },\n);\n\nexport const selectAllPolarBarPositions: (\n  state: RechartsRootState,\n  radiusAxisId: AxisId,\n  angleAxisId: AxisId,\n  radialBarSettings: RadialBarSettings,\n  cells: ReadonlyArray<ReactElement> | undefined,\n) => ReadonlyArray<BarWithPosition> | undefined = createSelector(\n  [\n    selectPolarBarSizeList,\n    selectRootMaxBarSize,\n    selectBarGap,\n    selectBarCategoryGap,\n    selectPolarBarBandSize,\n    selectBandSizeOfPolarAxis,\n    pickMaxBarSize,\n  ],\n  combineAllBarPositions,\n);\n\nexport const selectPolarBarPosition: (\n  state: RechartsRootState,\n  radiusAxisId: AxisId,\n  angleAxisId: AxisId,\n  radialBarSettings: RadialBarSettings,\n  cells: ReadonlyArray<ReactElement> | undefined,\n) => BarPositionPosition | undefined = createSelector(\n  [selectAllPolarBarPositions, selectSynchronisedRadialBarSettings],\n  combineBarPosition,\n);\n\nconst selectStackedRadialBars: (\n  state: RechartsRootState,\n  axisType: PolarAxisType,\n  polarAxisId: AxisId,\n) => ReadonlyArray<DefinitelyStackedGraphicalItem> = createSelector(\n  [selectPolarItemsSettings],\n  (allPolarItems: ReadonlyArray<PolarGraphicalItemSettings>): ReadonlyArray<DefinitelyStackedGraphicalItem> =>\n    allPolarItems.filter(isRadialBar).filter(isStacked),\n);\n\nconst selectPolarCombinedStackedData: (\n  state: RechartsRootState,\n  axisType: PolarAxisType,\n  polarAxisId: AxisId,\n) => DisplayedStackedData = createSelector(\n  [selectStackedRadialBars, selectChartDataAndAlwaysIgnoreIndexes, selectTooltipAxis],\n  combineDisplayedStackedData,\n);\n\nconst selectStackGroups: (\n  state: RechartsRootState,\n  axisType: PolarAxisType,\n  polarAxisId: AxisId,\n) => AllStackGroups | undefined = createSelector(\n  [selectPolarCombinedStackedData, selectStackedRadialBars, selectStackOffsetType, selectReverseStackOrder],\n  combineStackGroups,\n);\n\nconst selectRadialBarStackGroups: (\n  state: RechartsRootState,\n  radiusAxisId: AxisId,\n  angleAxisId: AxisId,\n  radialBarSettings: RadialBarSettings,\n  cells: ReadonlyArray<ReactElement> | undefined,\n) => AllStackGroups | undefined = (state, radiusAxisId, angleAxisId) => {\n  const layout = selectChartLayout(state);\n  if (layout === 'centric') {\n    return selectStackGroups(state, 'radiusAxis', radiusAxisId);\n  }\n  return selectStackGroups(state, 'angleAxis', angleAxisId);\n};\n\nconst selectPolarStackedData: (\n  state: RechartsRootState,\n  radiusAxisId: AxisId,\n  angleAxisId: AxisId,\n  radialBarSettings: RadialBarSettings,\n  cells: ReadonlyArray<ReactElement> | undefined,\n) => StackSeries | undefined = createSelector(\n  [selectRadialBarStackGroups, selectSynchronisedRadialBarSettings],\n  combineStackedData,\n);\n\nexport const selectRadialBarSectors: (\n  state: RechartsRootState,\n  radiusAxisId: AxisId,\n  angleAxisId: AxisId,\n  radialBarSettings: RadialBarSettings,\n  cells: ReadonlyArray<ReactElement> | undefined,\n) => ReadonlyArray<RadialBarDataItem> = createSelector(\n  [\n    selectAngleAxisWithScale,\n    selectAngleAxisTicks,\n    selectRadiusAxisWithScale,\n    selectRadiusAxisTicks,\n    selectChartDataWithIndexes,\n    selectSynchronisedRadialBarSettings,\n    selectBandSizeOfPolarAxis,\n    selectChartLayout,\n    selectBaseValue,\n    selectPolarViewBox,\n    pickCells,\n    selectPolarBarPosition,\n    selectPolarStackedData,\n  ],\n  (\n    angleAxis: BaseAxisWithScale | undefined,\n    angleAxisTicks: ReadonlyArray<TickItem> | undefined,\n    radiusAxis: BaseAxisWithScale | undefined,\n    radiusAxisTicks: ReadonlyArray<TickItem> | undefined,\n    { chartData, dataStartIndex, dataEndIndex }: ChartDataState,\n    radialBarSettings: RadialBarSettings | undefined,\n    bandSize: number | undefined,\n    layout: LayoutType,\n    baseValue: number | unknown,\n    polarViewBox: PolarViewBoxRequired | undefined,\n    cells: ReadonlyArray<ReactElement> | undefined,\n    pos: BarPositionPosition | undefined,\n    stackedData: Series<StackDataPoint, StackSeriesIdentifier> | undefined,\n  ): ReadonlyArray<RadialBarDataItem> => {\n    if (\n      radialBarSettings == null ||\n      radiusAxis == null ||\n      angleAxis == null ||\n      chartData == null ||\n      bandSize == null ||\n      pos == null ||\n      (layout !== 'centric' && layout !== 'radial') ||\n      radiusAxisTicks == null ||\n      polarViewBox == null\n    ) {\n      return [];\n    }\n    const { dataKey, minPointSize } = radialBarSettings;\n    const { cx, cy, startAngle, endAngle } = polarViewBox;\n    const displayedData = chartData.slice(dataStartIndex, dataEndIndex + 1);\n    const numericAxis = layout === 'centric' ? radiusAxis : angleAxis;\n    const stackedDomain: ReadonlyArray<unknown> | null = stackedData ? numericAxis.scale.domain() : null;\n    return computeRadialBarDataItems({\n      angleAxis,\n      angleAxisTicks,\n      bandSize,\n      baseValue,\n      cells,\n      cx,\n      cy,\n      dataKey,\n      dataStartIndex,\n      displayedData,\n      endAngle,\n      layout,\n      minPointSize,\n      pos,\n      radiusAxis,\n      radiusAxisTicks,\n      stackedData,\n      stackedDomain,\n      startAngle,\n    });\n  },\n);\n\nexport const selectRadialBarLegendPayload: (\n  state: RechartsRootState,\n  legendType: LegendType | undefined,\n) => ReadonlyArray<LegendPayload> = createSelector(\n  [selectChartDataAndAlwaysIgnoreIndexes, (_s: RechartsRootState, l: LegendType | undefined) => l],\n  (\n    { chartData, dataStartIndex, dataEndIndex }: ChartDataState,\n    legendType: LegendType | undefined,\n  ): ReadonlyArray<LegendPayload> => {\n    if (chartData == null) {\n      return [];\n    }\n    const displayedData = chartData.slice(dataStartIndex, dataEndIndex + 1);\n\n    if (displayedData.length === 0) {\n      return [];\n    }\n\n    return displayedData.map((entry): LegendPayload => {\n      return {\n        type: legendType,\n        // @ts-expect-error we need a better typing for our data inputs\n        value: entry.name,\n        // @ts-expect-error we need a better typing for our data inputs\n        color: entry.fill,\n        // @ts-expect-error Legend payload.payload says it wants objects but our data can be unknown\n        payload: entry,\n      };\n    });\n  },\n);\n","import * as React from 'react';\nimport { MutableRefObject, PureComponent, ReactElement, ReactNode, useCallback, useRef, useState } from 'react';\nimport { clsx } from 'clsx';\n\nimport { Series } from 'victory-vendor/d3-shape';\nimport { parseCornerRadius, RadialBarSector, RadialBarSectorProps } from '../util/RadialBarUtils';\nimport { Props as SectorProps } from '../shape/Sector';\nimport { Layer } from '../container/Layer';\nimport { findAllByType } from '../util/ReactUtils';\nimport {\n  ImplicitLabelListType,\n  LabelListFromLabelProp,\n  PolarLabelListContextProvider,\n  PolarLabelListEntry,\n} from '../component/LabelList';\nimport { Cell } from '../component/Cell';\nimport { interpolate, mathSign, noop } from '../util/DataUtils';\nimport {\n  BarPositionPosition,\n  getCateCoordinateOfBar,\n  getNormalizedStackId,\n  getTooltipNameProp,\n  getValueByDataKey,\n  truncateByDomain,\n} from '../util/ChartUtils';\nimport {\n  ActiveShape,