ius = radiusAxis.scale.map(value[1]);\n      startAngle = getCateCoordinateOfBar({\n        axis: angleAxis,\n        ticks: angleAxisTicks,\n        bandSize,\n        offset: pos.offset,\n        entry,\n        index,\n      });\n      if (innerRadius != null && outerRadius != null && startAngle != null) {\n        endAngle = startAngle + pos.size;\n        const deltaRadius = outerRadius - innerRadius;\n\n        if (Math.abs(minPointSize) > 0 && Math.abs(deltaRadius) < Math.abs(minPointSize)) {\n          const delta = mathSign(deltaRadius || minPointSize) * (Math.abs(minPointSize) - Math.abs(deltaRadius));\n          outerRadius += delta;\n        }\n      }\n    }\n\n    return {\n      // @ts-expect-error can't spread unknown\n      ...entry,\n      ...backgroundSector,\n      payload: entry,\n      value: stackedData ? value : value[1],\n      cx,\n      cy,\n      innerRadius,\n      outerRadius,\n      startAngle,\n      // @ts-expect-error endAngle is used before assigned (?)\n      endAngle,\n      ...(cells && cells[index] && cells[index].props),\n    } satisfies RadialBarDataItem;\n  });\n}\n\n/**\n * @consumes PolarChartContext\n * @provides LabelListContext\n * @provides CellReader\n */\nexport function RadialBar<DataPointType = any, DataValueType = any>(\n  outsideProps: RadialBarProps<DataPointType, DataValueType>,\n) {\n  const props: PropsWithDefaults<DataPointType, DataValueType> = resolveDefaultProps(\n    outsideProps,\n    defaultRadialBarProps,\n  );\n  return (\n    <RegisterGraphicalItemId id={props.id} type=\"radialBar\">\n      {id => (\n        <>\n          <SetPolarGraphicalItem\n            type=\"radialBar\"\n            id={id}\n            data={undefined} // why does RadialBar not allow data defined on the item?\n            dataKey={props.dataKey}\n            hide={props.hide ?? defaultRadialBarProps.hide}\n            angleAxisId={props.angleAxisId ?? defaultRadialBarProps.angleAxisId}\n            radiusAxisId={props.radiusAxisId ?? defaultRadialBarProps.radiusAxisId}\n            stackId={getNormalizedStackId(props.stackId)}\n            barSize={props.barSize}\n            minPointSize={props.minPointSize}\n            maxBarSize={props.maxBarSize}\n          />\n          <SetRadialBarPayloadLegend {...props} />\n          <RadialBarImpl {...props} id={id} />\n        </>\n      )}\n    </RegisterGraphicalItemId>\n  );\n}\n\nRadialBar.displayName = 'RadialBar';\n","import { isWellBehavedNumber } from '../util/isWellBehavedNumber';\n\nexport function getZIndexFromUnknown(input: unknown, defaultZIndex: number): number {\n  if (\n    input &&\n    typeof input === 'object' &&\n    'zIndex' in input &&\n    typeof input.zIndex === 'number' &&\n    isWellBehavedNumber(input.zIndex)\n  ) {\n    return input.zIndex;\n  }\n  return defaultZIndex;\n}\n","const PREFIX_LIST = ['Webkit', 'Moz', 'O', 'ms'];\n\nexport const generatePrefixStyle = (name: string, value: string) => {\n  if (!name) {\n    return undefined;\n  }\n\n  const camelName = name.replace(/(\\w)/, v => v.toUpperCase());\n  const result: Record<string, string> = PREFIX_LIST.reduce(\n    (res, entry) => ({\n      ...res,\n      [entry + camelName]: value,\n    }),\n    {},\n  );\n\n  result[name] = value;\n\n  return result;\n};\n","import { useEffect } from 'react';\nimport { ChartData, setChartData, setComputedData } from '../state/chartDataSlice';\nimport { useAppDispatch, useAppSelector } from '../state/hooks';\nimport { RechartsRootState } from '../state/store';\nimport { BrushStartEndIndex } from './brushUpdateContext';\nimport { useIsPanorama } from './PanoramaContext';\n\nexport const ChartDataContextProvider = (props: { chartData: ChartData | undefined }): null => {\n  const { chartData } = props;\n  const dispatch = useAppDispatch();\n  const isPanorama = useIsPanorama();\n  useEffect(() => {\n    if (isPanorama) {\n      // Panorama mode reuses data from the main chart, so we must not overwrite it here.\n      return 