\n      endX: this.handleTravellerDragStart.bind(this, 'endX'),\n    };\n\n    this.state = { brushMoveStartX: 0, movingTravellerId: undefined, endX: 0, startX: 0, slideMoveStartX: 0 };\n  }\n\n  leaveTimer: number | null | undefined;\n\n  travellerDragStartHandlers: Record<BrushTravellerId, (event: MouseOrTouchEvent) => void>;\n\n  static getDerivedStateFromProps(nextProps: BrushWithStateProps, prevState: State): Partial<State> | null {\n    const {\n      data,\n      width,\n      x,\n      travellerWidth,\n      startIndex,\n      endIndex,\n      startIndexControlledFromProps,\n      endIndexControlledFromProps,\n    } = nextProps;\n\n    if (data !== prevState.prevData) {\n      return {\n        prevData: data,\n        prevTravellerWidth: travellerWidth,\n        prevX: x,\n        prevWidth: width,\n        ...(data && data.length\n          ? createScale({ data, width, x, travellerWidth, startIndex, endIndex })\n          : { scale: undefined, scaleValues: undefined }),\n      };\n    }\n    const prevScale = prevState.scale;\n    if (\n      prevScale &&\n      (width !== prevState.prevWidth || x !== prevState.prevX || travellerWidth !== prevState.prevTravellerWidth)\n    ) {\n      prevScale.range([x, x + width - travellerWidth]);\n\n      const scaleValues = prevScale\n        .domain()\n        .map(entry => prevScale(entry))\n        .filter(value => value != null);\n\n      return {\n        prevData: data,\n        prevTravellerWidth: travellerWidth,\n        prevX: x,\n        prevWidth: width,\n        startX: prevScale(nextProps.startIndex),\n        endX: prevScale(nextProps.endIndex),\n        scaleValues,\n      };\n    }\n\n    if (\n      prevState.scale &&\n      !prevState.isSlideMoving &&\n      !prevState.isTravellerMoving &&\n      !prevState.isTravellerFocused &&\n      !prevState.isTextActive\n    ) {\n      /*\n       * If the startIndex or endIndex are controlled from the outside,\n       * we need to keep the startX and end up to date.\n       * Also we do not want to do that while user is interacting in the brush,\n       * because this will trigger re-render and interrupt the drag&drop.\n       */\n      if (\n        startIndexControlledFromProps != null &&\n        prevState.prevStartIndexControlledFromProps !== startIndexControlledFromProps\n      ) {\n        return {\n          startX: prevState.scale(startIndexControlledFromProps),\n          prevStartIndexControlledFromProps: startIndexControlledFromProps,\n        };\n      }\n\n      if (\n        endIndexControlledFromProps != null &&\n        prevState.prevEndIndexControlledFromProps !== endIndexControlledFromProps\n      ) {\n        return {\n          endX: prevState.scale(endIndexControlledFromProps),\n          prevEndIndexControlledFromProps: endIndexControlledFromProps,\n        };\n      }\n    }\n\n    return null;\n  }\n\n  componentWillUnmount() {\n    if (this.leaveTimer) {\n      clearTimeout(this.leaveTimer);\n      this.leaveTimer = null;\n    }\n\n    this.detachDragEndListener();\n  }\n\n  handleDrag = (e: React.Touch | React.MouseEvent<SVGGElement> | MouseEvent) => {\n    if (this.leaveTimer) {\n      clearTimeout(this.leaveTimer);\n      this.leaveTimer = null;\n    }\n\n    if (this.state.isTravellerMoving) {\n      this.handleTravellerMove(e);\n    } else if (this.state.isSlideMoving) {\n      this.handleSlideDrag(e);\n    }\n  };\n\n  handleTouchMove = (e: TouchEvent<SVGGElement>) => {\n    const touch = e.changedTouches?.[0];\n    if (touch != null) {\n      this.handleDrag(touch);\n    }\n  };\n\n  attachDragEndListener() {\n    window.addEventListener('mouseup', this.handleDragEnd, true);\n    window.addEventListener('touchend', this.handleDragEnd, true);\n    window.addEventListener('mousemove', this.handleDrag, true);\n  }\n\n  detachDragEndListener() {\n    window.removeEventListener('mouseup', this.handleDragEnd, true);\n    window.removeEventListener('touchend', this.handleDragEnd, true);\n    window.removeEventListener('mousemove', this.handleDrag, true);\n  }\n\n  handleDragEnd = () => {\n    this.setState(\n      {\n        isTravellerMoving: false,\n        isSlideMoving: false,\n      },\n      () => {\n        const { endIndex, onDragEnd, startIndex } = this.props;\n        onDragEnd?.({\n          endIndex,\n          startIndex,\n        });\n      },\n    );\n    this.detachDragEndListener();\n  };\n\n  handleLeaveWrapper = () => {\n    if (this.state.isTravellerMoving || this.state.isSlideMoving) {\n      this.leaveTimer = window.setTimeout(this.handleDragEnd, this.props.leaveTimeOut);\n    }\n  };\n\n  handleEnterSlideOrTraveller = () => {\n    this.setState({\n      isTextActive: true,\n    });\n  };\n\n  handleLeaveSlideOrTraveller = () => {\n    this.setState({\n      isTextActive: false,\n    });\n  };\n\n  handleSlideDragStart = (e: MouseOrTouchEvent) => {\n    const event = isTouch(e) ? e.changedTouches[0] : e;\n    if (event == null) {\n      return;\n    }\n\n    this.setState({\n      isTravellerMoving: false,\n      isSlideMoving: true,\n      slideMoveStartX: event.pageX,\n    });\n\n    this.attachDragEndListener();\n  };\n\n  handleSlideDrag(e: React.Touch | React.MouseEvent<SVGGElement> | MouseEvent) {\n    const { slideMoveStartX, startX, endX, scaleValues } = this.state;\n    if (scaleValues == null) {\n      return;\n    }\n    const { x, width, travellerWidth, startIndex, endIndex, onChange, data, gap } = this.props;\n    let delta = e.pageX - slideMoveStartX;\n\n    if (delta > 0) {\n      delta = Math.min(delta, x + width - travellerWidth - endX, x + width - travellerWidth - startX);\n    } else if (delta < 0) {\n      delta = Math.max(delta, x - startX, x - endX);\n    }\n    const newIndex = getIndex({\n      startX: startX + delta,\n      endX: endX + delta,\n      data,\n      gap,\n      scaleValues,\n    });\n\n    if ((newIndex.startIndex !== startIndex || newIndex.endIndex !== endIndex) && onChange) {\n      onChange(newIndex);\n    }\n\n    this.setState({\n      startX: startX + delta,\n      endX: endX + delta,\n      slideMoveStartX: e.pageX,\n    });\n  }\n\n  handleTravellerDragStart(id: BrushTravellerId, e: MouseOrTouchEvent) {\n    const event = isTouch(e) ? e.changedTouches[0] : e;\n    if (event == null) {\n      return;\n    }\n\n    this.setState({\n      isSlideMoving: false,\n      isTravellerMoving: true,\n      movingTravellerId: id,\n      brushMoveStartX: event.pageX,\n    });\n\n    this.attachDragEndListener();\n  }\n\n  handleTravellerMove(e: React.Touch | React.MouseEvent<SVGGElement> | MouseEvent) {\n    const { brushMoveStartX, movingTravellerId, endX, startX, scaleValues } = this.state;\n    if (movingTravellerId == null || scaleValues == null) {\n      return;\n    }\n    const prevValue = this.state[movingTravellerId];\n\n    const { x, width, travellerWidth, onChange, gap, data } = this.props;\n    const params = { startX: this.state.startX, endX: this.state.endX, data, gap, scaleValues };\n\n    let delta = e.pageX - brushMoveStartX;\n    if (delta > 0) {\n      delta = Math.min(delta, x + width - travellerWidth - prevValue);\n    } else if (delta < 0) {\n      delta = Math.max(delta, x - prevValue);\n    }\n\n    params[movingTravellerId] = prevValue + delta;\n\n    const newIndex = getIndex(params);\n    const { startIndex, endIndex } = newIndex;\n    const isFullGap = () => {\n      const lastIndex = data.length - 1;\n      if (\n        (movingTravellerId === 'startX' && (endX > startX ? startIndex % gap === 0 : endIndex % gap === 0)) ||\n        (endX < startX && endIndex === lastIndex) ||\n        (movingTravellerId === 'endX' && (endX > startX ? endIndex % gap === 0 : startIndex % gap === 0)) ||\n        (endX > startX && endIndex === lastIndex)\n      ) {\n        return true;\n      }\n      return false;\n    };\n\n    this.setState(\n      // @ts-expect-error not sure why typescript is not happy with this, partial update is fine in React\n      {\n        [movingTravellerId]: prevValue + delta,\n        brushMoveStartX: e.pageX,\n      },\n      () => {\n        if (onChange) {\n          if (isFullGap()) {\n            onChange(newIndex);\n          }\n        }\n      },\n    );\n  }\n\n  handleTravellerMoveKeyboard = (direction: 1 | -1, id: BrushTravellerId) => {\n    const { data, gap, startIndex, endIndex } = this.props;\n    // scaleValues are a list of coordinates. For example: [65, 250, 435, 620, 805, 990].\n    const { scaleValues, startX, endX } = this.state;\n    if (scaleValues == null) {\n      return;\n    }\n\n    // unless we search for the closest scaleValue to the current coordinate\n    // we need to move travelers via index when using the keyboard\n    let currentIndex: number = -1;\n    if (id === 'startX') {\n      currentIndex = startIndex;\n    } else if (id === 'endX') {\n      currentIndex = endIndex;\n    }\n\n    if (currentIndex < 0 || currentIndex >= data.length) {\n      return;\n    }\n\n    const newIndex = currentIndex + direction;\n    if (newIndex === -1 || newIndex >= scaleValues.length) {\n      return;\n    }\n\n    const newScaleValue = scaleValues[newIndex];\n    if (newScaleValue == null) {\n      return;\n    }\n\n    // Prevent travellers from being on top of each other or overlapping\n    if ((id === 'startX' && newScaleValue >= endX) || (id === 'endX' && newScaleValue <= startX)) {\n      return;\n    }\n\n    this.setState(\n      // @ts-expect-error not sure why typescript is not happy with this, partial update is fine in React\n      {\n        [id]: newScaleValue,\n      },\n      () => {\n        this.props.onChange(\n          getIndex({\n            startX: this.state.startX,\n            endX: this.state.endX,\n            data,\n            gap,\n            scaleValues,\n          }),\n        );\n      },\n    );\n  };\n\n  render() {\n    const {\n      data,\n      className,\n      children,\n      x,\n      y,\n      dy,\n      width,\n      height,\n      alwaysShowText,\n      fill,\n      stroke,\n      startIndex,\n      endIndex,\n      travellerWidth,\n      tickFormatter,\n      dataKey,\n      padding,\n    } = this.props;\n    const { startX, endX, isTextActive, isSlideMoving, isTravellerMoving, isTravellerFocused } = this.state;\n\n    if (\n      !data ||\n      !data.length ||\n      !isNumber(x) ||\n      !isNumber(y) ||\n      !isNumber(width) ||\n      !isNumber(height) ||\n      width <= 0 ||\n      height <= 0\n    ) {\n      return null;\n    }\n\n    const layerClass = clsx('recharts-brush', className);\n    const style = generatePrefixStyle('userSelect', 'none');\n    const calculatedY = y + (dy ?? 0);\n\n    return (\n      <Layer\n        className={layerClass}\n        onMouseLeave={this.handleLeaveWrapper}\n        onTouchMove={this.handleTouchMove}\n        style={style}\n      >\n        <Background x={x} y={calculatedY} width={width} height={height} fill={fill} stroke={stroke} />\n        <PanoramaContextProvider>\n          <Panorama x={x} y={calculatedY} width={width} height={height} data={data} padding={padding}>\n            {children}\n          </Panorama>\n        </PanoramaContextProvider>\n        <Slide\n          y={calculatedY}\n          height={height}\n          stroke={stroke}\n          travellerWidth={travellerWidth}\n          startX={startX}\n          endX={endX}\n          onMouseEnter={this.handleEnterSlideOrTraveller}\n          onMouseLeave={this.handleLeaveSlideOrTraveller}\n          onMouseDown={this.handleSlideDragStart}\n          onTouchStart={this.handleSlideDragStart}\n        />\n        <TravellerLayer\n          travellerX={startX}\n          id=\"startX\"\n          otherProps={{ ...this.props, y: calculatedY }}\n          onMouseEnter={this.handleEnterSlideOrTraveller}\n          onMouseLeave={this.handleLeaveSlideOrTraveller}\n          onMouseDown={this.travellerDragStartHandlers.startX}\n          onTouchStart={this.travellerDragStartHandlers.startX}\n          onTravellerMoveKeyboard={this.handleTravellerMoveKeyboard}\n          onFocus={() => {\n            this.setState({ isTravellerFocused: true });\n          }}\n          onBlur={() => {\n            this.setState({ isTravellerFocused: false });\n          }}\n        />\n        <TravellerLayer\n          travellerX={endX}\n          id=\"endX\"\n          otherProps={{ ...this.props, y: calculatedY }}\n          onMouseEnter={this.handleEnterSlideOrTraveller}\n          onMouseLeave={this.handleLeaveSlideOrTraveller}\n          onMouseDown={this.travellerDragStartHandlers.endX}\n          onTouchStart={this.travellerDragStartHandlers.endX}\n          onTravellerMoveKeyboard={this.handleTravellerMoveKeyboard}\n          onFocus={() => {\n            this.setState({ isTravellerFocused: true });\n          }}\n          onBlur={() => {\n            this.setState({ isTravellerFocused: false });\n          }}\n        />\n        {(isTextActive || isSlideMoving || isTravellerMoving || isTravellerFocused || alwaysShowText) && (\n          <BrushText\n            startIndex={startIndex}\n            endIndex={endIndex}\n            y={calculatedY}\n            height={height}\n            travellerWidth={travellerWidth}\n            stroke={stroke}\n            tickFormatter={tickFormatter}\n            dataKey={dataKey}\n            data={data}\n            startX={startX}\n            endX={endX}\n          />\n        )}\n      </Layer>\n    );\n  }\n}\n\nfunction BrushInternal(props: InternalProps) {\n  const dispatch = useAppDispatch();\n  const chartData = useChartData();\n  const dataIndexes = useDataIndex();\n  const onChangeFromContext = useContext(BrushUpdateDispatchContext);\n  const onChangeFromProps = props.onChange;\n  const { startIndex: startIndexFromProps, endIndex: endIndexFromProps } = props;\n\n  useEffect(() => {\n    // start and end index can be controlled from props, and we need them to stay up-to-date in the Redux state too\n    dispatch(setDataStartEndIndexes({ startIndex: startIndexFromProps, endIndex: endIndexFromProps }));\n  }, [dispatch, endIndexFromProps, startIndexFromProps]);\n\n  useBrushChartSynchronisation();\n\n  const onChange = useCallback(\n    (nextState: BrushStartEndIndex) => {\n      if (dataIndexes == null) {\n        return;\n      }\n      const { startIndex, endIndex } = dataIndexes;\n      if (nextState.startIndex !== startIndex || nextState.endIndex !== endIndex) {\n        onChangeFromContext?.(nextState);\n        onChangeFromProps?.(nextState);\n        dispatch(setDataStartEndIndexes(nextState));\n      }\n    },\n    [onChangeFromProps, onChangeFromContext, dispatch, dataIndexes],\n  );\n\n  const brushDimensions = useAppSelector(selectBrushDimensions);\n  if (brushDimensions == null || dataIndexes == null || chartData == null || !chartData.length) {\n    return null;\n  }\n\n  const { startIndex, endIndex } = dataIndexes;\n  const { x, y, width } = brushDimensions;\n\n  const contextProperties: PropertiesFromContext = {\n    data: chartData,\n    x,\n    y,\n    width,\n    startIndex,\n    endIndex,\n    onChange,\n  };\n  return (\n    <BrushWithState\n      {...props}\n      {...contextProperties}\n      startIndexControlledFromProps={startIndexFromProps ?? undefined}\n      endIndexControlledFromProps={endIndexFromProps ?? undefined}\n    />\n  );\n}\n\nfunction BrushSettingsDispatcher(props: BrushSettings): null {\n  const dispatch = useAppDispatch();\n  useEffect(() => {\n    dispatch(setBrushSettings(props));\n    return () => {\n      dispatch(setBrushSettings(null));\n    };\n  }, [dispatch, props]);\n  return null;\n}\n\nexport const defaultBrushProps = {\n  height: 40,\n  travellerWidth: 5,\n  gap: 1,\n  fill: '#fff',\n  stroke: '#666',\n  padding: { top: 1, right: 1, bottom: 1, left: 1 },\n  leaveTimeOut: 1000,\n  alwaysShowText: false,\n} as const satisfies Partial<Props>;\n\n/**\n * Renders a scrollbar that allows the user to zoom and pan in the chart along its XAxis.\n * It also allows you to render a small overview of the chart inside the brush that is always visible\n * and shows the full data set so that the user can see where they are zoomed in.\n *\n * If a chart is synchronized with other charts using the `syncId` prop on the chart,\n * the brush will also synchronize the zooming and panning between all synchronized charts.\n *\n * @see {@link https://recharts.github.io/en-US/examples/BrushBarChart/ BarChart with Brush}\n * @see {@link https://recharts.github.io/en-US/examples/SynchronizedLineChart/ Synchronized Brush}\n *\n * @consumes CartesianChartContext\n */\nexport function Brush(outsideProps: Props) {\n  const props = resolveDefaultProps(outsideProps, defaultBrushProps);\n  return (\n    <>\n      <BrushSettingsDispatcher\n        height={props.height}\n        x={props.x}\n        y={props.y}\n        width={props.width}\n        padding={props.padding}\n      />\n      <BrushInternal {...props} />\n    </>\n  );\n}\nBrush.displayName = 'Brush';\n","import { Coordinate, RectangleCoordinate, RectanglePosition, Size } from './types';\n\nexport const rectWithPoints = ({ x: x1, y: y1 }: Coordinate, { x: x2, y: y2 }: Coordinate): RectanglePosition => ({\n  x: Math.min(x1, x2),\n  y: Math.min(y1, y2),\n  width: Math.abs(x2 - x1),\n  height: Math.abs(y2 - y1),\n});\n\n/**\n * Compute the x, y, width, and height of a box from two reference points.\n * @param  {Object} coords     x1, x2, y1, and y2\n * @return {Object} object\n */\nexport const rectWithCoords = ({ x1, y1, x2, y2 }: RectangleCoordinate): RectanglePosition =>\n  rectWithPoints({ x: x1, y: y1 }, { x: x2, y: y2 });\n\n/** Normalizes the angle so that 0 <= angle < 180.\n * @param {number} angle Angle in degrees.\n * @return {number} the normalized angle with a value of at least 0 and never greater or equal to 180. */\nexport function normalizeAngle(angle: number) {\n  return ((angle % 180) + 180) % 180;\n}\n\n/** Calculates the width of the largest horizontal line that fits inside a rectangle that is displayed at an angle.\n * @param {Object} size Width and height of the text in a horizontal position.\n * @param {number} angle Angle in degrees in which the text is displayed.\n * @return {number} The width of the largest horizontal line that fits inside a rectangle that is displayed at an angle.\n */\nexport const getAngledRectangleWidth = ({ width, height }: Size, angle: number | undefined = 0) => {\n  // Ensure angle is >= 0 && < 180\n  const normalizedAngle = normalizeAngle(angle);\n  const angleRadians = (normalizedAngle * Math.PI) / 180;\n\n  /* Depending on the height and width of the rectangle, we may need to use different formulas to calculate the angled\n   * width. This threshold defines when each formula should kick in. */\n  const angleThreshold = Math.atan(height / width);\n\n  const angledWidth =\n    angleRadians > angleThreshold && angleRadians < Math.PI - angleThreshold\n      ? height / Math.sin(angleRadians)\n      : width / Math.cos(angleRadians);\n\n  return Math.abs(angledWidth);\n};\n","import { createSlice, current, PayloadAction } from '@reduxjs/toolkit';\nimport { castDraft, WritableDraft } from 'immer';\nimport { AxisId } from './cartesianAxisSlice';\nimport { IfOverflow } from '../util/IfOverflow';\nimport { ReferenceLineSegment } from '../cartesian/ReferenceLine';\n\nexport type ReferenceElementSettings = {\n  yAxisId: AxisId;\n  xAxisId: AxisId;\n  ifOverflow: IfOverflow;\n};\n\nexport type ReferenceDotSettings = ReferenceElementSettings & {\n  x: unknown;\n  y: unknown;\n  r: number;\n};\n\nexport type ReferenceAreaSettings = ReferenceElementSettings & {\n  x1: unknown;\n  x2: unknown;\n  y1: unknown;\n  y2: unknown;\n};\n\nexport type ReferenceLineSettings = ReferenceElementSettings & {\n  x: unknown;\n  y: unknown;\n  segment: ReferenceLineSegment | undefined;\n};\n\ntype ReferenceElementState = {\n  dots: ReadonlyArray<ReferenceDotSettings>;\n  areas: ReadonlyArray<ReferenceAreaSettings>;\n  lines: ReadonlyArray<ReferenceLineSettings>;\n};\n\nconst initialState: ReferenceElementState = {\n  dots: [],\n  areas: [],\n  lines: [],\n};\n\nexport const referenceElementsSlice = createSlice({\n  name: 'referenceElements',\n  initialState,\n  reducers: {\n    addDot: (state: WritableDraft<ReferenceElementState>, action: PayloadAction<ReferenceDotSettings>) => {\n      state.dots.push(action.payload);\n    },\n    removeDot: (state: WritableDraft<ReferenceElementState>, action: PayloadAction<ReferenceDotSettings>) => {\n      const index = current(state).dots.findIndex(dot => dot === action.payload);\n      if (index !== -1) {\n        state.dots.splice(index, 1);\n      }\n    },\n    addArea: (state: WritableDraft<ReferenceElementState>, action: PayloadAction<ReferenceAreaSettings>) => {\n      state.areas.push(action.payload);\n    },\n    removeArea: (state: WritableDraft<ReferenceElementState>, action: PayloadAction<ReferenceAreaSettings>) => {\n      const index = current(state).areas.findIndex(area => area === action.payload);\n      if (index !== -1) {\n        state.areas.splice(index, 1);\n      }\n    },\n    addLine: (state: WritableDraft<ReferenceElementState>, action: PayloadAction<ReferenceLineSettings>) => {\n      state.lines.push(castDraft(action.payload));\n    },\n    removeLine: (state: WritableDraft<ReferenceElementState>, action: PayloadAction<ReferenceLineSettings>) => {\n      const index = current(state).lines.findIndex(line => line === action.payload);\n      if (index !== -1) {\n        state.lines.splice(index, 1);\n      }\n    },\n  },\n});\n\nexport const { addDot, removeDot, addArea, removeArea, addLine, removeLine } = referenceElementsSlice.actions;\n\nexport const referenceElementsReducer = referenceElementsSlice.reducer;\n","import * as React from 'react';\nimport { createContext, ReactNode, useContext, useState } from 'react';\nimport { uniqueId } from '../util/DataUtils';\nimport { usePlotArea } from '../hooks';\n\nconst ClipPathIdContext = createContext<string | undefined>(undefined);\n\n/**\n * Generates a unique clip path ID for use in SVG elements,\n * and puts it in a context provider.\n *\n * To read the clip path ID, use the `useClipPathId` hook,\n * or render `<ClipPath>` component which will automatically use the ID from this context.\n *\n * @param props children - React children to be wrapped by the provider\n * @returns React Context Provider\n */\nexport const ClipPathProvider = ({ children }: { children: ReactNode }) => {\n  const [clipPathId] = useState<string>(`${uniqueId('recharts')}-clip`);\n\n  const plotArea = usePlotArea();\n\n  if (plotArea == null) {\n    return null;\n  }\n  const { x, y, width, height } = plotArea;\n\n  return (\n    <ClipPathIdContext.Provider value={clipPathId}>\n      <defs>\n        <clipPath id={clipPathId}>\n          <rect x={x} y={y} height={height} width={width} />\n        </clipPath>\n      </defs>\n      {children}\n    </ClipPathIdContext.Provider>\n  );\n};\n\nexport const useClipPathId = (): string | undefined => {\n  return useContext(ClipPathIdContext);\n};\n","import { BandPosition, RechartsScale } from './RechartsScale';\nimport { CategoricalDomainItem, Coordinate, NullableCoordinate } from '../types';\n\nexport interface CartesianScaleHelper<\n  XDomain extends CategoricalDomainItem = CategoricalDomainItem,\n  YDomain extends CategoricalDomainItem = CategoricalDomainItem,\n> {\n  map(value: { x: XDomain; y: YDomain }, { position }: { position: BandPosition }): Coordinate;\n\n  mapWithFallback(\n    value: { x?: XDomain | null | undefined; y?: YDomain | null | undefined },\n    { position, fallback }: { position?: BandPosition; fallback: 'rangeMin' | 'rangeMax' },\n  ): Coordinate;\n\n  isInRange({ x, y }: Partial<NullableCoordinate>): boolean;\n}\n\n/**\n * Groups X and Y scale functions together and provides helper methods.\n */\nexport class CartesianScaleHelperImpl<\n  XDomain extends CategoricalDomainItem = CategoricalDomainItem,\n  YDomain extends CategoricalDomainItem = CategoricalDomainItem,\n> implements CartesianScaleHelper<XDomain, YDomain> {\n  private xAxisScale: RechartsScale<XDomain>;\n\n  private yAxisScale: RechartsScale<YDomain>;\n\n  constructor({ x, y }: { x: RechartsScale<XDomain>; y: RechartsScale<YDomain> }) {\n    this.xAxisScale = x;\n    this.yAxisScale = y;\n  }\n\n  map(value: { x: XDomain; y: YDomain }, { position }: { position: BandPosition }): Coordinate {\n    return {\n      x: this.xAxisScale.map(value.x, { position }) ?? 0,\n      y: this.yAxisScale.map(value.y, { position }) ?? 0,\n    };\n  }\n\n  mapWithFallback(\n    value: { x?: XDomain | null | undefined; y?: YDomain | null | undefined },\n    { position, fallback }: { position?: BandPosition; fallback: 'rangeMin' | 'rangeMax' },\n  ): Coordinate {\n    let fallbackY: number, fallbackX: number;\n    if (fallback === 'rangeMin') {\n      fallbackY = this.yAxisScale.rangeMin();\n    } else if (fallback === 'rangeMax') {\n      fallbackY = this.yAxisScale.rangeMax();\n    } else {\n      fallbackY = 0;\n    }\n    if (fallback === 'rangeMin') {\n      fallbackX = this.xAxisScale.rangeMin();\n    } else if (fallback === 'rangeMax') {\n      fallbackX = this.xAxisScale.rangeMax();\n    } else {\n      fallbackX = 0;\n    }\n    return {\n      x: this.xAxisScale.map(value.x, { position }) ?? fallbackX,\n      y: this.yAxisScale.map(value.y, { position }) ?? fallbackY,\n    };\n  }\n\n  isInRange({ x, y }: Partial<NullableCoordinate>): boolean {\n    const xInRange = x == null || this.xAxisScale.isInRange(x);\n    const yInRange = y == null || this.yAxisScale.isInRange(y);\n    return xInRange && yInRange;\n  }\n}\n","/**\n * @fileOverview Reference Line\n */\nimport * as React from 'react';\nimport { ReactElement, SVGProps, useEffect } from 'react';\nimport { clsx } from 'clsx';\nimport { Layer } from '../container/Layer';\nimport { CartesianLabelContextProvider, CartesianLabelFromLabelProp, ImplicitLabelType } from '../component/Label';\nimport { IfOverflow, Overflowable } from '../util/IfOverflow';\nimport { isNumOrStr } from '../util/DataUtils';\nimport { rectWithCoords } from '../util/CartesianUtils';\nimport { CartesianViewBoxRequired, Coordinate } from '../util/types';\nimport { useViewBox } from '../context/chartLayoutContext';\nimport { addLine, ReferenceLineSettings, removeLine } from '../state/referenceElementsSlice';\nimport { useAppDispatch, useAppSelector } from '../state/hooks';\nimport { selectAxisScale, selectXAxisSettings, selectYAxisSettings } from '../state/selectors/axisSelectors';\nimport { useIsPanorama } from '../context/PanoramaContext';\n\nimport { useClipPathId } from '../container/ClipPathProvider';\nimport { svgPropertiesAndEvents } from '../util/svgPropertiesAndEvents';\nimport { RequiresDefaultProps, resolveDefaultProps } from '../util/resolveDefaultProps';\nimport { ZIndexable, ZIndexLayer } from '../zIndex/ZIndexLayer';\nimport { DefaultZIndexes } from '../zIndex/DefaultZIndexes';\nimport { isWellBehavedNumber } from '../util/isWellBehavedNumber';\nimport { BandPosition, RechartsScale } from '../util/scale/RechartsScale';\nimport { CartesianScaleHelper, CartesianScaleHelperImpl } from '../util/scale/CartesianScaleHelper';\n\n/**\n * Single point that defines one end of a segment.\n * These coordinates are in data space, meaning that you should provide\n * values that correspond to the data domain of the axes.\n * So you would provide a value of `Page A` to indicate the data value `Page A`\n * and then recharts will convert that to pixels.\n *\n * Likewise for numbers. If your x-axis goes from 0 to 100,\n * and you want the line to end at 50, you would provide `50` here.\n *\n * @inline\n */\nexport type ReferenceLineSegment = readonly [\n  {\n    x?: number | string;\n    y?: number | string;\n  },\n  {\n    x?: number | string;\n    y?: number | string;\n  },\n];\n\ntype ReferenceCoordinateValue = number | string;\n\ninterface ReferenceLineProps<\n  XValueType extends ReferenceCoordinateValue = any,\n  YValueType extends ReferenceCoordinateValue = any,\n>\n  extends Overflowable, ZIndexable {\n  /**\n   * If defined, renders a horizontal line on this position.\n   *\n   * This value is using your chart's domain, so you will provide a data value instead of a pixel value.\n   * ReferenceLine will internally calculate the correct pixel position.\n   *\n   * @example <ReferenceLine y=\"Page D\" />\n   */\n  y?: YValueType;\n\n  /**\n   * If defined, renders a vertical line on this position.\n   *\n   * This value is using your chart's domain, so you will provide a data value instead of a pixel value.\n   * ReferenceLine will internally calculate the correct pixel position.\n   *\n   * @example <ReferenceLine x=\"Monday\" />\n   */\n  x?: XValueType;\n\n  /**\n   * Tuple of coordinates. If defined, renders a diagonal line segment.\n   */\n  segment?: readonly [\n    {\n      x?: XValueType;\n      y?: YValueType;\n    },\n    {\n      x?: XValueType;\n      y?: YValueType;\n    },\n  ];\n\n  /**\n   * The position of the reference line when the axis has bandwidth\n   * (e.g., a band scale). This determines where within the band\n   * the line is drawn.\n   * @defaultValue 'middle'\n   */\n  position?: BandPosition;\n\n  className?: number | string;\n  /**\n   * The id of y-axis which is corresponding to the data.\n   * Required when there are multiple YAxes.\n   * @defaultValue 0\n   */\n  yAxisId?: number | string;\n  /**\n   * The id of x-axis which is corresponding to the data.\n   * Required when there are multiple XAxes.\n   * @defaultValue 0\n   */\n  xAxisId?: number | string;\n  shape?: ReactElement<SVGElement> | ((props: any) => ReactElement<SVGElement>);\n  /**\n   * Renders a single label.\n   *\n   * - `false`: no labels are rendered\n   * - `string` | `number`: the content of the label\n   * - `object`: the props of LabelList component\n   * - `ReactElement`: a custom label element\n   * - `function`: a render function of custom label\n   *\n   * @defaultValue false\n   *\n   * @see {@link https://recharts.github.io/en-US/examples/LineChartWithReferenceLines/ Reference elements with a label}\n   */\n  label?: ImplicitLabelType;\n  /**\n   * Z-Index of this component and its children. The higher the value,\n   * the more on top it will be rendered.\n   * Components with higher zIndex will appear in front of components with lower zIndex.\n   * If undefined or 0, the content is rendered in the default layer without portals.\n   *\n   * @since 3.4\n   * @defaultValue 400\n   * @see {@link https://recharts.github.io/en-US/guide/zIndex/ Z-Index and layers guide}\n   */\n  zIndex?: number;\n  /**\n   * The width of the stroke\n   * @defaultValue 1\n   */\n  strokeWidth?: number | string;\n}\n\n/**\n * This excludes `viewBox` prop from svg for two reasons:\n * 1. The components wants viewBox of object type, and svg wants string\n *    - so there's a conflict, and the component will throw if it gets string\n * 2. Internally the component calls `svgPropertiesNoEvents` which filters the viewBox away anyway\n */\nexport type Props<\n  XValueType extends ReferenceCoordinateValue = any,\n  YValueType extends ReferenceCoordinateValue = any,\n> = Omit<SVGProps<SVGLineElement>, 'viewBox'> & ReferenceLineProps<XValueType, YValueType>;\n\nconst renderLine = (option: ReferenceLineProps['shape'], props: SVGProps<SVGLineElement>) => {\n  let line;\n\n  if (React.isValidElement(option)) {\n    // @ts-expect-error element cloning is not typed\n    line = React.cloneElement(option, props);\n  } else if (typeof option === 'function') {\n    line = option(props);\n  } else {\n    if (\n      !isWellBehavedNumber(props.x1) ||\n      !isWellBehavedNumber(props.y1) ||\n      !isWellBehavedNumber(props.x2) ||\n      !isWellBehavedNumber(props.y2)\n    ) {\n      return null;\n    }\n    line = <line {...props} className=\"recharts-reference-line-line\" />;\n  }\n\n  return line;\n};\n\ntype EndPointsPropsSubset = Pick<PropsWithDefaults, 'y' | 'x' | 'segment' | 'ifOverflow'>;\n\nconst getHorizontalLineEndPoints = (\n  yCoord: number | string,\n  ifOverflow: IfOverflow,\n  position: Props['position'],\n  yAxisOrientation: Props['orientation'],\n  yAxisScale: RechartsScale,\n  viewBox: CartesianViewBoxRequired,\n): ReadonlyArray<Coordinate> | null => {\n  const { x, width } = viewBox;\n  const coord = yAxisScale.map(yCoord, { position });\n  // don't render the line if the scale can't compute a result that makes sense\n  if (!isWellBehavedNumber(coord)) {\n    return null;\n  }\n\n  if (ifOverflow === 'discard' && !yAxisScale.isInRange(coord)) {\n    return null;\n  }\n\n  const points = [\n    { x: x + width, y: coord },\n    { x, y: coord },\n  ];\n  return yAxisOrientation === 'left' ? points.reverse() : points;\n};\n\nconst getVerticalLineEndPoints = (\n  xCoord: number | string,\n  ifOverflow: IfOverflow,\n  position: Props['position'],\n  xAxisOrientation: Props['orientation'],\n  xAxisScale: RechartsScale,\n  viewBox: CartesianViewBoxRequired,\n): ReadonlyArray<Coordinate> | null => {\n  const { y, height } = viewBox;\n  const coord = xAxisScale.map(xCoord, { position });\n  // don't render the line if the scale can't compute a result that makes sense\n  if (!isWellBehavedNumber(coord)) {\n    return null;\n  }\n\n  if (ifOverflow === 'discard' && !xAxisScale.isInRange(coord)) {\n    return null;\n  }\n\n  const points = [\n    { x: coord, y: y + height },\n    { x: coord, y },\n  ];\n  return xAxisOrientation === 'top' ? points.reverse() : points;\n};\n\nconst getSegmentLineEndPoints = (\n  segment: ReferenceLineSegment,\n  ifOverflow: IfOverflow,\n  position: Props['position'],\n  scales: CartesianScaleHelper,\n): ReadonlyArray<Coordinate> | null => {\n  const points: [Coordinate, Coordinate] = [\n    scales.mapWithFallback(segment[0], { position, fallback: 'rangeMin' }),\n    scales.mapWithFallback(segment[1], { position, fallback: 'rangeMax' }),\n  ];\n\n  if (ifOverflow === 'discard' && points.some(p => !scales.isInRange(p))) {\n    return null;\n  }\n\n  return points;\n};\n\nexport const getEndPoints = (\n  xAxisScale: RechartsScale,\n  yAxisScale: RechartsScale,\n  viewBox: CartesianViewBoxRequired,\n  position: Props['position'],\n  xAxisOrientation: Props['orientation'],\n  yAxisOrientation: Props['orientation'],\n  props: EndPointsPropsSubset,\n): ReadonlyArray<Coordinate> | null => {\n  const { x: xCoord, y: yCoord, segment, ifOverflow } = props;\n  const isFixedX = isNumOrStr(xCoord);\n  const isFixedY = isNumOrStr(yCoord);\n\n  if (isFixedY) {\n    return getHorizontalLineEndPoints(yCoord, ifOverflow, position, yAxisOrientation, yAxisScale, viewBox);\n  }\n  if (isFixedX) {\n    return getVerticalLineEndPoints(xCoord, ifOverflow, position, xAxisOrientation, xAxisScale, viewBox);\n  }\n  if (segment != null && segment.length === 2) {\n    return getSegmentLineEndPoints(\n      segment,\n      ifOverflow,\n      position,\n      new CartesianScaleHelperImpl({ x: xAxisScale, y: yAxisScale }),\n    );\n  }\n\n  return null;\n};\n\nfunction ReportReferenceLine(props: ReferenceLineSettings): null {\n  const dispatch = useAppDispatch();\n  useEffect(() => {\n    dispatch(addLine(props));\n    return () => {\n      dispatch(removeLine(props));\n    };\n  });\n  return null;\n}\n\nfunction ReferenceLineImpl(props: PropsWithDefaults) {\n  const { xAxisId, yAxisId, shape, className, ifOverflow } = props;\n\n  const isPanorama = useIsPanorama();\n  const clipPathId = useClipPathId();\n  const xAxis = useAppSelector(state => selectXAxisSettings(state, xAxisId));\n  const yAxis = useAppSelector(state => selectYAxisSettings(state, yAxisId));\n  const xAxisScale = useAppSelector(state => selectAxisScale(state, 'xAxis', xAxisId, isPanorama));\n  const yAxisScale = useAppSelector(state => selectAxisScale(state, 'yAxis', yAxisId, isPanorama));\n\n  const viewBox = useViewBox();\n\n  if (!clipPathId || !viewBox || xAxis == null || yAxis == null || xAxisScale == null || yAxisScale == null) {\n    return null;\n  }\n\n  const endPoints: ReadonlyArray<Coordinate> | null = getEndPoints(\n    xAxisScale,\n    yAxisScale,\n    viewBox,\n    props.position,\n    xAxis.orientation,\n    yAxis.orientation,\n    props,\n  );\n  if (!endPoints) {\n    return null;\n  }\n\n  const point1 = endPoints[0];\n  const point2 = endPoints[1];\n  if (point1 == null || point2 == null) {\n    return null;\n  }\n  const { x: x1, y: y1 } = point1;\n  const { x: x2, y: y2 } = point2;\n\n  const clipPath = ifOverflow === 'hidden' ? `url(#${clipPathId})` : undefined;\n\n  const lineProps: SVGProps<SVGLineElement> = {\n    clipPath,\n    ...svgPropertiesAndEvents(props),\n    x1,\n    y1,\n    x2,\n    y2,\n  };\n\n  const rect = rectWithCoords({ x1, y1, x2, y2 });\n\n  return (\n    <ZIndexLayer zIndex={props.zIndex}>\n      <Layer className={clsx('recharts-reference-line', className)}>\n        {renderLine(shape, lineProps)}\n        <CartesianLabelContextProvider {...rect} lowerWidth={rect.width} upperWidth={rect.width}>\n          <CartesianLabelFromLabelProp label={props.label} />\n          {props.children}\n        </CartesianLabelContextProvider>\n      </Layer>\n    </ZIndexLayer>\n  );\n}\n\nexport const referenceLineDefaultProps = {\n  ifOverflow: 'discard',\n  xAxisId: 0,\n  yAxisId: 0,\n  fill: 'none',\n  label: false,\n  stroke: '#ccc',\n  fillOpacity: 1,\n  strokeWidth: 1,\n  position: 'middle',\n  zIndex: DefaultZIndexes.line,\n} as const satisfies Partial<Props>;\n\ntype PropsWithDefaults = RequiresDefaultProps<Props, typeof referenceLineDefaultProps>;\n\n/**\n * Draws a line on the chart connecting two points.\n *\n * This component, unlike {@link https://developer.mozilla.org/en-US/docs/Web/SVG/Reference/Element/line line}, is aware of the cartesian coordinate system,\n * so you specify the dimensions by using data coordinates instead of