sInput = {\n  angle?: number;\n  interval: CartesianAxisSettings['interval'] | undefined;\n  minTickGap: number;\n  orientation: XAxisOrientation | YAxisOrientation;\n  tick: CartesianAxisSettings['tick'];\n  tickFormatter?: CartesianAxisSettings['tickFormatter'];\n  ticks: ReadonlyArray<CartesianTickItem> | null;\n  unit?: CartesianAxisSettings['unit'];\n  viewBox: CartesianViewBoxRequired;\n};\n\nexport function getTicks(\n  props: GetTicksInput,\n  fontSize?: string,\n  letterSpacing?: string,\n): ReadonlyArray<CartesianTickItem> {\n  const { tick, ticks, viewBox, minTickGap, orientation, interval, tickFormatter, unit, angle } = props;\n\n  if (!ticks || !ticks.length || !tick) {\n    return [];\n  }\n\n  if (isNumber(interval) || Global.isSsr) {\n    return getNumberIntervalTicks(ticks, isNumber(interval) ? interval : 0) ?? [];\n  }\n\n  let candidates: ReadonlyArray<CartesianTickItem> = [];\n\n  const sizeKey = orientation === 'top' || orientation === 'bottom' ? 'width' : 'height';\n  const unitSize: Size =\n    unit && sizeKey === 'width' ? getStringSize(unit, { fontSize, letterSpacing }) : { width: 0, height: 0 };\n\n  const getTickSize = (content: CartesianTickItem, index: number) => {\n    const value = typeof tickFormatter === 'function' ? tickFormatter(content.value, index) : content.value;\n    // Recharts only supports angles when sizeKey === 'width'\n    return sizeKey === 'width'\n      ? getAngledTickWidth(getStringSize(value, { fontSize, letterSpacing }), unitSize, angle)\n      : getStringSize(value, { fontSize, letterSpacing })[sizeKey];\n  };\n\n  const tick0 = ticks[0];\n  const tick1 = ticks[1];\n  const sign = ticks.length >= 2 && tick0 != null && tick1 != null ? mathSign(tick1.coordinate - tick0.coordinate) : 1;\n  const boundaries = getTickBoundaries(viewBox, sign, sizeKey);\n\n  if (interval === 'equidistantPreserveStart') {\n    return getEquidistantTicks(sign, boundaries, getTickSize, ticks, minTickGap);\n  }\n  if (interval === 'equidistantPreserveEnd') {\n    return getEquidistantPreserveEndTicks(sign, boundaries, getTickSize, ticks, minTickGap);\n  }\n\n  if (interval === 'preserveStart' || interval === 'preserveStartEnd') {\n    candidates = getTicksStart(sign, boundaries, getTickSize, ticks, minTickGap, interval === 'preserveStartEnd');\n  } else {\n    candidates = getTicksEnd(sign, boundaries, getTickSize, ticks, minTickGap);\n  }\n\n  return candidates.filter(entry => entry.isShow);\n}\n","import { isVisible } from '../util/TickUtils';\nimport { CartesianTickItem } from '../util/types';\nimport { getEveryNth } from '../util/getEveryNth';\nimport { Sign } from './getTicks';\n\nexport function getEquidistantTicks(\n  sign: Sign,\n  boundaries: { start: number; end: number },\n  getTickSize: (tick: CartesianTickItem, index: number) => number,\n  ticks: ReadonlyArray<CartesianTickItem>,\n  minTickGap: number,\n): ReadonlyArray<CartesianTickItem> {\n  // If the ticks are readonly, then the slice might not be necessary\n  const result = (ticks || []).slice();\n\n  const { start: initialStart, end } = boundaries;\n  let index = 0;\n  // Premature optimisation idea 1: Estimate a lower bound, and start from there.\n  // For now, start from every tick\n  let stepsize = 1;\n  let start = initialStart;\n\n  while (stepsize <= result.length) {\n    // Given stepsize, evaluate whether every stepsize-th tick can be shown.\n    // If it can not, then increase the stepsize by 1, and try again.\n\n    const entry = ticks?.[index];\n\n    // Break condition - If we have evaluated all the ticks, then we are done.\n    if (entry === undefined) {\n      return getEveryNth(ticks, stepsize);\n    }\n\n    // Check if the element collides with the next element\n    const i = index;\n    let size: number | undefined;\n    const getSize = () => {\n      if (size === undefined) {\n        size = getTickSize(entry, i);\n      }\n\n      return size;\n    };\n\n    const tickCoord = entry.coordinate;\n    // We will always show the first tick.\n    const isShow = index === 0 || isVisible(sign, tickCoord, getSize, start, end);\n\n    if (!isShow) {\n      // Start all over with a larger stepsize\n      index = 0;\n      start = initialStart;\n      stepsize += 1;\n    }\n\n    if (isShow) {\n      // If it can be shown, update the start\n      start = tickCoord + sign * (getSize() / 2 + minTickGap);\n      index += stepsize;\n    }\n  }\n\n  return [];\n}\n\nexport function getEquidistantPreserveEndTicks(\n  sign: Sign,\n  boundaries: { start: number; end: number },\n  getTickSize: (tick: CartesianTickItem, index: number) => number,\n  ticks: ReadonlyArray<CartesianTickItem>,\n  minTickGap: number,\n): ReadonlyArray<CartesianTickItem> {\n  // If the ticks are readonly, then the slice might not be necessary\n  // Reworked logic for getEquidistantPreserveEndTicks\n  const result = (ticks || []).slice();\n  const len = result.length;\n\n  if (len === 0) {\n    return [];\n  }\n\n  const { start: initialStart, end } = boundaries;\n\n  // Start with stepsize = 1 (every tick) up to the maximum possible stepsize (len)\n  for (let stepsize = 1; stepsize <= len; stepsize++) {\n    // 1. Calculate the offset so the last tick (index len - 1) is always included in the sequence.\n    const offset = (len - 1) % stepsize;\n    let start = initialStart; // `start` tracks the coordinate of the last successfully drawn tick + gap\n    let ok = true;\n\n    // 2. Iterate through the end-anchored sequence: offset, offset + stepsize, ..., len - 1\n    for (let index = offset; index < len; index += stepsize) {\n      const entry = ticks[index];\n      if (entry == null) {\n        continue;\n      }\n      const i = index;\n      let size: number | undefined;\n\n      // Use a function to get size, as in the original code\n      const getSize = () => {\n        if (size === undefined) {\n          size = getTickSize(entry, i);\n        }\n        return size;\n      };\n\n      const tickCoord = entry.coordinate;\n\n      // 3. Apply visibility logic (including the first tick special case)\n      // The reviewer says *not* to unconditionally bypass checks for the last tick.\n      const isShow = index === offset || isVisible(sign, tickCoord, getSize, start, end);\n\n      if (!isShow) {\n        // If any tick in this end-anchored sequence fails visibility/collision,\n        // reject this stepsize and move to the next iteration (larger stepsize).\n        ok = false;\n        break;\n      }\n\n      // 4. If showable, update the 'start' coordinate for the next collision check\n      if (isShow) {\n        start = tickCoord + sign * (getSize() / 2 + minTickGap);\n      }\n    }\n\n    // 5. If the entire sequence for this stepsize passed the visibility check, return the result\n    if (ok) {\n      // Build the final result array explicitly using the validated stepsize and offset.\n      const finalTicks: CartesianTickItem[] = [];\n      for (let index = offset; index < len; index += stepsize) {\n        const tick = ticks[index];\n        if (tick != null) {\n          finalTicks.push(tick);\n        }\n      }\n      return finalTicks;\n    }\n  }\n\n  // If no stepsize works (this shouldn't happen unless minTickGap is huge), return an empty array.\n  return [];\n}\n","type IGetBoundingClient = Pick<Element, 'getBoundingClientRect'>;\n\n/**\n * Calculates the width of the Y-axis based on the tick labels and the axis label.\n * @param params - The parameters object.\n * @param [params.ticks] - An array-like object of tick elements, each with a `getBoundingClientRect` method.\n * @param [params.label] - The axis label element, with a `getBoundingClientRect` method.\n * @param [params.labelGapWithTick=5] - The gap between the label and the tick.\n * @param [params.tickSize=0] - The length of the tick line.\n * @param [params.tickMargin=0] - The margin between the tick line and the tick text.\n * @returns The calculated width of the Y-axis.\n */\nexport const getCalculatedYAxisWidth = ({\n  ticks,\n  label,\n  labelGapWithTick = 5, // Default gap between label and tick\n  tickSize = 0,\n  tickMargin = 0,\n}: {\n  ticks: ArrayLike<IGetBoundingClient> | null;\n  label: IGetBoundingClient | null | undefined;\n  labelGapWithTick: number | undefined;\n  tickSize: number | undefined;\n  tickMargin: number | undefined;\n}): number => {\n  // find the max width of the tick labels\n  let maxTickWidth = 0;\n  if (ticks) {\n    Array.from(ticks).forEach((tickNode: IGetBoundingClient) => {\n      if (tickNode) {\n        const bbox = tickNode.getBoundingClientRect();\n\n        if (bbox.width > maxTickWidth) {\n          maxTickWidth = bbox.width;\n        }\n      }\n    });\n\n    // calculate width of the axis label\n    const labelWidth = label ? label.getBoundingClientRect().width : 0;\n\n    const tickWidth = tickSize + tickMargin;\n\n    // calculate the updated width of the y-axis\n    const updatedYAxisWidth = maxTickWidth + tickWidth + labelWidth + (label ? labelGapWithTick : 0);\n\n    return Math.round(updatedYAxisWidth);\n  }\n\n  return 0;\n};\n","/**\n * @fileOverview this stores actually rendered ticks.\n *\n * What we do is that we have the domain -> ticks mapping in the cartesianSlice,\n * which is fine but the result then goes to CartesianAxis where we use DOM measurement\n * to decide which ticks to actually render.\n *\n * This renderedTickSlice stores those actually rendered ticks so that we can return them from a hook later.\n */\nimport { createSlice, PayloadAction } from '@reduxjs/toolkit';\nimport { castDraft, WritableDraft } from 'immer';\nimport { TickItem } from '../util/types';\nimport { AxisId } from './cartesianAxisSlice';\n\ntype RenderedTicksAxisState = {\n  [axisId: AxisId]: ReadonlyArray<TickItem>;\n};\n\ntype RenderedTicksState = {\n  xAxis: RenderedTicksAxisState;\n  yAxis: RenderedTicksAxisState;\n};\n\nconst initialState: RenderedTicksState = {\n  xAxis: {},\n  yAxis: {},\n};\n\nexport const renderedTicksSlice = createSlice({\n  name: 'renderedTicks',\n  initialState,\n  reducers: {\n    setRenderedTicks: (\n      state: WritableDraft<RenderedTicksState>,\n      action: PayloadAction<{\n        axisType: 'xAxis' | 'yAxis';\n        axisId: AxisId;\n        ticks: ReadonlyArray<TickItem>;\n      }>,\n    ) => {\n      const { axisType, axisId, ticks } = action.payload;\n      state[axisType][axisId] = castDraft(ticks);\n    },\n    removeRenderedTicks: (\n      state: WritableDraft<RenderedTicksState>,\n      action: PayloadAction<{\n        axisType: 'xAxis' | 'yAxis';\n        axisId: AxisId;\n      }>,\n    ) => {\n      const { axisType, axisId } = action.payload;\n      delete state[axisType][axisId];\n    },\n  },\n});\n\nexport const { setRenderedTicks, removeRenderedTicks } = renderedTicksSlice.actions;\n\nexport const renderedTicksReducer = renderedTicksSlice.reducer;\n","/**\n * @fileOverview Cartesian Axis\n */\nimport * as React from 'react';\nimport { SVGProps, useState, useRef, useCallback, forwardRef, useImperativeHandle, useEffect } from 'react';\n\nimport get from 'es-toolkit/compat/get';\nimport { clsx } from 'clsx';\nimport { Layer } from '../container/Layer';\nimport { Text, Props as TextProps, TextAnchor, TextVerticalAnchor, isValidTextAnchor } from '../component/Text';\nimport { CartesianLabelContextProvider, ImplicitLabelType, CartesianLabelFromLabelProp } from '../component/Label';\nimport { isNumber, noop } from '../util/DataUtils';\nimport {\n  CartesianViewBox,\n  adaptEventsOfChild,\n  PresentationAttributesAdaptChildEvent,\n  CartesianTickItem,\n  AxisInterval,\n  Coordinate,\n  RectangleCoordinate,\n  TickProp,\n  BaseTickContentProps,\n  XAxisTickContentProps,\n  YAxisTickContentProps,\n  TickItem as TickItemType,\n} from '../util/types';\nimport { getTicks } from './getTicks';\nimport { svgPropertiesNoEvents, svgPropertiesNoEventsFromUnknown } from '../util/svgPropertiesNoEvents';\nimport { AxisId, XAxisOrientation, XAxisPadding, YAxisOrientation, YAxisPadding } from '../state/cartesianAxisSlice';\nimport { getCalculatedYAxisWidth } from '../util/YAxisUtils';\nimport { RequiresDefaultProps, resolveDefaultProps } from '../util/resolveDefaultProps';\nimport { ZIndexable, ZIndexLayer } from '../zIndex/ZIndexLayer';\nimport { DefaultZIndexes } from '../zIndex/DefaultZIndexes';\nimport { getClassNameFromUnknown } from '../util/getClassNameFromUnknown';\nimport { removeRenderedTicks, setRenderedTicks } from '../state/renderedTicksSlice';\nimport { useAppDispatch } from '../state/hooks';\n\n/** The orientation of the axis in correspondence to the chart */\nexport type Orientation = XAxisOrientation | YAxisOrientation;\n/** A unit to be appended to a value */\nexport type Unit = string | number;\n/** The formatter function of tick */\nexport type TickFormatter = (value: any, index: number) => string;\n\nexport interface CartesianAxisProps extends ZIndexable {\n  className?: string;\n  axisType?: 'xAxis' | 'yAxis';\n  axisId?: AxisId;\n  x?: number;\n  y?: number;\n  width?: number;\n  height?: number;\n  unit?: Unit;\n  orientation?: Orientation;\n  // The viewBox of svg\n  viewBox?: CartesianViewBox;\n  tick?: TickProp<unknown>;\n  /**\n   * Additional props to spread to each tick Text element.\n   * Optional, the CartesianAxis component will provide its own defaults calculated from other props.\n   */\n  tickTextProps?: TextProps;\n  axisLine?: boolean | SVGProps<SVGLineElement>;\n  tickLine?: boolean | SVGProps<SVGLineElement>;\n  mirror?: boolean;\n  tickMargin?: number;\n  hide?: boolean;\n  label?: ImplicitLabelType;\n  /** Padding information passed to custom tick components */\n  padding?: XAxisPadding | YAxisPadding;\n\n  minTickGap?: number;\n  /**\n   * Careful - this is the same name as XAxis + YAxis `ticks` but completely different object!\n   */\n  ticks?: ReadonlyArray<CartesianTickItem>;\n  tickSize?: number;\n  tickFormatter?: TickFormatter;\n  interval?: AxisInterval;\n  /** Angle in which ticks will be rendered. */\n  angle?: number;\n  /**\n   * CartesianAxis reads scale internally and this prop is ignored since 3.0\n   * @deprecated\n   */\n  scale?: unknown;\n  labelRef?: React.RefObject<SVGTextElement> | null;\n\n  ref?: React.Ref<CartesianAxisRef>;\n}\n\nexport interface CartesianAxisRef {\n  getCalculatedWidth(): number;\n}\n\nexport const defaultCartesianAxisProps = {\n  x: 0,\n  y: 0,\n  width: 0,\n  height: 0,\n  viewBox: { x: 0, y: 0, width: 0, height: 0 },\n  // The orientation of axis\n  orientation: 'bottom',\n  // The ticks\n  ticks: [] as CartesianAxisProps['ticks'],\n\n  stroke: '#666',\n  tickLine: true,\n  axisLine: true,\n  tick: true,\n  mirror: false,\n\n  minTickGap: 5,\n  // The width or height of tick\n  tickSize: 6,\n  tickMargin: 2,\n  interval: 'preserveEnd',\n  zIndex: DefaultZIndexes.axis,\n} as const satisfies Partial<Props>;\n\n/*\n * `viewBox` and `scale` are SVG attributes.\n * Recharts however - unfortunately - has its own attributes named `viewBox` and `scale`\n * that are completely different data shape and different purpose.\n */\nexport type Props = Omit<PresentationAttributesAdaptChildEvent<any, SVGElement>, 'viewBox' | 'scale' | 'ref'> &\n  CartesianAxisProps;\n\ntype InternalProps = RequiresDefaultProps<Props, typeof defaultCartesianAxisProps>;\n\nfunction AxisLine(axisLineProps: {\n  x: number;\n  y: number;\n  width: number;\n  height: number;\n  orientation: Orientation;\n  mirror: boolean;\n  axisLine: boolean | SVGProps<SVGLineElement>;\n  otherSvgProps: SVGProps<SVGLineElement> | null;\n}) {\n  const { x, y, width, height, orientation, mirror, axisLine, otherSvgProps } = axisLineProps;\n\n  if (!axisLine) {\n    return null;\n  }\n\n  let props: SVGProps<SVGLineElement> = {\n    ...otherSvgProps,\n    ...svgPropertiesNoEvents(axisLine),\n    fill: 'none',\n  };\n\n  if (orientation === 'top' || orientation === 'bottom') {\n    const needHeight = +((orientation === 'top' && !mirror) || (orientation === 'bottom' && mirror));\n    props = {\n      ...props,\n      x1: x,\n      y1: y + needHeight * height,\n      x2: x + width,\n      y2: y + needHeight * height,\n    };\n  } else {\n    const needWidth = +((orientation === 'left' && !mirror) || (orientation === 'right' && mirror));\n    props = {\n      ...props,\n      x1: x + needWidth * width,\n      y1: y,\n      x2: x + needWidth * width,\n      y2: y + height,\n    };\n  }\n\n  return <line {...props} className={clsx('recharts-cartesian-axis-line', get(axisLine, 'className'))} />;\n}\n\n/**\n * Calculate the coordinates of endpoints in ticks.\n * @param data The data of a simple tick.\n * @param x The x-coordinate of the axis.\n * @param y The y-coordinate of the axis.\n * @param width The width of the axis.\n * @param height The height of the axis.\n * @param orientation The orientation of the axis.\n * @param tickSize The length of the tick line.\n * @param mirror If true, the ticks are mirrored.\n * @param tickMargin The margin between the tick line and the tick text.\n * @returns An object with `line` and `tick` coordinates.\n * `line` is the coordinates for the tick line, and `tick` is the coordinate for the tick text.\n */\nfunction getTickLineCoord(\n  data: CartesianTickItem,\n  x: number,\n  y: number,\n  width: number,\n  height: number,\n  orientation: Orientation,\n  tickSize: number,\n  mirror: boolean,\n  tickMargin: number,\n): {\n  line: RectangleCoordinate;\n  tick: Coordinate;\n} {\n  let x1, x2, y1, y2, tx, ty;\n\n  const sign = mirror ? -1 : 1;\n  const finalTickSize = data.tickSize || tickSize;\n  const tickCoord = isNumber(data.tickCoord) ? data.tickCoord : data.coordinate;\n\n  switch (orientation) {\n    case 'top':\n      x1 = x2 = data.coordinate;\n      y2 = y + +!mirror * height;\n      y1 = y2 - sign * finalTickSize;\n      ty = y1 - sign * tickMargin;\n      tx = tickCoord;\n      break;\n    case 'left':\n      y1 = y2 = data.coordinate;\n      x2 = x + +!mirror * width;\n      x1 = x2 - sign * finalTickSize;\n      tx = x1 - sign * tickMargin;\n      ty = tickCoord;\n      break;\n    case 'right':\n      y1 = y2 = data.coordinate;\n      x2 = x + +mirror * width;\n      x1 = x2 + sign * finalTickSize;\n      tx = x1 + sign * tickMargin;\n      ty = tickCoord;\n      break;\n    default:\n      x1 = x2 = data.coordinate;\n      y2 = y + +mirror * height;\n      y1 = y2 + sign * finalTickSize;\n      ty = y1 + sign * tickMargin;\n      tx = tickCoord;\n      break;\n  }\n\n  return { line: { x1, y1, x2, y2 }, tick: { x: tx, y: ty } };\n}\n\n/**\n * @param orientation The orientation of the axis.\n * @param mirror If true, the ticks are mirrored.\n * @returns The text anchor of the tick.\n */\nfunction getTickTextAnchor(orientation: Orientation, mirror: boolean): TextAnchor {\n  switch (orientation) {\n    case 'left':\n      return mirror ? 'start' : 'end';\n    case 'right':\n      return mirror ? 'end' : 'start';\n    default:\n      return 'middle';\n  }\n}\n\n/**\n * @param orientation The orientation of the axis.\n * @param mirror If true, the ticks are mirrored.\n * @returns The vertical text anchor of the tick.\n */\nfunction getTickVerticalAnchor(orientation: Orientation, mirror: boolean): TextVerticalAnchor {\n  switch (orientation) {\n    case 'left':\n    case 'right':\n      return 'middle';\n    case 'top':\n      return mirror ? 'start' : 'end';\n    default:\n      return mirror ? 'end' : 'start';\n  }\n}\n\nfunction TickItem(props: { option: Props['tick']; tickProps: TextProps; value: string }) {\n  const { option, tickProps, value } = props;\n  let tickItem;\n  const combinedClassName = clsx(tickProps.className, 'recharts-cartesian-axis-tick-value');\n\n  if (React.isValidElement(option)) {\n    // @ts-expect-error element cloning is not typed\n    tickItem = React.cloneElement(option, { ...tickProps, className: combinedClassName });\n  } else if (typeof option === 'function') {\n    tickItem = option({ ...tickProps, className: combinedClassName });\n  } else {\n    let className = 'recharts-cartesian-axis-tick-value';\n\n    if (typeof option !== 'boolean') {\n      className = clsx(className, getClassNameFromUnknown(option));\n    }\n\n    tickItem = (\n      <Text {...tickProps} className={className}>\n        {value}\n      </Text>\n    );\n  }\n\n  return tickItem;\n}\n\nfunction RenderedTicksReporter({\n  ticks,\n  axisType,\n  axisId,\n}: {\n  ticks: ReadonlyArray<TickItemType>;\n  axisType: 'xAxis' | 'yAxis' | undefined;\n  axisId: AxisId | undefined;\n}) {\n  const dispatch = useAppDispatch();\n  useEffect(() => {\n    if (axisId == null || axisType == null) {\n      return noop;\n    }\n    // Filter out irrelevant internal properties before exposing externally\n    const tickItems = ticks.map(tick => ({\n      value: tick.value,\n      coordinate: tick.coordinate,\n      offset: tick.offset,\n      index: tick.index,\n    }));\n    dispatch(setRenderedTicks({ ticks: tickItems, axisId, axisType }));\n    return () => {\n      dispatch(\n        removeRenderedTicks({\n          axisId,\n          axisType,\n        }),\n      );\n    };\n  }, [dispatch, ticks, axisId, axisType]);\n\n  return null;\n}\n\ntype TicksProps = {\n  axisType: 'xAxis' | 'yAxis' | undefined;\n  events: Omit<PresentationAttributesAdaptChildEvent<any, SVGElement>, 'scale' | 'viewBox'>;\n  fontSize: string;\n  getTicksConfig: Omit<Props, 'ticks' | 'ref'>;\n  height: number;\n  letterSpacing: string;\n  mirror: boolean;\n  orientation: Orientation;\n  padding?: Props['padding'];\n  stroke?: Props['stroke'];\n  tick?: Props['tick'];\n  tickFormatter?: Props['tickFormatter'];\n  tickLine?: Props['tickLine'];\n  tickMargin: number;\n  tickSize: number;\n  tickTextProps?: Props['tickTextProps'];\n  ticks?: ReadonlyArray<CartesianTickItem>;\n  unit?: Props['unit'];\n  width: number;\n  x: number;\n  y: number;\n  axisId: AxisId | undefined;\n};\n\nconst Ticks = forwardRef<SVGGElement, TicksProps>((props: TicksProps, ref) => {\n  const {\n    ticks = [],\n    tick,\n    tickLine,\n    stroke,\n    tickFormatter,\n    unit,\n    padding,\n    tickTextProps,\n    orientation,\n    mirror,\n    x,\n    y,\n    width,\n    height,\n    tickSize,\n    tickMargin,\n    fontSize,\n    letterSpacing,\n    getTicksConfig,\n    events,\n    axisType,\n    axisId,\n  } = props;\n  // @ts-expect-error some properties are optional in props but required in getTicks\n  const finalTicks = getTicks({ ...getTicksConfig, ticks }, fontSize, letterSpacing);\n  const axisProps = svgPropertiesNoEvents(getTicksConfig);\n  const customTickProps = svgPropertiesNoEventsFromUnknown(tick);\n  // Use user-provided textAnchor if available, otherwise calculate from orientation/mirror\n  const textAnchor: TextAnchor = isValidTextAnchor(axisProps.textAnchor)\n    ? axisProps.textAnchor\n    : getTickTextAnchor(orientation, mirror);\n  const verticalAnchor: TextVerticalAnchor = getTickVerticalAnchor(orientation, mirror);\n  let tickLinePropsObject: SVGProps<SVGLineElement> = {};\n  if (typeof tickLine === 'object') {\n    tickLinePropsObject = tickLine;\n  }\n  const tickLineProps: SVGProps<SVGLineElement> = {\n    ...axisProps,\n    fill: 'none',\n    ...tickLinePropsObject,\n  };\n\n  const tickLineCoords = finalTicks.map((entry: CartesianTickItem) => ({\n    entry,\n    ...getTickLineCoord(entry, x, y, width, height, orientation, tickSize, mirror, tickMargin),\n  }));\n\n  const tickLines = tickLineCoords.map(({ entry, line: lineCoord }) => {\n    return (\n      <Layer\n        className=\"recharts-cartesian-axis-tick\"\n        key={`tick-${entry.value}-${entry.coordinate}-${entry.tickCoord}`}\n      >\n        {tickLine && (\n          <line\n            {...tickLineProps}\n            {...lineCoord}\n            className={clsx('recharts-cartesian-axis-tick-line', get(tickLine, 'className'))}\n          />\n        )}\n      </Layer>\n    );\n  });\n\n  const tickLabels = tickLineCoords.map