tionActive}\n      hide={hide}\n      label={label}\n      legendType={legendType}\n      xAxisId={xAxisId}\n      yAxisId={yAxisId}\n      points={points}\n      layout={layout}\n      height={height}\n      width={width}\n      left={left}\n      top={top}\n      needClip={needClip}\n    />\n  );\n}\n\nexport function computeLinePoints({\n  layout,\n  xAxis,\n  yAxis,\n  xAxisTicks,\n  yAxisTicks,\n  dataKey,\n  bandSize,\n  displayedData,\n}: {\n  layout: CartesianLayout;\n  xAxis: BaseAxisWithScale;\n  yAxis: BaseAxisWithScale;\n  xAxisTicks: TickItem[];\n  yAxisTicks: TickItem[];\n  dataKey: Props['dataKey'];\n  bandSize: number;\n  displayedData: ChartData;\n}): ReadonlyArray<LinePointItem> {\n  return displayedData\n    .map((entry, index): LinePointItem | null => {\n      // getValueByDataKey does not validate the output type\n      const value: number = getValueByDataKey(entry, dataKey);\n\n      if (layout === 'horizontal') {\n        const x = getCateCoordinateOfLine({ axis: xAxis, ticks: xAxisTicks, bandSize, entry, index });\n        const y = isNullish(value) ? null : yAxis.scale.map(value);\n        return {\n          x,\n          y: y ?? null,\n          value,\n          payload: entry,\n        };\n      }\n\n      const x = isNullish(value) ? null : xAxis.scale.map(value);\n      const y = getCateCoordinateOfLine({ axis: yAxis, ticks: yAxisTicks, bandSize, entry, index });\n      if (x == null || y == null) {\n        return null;\n      }\n      return {\n        x,\n        y,\n        value,\n        payload: entry,\n      };\n    })\n    .filter(Boolean);\n}\n\nfunction LineFn(outsideProps: Props) {\n  const props = resolveDefaultProps(outsideProps, defaultLineProps);\n  const isPanorama = useIsPanorama();\n  return (\n    <RegisterGraphicalItemId id={props.id} type=\"line\">\n      {id => (\n        <>\n          <SetLegendPayload legendPayload={computeLegendPayloadFromAreaData(props)} />\n          <SetLineTooltipEntrySettings\n            dataKey={props.dataKey}\n            data={props.data}\n            stroke={props.stroke}\n            strokeWidth={props.strokeWidth}\n            fill={props.fill}\n            name={props.name}\n            hide={props.hide}\n            unit={props.unit}\n            tooltipType={props.tooltipType}\n            id={id}\n          />\n          <SetCartesianGraphicalItem\n            type=\"line\"\n            id={id}\n            data={props.data}\n            xAxisId={props.xAxisId}\n            yAxisId={props.yAxisId}\n            zAxisId={0}\n            dataKey={props.dataKey}\n            hide={props.hide}\n            isPanorama={isPanorama}\n          />\n          <LineImpl {...props} id={id} />\n        </>\n      )}\n    </RegisterGraphicalItemId>\n  );\n}\n\n/**\n * @provides LabelListContext\n * @provides ErrorBarContext\n * @consumes CartesianChartContext\n */\nexport const Line = React.memo(LineFn, propsAreEqual) as {\n  <DataPointType = any, ValueAxisType = any>(props: Props<DataPointType, ValueAxisType>): ReactElement;\n  (props: Props<any, any>): ReactElement;\n};\n// @ts-expect-error we need to set the displayName for debugging purposes\nLine.displayName = 'Line';\n","import { ActiveDotType, DotType } from './types';\nimport { svgPropertiesNoEventsFromUnknown } from './svgPropertiesNoEvents';\n\nexport function getRadiusAndStrokeWidthFromDot(dot: ActiveDotType | DotType): {\n  r: number;\n  strokeWidth: number;\n} {\n  const props = svgPropertiesNoEventsFromUnknown(dot);\n  const defaultR = 3;\n  const defaultStrokeWidth = 2;\n  if (props != null) {\n    const { r, strokeWidth } = props;\n    let realR = Number(r);\n    let realStrokeWidth = Number(strokeWidth);\n    if (Number.isNaN(realR) || realR < 0) {\n      realR = defaultR;\n    }\n    if (Number.isNaN(realStrokeWidth) || realStrokeWidth < 0) {\n      realStrokeWidth = defaultStrokeWidth;\n    }\n    return {\n      r: realR,\n      strokeWidth: realStrokeWidth,\n    };\n  }\n  return {\n    r: defaultR,\n    strokeWidth: defaultStrokeWidth,\n  };\n}\n","import { RechartsRootState } from '../store';\nimport { GraphicalItemId } from '../graphicalItemsSlice';\nimport { AxisId, defaultAxisId } from '../cartesianAxisSlice';\n\nexport function selectXAxisIdFromGraphicalItemId(state: RechartsRootState, id: GraphicalItemId): AxisId {\n  return state.graphicalItems.cartesianItems.find(item => item.id === id)?.xAxisId ?? defaultAxisId;\n}\n\nexport function selectYAxisIdFromGraphicalItemId(state: RechartsRootState, id: GraphicalItemId): AxisId {\n  return state.graphicalItems.cartesianItems.find(item => item.id === id)?.yAxisId ?? defaultAxisId;\n}\n","import { createSelector } from 'reselect';\nimport { SeriesPoint } from 'victory-vendor/d3-shape';\nimport { NullableCoordinate } from '../../util/types';\nimport { computeArea } from '../../cartesian/Area';\nimport {\n  selectAxisWithScale,\n  selectStackGroups,\n  selectTicksOfGraphicalItem,\n  selectUnfilteredCartesianItems,\n} from './axisSelectors';\nimport { RechartsRootState } from '../store';\nimport { AxisId } from '../cartesianAxisSlice';\nimport { selectChartLayout } from '../../context/chartLayoutContext';\nimport { selectChartDataWithIndexesIfNotInPanoramaPosition3 } from './dataSelectors';\nimport { getBandSizeOfAxis, isCategoricalAxis, StackId } from '../../util/ChartUtils';\nimport { ChartData } from '../chartDataSlice';\nimport { getStackSeriesIdentifier } from '../../util/stacks/getStackSeriesIdentifier';\nimport { StackDataPoint, StackGroup, StackSeries, StackSeriesIdentifier } from '../../util/stacks/stackTypes';\nimport { AreaSettings } from '../types/AreaSettings';\nimport { GraphicalItemId } from '../graphicalItemsSlice';\nimport { selectChartBaseValue } from './rootPropsSelectors';\nimport { selectXAxisIdFromGraphicalItemId, selectYAxisIdFromGraphicalItemId } from './graphicalItemSelectors';\n\nexport interface AreaPointItem extends NullableCoordinate {\n  x: number | null;\n  y: number | null;\n  value?: ReadonlyArray<unknown>;\n  payload?: any;\n}\n\nexport type ComputedArea = {\n  points: ReadonlyArray<AreaPointItem>;\n  baseLine: number | ReadonlyArray<AreaPointItem>;\n  isRange: boolean;\n};\n\nconst selectXAxisWithScale = (state: RechartsRootState, graphicalItemId: GraphicalItemId, isPanorama: boolean) =>\n  selectAxisWithScale(state, 'xAxis', selectXAxisIdFromGraphicalItemId(state, graphicalItemId), isPanorama);\n\nconst selectXAxisTicks = (state: RechartsRootState, graphicalItemId: GraphicalItemId, isPanorama: boolean) =>\n  selectTicksOfGraphicalItem(state, 'xAxis', selectXAxisIdFromGraphicalItemId(state, graphicalItemId), isPanorama);\n\nconst selectYAxisWithScale = (state: RechartsRootState, graphicalItemId: GraphicalItemId, isPanorama: boolean) =>\n  selectAxisWithScale(state, 'yAxis', selectYAxisIdFromGraphicalItemId(state, graphicalItemId), isPanorama);\n\nconst selectYAxisTicks = (state: RechartsRootState, graphicalItemId: GraphicalItemId, isPanorama: boolean) =>\n  selectTicksOfGraphicalItem(state, 'yAxis', selectYAxisIdFromGraphicalItemId(state, graphicalItemId), isPanorama);\n\nconst selectBandSize = createSelector(\n  [selectChartLayout, selectXAxisWithScale, selectYAxisWithScale, selectXAxisTicks, selectYAxisTicks],\n  (layout, xAxis, yAxis, xAxisTicks, yAxisTicks) => {\n    if (isCategoricalAxis(layout, 'xAxis')) {\n      return getBandSizeOfAxis(xAxis, xAxisTicks, false);\n    }\n    return getBandSizeOfAxis(yAxis, yAxisTicks, false);\n  },\n);\n\nconst pickAreaId = (_state: RechartsRootState, id: GraphicalItemId): GraphicalItemId => id;\n\n/*\n * There is a race condition problem because we read some data from props and some from the state.\n * The state is updated through a dispatch and is one render behind,\n * and so we have this weird one tick render where the displayedData in one selector have the old dataKey\n * but the new dataKey in another selector.\n *\n * A proper fix is to either move everything into the state, or read the dataKey always from props\n * - but this is a smaller change.\n */\nconst selectSynchronisedAreaSettings: (\n  state: RechartsRootState,\n  id: GraphicalItemId,\n  isPanorama: boolean,\n) => AreaSettings | undefined = createSelector(\n  [selectUnfilteredCartesianItems, pickAreaId],\n  (graphicalItems, id: GraphicalItemId) =>\n    graphicalItems.filter(item => item.type === 'area').find(item => item.id === id),\n);\n\nconst selectNumericalAxisType = (state: RechartsRootState): 'xAxis' | 'yAxis' => {\n  const layout = selectChartLayout(state);\n  const isXAxisCategorical = isCategoricalAxis(layout, 'xAxis');\n  return isXAxisCategorical ? 'yAxis' : 'xAxis';\n};\n\nconst selectNumericalAxisIdFromGraphicalItemId = (\n  state: RechartsRootState,\n  graphicalItemId: GraphicalItemId,\n): AxisId => {\n  const axisType = selectNumericalAxisType(state);\n  if (axisType === 'yAxis') {\n    return selectYAxisIdFromGraphicalItemId(state, graphicalItemId);\n  }\n  return selectXAxisIdFromGraphicalItemId(state, graphicalItemId);\n};\n\nconst selectNumericalAxisStackGroups = (\n  state: RechartsRootState,\n  graphicalItemId: GraphicalItemId,\n  isPanorama: boolean,\n): Record<StackId, StackGroup> | undefined =>\n  selectStackGroups(\n    state,\n    selectNumericalAxisType(state),\n    selectNumericalAxisIdFromGraphicalItemId(state, graphicalItemId),\n    isPanorama,\n  );\n\nexport const selectGraphicalItemStackedData: (\n  state: RechartsRootState,\n  id: GraphicalItemId,\n  isPanorama: boolean,\n) => ReadonlyArray<StackDataPoint> | undefined = createSelector(\n  [selectSynchronisedAreaSettings, selectNumericalAxisStackGroups],\n  (areaSettings: AreaSettings | undefined, stackGroups: Record<StackId, StackGroup> | undefined) => {\n    if (areaSettings == null || stackGroups == null) {\n      return undefined;\n    }\n    const { stackId } = areaSettings;\n    const stackSeriesIdentifier: StackSeriesIdentifier | undefined = getStackSeriesIdentifier(areaSettings);\n    if (stackId == null || stackSeriesIdentifier == null) {\n      return undefined;\n    }\n    const groups: ReadonlyArray<StackSeries> | undefined = stackGroups[stackId]?.stackedData;\n    const found: StackSeries | undefined = groups?.find(v => v.key === stackSeriesIdentifier);\n    if (found == null) {\n      return undefined;\n    }\n    return found.map((item: SeriesPoint<StackDataPoint>): StackDataPoint => [item[0], item[1]]);\n  },\n);\n\nexport const selectArea: (\n  state: RechartsRootState,\n  id: GraphicalItemId,\n  isPanorama: boolean,\n) => ComputedArea | undefined = createSelector(\n  [\n    selectChartLayout,\n    selectXAxisWithScale,\n    selectYAxisWithScale,\n    selectXAxisTicks,\n    selectYAxisTicks,\n    selectGraphicalItemStackedData,\n    selectChartDataWithIndexesIfNotInPanoramaPosition3,\n    selectBandSize,\n    selectSynchronisedAreaSettings,\n    selectChartBaseValue,\n  ],\n  (\n    layout,\n    xAxis,\n    yAxis,\n    xAxisTicks,\n    yAxisTicks,\n    stackedData: ReadonlyArray<StackDataPoint> | undefined,\n    { chartData, dataStartIndex, dataEndIndex },\n    bandSize,\n    areaSettings,\n    chartBaseValue,\n  ) => {\n    if (\n      areaSettings == null ||\n      (layout !== 'horizontal' && layout !== 'vertical') ||\n      xAxis == null ||\n      yAxis == null ||\n      xAxisTicks == null ||\n      yAxisTicks == null ||\n      xAxisTicks.length === 0 ||\n      yAxisTicks.length === 0 ||\n      bandSize == null\n    ) {\n      return undefined;\n    }\n    const { data } = areaSettings;\n\n    let displayedData: ChartData | undefined;\n    if (data && data.length > 0) {\n      displayedData = data;\n    } else {\n      displayedData = chartData?.slice(dataStartIndex, dataEndIndex + 1);\n    }\n\n    if (displayedData == null) {\n      return undefined;\n    }\n\n    return computeArea({\n      layout,\n      xAxis,\n      yAxis,\n      xAxisTicks,\n      yAxisTicks,\n      dataStartIndex,\n      areaSettings,\n      stackedData,\n      displayedData,\n      chartBaseValue,\n      bandSize,\n    });\n  },\n);\n","import * as React from 'react';\nimport {\n  MutableRefObject,\n  PureComponent,\n  ReactElement,\n  ReactNode,\n  useCallback,\n  useMemo,\n  useRef,\n  useState,\n} from 'react';\nimport { clsx } from 'clsx';\nimport { BaseLineType, Curve, CurveType, Props as CurveProps } from '../shape/Curve';\nimport { Layer } from '../container/Layer';\nimport {\n  CartesianLabelListContextProvider,\n  CartesianLabelListEntry,\n  ImplicitLabelListType,\n  LabelListFromLabelProp,\n} from '../component/LabelList';\nimport { Dots, DotsDotProps } from '../component/Dots';\nimport { interpolate, isNan, isNullish, isNumber, noop } from '../util/DataUtils';\nimport {\n  getCateCoordinateOfLine,\n  getNormalizedStackId,\n  getTooltipNameProp,\n  getValueByDataKey,\n  StackId,\n} from '../util/ChartUtils';\nimport {\n  ActiveDotType,\n  AnimationDuration,\n  AnimationTiming,\n  CartesianLayout,\n  DataConsumer,\n  DataKey,\n  DataProvider,\n  DotType,\n  LegendType,\n  NullableCoordinate,\n  TickItem,\n  TooltipType,\n  TrapezoidViewBox,\n} from '../util/types';\nimport { isClipDot } from '../util/ReactUtils';\nimport type { LegendPayload } from '../component/DefaultLegendContent';\nimport { ActivePoints } from '../component/ActivePoints';\nimport { TooltipPayloadConfiguration } from '../state/tooltipSlice';\nimport { SetTooltipEntrySettings } from '../state/SetTooltipEntrySettings';\nimport { GraphicalItemClipPath, useNeedsClip } from './GraphicalItemClipPath';\nimport { BaseAxisWithScale } from '../state/selectors/axisSelectors';\nimport { ChartData } from '../state/chartDataSlice';\nimport { AreaPointItem, ComputedArea, selectArea } from '../state/selectors/areaSelectors';\nimport { useIsPanorama } from '../context/PanoramaContext';\nimport { useCartesianChartLayout, useChartLayout } from '../context/chartLayoutContext';\nimport { useChartName } from '../state/selectors/selectors';\nimport { SetLegendPayload } from '../state/SetLegendPayload';\nimport { useAppSelector } from '../state/hooks';\nimport { useAnimationId } from '../util/useAnimationId';\nimport { RequiresDefaultProps, resolveDefaultProps } from '../util/resolveDefaultProps';\nimport { isWellBehavedNumber } from '../util/isWellBehavedNumber';\nimport { usePlotArea } from '../hooks';\nimport { WithIdRequired, WithoutId } from '../util/useUniqueId';\nimport { RegisterGraphicalItemId } from '../context/RegisterGraphicalItemId';\nimport { AreaSettings } from '../state/types/AreaSettings';\nimport { SetCartesianGraphicalItem } from '../state/SetGraphicalItem';\nimport { svgPropertiesNoEvents } from '../util/svgPropertiesNoEvents';\nimport { JavascriptAnimate } from '../animation/JavascriptAnimate';\nimport { getRadiusAndStrokeWidthFromDot } from '../util/getRadiusAndStrokeWidthFromDot';\nimport { svgPropertiesAndEvents } from '../util/svgPropertiesAndEvents';\nimport { ZIndexable, ZIndexLayer } from '../zIndex/ZIndexLayer';\nimport { DefaultZIndexes } from '../zIndex/DefaultZIndexes';\nimport { propsAreEqual } from '../util/propsAreEqual';\nimport { AxisId } from '../state/cartesianAxisSlice';\nimport { StackDataPoint } from '../util/stacks/stackTypes';\n\n/**\n * @inline\n */\nexport type BaseValue = number | 'dataMin' | 'dataMax';\n\n/**\n * Our base value array has payload in it, and we expose it externally too.\n */\ntype BaseValueCoordinate<DataPointType = any> = NullableCoordinate & { payload: DataPointType | undefined };\n\n/**\n * Internal props, combination of external props + defaultProps + private Recharts state\n */\ninterface InternalAreaProps extends ZIndexable {\n  activeDot: ActiveDotType;\n  animationBegin: number;\n  animationDuration: AnimationDuration;\n  animationEasing: AnimationTiming;\n  baseLine: BaseLineType | undefined;\n\n  baseValue?: BaseValue;\n  className?: string;\n  connectNulls: boolean;\n  data?: ChartData;\n  dataKey: DataKey<any>;\n  dot: DotType;\n  height: number;\n  hide: boolean;\n\n  /**\n   * ID is mandatory internally, but optional externally.\n   */\n  id: string;\n  isAnimationActive: boolean | 'auto';\n  isRange?: boolean;\n  label?: ImplicitLabelListType;\n  layout: CartesianLayout;\n  left: number;\n\n  legendType: LegendType;\n  name?: string | number;\n  needClip: boolean;\n  onAnimationEnd?: () => void;\n  onAnimationStart?: () => void;\n\n  points: ReadonlyArray<AreaPointItem>;\n  stackId?: StackId;\n\n  tooltipType?: TooltipType;\n  top: number;\n  type?: CurveType;\n  unit?: string | number;\n  width: number;\n  xAxisId: string | number;\n  yAxisId: string | number;\n}\n\n/**\n * External props, intended for end users to fill in\n */\ninterface AreaProps<DataPointType = any, DataValueType = any>\n  extends DataProvider<DataPointType>, Required<DataConsumer<DataPointType, DataValueType>>, ZIndexable {\n  /**\n   * The active dot is rendered on the closest data point when user interacts with the chart. Options:\n   *\n   * - `false`: dots do not change on user activity; both active and inactive dots follow the `dot` prop (see below)\n   * - `true`: renders the active dot with default settings\n   * - `object`: the props of the active dot. This will be merged with the internal calculated props of the active dot\n   * - `ReactElement`: the custom active dot element\n   * - `function`: a render function of the custom active dot\n   *\n   * @defaultValue true\n   * @example <Area dataKey=\"value\" activeDot={false} />\n   * @example <Area dataKey=\"value\" activeDot={{ stroke: 'red', strokeWidth: 2, r: 10 }} />\n   * @example <Area dataKey=\"value\" activeDot={CustomizedActiveDot} />\n   *\n   * @see {@link https://recharts.github.io/en-US/examples/SimpleLineChart/ A line chart with customized active dot}\n   */\n  activeDot?: ActiveDotType;\n  /**\n   * Specifies when the animation should begin, the unit of this option is ms.\n   * @defaultValue 0\n   */\n  animationBegin?: number;\n  /**\n   * Specifies the duration of