nsitionVal } from './util';\nimport { Global } from '../util/Global';\nimport { usePrefersReducedMotion } from '../util/usePrefersReducedMotion';\n\ntype CSSTransitionAnimateProps = {\n  animationId: string;\n  animationManager?: AnimationManager;\n  duration?: number;\n  begin?: number;\n  easing?: string;\n  isActive?: boolean | 'auto';\n  canBegin?: boolean;\n  from: string;\n  to: string;\n  attributeName: string;\n  onAnimationStart?: () => void;\n  onAnimationEnd?: () => void;\n  children: (style: CSSProperties | undefined) => React.ReactNode;\n};\n\nconst defaultProps = {\n  begin: 0,\n  duration: 1000,\n  easing: 'ease',\n  isActive: true,\n  canBegin: true,\n  onAnimationEnd: () => {},\n  onAnimationStart: () => {},\n} as const satisfies Partial<CSSTransitionAnimateProps>;\n\nexport function CSSTransitionAnimate(outsideProps: CSSTransitionAnimateProps) {\n  const props = resolveDefaultProps(outsideProps, defaultProps);\n  const {\n    animationId,\n    from,\n    to,\n    attributeName,\n    isActive: isActiveProp,\n    canBegin,\n    duration,\n    easing,\n    begin,\n    onAnimationEnd,\n    onAnimationStart: onAnimationStartFromProps,\n    children,\n  } = props;\n\n  const prefersReducedMotion = usePrefersReducedMotion();\n\n  const isActive = isActiveProp === 'auto' ? !Global.isSsr && !prefersReducedMotion : isActiveProp;\n\n  const animationManager = useAnimationManager(animationId + attributeName, props.animationManager);\n  const [style, setStyle] = useState<ReactSmoothStyle>(() => {\n    if (!isActive) {\n      return to;\n    }\n    return from;\n  });\n  const initialized = useRef(false);\n\n  const onAnimationStart = useCallback(() => {\n    setStyle(from);\n    onAnimationStartFromProps();\n  }, [from, onAnimationStartFromProps]);\n\n  useEffect(() => {\n    if (!isActive || !canBegin) {\n      return noop;\n    }\n\n    initialized.current = true;\n    const unsubscribe = animationManager.subscribe(setStyle);\n    animationManager.start([onAnimationStart, begin, to, duration, onAnimationEnd]);\n\n    return () => {\n      animationManager.stop();\n      if (unsubscribe) {\n        unsubscribe();\n      }\n      onAnimationEnd();\n    };\n  }, [isActive, canBegin, duration, easing, begin, onAnimationStart, onAnimationEnd, animationManager, to, from]);\n\n  if (!isActive) {\n    /*\n     * With isActive=false, the component always renders with the final style, immediately,\n     * and ignores all other props.\n     * Also there is no transition applied.\n     */\n    return children({\n      [attributeName]: to,\n    });\n  }\n  if (!canBegin) {\n    return children({\n      [attributeName]: from,\n    });\n  }\n\n  if (initialized.current) {\n    const transition = getTransitionVal([attributeName], duration, easing);\n    return children({\n      transition,\n      [attributeName]: style,\n    });\n  }\n  return children({\n    [attributeName]: from,\n  });\n}\n","/**\n * @fileOverview Render a group of error bar\n */\nimport * as React from 'react';\nimport { SVGProps } from 'react';\nimport { Layer } from '../container/Layer';\nimport { AnimationTiming, DataKey, RectangleCoordinate } from '../util/types';\nimport { BarRectangleItem } from './Bar';\nimport { LinePointItem } from './Line';\nimport { ScatterPointItem } from './Scatter';\nimport { ReportErrorBarSettings, useErrorBarContext } from '../context/ErrorBarContext';\nimport { useXAxis, useYAxis } from '../hooks';\nimport { resolveDefaultProps } from '../util/resolveDefaultProps';\nimport { svgPropertiesNoEvents } from '../util/svgPropertiesNoEvents';\nimport { useChartLayout } from '../context/chartLayoutContext';\nimport { CSSTransitionAnimate } from '../animation/CSSTransitionAnimate';\nimport { ZIndexable, ZIndexLayer } from '../zIndex/ZIndexLayer';\nimport { DefaultZIndexes } from '../zIndex/DefaultZIndexes';\n\nexport interface ErrorBarDataItem {\n  x: number | undefined;\n  y: number | undefined;\n  value: number;\n  errorVal?: number[] | number;\n}\n\n/**\n * So usually the direction is decided by the chart layout.\n * Horizontal layout means error bars are vertical means direction=y\n * Vertical layout means error bars are horizontal means direction=x\n *\n * Except! In Scatter chart, error bars can go both ways.\n *\n * So this property is only ever used in Scatter chart, and ignored elsewhere.\n */\nexport type ErrorBarDirection = 'x' | 'y';\n\nexport type ErrorBarDataPointFormatter<T extends BarRectangleItem | LinePointItem | ScatterPointItem> = (\n  entry: T,\n  dataKey: DataKey<T, number[] | number>,\n  direction: ErrorBarDirection,\n) => ErrorBarDataItem;\n\n/**\n * External ErrorBar props, visible for users of the library\n */\ninterface ErrorBarProps<DataPointType = any, DataValueType = any> extends ZIndexable {\n  /**\n   * Decides how to extract the value of this ErrorBar from the data:\n   * - `string`: the name of the field in the data object;\n   * - `number`: the index of the field in the data;\n   * - `function`: a function that receives the data object and returns the value of this ErrorBar.\n   *\n   * The error values can be a single value for symmetric error bars;\n   * or an array of a lower and upper error value for asymmetric error bars.\n   */\n  dataKey: DataKey<DataPointType, DataValueType>;\n  /**\n   * Width of the error bar ends (the serifs) in pixels.\n   * This is not the total width of the error bar, but just the width of the little lines at the ends.\n   *\n   * The total width of the error bar is determined by the data value plus/minus the error value.\n   *\n   * @defaultValue 5\n   */\n  width?: number;\n  /**\n   * Direction of the error bar. Usually determined by chart layout, except in Scatter chart.\n   * In Scatter chart, \"x\" means horizontal error bars, \"y\" means vertical error bars.\n   */\n  direction?: ErrorBarDirection;\n  /**\n   * @defaultValue true\n   */\n  isAnimationActive?: boolean;\n  /**\n   * @defaultValue 0\n   */\n  animationBegin?: number;\n  /**\n   * @defaultValue 400\n   */\n  animationDuration?: number;\n  /**\n   * @defaultValue ease-in-out\n   */\n  animationEasing?: AnimationTiming;\n  /**\n   * The width of the stroke\n   */\n  strokeWidth?: number | string;\n  /**\n   * The stroke color. If \"none\", no line will be drawn.\n   *\n   * @defaultValue black\n   */\n  stroke?: string;\n  /**\n   * @defaultValue 400\n   */\n  zIndex?: number;\n}\n\nexport type Props = SVGProps<SVGLineElement> & ErrorBarProps;\n\n/**\n * Props after defaults, and required props have been applied.\n */\ntype ErrorBarInternalProps = SVGProps<SVGLineElement> & {\n  dataKey: DataKey<any>;\n  /** the width of the error bar ends */\n  width: number;\n  /**\n   * Only used for ScatterChart with error bars in two directions.\n   * Only accepts a value of \"x\" or \"y\" and makes the error bars lie in that direction.\n   */\n  direction: ErrorBarDirection;\n  isAnimationActive: boolean;\n  animationBegin: number;\n  animationDuration: number;\n  animationEasing: AnimationTiming;\n};\n\nfunction ErrorBarImpl(props: ErrorBarInternalProps) {\n  const {\n    direction,\n    width,\n    dataKey,\n    isAnimationActive,\n    animationBegin,\n    animationDuration,\n    animationEasing,\n    ...others\n  } = props;\n  const svgProps = svgPropertiesNoEvents(others);\n\n  const { data, dataPointFormatter, xAxisId, yAxisId, errorBarOffset: offset } = useErrorBarContext();\n\n  const xAxis = useXAxis(xAxisId);\n  const yAxis = useYAxis(yAxisId);\n\n  if (xAxis?.scale == null || yAxis?.scale == null || data == null) {\n    return null;\n  }\n\n  // ErrorBar requires type number XAxis, why?\n  if (direction === 'x' && xAxis.type !== 'number') {\n    return null;\n  }\n\n  const errorBars = data.map((entry: any, dataIndex: number) => {\n    const { x, y, value, errorVal } = dataPointFormatter(entry, dataKey, direction);\n\n    if (!errorVal || x == null || y == null) {\n      return null;\n    }\n\n    const lineCoordinates: Array<RectangleCoordinate> = [];\n    let lowBound: number, highBound: number;\n\n    if (Array.isArray(errorVal)) {\n      const [low, high] = errorVal;\n      if (low == null || high == null) {\n        return null;\n      }\n      lowBound = low;\n      highBound = high;\n    } else {\n      lowBound = highBound = errorVal;\n    }\n\n    if (direction === 'x') {\n      // error bar for horizontal charts, the y is fixed, x is a range value\n      const { scale } = xAxis;\n\n      const yMid = y + offset;\n      const yMin = yMid + width;\n      const yMax = yMid - width;\n\n      const xMin = scale.map(value - lowBound);\n      const xMax = scale.map(value + highBound);\n\n      if (xMin != null && xMax != null) {\n        // the right line of |--|\n        lineCoordinates.push({ x1: xMax, y1: yMin, x2: xMax, y2: yMax });\n        // the middle line of |--|\n        lineCoordinates.push({ x1: xMin, y1: yMid, x2: xMax, y2: yMid });\n        // the left line of |--|\n        lineCoordinates.push({ x1: xMin, y1: yMin, x2: xMin, y2: yMax });\n      }\n    } else if (direction === 'y') {\n      // error bar for horizontal charts, the x is fixed, y is a range value\n      const { scale } = yAxis;\n\n      const xMid = x + offset;\n      const xMin = xMid - width;\n      const xMax = xMid + width;\n\n      const yMin = scale.map(value - lowBound);\n      const yMax = scale.map(value + highBound);\n\n      if (yMin != null && yMax != null) {\n        // the top line\n        lineCoordinates.push({ x1: xMin, y1: yMax, x2: xMax, y2: yMax });\n        // the middle line\n        lineCoordinates.push({ x1: xMid, y1: yMin, x2: xMid, y2: yMax });\n        // the bottom line\n        lineCoordinates.push({ x1: xMin, y1: yMin, x2: xMax, y2: yMin });\n      }\n    }\n\n    const scaleDirection: string = direction === 'x' ? 'scaleX' : 'scaleY';\n\n    const transformOrigin = `${x + offset}px ${y + offset}px`;\n\n    return (\n      <Layer className=\"recharts-errorBar\" key={`bar-${x}-${y}-${value}-${dataIndex}`} {...svgProps}>\n        {lineCoordinates.map((c, lineIndex) => {\n          const lineStyle = isAnimationActive ? { transformOrigin } : undefined;\n          return (\n            <CSSTransitionAnimate\n              animationId={`error-bar-${direction}_${c.x1}-${c.x2}-${c.y1}-${c.y2}`}\n              from={`${scaleDirection}(0)`}\n              to={`${scaleDirection}(1)`}\n              attributeName=\"transform\"\n              begin={animationBegin}\n              easing={animationEasing}\n              isActive={isAnimationActive}\n              duration={animationDuration}\n              key={`errorbar-${dataIndex}-${c.x1}-${c.y1}-${c.x2}-${c.y2}-${lineIndex}`}\n            >\n              {style => <line {...c} style={{ ...lineStyle, ...style }} />}\n            </CSSTransitionAnimate>\n          );\n        })}\n      </Layer>\n    );\n  });\n\n  return <Layer className=\"recharts-errorBars\">{errorBars}</Layer>;\n}\n\nfunction useErrorBarDirection(directionFromProps: ErrorBarDirection | undefined): ErrorBarDirection {\n  const layout = useChartLayout();\n  if (directionFromProps != null) {\n    return directionFromProps;\n  }\n  if (layout != null) {\n    return layout === 'horizontal' ? 'y' : 'x';\n  }\n  return 'x';\n}\n\nexport const errorBarDefaultProps = {\n  stroke: 'black',\n  strokeWidth: 1.5,\n  width: 5,\n  offset: 0,\n  isAnimationActive: true,\n  animationBegin: 0,\n  animationDuration: 400,\n  animationEasing: 'ease-in-out',\n  zIndex: DefaultZIndexes.line,\n} as const satisfies Partial<Props>;\n\n/**\n * ErrorBar renders whiskers to represent error margins on a chart.\n *\n * It must be a child of a graphical element.\n *\n * ErrorBar expects data in one of the following forms:\n * - Symmetric error bars: a single error value representing both lower and upper bounds.\n * - Asymmetric error bars: an array of two values representing lower and upper bounds separately. First value is the lower bound, second value is the upper bound.\n *\n * The values provided are relative to the main data value.\n * For example, if the main data value is 10 and the error value is 2,\n * the error bar will extend from 8 to 12 for symmetric error bars.\n *\n * In other words, what ErrorBar will render is:\n * - For symmetric error bars: [value - errorVal, value + errorVal]\n * - For asymmetric error bars: [value - errorVal[0], value + errorVal[1]]\n *\n * In stacked or ranged Bar charts, ErrorBar will use the higher data value\n * as the reference point for calculating the error bar positions.\n *\n * @consumes ErrorBarContext\n */\nexport function ErrorBar(outsideProps: Props) {\n  const realDirection: ErrorBarDirection = useErrorBarDirection(outsideProps.direction);\n  const props = resolveDefaultProps(outsideProps, errorBarDefaultProps);\n  const { width, isAnimationActive, animationBegin, animationDuration, animationEasing, zIndex } = props;\n\n  return (\n    <>\n      <ReportErrorBarSettings dataKey={props.dataKey} direction={realDirection} />\n      <ZIndexLayer zIndex={zIndex}>\n        <ErrorBarImpl\n          {...props}\n          direction={realDirection}\n          width={width}\n          isAnimationActive={isAnimationActive}\n          animationBegin={animationBegin}\n          animationDuration={animationDuration}\n          animationEasing={animationEasing}\n        />\n      </ZIndexLayer>\n    </>\n  );\n}\n\nErrorBar.displayName = 'ErrorBar';\n","import { createSelector } from 'reselect';\nimport { RechartsRootState } from '../store';\nimport { ActiveTooltipProps } from '../tooltipSlice';\nimport { selectChartLayout } from '../../context/chartLayoutContext';\nimport { selectTooltipAxisRangeWithReverse, selectTooltipAxisTicks } from './tooltipSelectors';\nimport { selectChartOffsetInternal } from './selectChartOffsetInternal';\nimport { combineActiveProps, selectOrderedTooltipTicks } from './selectors';\nimport { selectPolarViewBox } from './polarAxisSelectors';\nimport { RelativePointer } from '../../util/types';\nimport { selectTooltipAxisType } from './selectTooltipAxisType';\n\nconst pickChartPointer = (_state: RechartsRootState, chartPointer: RelativePointer) => chartPointer;\n\nexport const selectActivePropsFromChartPointer: (\n  state: RechartsRootState,\n  chartPointer: RelativePointer,\n) => ActiveTooltipProps | undefined = createSelector(\n  [\n    pickChartPointer,\n    selectChartLayout,\n    selectPolarViewBox,\n    selectTooltipAxisType,\n    selectTooltipAxisRangeWithReverse,\n    selectTooltipAxisTicks,\n    selectOrderedTooltipTicks,\n    selectChartOffsetInternal,\n  ],\n  combineActiveProps,\n);\n","import { RelativePointer, MousePointer, SVGMousePointer, TouchPointer, SVGTouchPointer } from './types';\n\n/**\n * Type guard to check if the pointer event is from an SVG element.\n */\nfunction isSvgPointer(pointer: MousePointer | TouchPointer): pointer is SVGMousePointer | SVGTouchPointer {\n  return 'getBBox' in pointer.currentTarget && typeof pointer.currentTarget.getBBox === 'function';\n}\n\n/**\n * Computes relative element coordinates from mouse or touch event.\n *\n * The output coordinates are relative to the top-left corner of the active element (= currentTarget),\n * where the top-left corner is (0, 0).\n * Moving right, the x-coordinate increases, and moving down, the y-coordinate increases.\n *\n * The coordinates are rounded to the nearest integer and account for CSS transform scale.\n * So element that's scaled will return the same coordinates as element that's not scaled.\n *\n * In other words: you zoom in or out, numbers stay the same.\n *\n * This function works with both HTML elements and SVG elements.\n *\n * It works with both Mouse and Touch events.\n * For Touch events, it returns an array of coordinates, one for each touch point.\n * For Mouse events, it returns a single coordinate object.\n *\n * @example\n * ```tsx\n * // In an HTML element event handler. Legend passes the native event as the 3rd argument.\n * <Legend onMouseMove={(_data, _i, e) => {\n *   // These coordinates are relative to the top-left corner of the Legend element\n *   const { relativeX, relativeY } = getRelativeCoordinate(e);\n *   console.log(`Mouse at Legend position: (${relativeX}, ${relativeY})`);\n * }}>\n * ```\n *\n * @example\n * ```tsx\n * // In an SVG element event handler. Area is an SVG element, and passes the event as second argument.\n * <Area onMouseMove={(_, e) => {\n *   const { relativeX, relativeY } = getRelativeCoordinate(e);\n *   console.log(`Mouse at Area position: (${relativeX}, ${relativeY})`);\n *   // Here you can call usePlotArea to convert to chart coordinates\n * }}>\n * ```\n *\n * @example\n * ```tsx\n * // In a chart root touch handler. Chart root passes the event as second argument.\n * <LineChart onTouchMove={(_, e) => {\n *   const touchPoints = getRelativeCoordinate(e);\n *   touchPoints.forEach(({ relativeX, relativeY }, index) => {\n *     console.log(`Touch point ${index} at LineChart position: (${relativeX}, ${relativeY})`);\n *   });\n * }}>\n * ```\n *\n * @since 3.8\n * @param event The mouse or touch event from React event handlers (works with both HTML and SVG elements)\n * @returns Coordinates relative to the top-left corner of the element. Single object for Mouse events, array of objects for Touch events.\n */\nexport function getRelativeCoordinate(event: MousePointer): RelativePointer;\nexport function getRelativeCoordinate(event: TouchPointer): Array<RelativePointer>;\nexport function getRelativeCoordinate(event: MousePointer | TouchPointer): RelativePointer | Array<RelativePointer> {\n  const rect = event.currentTarget.getBoundingClientRect();\n\n  let scaleX: number, scaleY: number;\n\n  if (isSvgPointer(event)) {\n    // For SVG elements, use getBBox() to get the intrinsic size in SVG coordinates\n    const bbox = event.currentTarget.getBBox();\n    scaleX = bbox.width > 0 ? rect.width / bbox.width : 1;\n    scaleY = bbox.height > 0 ? rect.height / bbox.height : 1;\n  } else {\n    // For HTML elements, use offsetWidth/offsetHeight\n    const element = event.currentTarget;\n    scaleX = element.offsetWidth > 0 ? rect.width / element.offsetWidth : 1;\n    scaleY = element.offsetHeight > 0 ? rect.height / element.offsetHeight : 1;\n  }\n\n  const getCoordinates = (clientX: number, clientY: number): RelativePointer => ({\n    /*\n     * Here it's important to use:\n     * - event.clientX and event.clientY to get the mouse position relative to the viewport, including scroll.\n     * - pageX and pageY are not used because they are relative to the whole document, and ignore scroll.\n     * - rect.left and rect.top are used to get the position of the chart relative to the viewport.\n     * - offsetX and offsetY are not used because they are relative to the offset parent\n     *  which may or may not be the same as the clientX and clientY, depending on the position of the chart in the DOM\n     *  and surrounding element styles. CSS position: relative, absolute, fixed, will change the offset parent.\n     * - scaleX and scaleY are necessary for when the chart element is scaled using CSS `transform: scale(N)`.\n     */\n    relativeX: Math.round((clientX - rect.left) / scaleX),\n    relativeY: Math.round((clientY - rect.top) / scaleY),\n  });\n\n  if ('touches' in event) {\n    return Array.from(event.touches).map(touch => getCoordinates(touch.clientX, touch.clientY));\n  }\n\n  return getCoordinates(event.clientX, event.clientY);\n}\n","import { createAction, createListenerMiddleware, ListenerEffectAPI, PayloadAction } from '@reduxjs/toolkit';\nimport { AppDispatch, RechartsRootState } from './store';\nimport { mouseLeaveChart, setMouseClickAxisIndex, setMouseOverAxisIndex } from './tooltipSlice';\nimport { selectActivePropsFromChartPointer } from './selectors/selectActivePropsFromChartPointer';\nimport { selectTooltipEventType } from './selectors/selectTooltipEventType';\n\nimport { getRelativeCoordinate } from '../util/getRelativeCoordinate';\nimport { RelativePointer, HTMLMousePointer } from '../util/types';\n\nexport const mouseClickAction = createAction<HTMLMousePointer>('mouseClick');\n\nexport const mouseClickMiddleware = createListenerMiddleware<RechartsRootState>();\n\n// TODO: there's a bug here when you click the chart the activeIndex resets to zero\nmouseClickMiddleware.startListening({\n  actionCreator: mouseClickAction,\n  effect: (action: PayloadAction<HTMLMousePointer>, listenerApi: ListenerEffectAPI<RechartsRootState, AppDispatch>) => {\n    const mousePointer = action.payload;\n    const activeProps = selectActivePropsFromChartPointer(listenerApi.getState(), getRelativeCoordinate(mousePointer));\n    if (activeProps?.activeIndex != null) {\n      listenerApi.dispatch(\n        setMouseClickAxisIndex({\n          activeIndex: activeProps.activeIndex,\n          activeDataKey: undefined,\n          activeCoordinate: activeProps.activeCoordinate,\n        }),\n      );\n    }\n  },\n});\n\nexport const mouseMoveAction = createAction<HTMLMousePointer>('mouseMove');\n\nexport const mouseMoveMiddleware = createListenerMiddleware<RechartsRootState>();\n\n/*\n * This single rafId is safe because:\n * 1. Each chart has its own Redux store instance with its own middleware\n * 2. mouseMoveAction only fires from one DOM element (the chart wrapper)\n * 3. Rapid mousemove events from the same element SHOULD debounce - we only care about the latest position\n * This is different from externalEventsMiddleware which handles multiple event types\n * (click, mouseenter, mouseleave, etc.) that should NOT cancel each other.\n */\nlet rafId: number | null = null;\nlet timeoutId: ReturnType<typeof setTimeout> | null = null;\nlet latestChartPointer: RelativePointer | null = null;\n\nmouseMoveMiddleware.startListening({\n  actionCreator: mouseMoveAction,\n  effect: (action: PayloadAction<HTMLMousePointer>, listenerApi: ListenerEffectAPI<RechartsRootState, AppDispatch>) => {\n    const mousePointer = action.payload;\n\n    const state = listenerApi.getState();\n    const { throttleDelay, throttledEvents } = state.eventSettings;\n    const isThrottled = throttledEvents === 'all' || throttledEvents?.includes('mousemove');\n\n    // Cancel any pending execution\n    if (rafId !== null) {\n      cancelAnimationFrame(rafId);\n      rafId = null;\n    }\n    if (timeoutId !== null && (typeof throttleDelay !== 'number' || !isThrottled)) {\n      clearTimeout(timeoutId);\n      timeoutId = null;\n    }\n\n    /*\n     * Here it is important to resolve the chart pointer _before_ the callback,\n     * because once we leave the current event loop, the mousePointer event object will lose\n     * reference to currentTarget which getRelativeCoordinate uses.\n     */\n    latestChartPointer = getRelativeCoordinate(mousePointer);\n    const callback = () => {\n      /*\n       * Here we read a fresh state again inside the callback to ensure we have the latest state values\n       * after any potential actions that may have been dispatched between the original event and this callback.\n       */\n      const currentState = listenerApi.getState();\n      const tooltipEventType = selectTooltipEventType(currentState, currentState.tooltip.settings.shared);\n      if (!latestChartPointer) {\n        rafId = null;\n        timeoutId = null;\n        return;\n      }\n\n      /*\n       * This functionality only applies to charts that have axes.\n       * Graphical items have its own mouse events handling mechanism where they attach events directly to the items.\n       */\n      if (tooltipEventType === 'axis') {\n        const activeProps = selectActivePropsFromChartPointer(currentState, latestChartPointer);\n        if (activeProps?.activeIndex != null) {\n          listenerApi.dispatch(\n            setMouseOverAxisIndex({\n              activeIndex: activeProps.activeIndex,\n              activeDataKey: undefined,\n              activeCoordinate: activeProps.activeCoordinate,\n            }),\n          );\n        } else {\n          // this is needed to clear tooltip state when the mouse moves out of the inRange (svg - offset) function, but not yet out of the svg\n          listenerApi.dispatch(mouseLeaveChart());\n        }\n      }\n      rafId = null;\n      timeoutId = null;\n    };\n\n    if (!isThrottled) {\n      callback();\n      return;\n    }\n\n    if (throttleDelay === 'raf') {\n      rafId = requestAnimationFrame(callback);\n    } else if (typeof throttleDelay === 'number') {\n      if (timeoutId === null) {\n        timeoutId = setTimeout(callback, throttleDelay);\n      }\n    }\n  },\n});\n","export function reduxDevtoolsJsonStringifyReplacer(key: string, value: unknown) {\n  if (value instanceof HTMLElement) {\n    return `HTMLElement <${value.tagName} class=\"${value.className}\">`;\n  }\n  if (value === window) {\n    return 'global.window';\n  }\n  if (key === 'children' && typeof value === 'object' && value !== null) {\n    return '<<CHILDREN>>';\n  }\n  return value;\n}\n","import { createSlice, PayloadAction } from '@reduxjs/toolkit';\nimport { StackOffsetType } from '../util/types';\nimport { SyncMethod } from '../synchronisation/types';\nimport { BaseValue } from '../cartesian/Area';\n\n/**\n * These are chart options that users can choose - which means they can also\n * choose to change them which should trigger a re-render.\n */\nexport type UpdatableChartOptions = {\n  accessibilityLayer: boolean;\n  barCategoryGap: number | string;\n  barGap: number | string;\n  barSize: string | number | undefined;\n  /**\n   * Useful for debugging which chart is which when synchronising.\n   * The className is also passed to the root element of the chart but that's done in the JSX, not through Redux.\n   */\n  className: string | undefined;\n  maxBarSize: number | undefined;\n  stackOffset: StackOffsetType;\n  /**\n   * Charts that share the same syncId will have their Tooltip and Brush synchronised.\n   */\n  syncId: number | string | undefined;\n  syncMethod: SyncMethod;\n  baseValue: BaseValue | undefined;\n  /**\n   * If false, stacked items will be rendered left to right. If true, stacked items will be rendered right to left.\n   * (Render direction affects SVG layering, not x position.)\n   */\n  reverseStackOrder: boolean;\n};\n\nexport const initialState: UpdatableChartOptions = {\n  accessibilityLayer: true,\n  barCategoryGap: '10%',\n  barGap: 4,\n  barSize: undefined,\n  className: undefined,\n  maxBarSize: undefined,\n  stackOffset: 'none',\n  syncId: undefined,\n  syncMethod: 'index',\n  baseValue: undefined,\n  reverseStackOrder: false,\n};\n\nconst rootPropsSlice = createSlice({\n  name: 'rootProps',\n  initialState,\n  reducers: {\n    updateOptions: (state: UpdatableChartOptions, action: PayloadAction<UpdatableChartOptions>) => {\n      state.accessibilityLayer = action.payload.accessibilityLayer;\n      state.barCategoryGap = action.payload.barCategoryGap;\n      state.barGap = action.payload.barGap ?? initialState.barGap;\n      state.barSize = action.payload.barSize;\n      state.maxBarSize = action.payload.maxBarSize;\n      state.stackOffset = action.payload.stackOffset;\n      state.syncId = action.payload.syncId;\n      state.syncMethod = action.payload.syncMethod;\n      state.className = action.payload.className;\n      state.baseValue = action.payload.baseValue;\n      state.reverseStackOrder = action.payload.reverseStackOrder;\n    },\n  },\n});\n\nexport const rootPropsReducer = rootPropsSlice.reducer;\n\nexport const { updateOptions } = rootPropsSlice.actions;\n","import { createSlice, PayloadAction } from '@reduxjs/toolkit';\n\nexport type PolarChartOptions = {\n  cx: number | string;\n  cy: number | string;\n  startAngle: number;\n  endAngle: number;\n  innerRadius: number | string;\n  outerRadius: number | string;\n};\n\ntype PolarChartState = PolarChartOptions | null;\n\nconst initialState: PolarChartState = null;\n\nconst reducers = {\n  updatePolarOptions: (state: PolarChartState, action: PayloadAction<PolarChartOptions>): PolarChartOptions => {\n    if (state === null) {\n      return action.payload;\n    }\n    state.startAngle = action.payload.startAngle;\n    state.endAngle = action.payload.endAngle;\n    state.cx = action.payload.cx;\n    state.cy = action.payload.cy;\n    state.innerRadius = action.payload.innerRadius;\n    state.outerRadius = action.payload.outerRadius;\n    return state;\n  },\n};\n\nconst polarOptionsSlice = createSlice<PolarChartState, typeof reducers>({\n  name: 'polarOptions',\n  initialState,\n  reducers,\n});\n\nexport const { updatePolarOptions } = polarOptionsSlice.actions;\n\nexport const polarOptionsReducer = polarOptionsSlice.reducer;\n","import { createAction, createListenerMiddleware, ListenerEffectAPI } from '@reduxjs/toolkit';\nimport { setKeyboardInteraction, TooltipInteractionState } from './tooltipSlice';\nimport { AppDispatch, RechartsRootState } from './store';\nimport {\n  selectTooltipAxisDomain,\n  selectTooltipAxisTicks,\n  selectTooltipDisplayedData,\n} from './selectors/tooltipSelectors';\nimport { selectCoordinateForDefaultIndex } from './selectors/selectors';\nimport { selectChartDirection, selectTooltipAxisDataKey } from './selectors/axisSelectors';\nimport { combineActiveTooltipIndex } from './selectors/combiners/combineActiveTooltipIndex';\nimport { selectTooltipEventType } from './selectors/selectTooltipEventType';\n\nexport const keyDownAction = createAction<KeyboardEvent['key']>('keyDown');\nexport const focusAction = createAction('focus');\nexport const blurAction = createAction('blur');\n\nexport const keyboardEventsMiddleware = createListenerMiddleware<RechartsRootState>();\n\nlet rafId: number | null = null;\nlet timeoutId: ReturnType<typeof setTimeout> | null = null;\nlet latestKeyboardActionPayload: KeyboardEvent['key'] | null = null;\n\nkeyboardEventsMiddleware.startListening({\n  actionCreator: keyDownAction,\n  effect: (\n    action: ReturnType<typeof keyDownAction>,\n    listenerApi: ListenerEffectAPI<RechartsRootState, AppDispatch>,\n  ) => {\n    latestKeyboardActionPayload = action.payload;\n\n    if (rafId !== null) {\n      cancelAnimationFrame(rafId);\n      rafId = null;\n    }\n\n    const state: RechartsRootState = listenerApi.getState();\n    const { throttleDelay, throttledEvents } = state.eventSettings;\n    const isThrottled = throttledEvents === 'all' || throttledEvents.includes('keydown');\n\n    if (timeoutId !== null && (typeof throttleDelay !== 'number' || !isThrottled)) {\n      clearTimeout(timeoutId);\n      timeoutId = null;\n    }\n\n    const callback = () => {\n      try {\n        const currentState = listenerApi.getState();\n        const accessibilityLayerIsActive = currentState.rootProps.accessibilityLayer !== false;\n        if (!accessibilityLayerIsActive) {\n          return;\n        }\n        const { keyboardInteraction } = currentState.tooltip;\n        const key = latestKeyboardActionPayload;\n        if (key !== 'ArrowRight' && key !== 'ArrowLeft' && key !== 'Enter') {\n          return;\n        }\n\n        // TODO this is lacking index for charts that do not support numeric indexes\n        const resolvedIndex = combineActiveTooltipIndex(\n          keyboardInteraction,\n          selectTooltipDisplayedData(currentState),\n          selectTooltipAxisDataKey(currentState),\n          selectTooltipAxisDomain(currentState),\n        );\n        const currentIndex = resolvedIndex == null ? -1 : Number(resolvedIndex);\n        const isOutsideDomain = !Number.isFinite(currentIndex) || currentIndex < 0;\n        const tooltipTicks = selectTooltipAxisTicks(currentState);\n        const displayedData = selectTooltipDisplayedData(currentState);\n        const tooltipEventType = selectTooltipEventType(currentState, currentState.tooltip.settings.shared);\n        if (key === 'Enter') {\n          if (isOutsideDomain) {\n            return;\n          }\n          const coordinate = selectCoordinateForDefaultIndex(\n            currentState,\n            tooltipEventType,\n            'hover',\n            String(keyboardInteraction.index),\n          );\n          listenerApi.dispatch(\n            setKeyboardInteraction({\n              active: !keyboardInteraction.active,\n              activeIndex: keyboardInteraction.index,\n              activeCoordinate: coordinate,\n            }),\n          );\n          return;\n        }\n\n        const direction = selectChartDirection(currentState);\n        const directionMultiplier = direction === 'left-to-right' ? 1 : -1;\n        const movement = key === 'ArrowRight' ? 1 : -1;\n        let nextIndex: number;\n        if (isOutsideDomain) {\n          const axisDataKey = selectTooltipAxisDataKey(currentState);\n          const domain = selectTooltipAxisDomain(currentState);\n          const effectiveMovement = movement * directionMultiplier;\n\n          // Build a minimal TooltipInteractionState for the candidate-index check.\n          const mkInteraction = (i: number): TooltipInteractionState => ({\n            active: false,\n            index: String(i),\n            dataKey: undefined,\n            graphicalItemId: undefined,\n            coordinate: undefined,\n          });\n\n          nextIndex = -1;\n          if (effectiveMovement > 0) {\n            for (let i = 0; i < displayedData.length; i++) {\n              if (combineActiveTooltipIndex(mkInteraction(i), displayedData, axisDataKey, domain) != null) {\n                nextIndex = i;\n                break;\n              }\n            }\n          } else {\n            for (let i = displayedData.length - 1; i >= 0; i--) {\n              if (combineActiveTooltipIndex(mkInteraction(i), displayedData, axisDataKey, domain) != null) {\n                nextIndex = i;\n                break;\n              }\n            }\n          }\n\n          if (nextIndex < 0) {\n            return;\n          }\n        } else {\n          nextIndex = currentIndex + movement * directionMultiplier;\n          const dataLength = tooltipTicks?.length || displayedData.length;\n          if (dataLength === 0 || nextIndex >= dataLength || nextIndex < 0) {\n            return;\n          }\n        }\n        const coordinate = selectCoordinateForDefaultIndex(currentState, tooltipEventType, 'hover', String(nextIndex));\n        listenerApi.dispatch(\n          setKeyboardInteraction({\n            active: true,\n            activeIndex: nextIndex.toString(),\n            activeCoordinate: coordinate,\n          }),\n        );\n      } finally {\n        rafId = null;\n        timeoutId = null;\n      }\n    };\n\n    if (!isThrottled) {\n      callback();\n      return;\n    }\n\n    if (throttleDelay === 'raf') {\n      rafId = requestAnimationFrame(callback);\n    } else if (typeof throttleDelay === 'number') {\n      if (timeoutId === null) {\n        callback();\n        latestKeyboardActionPayload = null;\n\n        timeoutId = setTimeout(() => {\n          if (latestKeyboardActionPayload) {\n            callback();\n          } else {\n            timeoutId = null;\n            rafId = null;\n          }\n        }, throttleDelay);\n      }\n    }\n  },\n});\n\nkeyboardEventsMiddleware.startListening({\n  actionCreator: focusAction,\n  effect: (_action, listenerApi: ListenerEffectAPI<RechartsRootState, AppDispatch>) => {\n    const state: RechartsRootState = listenerApi.getState();\n    const accessibilityLayerIsActive = state.rootProps.accessibilityLayer !== false;\n    if (!accessibilityLayerIsActive) {\n      return;\n    }\n    const { keyboardInteraction } = state.tooltip;\n    if (keyboardInteraction.active) {\n      return;\n    }\n    if (keyboardInteraction.index == null) {\n      const nextIndex = '0';\n      const tooltipEventType = selectTooltipEventType(state, state.tooltip.settings.shared);\n      const coordinate = selectCoordinateForDefaultIndex(state, tooltipEventType, 'hover', String(nextIndex));\n      listenerApi.dispatch(\n        setKeyboardInteraction({\n          active: true,\n          activeIndex: nextIndex,\n          activeCoordinate: coordinate,\n        }),\n      );\n    }\n  },\n});\n\nkeyboardEventsMiddleware.startListening({\n  actionCreator: blurAction,\n  effect: (_action, listenerApi: ListenerEffectAPI<RechartsRootState, AppDispatch>) => {\n    const state: RechartsRootState = listenerApi.getState();\n    const accessibilityLayerIsActive = state.rootProps.accessibilityLayer !== false;\n    if (!accessibilityLayerIsActive) {\n      return;\n    }\n    const { keyboardInteraction } = state.tooltip;\n    if (keyboardInteraction.active) {\n      listenerApi.dispatch(\n        setKeyboardInteraction({\n          active: false,\n          activeIndex: keyboardInteraction.index,\n          activeCoordinate: keyboardInteraction.coordinate,\n        }),\n      );\n    }\n  },\n});\n","import { SyntheticEvent } from 'react';\n\nexport function createEventProxy<T extends SyntheticEvent>(reactEvent: T): T {\n  reactEvent.persist();\n  const { currentTarget } = reactEvent;\n  return new Proxy(reactEvent, {\n    get: (target, prop) => {\n      if (prop === 'currentTarget') {\n        return currentTarget;\n      }\n      const value = Reflect.get(target, prop);\n      if (typeof value === 'function') {\n        return value.bind(target);\n      }\n      return value;\n    },\n  });\n}\n","import { createAction, createListenerMiddleware, ListenerEffectAPI, PayloadAction } from '@reduxjs/toolkit';\nimport { SyntheticEvent } from 'react';\nimport { CategoricalChartFunc } from '../chart/types';\nimport { MouseHandlerDataParam } from '../synchronisation/types';\nimport {\n  selectActiveLabel,\n  selectActiveTooltipCoordinate,\n  selectActiveTooltipDataKey,\n  selectActiveTooltipIndex,\n  selectIsTooltipActive,\n} from './selectors/tooltipSelectors';\nimport { AppDispatch, RechartsRootState } from './store';\nimport { createEventProxy } from '../util/createEventProxy';\n\ntype ExternalEventActionPayload<E = SyntheticEvent> = {\n  reactEvent: E;\n  handler: CategoricalChartFunc<E> | undefined;\n};\n\nexport const externalEventAction = createAction<ExternalEventActionPayload<any>>('externalEvent');\n\nexport const externalEventsMiddleware = createListenerMiddleware<RechartsRootState>();\n\n/*\n * We need a Map keyed by event type because this middleware handles MULTIPLE different event types\n * (click, mouseenter, mouseleave, mousedown, mouseup, contextmenu, dblclick, touchstart, touchmove, touchend)\n * from the same DOM element. Different event types should NOT cancel each other's animation frames.\n * For example, a click event and a mousemove event can happen in quick succession and both should be processed.\n * This is different from mouseMoveMiddleware which only handles one event type and uses a single rafId.\n */\nconst rafIdMap = new Map<string, number>();\nconst timeoutIdMap = new Map<string, ReturnType<typeof setTimeout>>();\nconst latestEventMap = new Map<string, ExternalEventActionPayload>();\n\nexternalEventsMiddleware.startListening({\n  actionCreator: externalEventAction,\n  effect: (\n    action: PayloadAction<ExternalEventActionPayload>,\n    listenerApi: ListenerEffectAPI<RechartsRootState, AppDispatch>,\n  ) => {\n    const { handler, reactEvent } = action.payload;\n    if (handler == null) {\n      return;\n    }\n\n    const eventType = reactEvent.type;\n    const eventProxy = createEventProxy(reactEvent);\n\n    latestEventMap.set(eventType, {\n      handler,\n      reactEvent: eventProxy,\n    });\n\n    // Cancel any pending execution for this event type\n    const existingRafId = rafIdMap.get(eventType);\n    if (existingRafId !== undefined) {\n      cancelAnimationFrame(existingRafId);\n      rafIdMap.delete(eventType);\n    }\n\n    const state = listenerApi.getState();\n    const { throttleDelay, throttledEvents } = state.eventSettings;\n\n    /*\n     * reactEvent.type gives us the event type as a string, e.g., 'click', 'mousemove', etc.\n     * which is the same as the names used in throttledEvents array\n     * but that array is strictly typed as ReadonlyArray<keyof GlobalEventHandlersEventMap> | 'all' | undefined\n     * so that we can have relevant autocomplete and type checking elsewhere.\n     * This makes TypeScript panic because it refuses to call .includes() on ReadonlyArray<keyof GlobalEventHandlersEventMap>\n     * with a string argument.\n     * To satisfy TypeScript, we need to explicitly typecast throttledEvents here.\n     */\n    const eventListAsString: 'all' | ReadonlyArray<string> | undefined = throttledEvents;\n\n    // Check if this event type should be throttled\n    // throttledEvents can be 'all' or an array of event names\n    const isThrottled = eventListAsString === 'all' || eventListAsString?.includes(eventType);\n\n    const existingTimeoutId = timeoutIdMap.get(eventType);\n    if (existingTimeoutId !== undefined && (typeof throttleDelay !== 'number' || !isThrottled)) {\n      clearTimeout(existingTimeoutId);\n      timeoutIdMap.delete(eventType);\n    }\n\n    const callback = () => {\n      const latestAction = latestEventMap.get(eventType);\n\n      try {\n        if (!latestAction) {\n          // This happens if the event was consumed by the leading edge and no new event came in\n          return;\n        }\n\n        const { handler: latestHandler, reactEvent: latestEvent } = latestAction;\n        const currentState: RechartsRootState = listenerApi.getState();\n        const nextState: MouseHandlerDataParam = {\n          activeCoordinate: selectActiveTooltipCoordinate(currentState),\n          activeDataKey: selectActiveTooltipDataKey(currentState),\n          activeIndex: selectActiveTooltipIndex(currentState),\n          activeLabel: selectActiveLabel(currentState),\n          activeTooltipIndex: selectActiveTooltipIndex(currentState),\n          isTooltipActive: selectIsTooltipActive(currentState),\n        };\n\n        if (latestHandler) {\n          latestHandler(nextState, latestEvent);\n        }\n      } finally {\n        rafIdMap.delete(eventType);\n        timeoutIdMap.delete(eventType);\n        latestEventMap.delete(eventType);\n      }\n    };\n\n    if (!isThrottled) {\n      // Execute immediately\n      callback();\n      return;\n    }\n\n    if (throttleDelay === 'raf') {\n      const rafId = requestAnimationFrame(callback);\n      rafIdMap.set(eventType, rafId);\n    } else if (typeof throttleDelay === 'number') {\n      if (!timeoutIdMap.has(eventType)) {\n        /*\n         * Leading edge execution - execute immediately on the first event\n         * and then start the cooldown period to throttle subsequent events.\n         */\n        callback();\n\n        // Start cooldown\n        const timeoutId = setTimeout(callback, throttleDelay);\n        timeoutIdMap.set(eventType, timeoutId);\n      }\n    } else {\n      // Should not happen based on type, but fallback to immediate\n      callback();\n    }\n  },\n});\n","import { createSelector } from 'reselect';\nimport { RechartsRootState } from '../store';\nimport { TooltipIndex, TooltipPayloadConfiguration } from '../tooltipSlice';\nimport { Coordinate } from '../../util/types';\nimport { selectTooltipState } from './selectTooltipState';\nimport { GraphicalItemId } from '../graphicalItemsSlice';\n\nconst selectAllTooltipPayloadConfiguration: (state: RechartsRootState) => ReadonlyArray<TooltipPayloadConfiguration> =\n  createSelector([selectTooltipState], tooltipState => tooltipState.tooltipItemPayloads);\n\nexport const selectTooltipCoordinate: (\n  state: RechartsRootState,\n  tooltipIndex: TooltipIndex,\n  graphicalItemId: GraphicalItemId,\n) => Coordinate | undefined = createSelector(\n  [\n    selectAllTooltipPayloadConfiguration,\n    (_state: RechartsRootState, tooltipIndex: TooltipIndex): TooltipIndex => tooltipIndex,\n    (_state: RechartsRootState, _tooltipIndex: TooltipIndex, graphicalItemId: GraphicalItemId): GraphicalItemId =>\n      graphicalItemId,\n  ],\n  (\n    allTooltipConfigurations: ReadonlyArray<TooltipPayloadConfiguration>,\n    tooltipIndex: TooltipIndex,\n    graphicalItemId: GraphicalItemId,\n  ): Coordinate | undefined => {\n    if (tooltipIndex == null) {\n      return undefined;\n    }\n    const mostRelevantTooltipConfiguration = allTooltipConfigurations.find(tooltipConfiguration => {\n      return tooltipConfiguration.settings.graphicalItemId === graphicalItemId;\n    });\n    if (mostRelevantTooltipConfiguration == null) {\n      return undefined;\n    }\n    const { getPosition } = mostRelevantTooltipConfiguration;\n    if (getPosition == null) {\n      return undefined;\n    }\n    return getPosition(tooltipIndex);\n  },\n);\n","import { createAction, createListenerMiddleware, ListenerEffectAPI, PayloadAction } from '@reduxjs/toolkit';\nimport * as React from 'react';\nimport { AppDispatch, RechartsRootState } from './store';\nimport { setActiveMouseOverItemIndex, setMouseOverAxisIndex } from './tooltipSlice';\nimport { selectActivePropsFromChartPointer } from './selectors/selectActivePropsFromChartPointer';\n\nimport { getRelativeCoordinate } from '../util/getRelativeCoordinate';\nimport { selectTooltipEventType } from './selectors/selectTooltipEventType';\nimport { DATA_ITEM_GRAPHICAL_ITEM_ID_ATTRIBUTE_NAME, DATA_ITEM_INDEX_ATTRIBUTE_NAME } from '../util/Constants';\nimport { selectTooltipCoordinate } from './selectors/touchSelectors';\nimport { selectAllGraphicalItemsSettings } from './selectors/tooltipSelectors';\nimport { RelativePointer } from '../util/types';\nimport { createEventProxy } from '../util/createEventProxy';\n\nexport const touchEventAction = createAction<React.TouchEvent<HTMLDivElement>>('touchMove');\n\nexport const touchEventMiddleware = createListenerMiddleware<RechartsRootState>();\n\nlet rafId: number | null = null;\nlet timeoutId: ReturnType<typeof setTimeout> | null = null;\nlet latestChartPointers: ReadonlyArray<RelativePointer> | null = null;\nlet latestTouchEvent: React.TouchEvent<HTMLDivElement> | null = null;\n\ntouchEventMiddleware.startListening({\n  actionCreator: touchEventAction,\n  effect: (\n    action: PayloadAction<React.TouchEvent<HTMLDivElement>>,\n    listenerApi: ListenerEffectAPI<RechartsRootState, AppDispatch>,\n  ) => {\n    const touchEvent = action.payload;\n    if (touchEvent.touches == null || touchEvent.touches.length === 0) {\n      return;\n    }\n\n    latestTouchEvent = createEventProxy(touchEvent);\n\n    const state = listenerApi.getState();\n    const { throttleDelay, throttledEvents } = state.eventSettings;\n    const isThrottled = throttledEvents === 'all' || throttledEvents.includes('touchmove');\n\n    if (rafId !== null) {\n      cancelAnimationFrame(rafId);\n      rafId = null;\n    }\n    if (timeoutId !== null && (typeof throttleDelay !== 'number' || !isThrottled)) {\n      clearTimeout(timeoutId);\n      timeoutId = null;\n    }\n\n    latestChartPointers = Array.from(touchEvent.touches).map(touch =>\n      getRelativeCoordinate({\n        clientX: touch.clientX,\n        clientY: touch.clientY,\n        currentTarget: touchEvent.currentTarget,\n      }),\n    );\n\n    const callback = () => {\n      if (latestTouchEvent == null) {\n        return;\n      }\n\n      const currentState = listenerApi.getState();\n      const tooltipEventType = selectTooltipEventType(currentState, currentState.tooltip.settings.shared);\n      if (tooltipEventType === 'axis') {\n        const latestTouchPointer = latestChartPointers?.[0];\n        if (latestTouchPointer == null) {\n          rafId = null;\n          timeoutId = null;\n          return;\n        }\n        const activeProps = selectActivePropsFromChartPointer(currentState, latestTouchPointer);\n        if (activeProps?.activeIndex != null) {\n          listenerApi.dispatch(\n            setMouseOverAxisIndex({\n              activeIndex: activeProps.activeIndex,\n              activeDataKey: undefined,\n              activeCoordinate: activeProps.activeCoordinate,\n            }),\n          );\n        }\n      } else if (tooltipEventType === 'item') {\n        const touch = latestTouchEvent.touches[0];\n        if (document.elementFromPoint == null || touch == null) {\n          return;\n        }\n        const target = document.elementFromPoint(touch.clientX, touch.clientY);\n        if (!target || !target.getAttribute) {\n          return;\n        }\n        const itemIndex = target.getAttribute(DATA_ITEM_INDEX_ATTRIBUTE_NAME);\n        const graphicalItemId = target.getAttribute(DATA_ITEM_GRAPHICAL_ITEM_ID_ATTRIBUTE_NAME) ?? undefined;\n        const settings = selectAllGraphicalItemsSettings(currentState).find(item => item.id === graphicalItemId);\n        if (itemIndex == null || settings == null || graphicalItemId == null) {\n          return;\n        }\n        const { dataKey } = settings;\n        const coordinate = selectTooltipCoordinate(currentState, itemIndex, graphicalItemId);\n\n        listenerApi.dispatch(\n          setActiveMouseOverItemIndex({\n            activeDataKey: dataKey,\n            activeIndex: itemIndex,\n            activeCoordinate: coordinate,\n            activeGraphicalItemId: graphicalItemId,\n          }),\n        );\n      }\n      rafId = null;\n      timeoutId = null;\n    };\n\n    if (!isThrottled) {\n      callback();\n      return;\n    }\n\n    if (throttleDelay === 'raf') {\n      rafId = requestAnimationFrame(callback);\n    } else if (typeof throttleDelay === 'number') {\n      if (timeoutId === null) {\n        callback();\n        latestTouchEvent = null;\n\n        timeoutId = setTimeout(() => {\n          if (latestTouchEvent) {\n            callback();\n          } else {\n            timeoutId = null;\n            rafId = null;\n          }\n        }, throttleDelay);\n      }\n    }\n  },\n});\n","import { createSlice, PayloadAction } from '@reduxjs/toolkit';\nimport { castDraft } from 'immer';\nimport { EventThrottlingProps } from '../util/types';\n\nexport type EventSettingsState = Required<EventThrottlingProps>;\n\nexport const initialEventSettingsState: EventSettingsState = {\n  throttleDelay: 'raf',\n  throttledEvents: ['mousemove', 'touchmove', 'pointermove', 'scroll', 'wheel'],\n};\n\nconst eventSettingsSlice = createSlice({\n  name: 'eventSettings',\n  initialState: initialEventSettingsState,\n  reducers: {\n    setEventSettings: (state, action: PayloadAction<EventThrottlingProps>) => {\n      if (action.payload.throttleDelay != null) {\n        state.throttleDelay = action.payload.throttleDelay;\n      }\n      if (action.payload.throttledEvents != null) {\n        state.throttledEvents = castDraft(action.payload.throttledEvents);\n      }\n    },\n  },\n});\n\nexport const { setEventSettings } = eventSettingsSlice.actions;\n\nexport const eventSettingsReducer = eventSettingsSlice.reducer;\n","import { Action, autoBatchEnhancer, combineReducers, configureStore, Dispatch, Reducer, Store } from '@reduxjs/toolkit';\nimport { optionsReducer } from './optionsSlice';\nimport { tooltipReducer } from './tooltipSlice';\nimport { chartDataReducer } from './chartDataSlice';\nimport { chartLayoutReducer } from './layoutSlice';\nimport { mouseClickMiddleware, mouseMoveMiddleware } from './mouseEventsMiddleware';\nimport { reduxDevtoolsJsonStringifyReplacer } from './reduxDevtoolsJsonStringifyReplacer';\nimport { cartesianAxisReducer } from './cartesianAxisSlice';\nimport { graphicalItemsReducer } from './graphicalItemsSlice';\nimport { referenceElementsReducer } from './referenceElementsSlice';\nimport { brushReducer } from './brushSlice';\nimport { legendReducer } from './legendSlice';\nimport { rootPropsReducer } from './rootPropsSlice';\nimport { polarAxisReducer } from './polarAxisSlice';\nimport { polarOptionsReducer } from './polarOptionsSlice';\nimport { keyboardEventsMiddleware } from './keyboardEventsMiddleware';\nimport { externalEventsMiddleware } from './externalEventsMiddleware';\nimport { touchEventMiddleware } from './touchEventsMiddleware';\nimport { errorBarReducer } from './errorBarSlice';\nimport { Global } from '../util/Global';\nimport { zIndexReducer } from './zIndexSlice';\nimport { eventSettingsReducer } from './eventSettingsSlice';\nimport { renderedTicksReducer } from './renderedTicksSlice';\n\nexport type RechartsRootState = {\n  brush: ReturnType<typeof brushReducer>;\n  cartesianAxis: ReturnType<typeof cartesianAxisReducer>;\n  chartData: ReturnType<typeof chartDataReducer>;\n  errorBars: ReturnType<typeof errorBarReducer>;\n  eventSettings: ReturnType<typeof eventSettingsReducer>;\n  graphicalItems: ReturnType<typeof graphicalItemsReducer>;\n  layout: ReturnType<typeof chartLayoutReducer>;\n  legend: ReturnType<typeof legendReducer>;\n  options: ReturnType<typeof optionsReducer>;\n  polarAxis: ReturnType<typeof polarAxisReducer>;\n  polarOptions: ReturnType<typeof polarOptionsReducer>;\n  referenceElements: ReturnType<typeof referenceElementsReducer>;\n  renderedTicks: ReturnType<typeof renderedTicksReducer>;\n  rootProps: ReturnType<typeof rootPropsReducer>;\n  tooltip: ReturnType<typeof tooltipReducer>;\n  zIndex: ReturnType<typeof zIndexReducer>;\n};\n\nconst rootReducer: Reducer<RechartsRootState> = combineReducers({\n  brush: brushReducer,\n  cartesianAxis: cartesianAxisReducer,\n  chartData: chartDataReducer,\n  errorBars: errorBarReducer,\n  eventSettings: eventSettingsReducer,\n  graphicalItems: graphicalItemsReducer,\n  layout: chartLayoutReducer,\n  legend: legendReducer,\n  options: optionsReducer,\n  polarAxis: polarAxisReducer,\n  polarOptions: polarOptionsReducer,\n  referenceElements: referenceElementsReducer,\n  renderedTicks: renderedTicksReducer,\n  rootProps: rootPropsReducer,\n  tooltip: tooltipReducer,\n  zIndex: zIndexReducer,\n});\n\nexport const createRechartsStore = (\n  preloadedState?: Partial<RechartsRootState>,\n  chartName: string = 'Chart',\n): Store<RechartsRootState> => {\n  return configureStore<RechartsRootState>({\n    reducer: rootReducer,\n    // redux-toolkit v1 types are unhappy with the preloadedState type. Remove the `as any` when bumping to v2\n    preloadedState: preloadedState as any,\n    // @ts-expect-error redux-toolkit v1 types are unhappy with the middleware array. Remove this comment when bumping to v2\n    middleware: getDefaultMiddleware =>\n      getDefaultMiddleware({\n        serializableCheck: false,\n        immutableCheck: !['commonjs', 'es6', 'production'].includes(process.env.NODE_ENV ?? ''),\n      }).concat([\n        mouseClickMiddleware.middleware,\n        mouseMoveMiddleware.middleware,\n        keyboardEventsMiddleware.middleware,\n        externalEventsMiddleware.middleware,\n        touchEventMiddleware.middleware,\n      ]),\n    /*\n     * I can't find out how to satisfy typescript here.\n     * We return `EnhancerArray<[StoreEnhancer<{}, {}>, StoreEnhancer]>` from this function,\n     * but the types say we should return `EnhancerArray<StoreEnhancer<{}, {}>`.\n     * Looks like it's badly inferred generics, but it won't allow me to provide the correct type manually either.\n     * So let's just ignore the error for now.\n     */\n    // @ts-expect-error mismatched generics\n    enhancers: getDefaultEnhancers => {\n      let enhancers = getDefaultEnhancers;\n      if (typeof getDefaultEnhancers === 'function') {\n        /*\n         * In RTK v2 this is always a function, but in v1 it is an array.\n         * Because we have @types/redux-toolkit v1 as a dependency, typescript is going to flag this as an error.\n         * We support both RTK v1 and v2, so we need to do this check.\n         * https://redux-toolkit.js.org/usage/migrating-rtk-2#configurestoreenhancers-must-be-a-callback\n         */\n        // @ts-expect-error RTK v2 behaviour on RTK v1 types\n        enhancers = getDefaultEnhancers();\n      }\n      return enhancers.concat(\n        autoBatchEnhancer({\n          type: 'raf',\n        }),\n      );\n    },\n    devTools: Global.devToolsEnabled && {\n      serialize: {\n        replacer: reduxDevtoolsJsonStringifyReplacer,\n      },\n      name: `recharts-${chartName}`,\n    },\n  });\n};\n\nexport type AppDispatch = Dispatch<Action>;\n","import * as React from 'react';\nimport { Context, MutableRefObject, ReactNode, useRef } from 'react';\nimport { Provider } from 'react-redux';\nimport { Action, Store } from '@reduxjs/toolkit';\nimport { createRechartsStore, RechartsRootState } from './store';\nimport { useIsPanorama } from '../context/PanoramaContext';\nimport { RechartsReduxContext, RechartsReduxContextValue } from './RechartsReduxContext';\n\ntype RechartsStoreProviderProps = {\n  children: ReactNode;\n  preloadedState?: Partial<RechartsRootState>;\n  reduxStoreName?: string;\n};\n\nexport function RechartsStoreProvider({ preloadedState, children, reduxStoreName }: RechartsStoreProviderProps) {\n  const isPanorama = useIsPanorama();\n  /*\n   * Why the ref? Redux official documentation recommends to use store as a singleton,\n   * and reuse that everywhere: https://redux-toolkit.js.org/api/configureStore#basic-example\n   *\n   * Which is correct! Except that is considering deploying Redux in an app.\n   * Recharts as a library supports multiple charts on the same page.\n   * And each of these charts needs its own store independent of others!\n   *\n   * The alternative is to have everything in the store keyed by the chart id.\n   * Which would make working with everything a little bit more painful because we need the chart id everywhere.\n   */\n  const storeRef: MutableRefObject<Store<RechartsRootState, Action> | null> = useRef(null);\n\n  /*\n   * Panorama means that this chart is not its own chart, it's only a \"preview\"\n   * being rendered as a child of Brush.\n   * In such case, it should not have a store on its own - it should implicitly inherit\n   * whatever data is in the \"parent\" or \"root\" chart.\n   * Which here is represented by not having a Provider at all. All selectors will use the root store by default.\n   */\n  if (isPanorama) {\n    return children;\n  }\n\n  if (storeRef.current == null) {\n    storeRef.current = createRechartsStore(preloadedState, reduxStoreName);\n  }\n\n  // @ts-expect-error React-Redux types demand that the context internal value is not null, but we have that as default.\n  const nonNullContext: Context<RechartsReduxContextValue> = RechartsReduxContext;\n\n  return (\n    <Provider context={nonNullContext} store={storeRef.current}>\n      {children}\n    </Provider>\n  );\n}\n","import { memo, ReactNode, useEffect } from 'react';\nimport { LayoutType, Margin } from '../util/types';\nimport { useIsPanorama } from '../context/PanoramaContext';\nimport { setLayout, setMargin } from './layoutSlice';\nimport { useAppDispatch } from './hooks';\nimport { propsAreEqual } from '../util/propsAreEqual';\n\n/**\n * \"Main\" props are props that are only accepted on the main chart,\n * as opposed to the small panorama chart inside a Brush.\n */\ntype MainChartProps = {\n  layout: LayoutType;\n  margin: Partial<Margin>;\n};\n\nfunction ReportMainChartPropsImpl({ layout, margin }: MainChartProps): ReactNode {\n  const dispatch = useAppDispatch();\n\n  /*\n   * Skip dispatching properties in panorama chart for two reasons:\n   * 1. The root chart should be deciding on these properties, and\n   * 2. Brush reads these properties from redux store, and so they must remain stable\n   *      to avoid circular dependency and infinite re-rendering.\n   */\n  const isPanorama = useIsPanorama();\n  /*\n   * useEffect here is required to avoid the \"Cannot update a component while rendering a different component\" error.\n   * https://github.com/facebook/react/issues/18178\n   *\n   * Reported in https://github.com/recharts/recharts/issues/5514\n   */\n  useEffect(() => {\n    if (!isPanorama) {\n      dispatch(setLayout(layout));\n      dispatch(setMargin(margin));\n    }\n  }, [dispatch, isPanorama, layout, margin]);\n  return null;\n}\n\nexport const ReportMainChartProps = memo(ReportMainChartPropsImpl, propsAreEqual);\n","import { useEffect } from 'react';\nimport { updateOptions, UpdatableChartOptions } from './rootPropsSlice';\nimport { useAppDispatch } from './hooks';\n\nexport function ReportChartProps(props: UpdatableChartOptions): null {\n  const dispatch = useAppDispatch();\n  useEffect(() => {\n    dispatch(updateOptions(props));\n  }, [dispatch, props]);\n  return null;\n}\n","import { useEffect, memo } from 'react';\nimport { useAppDispatch } from './hooks';\nimport { setEventSettings } from './eventSettingsSlice';\nimport { propsAreEqual } from '../util/propsAreEqual';\nimport { EventThrottlingProps } from '../util/types';\n\nconst ReportEventSettingsImpl = (props: EventThrottlingProps) => {\n  const dispatch = useAppDispatch();\n\n  useEffect(() => {\n    dispatch(setEventSettings(props));\n  }, [dispatch, props]);\n\n  return null;\n};\n\nexport const ReportEventSettings = memo(ReportEventSettingsImpl, propsAreEqual);\n","import * as React from 'react';\nimport { useLayoutEffect, useRef } from 'react';\nimport { useAppDispatch, useAppSelector } from '../state/hooks';\nimport { registerZIndexPortalElement, unregisterZIndexPortalElement } from '../state/zIndexSlice';\nimport { selectAllRegisteredZIndexes } from './zIndexSelectors';\n\nfunction ZIndexSvgPortal({ zIndex, isPanorama }: { zIndex: number; isPanorama: boolean }) {\n  const ref = useRef<SVGGElement>(null);\n  const dispatch = useAppDispatch();\n  useLayoutEffect(() => {\n    if (ref.current) {\n      dispatch(registerZIndexPortalElement({ zIndex, element: ref.current, isPanorama }));\n    }\n    return () => {\n      dispatch(unregisterZIndexPortalElement({ zIndex, isPanorama }));\n    };\n  }, [dispatch, zIndex, isPanorama]);\n  // these g elements should not be tabbable\n  return <g tabIndex={-1} ref={ref} className={`recharts-zIndex-layer_${zIndex}`} />;\n}\n\nexport function AllZIndexPortals({ children, isPanorama }: { children?: React.ReactNode; isPanorama: boolean }) {\n  const allRegisteredZIndexes: ReadonlyArray<number> | undefined = useAppSelector(selectAllRegisteredZIndexes);\n\n  if (!allRegisteredZIndexes || allRegisteredZIndexes.length === 0) {\n    return children;\n  }\n\n  const allNegativeZIndexes = allRegisteredZIndexes.filter(zIndex => zIndex < 0);\n  // We exclude zero on purpose - that is the default layer, and it doesn't need a portal.\n  const allPositiveZIndexes = allRegisteredZIndexes.filter(zIndex => zIndex > 0);\n\n  return (\n    <>\n      {allNegativeZIndexes.map(zIndex => (\n        <ZIndexSvgPortal key={zIndex} zIndex={zIndex} isPanorama={isPanorama} />\n      ))}\n      {children}\n      {allPositiveZIndexes.map(zIndex => (\n        <ZIndexSvgPortal key={zIndex} zIndex={zIndex} isPanorama={isPanorama} />\n      ))}\n    </>\n  );\n}\n","import * as React from 'react';\nimport { forwardRef, ReactNode } from 'react';\nimport { useChartHeight, useChartWidth } from '../context/chartLayoutContext';\nimport { useAccessibilityLayer } from '../context/accessibilityContext';\nimport { useIsPanorama } from '../context/PanoramaContext';\nimport { Surface } from './Surface';\nimport { useAppSelector } from '../state/hooks';\nimport { selectBrushDimensions } from '../state/selectors/brushSelectors';\nimport { isPositiveNumber } from '../util/isWellBehavedNumber';\nimport { AllZIndexPortals } from '../zIndex/ZIndexPortal';\n\ntype RootSurfaceProps = {\n  children: ReactNode;\n  title: string | undefined;\n  desc: string | undefined;\n  otherAttributes: Record<string, unknown> | null;\n};\n\nconst FULL_WIDTH_AND_HEIGHT = {\n  width: '100%',\n  height: '100%',\n  /*\n   * display: block is necessary here because the default for an SVG is display: inline,\n   * which in some browsers (Chrome) adds a little bit of extra space above and below the SVG\n   * to make space for the descender of letters like \"g\" and \"y\". This throws off the height calculation\n   * and causes the container to grow indefinitely on each render with responsive=true.\n   * Display: block removes that extra space.\n   *\n   * Interestingly, Firefox does not have this problem, but it doesn't hurt to add the style anyway.\n   */\n  display: 'block',\n};\n\nconst MainChartSurface = forwardRef<SVGSVGElement, RootSurfaceProps>((props: RootSurfaceProps, ref) => {\n  const width = useChartWidth();\n  const height = useChartHeight();\n  const hasAccessibilityLayer = useAccessibilityLayer();\n\n  if (!isPositiveNumber(width) || !isPositiveNumber(height)) {\n    return null;\n  }\n\n  const { children, otherAttributes, title, desc } = props;\n\n  let tabIndex: number | undefined, role: string | undefined;\n\n  if (otherAttributes != null) {\n    if (typeof otherAttributes.tabIndex === 'number') {\n      tabIndex = otherAttributes.tabIndex;\n    } else {\n      tabIndex = hasAccessibilityLayer ? 0 : undefined;\n    }\n\n    if (typeof otherAttributes.role === 'string') {\n      role = otherAttributes.role;\n    } else {\n      role = hasAccessibilityLayer ? 'application' : undefined;\n    }\n  }\n\n  return (\n    <Surface\n      {...otherAttributes}\n      title={title}\n      desc={desc}\n      role={role}\n      tabIndex={tabIndex}\n      width={width}\n      height={height}\n      style={FULL_WIDTH_AND_HEIGHT}\n      ref={ref}\n    >\n      {children}\n    </Surface>\n  );\n});\n\nconst BrushPanoramaSurface = ({ children }: { children: ReactNode }) => {\n  const brushDimensions = useAppSelector(selectBrushDimensions);\n\n  if (!brushDimensions) {\n    return null;\n  }\n\n  const { width, height, y, x } = brushDimensions;\n\n  return (\n    <Surface width={width} height={height} x={x} y={y}>\n      {children}\n    </Surface>\n  );\n};\n\nexport const RootSurface = forwardRef<SVGSVGElement, RootSurfaceProps>(\n  ({ children, ...rest }: RootSurfaceProps, ref) => {\n    const isPanorama = useIsPanorama();\n\n    if (isPanorama) {\n      return (\n        <BrushPanoramaSurface>\n          <AllZIndexPortals isPanorama>{children}</AllZIndexPortals>\n        </BrushPanoramaSurface>\n      );\n    }\n    return (\n      <MainChartSurface ref={ref} {...rest}>\n        <AllZIndexPortals isPanorama={false}>{children}</AllZIndexPortals>\n      </MainChartSurface>\n    );\n  },\n);\n","import * as React from 'react';\nimport {\n  CSSProperties,\n  forwardRef,\n  HTMLAttributes,\n  MutableRefObject,\n  ReactNode,\n  Ref,\n  useCallback,\n  useEffect,\n  useRef,\n  useState,\n} from 'react';\nimport { clsx } from 'clsx';\nimport { mouseLeaveChart } from '../state/tooltipSlice';\nimport { useAppDispatch } from '../state/hooks';\nimport { mouseClickAction, mouseMoveAction } from '../state/mouseEventsMiddleware';\nimport { useSynchronisedEventsFromOtherCharts } from '../synchronisation/useChartSynchronisation';\nimport { focusAction, keyDownAction, blurAction } from '../state/keyboardEventsMiddleware';\nimport { useReportScale } from '../util/useReportScale';\nimport { ExternalMouseEvents } from './types';\nimport { externalEventAction } from '../state/externalEventsMiddleware';\nimport { touchEventAction } from '../state/touchEventsMiddleware';\nimport { TooltipPortalContext } from '../context/tooltipPortalContext';\nimport { LegendPortalContext } from '../context/legendPortalContext';\nimport { ReportChartSize } from '../context/chartLayoutContext';\nimport { useResponsiveContainerContext } from '../component/ResponsiveContainer';\nimport { Percent } from '../util/types';\n\nexport type RechartsWrapperProps = ExternalMouseEvents & {\n  children: ReactNode;\n  width: number | Percent | undefined;\n  height: number | Percent | undefined;\n  /**\n   * If true, then it will listen to container size changes and adapt the SVG chart accordingly.\n   * If false, then it renders the chart at the specified width and height and will stay that way\n   * even if the container size changes.\n   */\n  responsive: boolean;\n  className?: string;\n  style?: CSSProperties;\n  ref?: Ref<HTMLDivElement>;\n  /**\n   * Treemap is special snowflake that handles its own mouse events so\n   * here is a flag to disable the dispatching of mouse events from RechartsWrapper.\n   * If false, then this disables mouse click and touch event dispatching.\n   * Mouse move events are still dispatched because they are needed for tooltip synchronization.\n   * @default true\n   */\n  dispatchTouchEvents?: boolean;\n};\n\nconst EventSynchronizer = (): ReactNode => {\n  useSynchronisedEventsFromOtherCharts();\n  return null;\n};\n\nfunction getNumberOrZero(value: number | string | undefined): number {\n  if (typeof value === 'number') {\n    return value;\n  }\n  if (typeof value === 'string') {\n    const parsed = parseFloat(value);\n    if (!Number.isNaN(parsed)) {\n      return parsed;\n    }\n  }\n  return 0;\n}\n\ntype WrapperDivProps = HTMLAttributes<HTMLDivElement> & {\n  width: number | string | undefined;\n  height: number | string | undefined;\n};\n\nconst ResponsiveDiv = forwardRef<HTMLDivElement, WrapperDivProps>((props: WrapperDivProps, ref): ReactNode => {\n  const observerRef: MutableRefObject<ResizeObserver | null> = useRef(null);\n\n  const [sizes, setSizes] = useState<{\n    containerWidth: number;\n    containerHeight: number;\n  }>({\n    containerWidth: getNumberOrZero(props.style?.width),\n    containerHeight: getNumberOrZero(props.style?.height),\n  });\n\n  const setContainerSize = useCallback((newWidth: number, newHeight: number) => {\n    setSizes(prevState => {\n      const roundedWidth = Math.round(newWidth);\n      const roundedHeight = Math.round(newHeight);\n      if (prevState.containerWidth === roundedWidth && prevState.containerHeight === roundedHeight) {\n        return prevState;\n      }\n\n      return { containerWidth: roundedWidth, containerHeight: roundedHeight };\n    });\n  }, []);\n\n  const innerRef = useCallback(\n    (node: HTMLDivElement | null) => {\n      // 1. First, call the external ref if it was provided\n      if (typeof ref === 'function') {\n        ref(node);\n      }\n\n      // 2. Disconnect any previously active ResizeObserver instance to prevent memory leaks\n      if (observerRef.current != null) {\n        observerRef.current.disconnect();\n        observerRef.current = null;\n      }\n\n      // 3. Initiate a new ResizeObserver on the valid DOM node\n      if (node != null && typeof ResizeObserver !== 'undefined') {\n        const { width: containerWidth, height: containerHeight } = node.getBoundingClientRect();\n        setContainerSize(containerWidth, containerHeight);\n\n        const callback = (entries: ResizeObserverEntry[]) => {\n          const entry = entries[0];\n          if (entry == null) {\n            return;\n          }\n          const { width, height } = entry.contentRect;\n          setContainerSize(width, height);\n        };\n\n        const observer = new ResizeObserver(callback);\n        observer.observe(node);\n        observerRef.current = observer;\n      }\n    },\n    [ref, setContainerSize],\n  );\n\n  useEffect(() => {\n    return () => {\n      const observer = observerRef.current;\n      if (observer != null) {\n        observer.disconnect();\n      }\n    };\n  }, [setContainerSize]);\n\n  return (\n    <>\n      <ReportChartSize width={sizes.containerWidth} height={sizes.containerHeight} />\n      <div ref={innerRef} {...props} />\n    </>\n  );\n});\n\nconst ReadSizeOnceDiv = forwardRef<HTMLDivElement, WrapperDivProps>((props: WrapperDivProps, ref): ReactNode => {\n  const { width, height } = props;\n  const [sizes, setSizes] = useState<{\n    containerWidth: number;\n    containerHeight: number;\n  }>({\n    containerWidth: getNumberOrZero(width),\n    containerHeight: getNumberOrZero(height),\n  });\n\n  const setContainerSize = useCallback((newWidth: number, newHeight: number) => {\n    setSizes(prevState => {\n      const roundedWidth = Math.round(newWidth);\n      const roundedHeight = Math.round(newHeight);\n      if (prevState.containerWidth === roundedWidth && prevState.containerHeight === roundedHeight) {\n        return prevState;\n      }\n\n      return { containerWidth: roundedWidth, containerHeight: roundedHeight };\n    });\n  }, []);\n\n  const innerRef = useCallback(\n    (node: HTMLDivElement | null) => {\n      if (typeof ref === 'function') {\n        ref(node);\n      }\n      if (node != null) {\n        const { width: containerWidth, height: containerHeight } = node.getBoundingClientRect();\n        setContainerSize(containerWidth, containerHeight);\n      }\n    },\n    [ref, setContainerSize],\n  );\n  return (\n    <>\n      <ReportChartSize width={sizes.containerWidth} height={sizes.containerHeight} />\n      <div ref={innerRef} {...props} />\n    </>\n  );\n});\n\ntype StaticDivProps = HTMLAttributes<HTMLDivElement> & {\n  width: number;\n  height: number;\n};\n\nconst StaticDiv = forwardRef<HTMLDivElement, StaticDivProps>((props: StaticDivProps, ref): ReactNode => {\n  const { width, height } = props;\n\n  return (\n    <>\n      <ReportChartSize width={width} height={height} />\n      <div ref={ref} {...props} />\n    </>\n  );\n});\n\nconst NonResponsiveDiv = forwardRef<HTMLDivElement, WrapperDivProps>((props: WrapperDivProps, ref): ReactNode => {\n  const { width, height } = props;\n  // When width or height are percentages or CSS short names, read size from DOM once\n  if (typeof width === 'string' || typeof height === 'string') {\n    return <ReadSizeOnceDiv {...props} ref={ref} />;\n  }\n  // When both are numbers, use them directly\n  if (typeof width === 'number' && typeof height === 'number') {\n    return <StaticDiv {...props} width={width} height={height} ref={ref} />;\n  }\n  // When width/height are undefined, render wrapper div without reporting size\n  // This results in no SVG being rendered (intentional for backwards compatibility)\n  return (\n    <>\n      <ReportChartSize width={width} height={height} />\n      <div ref={ref} {...props} />\n    </>\n  );\n});\n\nfunction getWrapperDivComponent(responsive: boolean) {\n  return responsive ? ResponsiveDiv : NonResponsiveDiv;\n}\n\nexport const RechartsWrapper = forwardRef<HTMLDivElement | null, RechartsWrapperProps>(\n  (props: RechartsWrapperProps, ref: Ref<HTMLDivElement | null>) => {\n    const {\n      children,\n      className,\n      height: heightFromProps,\n      onClick,\n      onContextMenu,\n      onDoubleClick,\n      onMouseDown,\n      onMouseEnter,\n      onMouseLeave,\n      onMouseMove,\n      onMouseUp,\n      onTouchEnd,\n      onTouchMove,\n      onTouchStart,\n      style,\n      width: widthFromProps,\n      responsive,\n      dispatchTouchEvents = true,\n    } = props;\n    const containerRef: MutableRefObject<HTMLDivElement | null> = useRef<HTMLDivElement>(null);\n    const dispatch = useAppDispatch();\n    const [tooltipPortal, setTooltipPortal] = useState<HTMLElement | null>(null);\n    const [legendPortal, setLegendPortal] = useState<HTMLElement | null>(null);\n\n    const setScaleRef = useReportScale();\n\n    const responsiveContainerCalculations = useResponsiveContainerContext();\n    const width = responsiveContainerCalculations?.width > 0 ? responsiveContainerCalculations.width : widthFromProps;\n    const height =\n      responsiveContainerCalculations?.height > 0 ? responsiveContainerCalculations.height : heightFromProps;\n\n    const innerRef = useCallback(\n      (node: HTMLDivElement | null) => {\n        setScaleRef(node);\n        if (typeof ref === 'function') {\n          ref(node);\n        }\n        setTooltipPortal(node);\n        setLegendPortal(node);\n        if (node != null) {\n          containerRef.current = node;\n        }\n      },\n      [setScaleRef, ref, setTooltipPortal, setLegendPortal],\n    );\n\n    const myOnClick = useCallback(\n      (e: React.MouseEvent<HTMLDivElement>) => {\n        dispatch(mouseClickAction(e));\n        dispatch(externalEventAction({ handler: onClick, reactEvent: e }));\n      },\n      [dispatch, onClick],\n    );\n\n    const myOnMouseEnter = useCallback(\n      (e: React.MouseEvent<HTMLDivElement>) => {\n        dispatch(mouseMoveAction(e));\n        dispatch(externalEventAction({ handler: onMouseEnter, reactEvent: e }));\n      },\n      [dispatch, onMouseEnter],\n    );\n\n    const myOnMouseLeave = useCallback(\n      (e: React.MouseEvent<HTMLDivElement>) => {\n        dispatch(mouseLeaveChart());\n        dispatch(externalEventAction({ handler: onMouseLeave, reactEvent: e }));\n      },\n      [dispatch, onMouseLeave],\n    );\n\n    const myOnMouseMove = useCallback(\n      (e: React.MouseEvent<HTMLDivElement>) => {\n        dispatch(mouseMoveAction(e));\n        dispatch(externalEventAction({ handler: onMouseMove, reactEvent: e }));\n      },\n      [dispatch, onMouseMove],\n    );\n\n    const onFocus = useCallback(() => {\n      dispatch(focusAction());\n    }, [dispatch]);\n\n    const onBlur = useCallback(() => {\n      dispatch(blurAction());\n    }, [dispatch]);\n\n    const onKeyDown = useCallback(\n      (e: React.KeyboardEvent<HTMLDivElement>) => {\n        dispatch(keyDownAction(e.key));\n      },\n      [dispatch],\n    );\n\n    const myOnContextMenu = useCallback(\n      (e: React.MouseEvent<HTMLDivElement>) => {\n        dispatch(externalEventAction({ handler: onContextMenu, reactEvent: e }));\n      },\n      [dispatch, onContextMenu],\n    );\n\n    const myOnDoubleClick = useCallback(\n      (e: React.MouseEvent<HTMLDivElement>) => {\n        dispatch(externalEventAction({ handler: onDoubleClick, reactEvent: e }));\n      },\n      [dispatch, onDoubleClick],\n    );\n\n    const myOnMouseDown = useCallback(\n      (e: React.MouseEvent<HTMLDivElement>) => {\n        dispatch(externalEventAction({ handler: onMouseDown, reactEvent: e }));\n      },\n      [dispatch, onMouseDown],\n    );\n\n    const myOnMouseUp = useCallback(\n      (e: React.MouseEvent<HTMLDivElement>) => {\n        dispatch(externalEventAction({ handler: onMouseUp, reactEvent: e }));\n      },\n      [dispatch, onMouseUp],\n    );\n\n    const myOnTouchStart = useCallback(\n      (e: React.TouchEvent<HTMLDivElement>) => {\n        dispatch(externalEventAction({ handler: onTouchStart, reactEvent: e }));\n      },\n      [dispatch, onTouchStart],\n    );\n\n    /*\n     * onTouchMove is special because it behaves different from mouse events.\n     * Mouse events have 'enter' + 'leave' combo that notify us when the mouse is over\n     * a certain element. Touch events don't have that; touch only gives us\n     * start (finger down), end (finger up) and move (finger moving).\n     * So we need to figure out which element the user is touching\n     * ourselves. Fortunately, there's a convenient method for that:\n     * https://developer.mozilla.org/en-US/docs/Web/API/Document/elementFromPoint\n     */\n    const myOnTouchMove = useCallback(\n      (e: React.TouchEvent<HTMLDivElement>) => {\n        if (dispatchTouchEvents) {\n          dispatch(touchEventAction(e));\n        }\n        dispatch(externalEventAction({ handler: onTouchMove, reactEvent: e }));\n      },\n      [dispatch, dispatchTouchEvents, onTouchMove],\n    );\n\n    const myOnTouchEnd = useCallback(\n      (e: React.TouchEvent<HTMLDivElement>) => {\n        dispatch(externalEventAction({ handler: onTouchEnd, reactEvent: e }));\n      },\n      [dispatch, onTouchEnd],\n    );\n\n    const WrapperDiv = getWrapperDivComponent(responsive);\n\n    return (\n      <TooltipPortalContext.Provider value={tooltipPortal}>\n        <LegendPortalContext.Provider value={legendPortal}>\n          <WrapperDiv\n            width={width ?? style?.width}\n            height={height ?? style?.height}\n            className={clsx('recharts-wrapper', className)}\n            style={{\n              position: 'relative',\n              cursor: 'default',\n              width,\n              height,\n              ...style,\n            }}\n            onClick={myOnClick}\n            onContextMenu={myOnContextMenu}\n            onDoubleClick={myOnDoubleClick}\n            onFocus={onFocus}\n            onBlur={onBlur}\n            onKeyDown={onKeyDown}\n            onMouseDown={myOnMouseDown}\n            onMouseEnter={myOnMouseEnter}\n            onMouseLeave={myOnMouseLeave}\n            onMouseMove={myOnMouseMove}\n            onMouseUp={myOnMouseUp}\n            onTouchEnd={myOnTouchEnd}\n            onTouchMove={myOnTouchMove}\n            onTouchStart={myOnTouchStart}\n            ref={innerRef}\n          >\n            <EventSynchronizer />\n            {children}\n          </WrapperDiv>\n        </LegendPortalContext.Provider>\n      </TooltipPortalContext.Provider>\n    );\n  },\n);\n","import { useEffect, useState } from 'react';\nimport { useAppDispatch, useAppSelector } from '../state/hooks';\nimport { selectContainerScale } from '../state/selectors/containerSelectors';\nimport { setScale } from '../state/layoutSlice';\nimport { isWellBehavedNumber } from './isWellBehavedNumber';\n\nexport function useReportScale() {\n  const dispatch = useAppDispatch();\n  const [ref, setRef] = useState<HTMLElement | null>(null);\n  const scale = useAppSelector(selectContainerScale);\n  useEffect(() => {\n    if (ref == null) {\n      return;\n    }\n    const rect = ref.getBoundingClientRect();\n    const newScale = rect.width / ref.offsetWidth;\n    if (isWellBehavedNumber(newScale) && newScale !== scale) {\n      dispatch(setScale(newScale));\n    }\n  }, [ref, dispatch, scale]);\n  return setRef;\n}\n","import * as React from 'react';\nimport { forwardRef } from 'react';\nimport { RootSurface } from '../container/RootSurface';\nimport { RechartsWrapper } from './RechartsWrapper';\nimport { ClipPathProvider } from '../container/ClipPathProvider';\nimport { CartesianChartProps } from '../util/types';\nimport { svgPropertiesNoEvents } from '../util/svgPropertiesNoEvents';\nimport { ReportChartSize } from '../context/chartLayoutContext';\n\nexport const CategoricalChart = forwardRef<SVGSVGElement, CartesianChartProps>((props: CartesianChartProps, ref) => {\n  const { width, height, responsive, children, className, style, compact, title, desc, ...others } = props;\n  const attrs = svgPropertiesNoEvents(others);\n\n  /*\n   * The \"compact\" mode is used as the panorama within Brush.\n   * However because `compact` is a public prop, let's assume that it can render outside of Brush too.\n   */\n  if (compact) {\n    return (\n      <>\n        <ReportChartSize width={width} height={height} />\n        <RootSurface otherAttributes={attrs} title={title} desc={desc}>\n          {children}\n        </RootSurface>\n      </>\n    );\n  }\n\n  return (\n    <RechartsWrapper\n      className={className}\n      style={style}\n      width={width}\n      height={height}\n      responsive={responsive ?? false}\n      onClick={props.onClick}\n      onMouseLeave={props.onMouseLeave}\n      onMouseEnter={props.onMouseEnter}\n      onMouseMove={props.onMouseMove}\n      onMouseDown={props.onMouseDown}\n      onMouseUp={props.onMouseUp}\n      onContextMenu={props.onContextMenu}\n      onDoubleClick={props.onDoubleClick}\n      onTouchStart={props.onTouchStart}\n      onTouchMove={props.onTouchMove}\n      onTouchEnd={props.onTouchEnd}\n    >\n      <RootSurface otherAttributes={attrs} title={title} desc={desc} ref={ref}>\n        <ClipPathProvider>{children}</ClipPathProvider>\n      </RootSurface>\n    </RechartsWrapper>\n  );\n});\n","import * as React from 'react';\nimport { forwardRef } from 'react';\nimport { ChartOptions } from '../state/optionsSlice';\nimport { RechartsStoreProvider } from '../state/RechartsStoreProvider';\nimport { ChartDataContextProvider } from '../context/chartDataContext';\nimport { ReportMainChartProp