e,\n    validateTooltipEventTypes,\n    tooltipPayloadSearcher,\n    eventEmitter: undefined,\n  };\n\n  return (\n    <RechartsStoreProvider preloadedState={{ options }} reduxStoreName={categoricalChartProps.id ?? chartName}>\n      <ChartDataContextProvider chartData={categoricalChartProps.data} />\n      <ReportMainChartProps layout={rootChartProps.layout} margin={rootChartProps.margin} />\n      <ReportEventSettings\n        throttleDelay={rootChartProps.throttleDelay}\n        throttledEvents={rootChartProps.throttledEvents}\n      />\n      <ReportChartProps\n        baseValue={rootChartProps.baseValue}\n        accessibilityLayer={rootChartProps.accessibilityLayer}\n        barCategoryGap={rootChartProps.barCategoryGap}\n        maxBarSize={rootChartProps.maxBarSize}\n        stackOffset={rootChartProps.stackOffset}\n        barGap={rootChartProps.barGap}\n        barSize={rootChartProps.barSize}\n        syncId={rootChartProps.syncId}\n        syncMethod={rootChartProps.syncMethod}\n        className={rootChartProps.className}\n        reverseStackOrder={rootChartProps.reverseStackOrder}\n      />\n      <CategoricalChart {...rootChartProps} ref={ref} />\n    </RechartsStoreProvider>\n  );\n});\n","import * as React from 'react';\nimport { forwardRef } from 'react';\nimport { arrayTooltipSearcher } from '../state/optionsSlice';\nimport { CartesianChart } from './CartesianChart';\nimport { CartesianChartProps, TooltipEventType } from '../util/types';\n\nconst allowedTooltipTypes: ReadonlyArray<TooltipEventType> = ['axis'];\n\n/**\n * @consumes ResponsiveContainerContext\n * @provides CartesianViewBoxContext\n * @provides CartesianChartContext\n */\nexport const LineChart = forwardRef<SVGSVGElement, CartesianChartProps<unknown>>(\n  (props: CartesianChartProps<unknown>, ref) => {\n    return (\n      <CartesianChart\n        chartName=\"LineChart\"\n        defaultTooltipEventType=\"axis\"\n        validateTooltipEventTypes={allowedTooltipTypes}\n        toolt