getValueByDataKey(payload.source, nameKey, '');\n    // @ts-expect-error we're sending number indexes as source and target, but getValueByDataKey expects objects\n    const targetName = getValueByDataKey(payload.target, nameKey, '');\n\n    return {\n      payload,\n      name: `${sourceName} - ${targetName}`,\n      value: getValueByDataKey(payload, 'value'),\n    };\n  }\n\n  return undefined;\n};\n\nexport const sankeyPayloadSearcher: TooltipPayloadSearcher = (\n  _: unknown,\n  activeIndex: TooltipIndex,\n  computedData?: unknown,\n  nameKey?,\n): SankeyTooltipPayload | undefined => {\n  if (activeIndex == null || typeof activeIndex !== 'string') {\n    return undefined;\n  }\n  if (computedData == null || typeof computedData !== 'object') {\n    return undefined;\n  }\n  const splitIndex = activeIndex.split('-');\n  const [targetType, index] = splitIndex;\n  const item = get(computedData, `${targetType}s[${index}]`);\n  if (item) {\n    // @ts-expect-error nameKey type does not match SankeyElementType\n    const payload = getPayloadOfTooltip(item, targetType as SankeyElementType, nameKey);\n    return payload;\n  }\n  return undefined;\n};\n\nconst options: ChartOptions = {\n  chartName: 'Sankey',\n  defaultTooltipEventType: 'item',\n  validateTooltipEventTypes: ['item'],\n  tooltipPayloadSearcher: sankeyPayloadSearcher,\n  eventEmitter: undefined,\n};\n\nconst SetSankeyTooltipEntrySettings = React.memo(\n  ({\n    dataKey,\n    nameKey,\n    stroke,\n    strokeWidth,\n    fill,\n    name,\n    data,\n    id,\n  }: Pick<InternalSankeyProps, 'dataKey' | 'nameKey' | 'stroke' | 'strokeWidth' | 'fill' | 'name' | 'data' | 'id'>) => {\n    const tooltipEntrySettings: TooltipPayloadConfiguration = {\n      dataDefinedOnItem: data,\n      getPosition: noop,\n      settings: {\n        stroke,\n        strokeWidth,\n        fill,\n        dataKey,\n        name,\n        nameKey,\n        hide: false,\n        type: undefined,\n        color: fill,\n        unit: '',\n        graphicalItemId: id,\n      },\n    };\n    return <SetTooltipEntrySettings tooltipEntrySettings={tooltipEntrySettings} />;\n  },\n);\n\ninterface LinkDataItem {\n  source: number;\n  target: number;\n  value: number;\n}\n\nexport interface NodeProps extends Omit<SVGProps<SVGRectElement>, 'height' | 'width'> {\n  height: number;\n  width: number;\n  payload: SankeyNode;\n  index: number;\n  x: number;\n  y: number;\n}\n\nexport interface LinkProps extends SVGProps<SVGPathElement> {\n  sourceX: number;\n  targetX: number;\n  sourceY: number;\n  targetY: number;\n  sourceControlX: number;\n  targetControlX: number;\n  sourceRelativeY: number;\n  targetRelativeY: number;\n  linkWidth: number;\n  index: number;\n  // payload is SankeyLink except source and target are now Node objects instead of numbers\n  payload: Omit<SankeyLink, 'source' | 'target'> & { source: SankeyNode; target: SankeyNode };\n}\n\nexport interface SankeyData {\n  nodes: any[];\n  links: LinkDataItem[];\n}\n\n// TODO: improve types - NodeOptions uses SankeyNode, LinkOptions uses LinkProps. Standardize.\nexport type SankeyNodeOptions =\n  | ReactElement<SVGProps<SVGRectElement>>\n  | ((props: NodeProps) => ReactNode)\n  | RectangleProps;\n\ntype SankeyLinkOptions =\n  | ReactElement<SVGProps<SVGPathElement>>\n  | ((props: LinkProps) => ReactElement<SVGProps<SVGPathElement>>)\n  | SVGProps<SVGPathElement>;\n\ninterface SankeyProps extends EventThrottlingProps {\n  /**\n   * Name represents each sector in the tooltip.\n   * This allows you to extract the name from the data:\n   *\n   * - `string`: the name of the field in the data object;\n   * - `number`: the index of the field in the data;\n   * - `function`: a function that receives the data object and returns the name.\n   *\n   * @defaultValue name\n   */\n  nameKey?: DataKey<any>;\n  /**\n   * dataKey prop in Sankey defines which key in the link objects represents the value of the link _in Tooltip only_.\n   *\n   * Unlike other charts where dataKey is used to extract values from the data array, in Sankey charts,\n   * the value of each link is directly taken from the 'value' property of the link objects.\n   *\n   * @default 'value'\n   */\n  dataKey?: DataKey<any>;\n  /**\n   * The width of chart container.\n   * Can be a number or a percent string like \"100%\".\n   *\n   * @see {@link https://recharts.github.io/en-US/guide/sizes/ Chart sizing guide}\n   */\n  width?: number | Percent;\n  /**\n   * The height of chart container.\n   * Can be a number or a percent string like \"100%\".\n   *\n   * @see {@link https://recharts.github.io/en-US/guide/sizes/ Chart sizing guide}\n   */\n  height?: number | Percent;\n  /**\n   * The source data, including the array of nodes, and the relationships, represented by links.\n   *\n   * Note that Sankey requires a specific data structure.\n   * Each node should have a unique index in the nodes array, and each link should reference these nodes by their indices.\n   * This is different from other chart types in Recharts, which accept arbitrary data.\n   *\n   * @example\n   * nodes: [\n   *   { name: 'Visit' },\n   *   { name: 'Direct-Favourite' },\n   *   { name: 'Page-Click' },\n   *   { name: 'Detail-Favourite' },\n   *   { name: 'Lost' },\n   * ],\n   * links: [\n   *   { source: 0, target: 1, value: 3728.3 },\n   *   { source: 0, target: 2, value: 354170 },\n   *   { source: 2, target: 3, value: 62429 },\n   *   { source: 2, target: 4, value: 291741 },\n   * ],\n   */\n  data: SankeyData;\n  /**\n   * The padding between the nodes\n   * @default 10\n   */\n  nodePadding?: number;\n  /**\n   * The width of node\n   * @default 10\n   */\n  nodeWidth?: number;\n  /**\n   * The curvature of width\n   * @default 0.5\n   */\n  linkCurvature?: number;\n  /**\n   * The number of the iterations between the links\n   * @default 32\n   */\n  iterations?: number;\n  /**\n   * If set an object, the option is the configuration of nodes.\n   * If set a React element, the option is the custom react element of drawing the nodes.\n   *\n   * @example <Sankey node={MyCustomComponent} />\n   * @example <Sankey node={{stroke: #77c878, strokeWidth: 2}} />\n   */\n  node?: SankeyNodeOptions;\n  /**\n   * If set an object, the option is the configuration of links.\n   * If set a React element, the option is the custom react element of drawing the links.\n   *\n   * @example <Sankey link={MyCustomComponent} />\n   * @example <Sankey link={{ fill: #77c878 }} />\n   */\n  link?: SankeyLinkOptions;\n  style?: React.CSSProperties;\n  className?: string;\n  children?: ReactNode;\n  /**\n   * Empty space around the container.\n   *\n   * @defaultValue {\"top\":5,\"right\":5,\"bottom\":5,\"left\":5}\n   */\n  margin?: Partial<Margin>;\n  /**\n   * The customized event handler of click on the area in this group\n   */\n  onClick?: (item: NodeProps | LinkProps, type: SankeyElementType, e: MouseEvent<SVGGraphicsElement>) => void;\n  /**\n   * The customized event handler of mouseenter on the area in this group\n   */\n  onMouseEnter?: (item: NodeProps | LinkProps, type: SankeyElementType, e: MouseEvent<SVGGraphicsElement>) => void;\n  /**\n   * The customized event handler of mouseleave on the area in this group\n   */\n  onMouseLeave?: (item: NodeProps | LinkProps, type: SankeyElementType, e: MouseEvent<SVGGraphicsElement>) => void;\n  /**\n   * Whether to sort the nodes on the y axis, or to display them as user-defined.\n   * @default true\n   */\n  sort?: boolean;\n  /**\n   * Controls the vertical spacing of nodes within a depth. 'justify' distributes nodes evenly and balances link paths, while 'top' positions the group starting from the top edge of the chart.\n   * @default 'justify'\n   */\n  verticalAlign?: SankeyVerticalAlign;\n  /**\n   * If set to 'justify', the start nodes will be aligned to the left edge of the chart and the end nodes will be aligned to the right edge of the chart. If set to 'left', the start nodes will be aligned to the left edge of the chart.\n   * @default 'justify'\n   */\n  align?: 'left' | 'justify';\n}\n\nexport type Props = Omit<SVGProps<SVGSVGElement>, keyof SankeyProps> & SankeyProps;\n\nexport type SankeyElementType = 'node' | 'link';\n\nfunction renderLinkItem(option: SankeyLinkOptions | undefined, props: LinkProps) {\n  if (React.isValidElement(option)) {\n    return React.cloneElement(option, props);\n  }\n  if (typeof option === 'function') {\n    return option(props);\n  }\n\n  const { sourceX, sourceY, sourceControlX, targetX, targetY, targetControlX, linkWidth, ...others } = props;\n\n  return (\n    <path\n      className=\"recharts-sankey-link\"\n      d={`\n          M${sourceX},${sourceY}\n          C${sourceControlX},${sourceY} ${targetControlX},${targetY} ${targetX},${targetY}\n        `}\n      fill=\"none\"\n      stroke=\"#333\"\n      strokeWidth={linkWidth}\n      strokeOpacity=\"0.2\"\n      {...svgPropertiesNoEvents(others)}\n    />\n  );\n}\n\nconst buildLinkProps = ({\n  link,\n  nodes,\n  left,\n  top,\n  i,\n  linkContent,\n  linkCurvature,\n}: {\n  link: SankeyLink;\n  nodes: ReadonlyArray<SankeyNode>;\n  top: number;\n  left: number;\n  linkContent: SankeyLinkOptions | undefined;\n  i: number;\n  linkCurvature: number;\n}): LinkProps | undefined => {\n  const { sy: sourceRelativeY, ty: targetRelativeY, dy: linkWidth } = link;\n  const sourceNode = nodes[link.source];\n  const targetNode = nodes[link.target];\n  if (sourceNode == null || targetNode == null) {\n    return undefined;\n  }\n  const sourceX = sourceNode.x + sourceNode.dx + left;\n  const targetX = targetNode.x + left;\n  const interpolationFunc = interpolationGenerator(sourceX, targetX);\n  const sourceControlX = interpolationFunc(linkCurvature);\n  const targetControlX = interpolationFunc(1 - linkCurvature);\n  const sourceY = sourceNode.y + sourceRelativeY + linkWidth / 2 + top;\n  const targetY = targetNode.y + targetRelativeY + linkWidth / 2 + top;\n\n  const linkProps: LinkProps = {\n    sourceX,\n    // @ts-expect-error the linkContent from below is contributing unknown props\n    targetX,\n    sourceY,\n    // @ts-expect-error the linkContent from below is contributing unknown props\n    targetY,\n    sourceControlX,\n    targetControlX,\n    sourceRelativeY,\n    targetRelativeY,\n    linkWidth,\n    index: i,\n    payload: { ...link, source: sourceNode, target: targetNode },\n    ...svgPropertiesNoEventsFromUnknown(linkContent),\n  };\n\n  return linkProps;\n};\n\nfunction SankeyLinkElement({\n  graphicalItemId,\n  props,\n  i,\n  linkContent,\n  onMouseEnter,\n  onMouseLeave,\n  onClick,\n  dataKey,\n}: {\n  graphicalItemId: GraphicalItemId;\n  props: LinkProps;\n  i: number;\n  linkContent: SankeyLinkOptions | undefined;\n  onMouseEnter: (linkProps: LinkProps, e: MouseEvent<SVGGraphicsElement>) => void;\n  onMouseLeave: (linkProps: LinkProps, e: MouseEvent<SVGGraphicsElement>) => void;\n  onClick: (linkProps: LinkProps, e: MouseEvent<SVGGraphicsElement>) => void;\n  dataKey: DataKey<any>;\n}) {\n  const activeCoordinate = getLinkCoordinateOfTooltip(props);\n  const activeIndex = `link-${i}`;\n\n  const dispatch = useAppDispatch();\n\n  const events = {\n    onMouseEnter: (e: MouseEvent<SVGGraphicsElement>) => {\n      dispatch(\n        setActiveMouseOverItemIndex({\n          activeIndex,\n          activeDataKey: dataKey,\n          activeCoordinate,\n          activeGraphicalItemId: graphicalItemId,\n        }),\n      );\n      onMouseEnter(props, e);\n    },\n    onMouseLeave: (e: MouseEvent<SVGGraphicsElement>) => {\n      dispatch(mouseLeaveItem());\n      onMouseLeave(props, e);\n    },\n    onClick: (e: MouseEvent<SVGGraphicsElement>) => {\n      dispatch(\n        setActiveClickItemIndex({\n          activeIndex,\n          activeDataKey: dataKey,\n          activeCoordinate,\n          activeGraphicalItemId: graphicalItemId,\n        }),\n      );\n      onClick(props, e);\n    },\n  };\n\n  return <Layer {...events}>{renderLinkItem(linkContent, props)}</Layer>;\n}\n\nfunction AllSankeyLinkElements({\n  graphicalItemId,\n  modifiedLinks,\n  links,\n  linkContent,\n  onMouseEnter,\n  onMouseLeave,\n  onClick,\n  dataKey,\n}: {\n  graphicalItemId: GraphicalItemId;\n  modifiedLinks: ReadonlyArray<LinkProps>;\n  links: ReadonlyArray<SankeyLink>;\n  linkContent: SankeyLinkOptions | undefined;\n  onMouseEnter: (linkProps: LinkProps, e: MouseEvent<SVGGraphicsElement>) => void;\n  onMouseLeave: (linkProps: LinkProps, e: MouseEvent<SVGGraphicsElement>) => void;\n  onClick: (linkProps: LinkProps, e: MouseEvent<SVGGraphicsElement>) => void;\n  dataKey: DataKey<any>;\n}) {\n  return (\n    <Layer className=\"recharts-sankey-links\" key=\"recharts-sankey-links\">\n      {links.map((link: SankeyLink, i: number) => {\n        const linkProps = modifiedLinks[i];\n        if (linkProps == null) {\n          return null;\n        }\n        return (\n          <SankeyLinkElement\n            graphicalItemId={graphicalItemId}\n            key={`link-${link.source}-${link.target}-${link.value}`}\n            props={linkProps}\n            linkContent={linkContent}\n            i={i}\n            onMouseEnter={onMouseEnter}\n            onMouseLeave={onMouseLeave}\n            onClick={onClick}\n            dataKey={dataKey}\n          />\n        );\n      })}\n    </Layer>\n  );\n}\n\nfunction renderNodeItem(option: SankeyNodeOptions | undefined, props: NodeProps) {\n  if (React.isValidElement(option)) {\n    return React.cloneElement(option, props);\n  }\n  if (typeof option === 'function') {\n    return option(props);\n  }\n\n  return (\n    // @ts-expect-error recharts radius is not compatible with SVG radius\n    <Rectangle className=\"recharts-sankey-node\" fill=\"#0088fe\" fillOpacity=\"0.8\" {...svgPropertiesNoEvents(props)} />\n  );\n}\n\nconst buildNodeProps = ({\n  node,\n  nodeContent,\n  top,\n  left,\n  i,\n}: {\n  node: SankeyNode;\n  nodeContent: SankeyNodeOptions | undefined;\n  top: number;\n  left: number;\n  i: number;\n}) => {\n  const { x, y, dx, dy } = node;\n  // @ts-expect-error nodeContent is passing in unknown props\n  const nodeProps: NodeProps = {\n    ...svgPropertiesNoEventsFromUnknown(nodeContent),\n    x: x + left,\n    y: y + top,\n    width: dx,\n    height: dy,\n    index: i,\n    payload: node,\n  };\n  return nodeProps;\n};\n\nfunction NodeElement({\n  graphicalItemId,\n  props,\n  nodeContent,\n  i,\n  onMouseEnter,\n  onMouseLeave,\n  onClick,\n  dataKey,\n}: {\n  graphicalItemId: GraphicalItemId;\n  props: NodeProps;\n  nodeContent: SankeyNodeOptions | undefined;\n  i: number;\n  onMouseEnter: (nodeProps: NodeProps, e: MouseEvent<SVGGraphicsElement>) => void;\n  onMouseLeave: (nodeProps: NodeProps, e: MouseEvent<SVGGraphicsElement>) => void;\n  onClick: (nodeProps: NodeProps, e: MouseEvent<SVGGraphicsElement>) => void;\n  dataKey: DataKey<any>;\n}) {\n  const dispatch = useAppDispatch();\n\n  const activeCoordinate = getNodeCoordinateOfTooltip(props);\n  const activeIndex = `node-${i}`;\n\n  const events = {\n    onMouseEnter: (e: MouseEvent<SVGGraphicsElement>) => {\n      dispatch(\n        setActiveMouseOverItemIndex({\n          activeIndex,\n          activeDataKey: dataKey,\n          activeCoordinate,\n          activeGraphicalItemId: graphicalItemId,\n        }),\n      );\n      onMouseEnter(props, e);\n    },\n    onMouseLeave: (e: MouseEvent<SVGGraphicsElement>) => {\n      dispatch(mouseLeaveItem());\n      onMouseLeave(props, e);\n    },\n    onClick: (e: MouseEvent<SVGGraphicsElement>) => {\n      dispatch(\n        setActiveClickItemIndex({\n          activeIndex,\n          activeDataKey: dataKey,\n          activeCoordinate,\n          activeGraphicalItemId: graphicalItemId,\n        }),\n      );\n      onClick(props, e);\n    },\n  };\n\n  return <Layer {...events}>{renderNodeItem(nodeContent, props)}</Layer>;\n}\n\nfunction AllNodeElements({\n  graphicalItemId,\n  modifiedNodes,\n  nodeContent,\n  onMouseEnter,\n  onMouseLeave,\n  onClick,\n  dataKey,\n}: {\n  graphicalItemId: GraphicalItemId;\n  modifiedNodes: ReadonlyArray<NodeProps>;\n  nodeContent: SankeyNodeOptions | undefined;\n  onMouseEnter: (nodeProps: NodeProps, e: MouseEvent<SVGGraphicsElement>) => void;\n  onMouseLeave: (nodeProps: NodeProps, e: MouseEvent<SVGGraphicsElement>) => void;\n  onClick: (nodeProps: NodeProps, e: MouseEvent<SVGGraphicsElement>) => void;\n  dataKey: DataKey<any>;\n}) {\n  return (\n    <Layer className=\"recharts-sankey-nodes\" key=\"recharts-sankey-nodes\">\n      {modifiedNodes.map((modifiedNode, i) => {\n        return (\n          <NodeElement\n            graphicalItemId={graphicalItemId}\n            key={`node-${modifiedNode.index}-${modifiedNode.x}-${modifiedNode.y}`}\n            props={modifiedNode}\n            nodeContent={nodeContent}\n            i={i}\n            onMouseEnter={onMouseEnter}\n            onMouseLeave={onMouseLeave}\n            onClick={onClick}\n            dataKey={dataKey}\n          />\n        );\n      })}\n    </Layer>\n  );\n}\n\nexport const sankeyDefaultProps = {\n  align: 'justify',\n  dataKey: 'value',\n  iterations: 32,\n  linkCurvature: 0.5,\n  margin: { top: 5, right: 5, bottom: 5, left: 5 },\n  nameKey: 'name',\n  nodePadding: 10,\n  nodeWidth: 10,\n  sort: true,\n  verticalAlign: 'justify',\n  ...initialEventSettingsState,\n} as const satisfies Partial<Props>;\n\ntype PropsWithResolvedDefaults = RequiresDefaultProps<Props, typeof sankeyDefaultProps>;\n\ntype InternalSankeyProps = WithIdRequired<PropsWithResolvedDefaults>;\n\nfunction SankeyImpl(props: InternalSankeyProps) {\n  const { className, style, children, id, ...others } = props;\n  const {\n    link,\n    dataKey,\n    node,\n    onMouseEnter,\n    onMouseLeave,\n    onClick,\n    data,\n    iterations,\n    nodeWidth,\n    nodePadding,\n    sort,\n    linkCurvature,\n    margin,\n    verticalAlign,\n    align,\n  } = props;\n\n  const attrs = svgPropertiesNoEvents(others);\n\n  const width = useChartWidth();\n  const height = useChartHeight();\n\n  const { links, modifiedLinks, modifiedNodes } = useMemo(() => {\n    if (!data || !width || !height || width <= 0 || height <= 0) {\n      return { nodes: [], links: [], modifiedLinks: [], modifiedNodes: [] };\n    }\n    const contentWidth = width - (margin.left ?? 0) - (margin.right ?? 0);\n    const contentHeight = height - (margin.top ?? 0) - (margin.bottom ?? 0);\n    const computed = computeData({\n      data,\n      width: contentWidth,\n      height: contentHeight,\n      iterations,\n      nodeWidth,\n      nodePadding,\n      sort,\n      verticalAlign,\n      align,\n    });\n\n    const top = margin.top || 0;\n    const left = margin.left || 0;\n    const newModifiedLinks = computed.links\n      .map((l, i) => {\n        return buildLinkProps({ link: l, nodes: computed.nodes, i, top, left, linkContent: link, linkCurvature });\n      })\n      .filter(isNotNil);\n\n    const newModifiedNodes = computed.nodes.map((n, i) => {\n      return buildNodeProps({\n        node: n,\n        nodeContent: node,\n        i,\n        top,\n        left,\n      });\n    });\n\n    return {\n      nodes: computed.nodes,\n      links: computed.links,\n      modifiedLinks: newModifiedLinks,\n      modifiedNodes: newModifiedNodes,\n    };\n  }, [\n    data,\n    width,\n    height,\n    margin,\n    iterations,\n    nodeWidth,\n    nodePadding,\n    sort,\n    link,\n    node,\n    linkCurvature,\n    align,\n    verticalAlign,\n  ]);\n\n  const handleMouseEnter = useCallback(\n    (item: NodeProps | LinkProps, type: SankeyElementType, e: MouseEvent<SVGGraphicsElement>) => {\n      if (onMouseEnter) {\n        onMouseEnter(item, type, e);\n      }\n    },\n    [onMouseEnter],\n  );\n\n  const handleMouseLeave = useCallback(\n    (item: NodeProps | LinkProps, type: SankeyElementType, e: MouseEvent<SVGGraphicsElement>) => {\n      if (onMouseLeave) {\n        onMouseLeave(item, type, e);\n      }\n    },\n    [onMouseLeave],\n  );\n\n  const handleClick = useCallback(\n    (item: NodeProps | LinkProps, type: SankeyElementType, e: MouseEvent<SVGGraphicsElement>) => {\n      if (onClick) {\n        onClick(item, type, e);\n      }\n    },\n    [onClick],\n  );\n\n  if (!isPositiveNumber(width) || !isPositiveNumber(height) || !data || !data.links || !data.nodes) {\n    return null;\n  }\n\n  return (\n    <>\n      <SetComputedData computedData={{ links: modifiedLinks, nodes: modifiedNodes }} />\n      <Surface {...attrs} width={width} height={height}>\n        {children}\n        <AllSankeyLinkElements\n          graphicalItemId={id}\n          links={links}\n          modifiedLinks={modifiedLinks}\n          linkContent={link}\n          dataKey={dataKey}\n          onMouseEnter={(linkProps: LinkProps, e: MouseEvent<SVGGraphicsElement>) =>\n            handleMouseEnter(linkProps, 'link', e)\n          }\n          onMouseLeave={(linkProps: LinkProps, e: MouseEvent<SVGGraphicsElement>) =>\n            handleMouseLeave(linkProps, 'link', e)\n          }\n          onClick={(linkProps: LinkProps, e: MouseEvent<SVGGraphicsElement>) => handleClick(linkProps, 'link', e)}\n        />\n        <AllNodeElements\n          graphicalItemId={id}\n          modifiedNodes={modifiedNodes}\n          nodeContent={node}\n          dataKey={dataKey}\n          onMouseEnter={(nodeProps: NodeProps, e: MouseEvent<SVGGraphicsElement>) =>\n            handleMouseEnter(nodeProps, 'node', e)\n          }\n          onMouseLeave={(nodeProps: NodeProps, e: MouseEvent<SVGGraphicsElement>) =>\n            handleMouseLeave(nodeProps, 'node', e)\n          }\n          onClick={(nodeProps: NodeProps, e: MouseEvent<SVGGraphicsElement>) => handleClick(nodeProps, 'node', e)}\n        />\n      </Surface>\n    </>\n  );\n}\n\n/**\n * Flow diagram in which the width of the arrows is proportional to the flow rate.\n * It is typically used to visualize energy or material or cost transfers between processes.\n *\n * @consumes ResponsiveContainerContext\n * @provides TooltipEntrySettings\n */\nexport function Sankey(outsideProps: Props) {\n  const props: PropsWithResolvedDefaults = resolveDefaultProps(outsideProps, sankeyDefaultProps);\n  const { width, height, style, className, id: externalId, throttleDelay, throttledEvents } = props;\n  const [tooltipPortal, setTooltipPortal] = useState<HTMLElement | null>(null);\n\n  return (\n    <RechartsStoreProvider preloadedState={{ options }} reduxStoreName={className ?? 'Sankey'}>\n      <ReportChartSize width={width} height={height} />\n      <ReportChartMargin margin={props.margin} />\n      <ReportEventSettings throttleDelay={throttleDelay} throttledEvents={throttledEvents} />\n\n      <RechartsWrapper\n        className={className}\n        style={style}\n        width={width}\n        height={height}\n        /*\n         * Sankey, same as Treemap, suffers from overfilling the container\n         * and causing infinite render loops where the chart keeps growing.\n         */\n        responsive={false}\n        ref={(node: HTMLDivElement | null) => {\n          if (node && !tooltipPortal) {\n            setTooltipPortal(node);\n          }\n        }}\n        onMouseEnter={undefined}\n        onMouseLeave={undefined}\n        onClick={undefined}\n        onMouseMove={undefined}\n        onMouseDown={undefined}\n        onMouseUp={undefined}\n        onContextMenu={undefined}\n        onDoubleClick={undefined}\n        onTouchStart={undefined}\n        onTouchMove={undefined}\n        onTouchEnd={undefined}\n      >\n        <TooltipPortalContext.Provider value={tooltipPortal}>\n          <RegisterGraphicalItemId id={externalId} type=\"sankey\">\n            {id => (\n              <>\n                <SetSankeyTooltipEntrySettings\n                  dataKey={props.dataKey}\n                  nameKey={props.nameKey}\n                  stroke={props.stroke}\n                  strokeWidth={props.strokeWidth}\n                  fill={props.fill}\n                  name={props.name}\n                  data={props.data}\n                  id={id}\n                />\n                <SankeyImpl {...props} id={id} />\n              </>\n            )}\n          </RegisterGraphicalItemId>\n        </TooltipPortalContext.Provider>\n      </RechartsWrapper>\n    </RechartsStoreProvider>\n  );\n}\n\nSankey.displayName = 'Sankey';\n","import * as React from 'react';\nimport { forwardRef } from 'react';\nimport { arrayTooltipSearcher } from '../state/optionsSlice';\nimport { PolarChartProps, PolarLayout, TooltipEventType } from '../util/types';\nimport { resolveDefaultProps } from '../util/resolveDefaultProps';\nimport { defaultPolarChartProps, PolarChart } from './PolarChart';\n\nconst allowedTooltipTypes: ReadonlyArray<TooltipEventType> = ['axis'];\n\nexport const defaultRadarChartProps = {\n  ...defaultPolarChartProps,\n  layout: 'centric',\n  startAngle: 90,\n  endAngle: -270,\n} as const satisfies Partial<PolarChartProps<never>>;\n\ntype RadarChartProps<DataPointType> = Omit<PolarChartProps<DataPointType>, 'layout' | 'startAngle' | 'endAngle'> & {\n  /**\n   * The layout of chart defines the orientation of axes, graphical items, and tooltip.\n   *\n   * @defaultValue centric\n   */\n  layout?: PolarLayout;\n  /**\n   * Angle in degrees from which the chart should start.\n   * @defaultValue 90\n   *\n   */\n  startAngle?: number;\n  /**\n   * Angle, in degrees, at which the chart should end.\n   *\n   * @defaultValue -270\n   */\n  endAngle?: number;\n};\n\n/**\n * @consumes ResponsiveContainerContext\n * @provides PolarViewBoxContext\n * @provides PolarChartContext\n */\nexport const RadarChart = forwardRef<SVGSVGElement, RadarChartProps<unknown>>(\n  (props: RadarChartProps<unknown>, ref) => {\n    const propsWithDefaults = resolveDefaultProps(props, defaultRadarChartProps);\n    return (\n      <PolarChart\n        chartName=\"RadarChart\"\n        defaultTooltipEventType=\"axis\"\n        validateTooltipEventTypes={allowedTooltipTypes}\n        tooltipPayloadSearcher={arrayTooltipSearcher}\n        categoricalChartProps={propsWithDefaults}\n        ref={ref}\n      />\n    );\n  },\n) as <DataPointType = any>(\n  props: PolarChartProps<DataPointType> & { ref?: React.Ref<SVGSVGElement> },\n) => React.ReactElement;\n","import * as React from 'react';\nimport { forwardRef } from 'react';\nimport { arrayTooltipSearcher } from '../state/optionsSlice';\nimport { CartesianChart } from './CartesianChart';\nimport { CartesianChartProps, TooltipEventType } from '../util/types';\n\nconst allowedTooltipTypes: ReadonlyArray<TooltipEventType> = ['item'];\n\n/**\n * @consumes ResponsiveContainerContext\n * @provides CartesianViewBoxContext\n * @provides CartesianChartContext\n */\nexport const ScatterChart = forwardRef<SVGSVGElement, CartesianChartProps<unknown>>(\n  (props: CartesianChartProps<unknown>, ref) => {\n    return (\n      <CartesianChart\n        chartName=\"ScatterChart\"\n        defaultTooltipEventType=\"item\"\n        validateTooltipEventTypes={allowedTooltipTypes}\n        tooltipPayloadSearcher={arrayTooltipSearcher}\n        categoricalChartProps={props}\n        ref={ref}\n      />\n    );\n  },\n) as <DataPointType = any>(\n  props: CartesianChartProps<DataPointType> & { ref?: React.Ref<SVGSVGElement> },\n) => React.ReactElement;\n","import * as React from 'react';\nimport { forwardRef } from 'react';\nimport { arrayTooltipSearcher } from '../state/optionsSlice';\nimport { CartesianChart } from './CartesianChart';\nimport { CartesianChartProps, TooltipEventType } from '../util/types';\n\nconst allowedTooltipTypes: ReadonlyArray<TooltipEventType> = ['axis'];\n\n/**\n * @consumes ResponsiveContainerContext\n * @provides CartesianViewBoxContext\n * @provides CartesianChartContext\n */\nexport const AreaChart = forwardRef<SVGSVGElement, CartesianChartProps<unknown>>(\n  (props: CartesianChartProps<unknown>, ref) => {\n    return (\n      <CartesianChart\n        chartName=\"AreaChart\"\n        defaultTooltipEventType=\"axis\"\n        validateTooltipEventTypes={allowedTooltipTypes}\n        tooltipPayloadSearcher={arrayTooltipSearcher}\n        categoricalChartProps={props}\n        ref={ref}\n      />\n    );\n  },\n) as <DataPointType = any>(\n  props: CartesianChartProps<DataPointType> & { ref?: React.Ref<SVGSVGElement> },\n) => React.ReactElement;\n","import * as React from 'react';\nimport { forwardRef } from 'react';\nimport { arrayTooltipSearcher } from '../state/optionsSlice';\nimport { PolarChartProps, TooltipEventType } from '../util/types';\nimport { resolveDefaultProps } from '../util/resolveDefaultProps';\nimport { defaultPolarChartProps, PolarChart } from './PolarChart';\n\nconst allowedTooltipTypes: ReadonlyArray<TooltipEventType> = ['axis', 'item'];\n\nexport const defaultRadialBarChartProps = {\n  ...defaultPolarChartProps,\n  layout: 'radial',\n  startAngle: 0,\n  endAngle: 360,\n} as const satisfies Partial<PolarChartProps<never>>;\n\n/**\n * @consumes ResponsiveContainerContext\n * @provides PolarViewBoxContext\n * @provides PolarChartContext\n */\nexport const RadialBarChart = forwardRef<SVGSVGElement, PolarChartProps<unknown>>(\n  (props: PolarChartProps<unknown>, ref) => {\n    const propsWithDefaults = resolveDefaultProps(props, defaultRadialBarChartProps);\n    return (\n      <PolarChart\n        chartName=\"RadialBarChart\"\n        defaultTooltipEventType=\"axis\"\n        validateTooltipEventTypes={allowedTooltipTypes}\n        tooltipPayloadSearcher={arrayTooltipSearcher}\n        categoricalChartProps={propsWithDefaults}\n        ref={ref}\n      />\n    );\n  },\n) as <DataPointType = any>(\n  props: PolarChartProps<DataPointType> & { ref?: React.Ref<SVGSVGElement> },\n) => React.ReactElement;\n","import * as React from 'react';\nimport { forwardRef } from 'react';\nimport { arrayTooltipSearcher } from '../state/optionsSlice';\nimport { CartesianChart } from './CartesianChart';\nimport { CartesianChartProps, TooltipEventType } from '../util/types';\n\nconst allowedTooltipTypes: ReadonlyArray<TooltipEventType> = ['axis'];\n\n/**\n * @consumes ResponsiveContainerContext\n * @provides CartesianViewBoxContext\n * @provides CartesianChartContext\n */\nexport const ComposedChart = forwardRef<SVGSVGElement, CartesianChartProps<unknown>>(\n  (props: CartesianChartProps<unknown>, ref) => {\n    return (\n      <CartesianChart\n        chartName=\"ComposedChart\"\n        defaultTooltipEventType=\"axis\"\n        validateTooltipEventTypes={allowedTooltipTypes}\n        tooltipPayloadSearcher={arrayTooltipSearcher}\n        categoricalChartProps={props}\n        ref={ref}\n      />\n    );\n  },\n) as <DataPointType = any>(\n  props: CartesianChartProps<DataPointType> & { ref?: React.Ref<SVGSVGElement> },\n) => React.ReactElement;\n","import * as React from 'react';\nimport { CSSProperties, useState } from 'react';\nimport { scaleLinear } from 'victory-vendor/d3-scale';\nimport { clsx } from 'clsx';\nimport get from 'es-toolkit/compat/get';\nimport { Surface } from '../container/Surface';\nimport { Layer } from '../container/Layer';\nimport { Sector } from '../shape/Sector';\nimport { Text, Props as TextProps } from '../component/Text';\nimport { polarToCartesian } from '../util/PolarUtils';\nimport { ReportChartMargin, ReportChartSize, useChartHeight, useChartWidth } from '../context/chartLayoutContext';\nimport { TooltipPortalContext } from '../context/tooltipPortalContext';\nimport { RechartsWrapper } from './RechartsWrapper';\nimport {\n  mouseLeaveItem,\n  setActiveClickItemIndex,\n  setActiveMouseOverItemIndex,\n  TooltipIndex,\n  TooltipPayloadConfiguration,\n  TooltipPayloadSearcher,\n} from '../state/tooltipSlice';\nimport { SetTooltipEntrySettings } from '../state/SetTooltipEntrySettings';\nimport { RechartsStoreProvider } from '../state/RechartsStoreProvider';\nimport { ReportEventSettings } from '../state/ReportEventSettings';\nimport { ChartCoordinate, DataKey, EventThrottlingProps, Margin, Percent } from '../util/types';\nimport { useAppDispatch } from '../state/hooks';\nimport { RechartsRootState } from '../state/store';\nimport { RegisterGraphicalItemId } from '../context/RegisterGraphicalItemId';\nimport { WithIdRequired } from '../util/useUniqueId';\nimport { RequiresDefaultProps, resolveDefaultProps } from '../util/resolveDefaultProps';\nimport { initialEventSettingsState } from '../state/eventSettingsSlice';\n\nexport interface SunburstData {\n  [key: string]: any;\n  name: string;\n  value?: number;\n  fill?: string;\n  tooltipIndex?: TooltipIndex;\n  children?: SunburstData[];\n}\n\n/**\n * We require tooltipIndex on each node internally to track which node is active in the tooltip.\n * This is not required from the outside user - we can calculate it as we traverse the tree.\n */\ninterface SunburstNode extends SunburstData {\n  tooltipIndex: TooltipIndex;\n}\n\nexport interface SunburstChartProps extends EventThrottlingProps {\n  className?: string;\n  /**\n   * The source data. Each element should be an object.\n   * The properties of each object represent the values of different data dimensions.\n   *\n   * Use the `dataKey` prop to specify which properties to use.\n   *\n   * @example data={[{ name: 'a', value: 12, fill: '#8884d8' }, { name: 'b', value: 5, fill: '#83a6ed' }]}\n   */\n  data: SunburstData;\n  /**\n   * The width of chart container.\n   * Can be a number or a percent string like \"100%\".\n   *\n   * @see {@link https://recharts.github.io/en-US/guide/sizes/ Chart sizing guide}\n   */\n  width?: number | Percent;\n  /**\n   * The height of chart container.\n   * Can be a number or a percent string like \"100%\".\n   *\n   * @see {@link https://recharts.github.io/en-US/guide/sizes/ Chart sizing guide}\n   */\n  height?: number | Percent;\n  /**\n   * If true, then it will listen to container size changes and adapt the SVG chart accordingly.\n   * If false, then it renders the chart at the specified width and height and will stay that way\n   * even if the container size changes.\n   *\n   * This is similar to ResponsiveContainer but without the need for an extra wrapper component.\n   * The `responsive` prop also uses standard CSS sizing rules, instead of custom resolution logic (like ResponsiveContainer does).\n   * @default false\n   */\n  responsive?: boolean;\n  /**\n   * Distance between sectors.\n   *\n   * @defaultValue 2\n   */\n  padding?: number;\n  /**\n   * Decides how to extract value from the data.\n   *\n   * @defaultValue value\n   */\n  dataKey?: string;\n  /**\n   * Name represents each sector in the tooltip.\n   * This allows you to extract the name from the data:\n   *\n   * - `string`: the name of the field in the data object;\n   * - `number`: the index of the field in the data;\n   * - `function`: a function that receives the data object and returns the name.\n   *\n   * @defaultValue name\n   */\n  nameKey?: DataKey<any>;\n  /**\n   * Padding between each hierarchical level.\n   */\n  ringPadding?: number;\n  /**\n   * The radius of the inner circle at the center of the chart.\n   *\n   * @defaultValue 50\n   */\n  innerRadius?: number;\n  /**\n   * Outermost edge of the chart.\n   * Defaults to the max possible radius for a circle inscribed in the chart container\n   */\n  outerRadius?: number;\n  /**\n   * The x-coordinate of center in pixels.\n   * If undefined, it will be set to half of the chart width.\n   */\n  cx?: number;\n  /**\n   * The y-coordinate of center in pixels.\n   * If undefined, it will be set to half of the chart height.\n   */\n  cy?: number;\n  /** Angle in degrees from which the chart should start. */\n  startAngle?: number;\n  /** Angle, in degrees, at which the chart should end. */\n  endAngle?: number;\n  children?: React.ReactNode;\n  fill?: string;\n  stroke?: string;\n  /**\n   * An object with svg text options to control the appearance of the chart labels.\n   */\n  textOptions?: TextProps;\n\n  onMouseEnter?: (node: SunburstData, e: React.MouseEvent) => void;\n\n  onMouseLeave?: (node: SunburstData, e: React.MouseEvent) => void;\n\n  onClick?: (node: SunburstData) => void;\n  style?: CSSProperties;\n  id?: string;\n}\n\ninterface DrawArcOptions {\n  radius: number;\n  innerR: number;\n  initialAngle: number;\n  childColor?: string;\n  nestedActiveTooltipIndex?: TooltipIndex | undefined;\n}\n\nconst defaultTextProps = {\n  fontWeight: 'bold',\n  paintOrder: 'stroke fill',\n  fontSize: '.75rem',\n  stroke: '#FFF',\n  fill: 'black',\n  pointerEvents: 'none',\n};\n\nfunction getMaxDepthOf(node: SunburstData): number {\n  if (!node.children || node.children.length === 0) return 1;\n\n  // Calculate depth for each child and find the maximum\n  const childDepths = node.children.map(d => getMaxDepthOf(d));\n  return 1 + Math.max(...childDepths);\n}\n\nconst SetSunburstTooltipEntrySettings = React.memo(\n  ({\n    dataKey,\n    nameKey,\n    data,\n    stroke,\n    fill,\n    positions,\n    id,\n  }: Pick<WithIdRequired<SunburstChartProps>, 'dataKey' | 'data' | 'stroke' | 'fill' | 'nameKey' | 'id'> & {\n    positions: SunburstPositionMap;\n  }) => {\n    const tooltipEntrySettings: TooltipPayloadConfiguration = {\n      dataDefinedOnItem: data.children,\n      getPosition: index => positions.get(index),\n      // Sunburst does not support many of the properties as other charts do so there's plenty of defaults here\n      settings: {\n        stroke,\n        strokeWidth: undefined,\n        fill,\n        nameKey,\n        dataKey,\n        // if there is a nameKey use it, otherwise make the name of the tooltip the dataKey itself\n        name: nameKey ? undefined : dataKey,\n        hide: false,\n        type: undefined,\n        color: fill,\n        unit: '',\n        graphicalItemId: id,\n      },\n    };\n    return <SetTooltipEntrySettings tooltipEntrySettings={tooltipEntrySettings} />;\n  },\n);\n\n// Why is margin not a sunburst prop? No clue. Probably it should be\nconst defaultSunburstMargin: Margin = {\n  top: 0,\n  right: 0,\n  bottom: 0,\n  left: 0,\n};\n\nexport const payloadSearcher: TooltipPayloadSearcher = (data: unknown, activeIndex: TooltipIndex): unknown => {\n  if (activeIndex == null) {\n    return undefined;\n  }\n  return get(data, activeIndex);\n};\n\nconst addToSunburstNodeIndex = (\n  indexInChildrenArr: number,\n  activeTooltipIndexSoFar: TooltipIndex | undefined = '',\n): TooltipIndex => {\n  return `${activeTooltipIndexSoFar}children[${indexInChildrenArr}]`;\n};\n\nconst preloadedState: Partial<RechartsRootState> = {\n  options: {\n    validateTooltipEventTypes: ['item'],\n    defaultTooltipEventType: 'item',\n    chartName: 'Sunburst',\n    tooltipPayloadSearcher: payloadSearcher,\n    eventEmitter: undefined,\n  },\n};\n\ntype SunburstPositionMap = Map<string, ChartCoordinate>;\n\nexport const defaultSunburstChartProps = {\n  padding: 2,\n  dataKey: 'value',\n  nameKey: 'name',\n  ringPadding: 2,\n  innerRadius: 50,\n  fill: '#333',\n  stroke: '#FFF',\n  textOptions: defaultTextProps,\n  startAngle: 0,\n  endAngle: 360,\n  responsive: false,\n  ...initialEventSettingsState,\n} as const satisfies Partial<SunburstChartProps>;\n\ntype InternalSunburstChartProps = WithIdRequired<\n  RequiresDefaultProps<SunburstChartProps, typeof defaultSunburstChartProps>\n>;\n\nconst SunburstChartImpl = ({\n  className,\n  data,\n  children,\n  padding,\n  dataKey,\n  nameKey,\n  ringPadding,\n  innerRadius,\n  fill,\n  stroke,\n  textOptions,\n  outerRadius: outerRadiusFromProps,\n  cx: cxFromProps,\n  cy: cyFromProps,\n  startAngle,\n  endAngle,\n  onClick,\n  onMouseEnter,\n  onMouseLeave,\n  id,\n}: InternalSunburstChartProps) => {\n  const dispatch = useAppDispatch();\n\n  const width = useChartWidth();\n  const height = useChartHeight();\n\n  if (width == null || height == null) {\n    return null;\n  }\n\n  const outerRadius = outerRadiusFromProps ?? Math.min(width, height) / 2;\n  const cx = cxFromProps ?? width / 2;\n  const cy = cyFromProps ?? height / 2;\n\n  const rScale = scaleLinear([0, data[dataKey]], [0, endAngle]);\n  const treeDepth = getMaxDepthOf(data);\n  const thickness = (outerRadius - innerRadius) / treeDepth;\n\n  const sectors: React.ReactNode[] = [];\n  const positions: SunburstPositionMap = new Map<string, ChartCoordinate>([]);\n\n  // event handlers\n  function handleMouseEnter(node: SunburstNode, e: React.MouseEvent) {\n    if (onMouseEnter) onMouseEnter(node, e);\n\n    dispatch(\n      setActiveMouseOverItemIndex({\n        activeIndex: node.tooltipIndex,\n        activeDataKey: dataKey,\n        activeCoordinate: positions.get(node.name),\n        activeGraphicalItemId: id,\n      }),\n    );\n  }\n\n  function handleMouseLeave(node: SunburstNode, e: React.MouseEvent) {\n    if (onMouseLeave) onMouseLeave(node, e);\n\n    dispatch(mouseLeaveItem());\n  }\n\n  function handleClick(node: SunburstNode) {\n    if (onClick) onClick(node);\n\n    dispatch(\n      setActiveClickItemIndex({\n        activeIndex: node.tooltipIndex,\n        activeDataKey: dataKey,\n        activeCoordinate: positions.get(node.name),\n        activeGraphicalItemId: id,\n      }),\n    );\n  }\n\n  // recursively add nodes for each data point and its children\n  function drawArcs(childNodes: SunburstData[] | undefined, options: DrawArcOptions, depth: number = 1): void {\n    const { radius, innerR, initialAngle, childColor, nestedActiveTooltipIndex } = options;\n\n    let currentAngle = initialAngle;\n\n    if (!childNodes) return; // base case: no children of this node\n\n    childNodes.forEach((d, i) => {\n      const currentTooltipIndex = depth === 1 ? `[${i}]` : addToSunburstNodeIndex(i, nestedActiveTooltipIndex);\n      const nodeWithIndex: SunburstNode = { ...d, tooltipIndex: currentTooltipIndex };\n\n      const arcLength = rScale(d[dataKey]);\n      const start = currentAngle;\n      // color priority - if there's a color on the individual point use that, otherwise use parent color or default\n      const fillColor = d?.fill ?? childColor ?? fill;\n      const { x: textX, y: textY } = polarToCartesian(0, 0, innerR + radius / 2, -(start + arcLength - arcLength / 2));\n      currentAngle += arcLength;\n      sectors.push(\n        <g key={`sunburst-sector-${d.name}-${i}`}>\n          <Sector\n            onClick={() => handleClick(nodeWithIndex)}\n            onMouseEnter={e => handleMouseEnter(nodeWithIndex, e)}\n            onMouseLeave={e => handleMouseLeave(nodeWithIndex, e)}\n            fill={fillColor}\n            stroke={stroke}\n            strokeWidth={padding}\n            startAngle={start}\n            endAngle={start + arcLength}\n            innerRadius={innerR}\n            outerRadius={innerR + radius}\n            cx={cx}\n            cy={cy}\n          />\n          <Text {...textOptions} alignmentBaseline=\"middle\" textAnchor=\"middle\" x={textX + cx} y={cy - textY}>\n            {d[dataKey]}\n          </Text>\n        </g>,\n      );\n\n      const { x: tooltipX, y: tooltipY } = polarToCartesian(cx, cy, innerR + radius / 2, start);\n      positions.set(d.name, { x: tooltipX, y: tooltipY });\n\n      return drawArcs(\n        d.children,\n        {\n          radius,\n          innerR: innerR + radius + ringPadding,\n          initialAngle: start,\n          childColor: fillColor,\n          nestedActiveTooltipIndex: currentTooltipIndex,\n        },\n        depth + 1,\n      );\n    });\n  }\n\n  drawArcs(data.children, { radius: thickness, innerR: innerRadius, initialAngle: startAngle });\n\n  const layerClass = clsx('recharts-sunburst', className);\n  return (\n    <Surface width={width} height={height}>\n      <Layer className={layerClass}>{sectors}</Layer>\n      <SetSunburstTooltipEntrySettings\n        dataKey={dataKey}\n        nameKey={nameKey}\n        data={data}\n        stroke={stroke}\n        fill={fill}\n        positions={positions}\n        id={id}\n      />\n      {children}\n    </Surface>\n  );\n};\n\n/**\n * The sunburst is a hierarchical chart, similar to a {@link Treemap}, plotted in polar coordinates.\n * Sunburst charts effectively convey the hierarchical relationships and proportions within each level.\n * It is easy to see all the middle layers in the hierarchy, which might get lost in other visualizations.\n * For some datasets, the radial layout may be more visually appealing and intuitive than a traditional {@link Treemap}.\n *\n * @consumes ResponsiveContainerContext\n * @provides TooltipEntrySettings\n */\nexport const SunburstChart = (outsideProps: SunburstChartProps) => {\n  const props = resolveDefaultProps(outsideProps, defaultSunburstChartProps);\n  const { className, width, height, responsive, style, id: externalId, throttleDelay, throttledEvents } = props;\n  const [tooltipPortal, setTooltipPortal] = useState<HTMLElement | null>(null);\n  return (\n    <RechartsStoreProvider preloadedState={preloadedState} reduxStoreName={className ?? 'SunburstChart'}>\n      <ReportChartSize width={width} height={height} />\n      <ReportChartMargin margin={defaultSunburstMargin} />\n      <ReportEventSettings throttleDelay={throttleDelay} throttledEvents={throttledEvents} />\n      <TooltipPortalContext.Provider value={tooltipPortal}>\n        <RechartsWrapper\n          className={className}\n          width={width}\n          height={height}\n          responsive={responsive}\n          style={style}\n          ref={(node: HTMLDivElement) => {\n            if (tooltipPortal == null && node != null) {\n              setTooltipPortal(node);\n            }\n          }}\n          onMouseEnter={undefined}\n          onMouseLeave={undefined}\n          onClick={undefined}\n          onMouseMove={undefined}\n          onMouseDown={undefined}\n          onMouseUp={undefined}\n          onContextMenu={undefined}\n          onDoubleClick={undefined}\n          onTouchStart={undefined}\n          onTouchMove={undefined}\n          onTouchEnd={undefined}\n        >\n          <RegisterGraphicalItemId id={externalId} type=\"sunburst\">\n            {id => <SunburstChartImpl {...props} id={id} />}\n          </RegisterGraphicalItemId>\n        </RechartsWrapper>\n      </TooltipPortalContext.Provider>\n    </RechartsStoreProvider>\n  );\n};\n","import * as React from 'react';\nimport { Props as FunnelProps, FunnelTrapezoidItem } from '../cartesian/Funnel';\nimport { Shape } from './ActiveShapeUtils';\n\nexport type FunnelTrapezoidProps = { option: FunnelProps['activeShape']; isActive: boolean } & FunnelTrapezoidItem;\n\nexport function FunnelTrapezoid(props: FunnelTrapezoidProps) {\n  return <Shape shapeType=\"trapezoid\" {...props} />;\n}\n","import { createSelector } from 'reselect';\nimport { ReactElement } from 'react';\nimport { computeFunnelTrapezoids, FunnelTrapezoidItem } from '../../cartesian/Funnel';\nimport { ChartData } from '../chartDataSlice';\nimport { RechartsRootState } from '../store';\nimport { selectChartOffsetInternal } from './selectChartOffsetInternal';\nimport { selectChartDataAndAlwaysIgnoreIndexes } from './dataSelectors';\nimport { ChartOffsetInternal, DataKey, TooltipType } from '../../util/types';\nimport { CellProps } from '../..';\nimport { GraphicalItemId } from '../graphicalItemsSlice';\n\nexport type ResolvedFunnelSettings = {\n  dataKey: DataKey<any>;\n  data: ChartData | undefined;\n  nameKey: DataKey<any>;\n  tooltipType?: TooltipType;\n  lastShapeType?: 'triangle' | 'rectangle';\n  reversed?: boolean;\n  customWidth?: string | number;\n  cells: ReadonlyArray<ReactElement>;\n  presentationProps: Record<string, any> | null;\n  id: GraphicalItemId;\n};\n\nconst pickFunnelSettings = (\n  _state: RechartsRootState,\n  funnelSettings: ResolvedFunnelSettings,\n): ResolvedFunnelSettings => funnelSettings;\n\nexport const selectFunnelTrapezoids: (\n  state: RechartsRootState,\n  funnelSettings: ResolvedFunnelSettings,\n) => ReadonlyArray<FunnelTrapezoidItem> = createSelector(\n  [selectChartOffsetInternal, pickFunnelSettings, selectChartDataAndAlwaysIgnoreIndexes],\n  (\n    offset: ChartOffsetInternal,\n    {\n      data,\n      dataKey,\n      nameKey,\n      tooltipType,\n      lastShapeType,\n      reversed,\n      customWidth,\n      cells,\n      presentationProps,\n      id: graphicalItemId,\n    },\n    { chartData },\n  ): ReadonlyArray<FunnelTrapezoidItem> => {\n    let displayedData: ChartData | undefined;\n    if (data != null && data.length > 0) {\n      displayedData = data;\n    } else if (chartData != null && chartData.length > 0) {\n      displayedData = chartData;\n    }\n\n    if (displayedData && displayedData.length) {\n      displayedData = displayedData.map((entry: any, index: number) => ({\n        payload: entry,\n        ...presentationProps,\n        ...entry,\n        ...(cells && cells[index] && cells[index].props),\n      }));\n    } else if (cells && cells.length) {\n      displayedData = cells.map((cell: ReactElement<CellProps>) => ({ ...presentationProps, ...cell.props }));\n    } else {\n      return [];\n    }\n\n    return computeFunnelTrapezoids({\n      dataKey,\n      nameKey,\n      displayedData,\n      tooltipType,\n      lastShapeType,\n      reversed,\n      offset,\n      customWidth,\n      graphicalItemId,\n    });\n  },\n);\n","import * as React from 'react';\nimport { MutableRefObject, ReactElement, ReactNode, useCallback, useMemo, useRef, useState } from 'react';\nimport omit from 'es-toolkit/compat/omit';\n\nimport { clsx } from 'clsx';\nimport { selectActiveIndex } from '../state/selectors/selectors';\nimport { useAppSelector } from '../state/hooks';\nimport { Layer } from '../container/Layer';\nimport { Props as TrapezoidProps } from '../shape/Trapezoid';\nimport {\n  CartesianLabelListContextProvider,\n  CartesianLabelListEntry,\n  ImplicitLabelListType,\n  LabelListFromLabelProp,\n} from '../component/LabelList';\nimport { getPercentValue, interpolate } from '../util/DataUtils';\nimport { getValueByDataKey } from '../util/ChartUtils';\nimport {\n  ActiveShape,\n  adaptEventsOfChild,\n  AnimationDuration,\n  AnimationTiming,\n  CartesianViewBoxRequired,\n  ChartOffsetInternal,\n  Coordinate,\n  DataConsumer,\n  DataKey,\n  DataProvider,\n  LegendType,\n  PresentationAttributesAdaptChildEvent,\n  TooltipType,\n  TrapezoidViewBox,\n} from '../util/types';\nimport { FunnelTrapezoid, FunnelTrapezoidProps } from '../util/FunnelUtils';\nimport {\n  useMouseClickItemDispatch,\n  useMouseEnterItemDispatch,\n  useMouseLeaveItemDispatch,\n} from '../context/tooltipContext';\nimport { TooltipPayload, TooltipPayloadConfiguration } from '../state/tooltipSlice';\nimport { SetTooltipEntrySettings } from '../state/SetTooltipEntrySettings';\nimport { ResolvedFunnelSettings, selectFunnelTrapezoids } from '../state/selectors/funnelSelectors';\nimport { findAllByType } from '../util/ReactUtils';\nimport { Cell } from '../component/Cell';\nimport { RequiresDefaultProps, resolveDefaultProps } from '../util/resolveDefaultProps';\nimport { usePlotArea } from '../hooks';\nimport { svgPropertiesNoEvents } from '../util/svgPropertiesNoEvents';\nimport { JavascriptAnimate } from '../animation/JavascriptAnimate';\nimport { useAnimationId } from '../util/useAnimationId';\nimport { GraphicalItemId } from '../state/graphicalItemsSlice';\nimport { RegisterGraphicalItemId } from '../context/RegisterGraphicalItemId';\nimport { WithIdRequired } from '../util/useUniqueId';\n\nexport type FunnelTrapezoidItem = TrapezoidProps &\n  TrapezoidViewBox & {\n    value?: number | string;\n    payload?: any;\n    tooltipPosition: Coordinate;\n    name: string;\n    labelViewBox: TrapezoidViewBox;\n    parentViewBox: CartesianViewBoxRequired;\n    val: number | ReadonlyArray<number>;\n    tooltipPayload: TooltipPayload;\n  };\n\n/**\n * Internal props, combination of external props + defaultProps + private Recharts state\n */\ntype InternalFunnelProps = RequiresDefaultProps<FunnelProps, typeof defaultFunnelProps> & {\n  id: GraphicalItemId;\n  trapezoids: ReadonlyArray<FunnelTrapezoidItem>;\n};\n\n/**\n * External props, intended for end users to fill in\n */\ninterface FunnelProps<DataPointType = any, DataValueType = any>\n  extends DataProvider<DataPointType>, Required<DataConsumer<DataPointType, DataValueType>> {\n  /**\n   * This component is rendered when this graphical item is activated\n   * (could be by mouse hover, touch, keyboard, programmatically).\n   */\n  activeShape?: ActiveShape<FunnelTrapezoidItem, SVGPathElement>;\n  /**\n   * Specifies when the animation should begin, the unit of this option is ms.\n   * @defaultValue 400\n   */\n  animationBegin?: number;\n  /**\n   * Specifies the duration of animation, the unit of this option is ms.\n   * @defaultValue 1500\n   */\n  animationDuration?: AnimationDuration;\n  /**\n   * The type of easing function.\n   * @defaultValue ease\n   */\n  animationEasing?: AnimationTiming;\n  className?: string;\n  /**\n   * Hides the whole graphical element when true.\n   *\n   * Hiding an element is different from removing it from the chart:\n   * Hidden graphical elements are still visible in Legend,\n   * and can be included in axis domain calculations,\n   * depending on `includeHidden` props of your XAxis/YAxis.\n   *\n   * @defaultValue false\n   */\n  hide?: boolean;\n  /**\n   * Unique identifier of this component.\n   * Used as an HTML attribute `id`, and also to identify this element internally.\n   *\n   * If undefined, Recharts will generate a unique ID automatically.\n   */\n  id?: string;\n  /**\n   * If set false, animation of funnel will be disabled.\n   * If set \"auto\", the animation will be disabled in SSR and will respect the user's prefers-reduced-motion system preference for accessibility.\n   * @defaultValue auto\n   */\n  isAnimationActive?: boolean | 'auto';\n  label?: ImplicitLabelListType;\n  /**\n   * @defaultValue triangle\n   */\n  lastShapeType?: 'triangle' | 'rectangle';\n  /**\n   * The type of icon in legend.  If set to 'none', no legend item will be rendered.\n   * @defaultValue rect\n   */\n  legendType?: LegendType;\n  /**\n   * Name represents each sector in the tooltip.\n   * This allows you to extract the name from the data:\n   *\n   * - `string`: the name of the field in the data object;\n   * - `number`: the index of the field in the data;\n   * - `function`: a function that receives the data object and returns the name.\n   *\n   * @defaultValue name\n   */\n  nameKey?: DataKey<DataPointType, DataValueType>;\n  /**\n   * The customized event handler of animation end\n   */\n  onAnimationEnd?: () => void;\n  /**\n   * The customized event handler of animation start\n   */\n  onAnimationStart?: () => void;\n  reversed?: boolean;\n  /**\n   * If set a ReactElement, the shape of funnel can be customized.\n   * If set a function, the function will be called to render customized shape.\n   */\n  shape?: ActiveShape<FunnelTrapezoidItem, SVGPathElement>;\n  tooltipType?: TooltipType;\n  /**\n   * The customized event handler of click on the area in this group\n   */\n  onClick?: (data: FunnelTrapezoidItem, index: number, e: React.MouseEvent<SVGPathElement>) => void;\n  /**\n   * The customized event handler of mousedown on the area in this group\n   */\n  onMouseDown?: (data: FunnelTrapezoidItem, index: number, e: React.MouseEvent<SVGPathElement>) => void;\n  /**\n   * The customized event handler of mouseup on the area in this group\n   */\n  onMouseUp?: (data: FunnelTrapezoidItem, index: number, e: React.MouseEvent<SVGPathElement>) => void;\n  /**\n   * The customized event handler of mousemove on the area in this group\n   */\n  onMouseMove?: (data: FunnelTrapezoidItem, index: number, e: React.MouseEvent<SVGPathElement>) => void;\n  /**\n   * The customized event handler of mouseover on the area in this group\n   */\n  onMouseOver?: (data: FunnelTrapezoidItem, index: number, e: React.MouseEvent<SVGPathElement>) => void;\n  /**\n   * The customized event handler of mouseout on the area in this group\n   */\n  onMouseOut?: (data: FunnelTrapezoidItem, index: number, e: React.MouseEvent<SVGPathElement>) => void;\n  /**\n   * The customized event handler of mouseenter on the area in this group\n   */\n  onMouseEnter?: (data: FunnelTrapezoidItem, index: number, e: React.MouseEvent<SVGPathElement>) => void;\n  /**\n   * The customized event handler of mouseleave on the area in this group\n   */\n  onMouseLeave?: (data: FunnelTrapezoidItem, index: number, e: React.MouseEvent<SVGPathElement>) => void;\n}\n\ntype FunnelSvgProps = Omit<PresentationAttributesAdaptChildEvent<FunnelTrapezoidItem, SVGPathElement>, 'ref'>;\n\ntype InternalProps = FunnelSvgProps & InternalFunnelProps;\n\nexport type Props<DataPointType = any, DataValueType = any> = FunnelSvgProps &\n  FunnelProps<DataPointType, DataValueType>;\n\ntype RealFunnelData = unknown;\n\ntype FunnelTrapezoidsProps = {\n  trapezoids: ReadonlyArray<FunnelTrapezoidItem>;\n  allOtherFunnelProps: InternalProps;\n};\n\nconst SetFunnelTooltipEntrySettings = React.memo(\n  ({\n    dataKey,\n    nameKey,\n    stroke,\n    strokeWidth,\n    fill,\n    name,\n    hide,\n    tooltipType,\n    data,\n    trapezoids,\n    id,\n  }: Pick<\n    InternalProps,\n    'dataKey' | 'nameKey' | 'stroke' | 'strokeWidth' | 'fill' | 'name' | 'hide' | 'tooltipType' | 'data' | 'id'\n  > & {\n    trapezoids: ReadonlyArray<FunnelTrapezoidItem>;\n  }) => {\n    const tooltipEntrySettings: TooltipPayloadConfiguration = {\n      dataDefinedOnItem: data,\n      getPosition: index => trapezoids[Number(index)]?.tooltipPosition,\n      settings: {\n        stroke,\n        strokeWidth,\n        fill,\n        dataKey,\n        name,\n        nameKey,\n        hide,\n        type: tooltipType,\n        color: fill,\n        unit: '', // Funnel does not have unit, why?\n        graphicalItemId: id,\n      },\n    };\n    return <SetTooltipEntrySettings tooltipEntrySettings={tooltipEntrySettings} />;\n  },\n);\n\nfunction FunnelLabelListProvider({\n  showLabels,\n  trapezoids,\n  children,\n}: {\n  showLabels: boolean;\n  trapezoids: ReadonlyArray<FunnelTrapezoidItem> | undefined;\n  children: ReactNode;\n}) {\n  const labelListEntries: ReadonlyArray<CartesianLabelListEntry> | undefined = useMemo(() => {\n    if (!showLabels) {\n      return undefined;\n    }\n    return trapezoids?.map((entry): CartesianLabelListEntry => {\n      const viewBox: TrapezoidViewBox = entry.labelViewBox;\n\n      return {\n        ...viewBox,\n        value: entry.name,\n        payload: entry.payload,\n        parentViewBox: entry.parentViewBox,\n        viewBox,\n        fill: entry.fill,\n      };\n    });\n  }, [showLabels, trapezoids]);\n\n  return <CartesianLabelListContextProvider value={labelListEntries}>{children}</CartesianLabelListContextProvider>;\n}\n\nfunction FunnelTrapezoids(props: FunnelTrapezoidsProps) {\n  const { trapezoids, allOtherFunnelProps } = props;\n  const activeItemIndex = useAppSelector(state =>\n    selectActiveIndex(state, 'item', state.tooltip.settings.trigger, undefined),\n  );\n  const {\n    onMouseEnter: onMouseEnterFromProps,\n    onClick: onItemClickFromProps,\n    onMouseLeave: onMouseLeaveFromProps,\n    shape,\n    activeShape,\n    ...restOfAllOtherProps\n  } = allOtherFunnelProps;\n\n  const onMouseEnterFromContext = useMouseEnterItemDispatch(\n    onMouseEnterFromProps,\n    allOtherFunnelProps.dataKey,\n    allOtherFunnelProps.id,\n  );\n  const onMouseLeaveFromContext = useMouseLeaveItemDispatch(onMouseLeaveFromProps);\n  const onClickFromContext = useMouseClickItemDispatch(\n    onItemClickFromProps,\n    allOtherFunnelProps.dataKey,\n    allOtherFunnelProps.id,\n  );\n\n  return (\n    <>\n      {trapezoids.map((entry: FunnelTrapezoidItem, i: number) => {\n        const isActiveIndex = Boolean(activeShape) && activeItemIndex === String(i);\n        const trapezoidOptions = isActiveIndex ? activeShape : shape;\n        const { id, ...trapezoidProps }: FunnelTrapezoidProps = {\n          ...entry,\n          option: trapezoidOptions,\n          isActive: isActiveIndex,\n          stroke: entry.stroke,\n        };\n\n        return (\n          <Layer\n            key={`trapezoid-${entry?.x}-${entry?.y}-${entry?.name}-${entry?.value}`}\n            className=\"recharts-funnel-trapezoid\"\n            {...adaptEventsOfChild(restOfAllOtherProps, entry, i)}\n            onMouseEnter={onMouseEnterFromContext(entry, i)}\n            onMouseLeave={onMouseLeaveFromContext(entry, i)}\n            onClick={onClickFromContext(entry, i)}\n          >\n            <FunnelTrapezoid {...trapezoidProps} />\n          </Layer>\n        );\n      })}\n    </>\n  );\n}\n\nfunction TrapezoidsWithAnimation({\n  previousTrapezoidsRef,\n  props,\n}: {\n  props: InternalProps;\n  previousTrapezoidsRef: MutableRefObject<ReadonlyArray<FunnelTrapezoidItem> | undefined>;\n}) {\n  const {\n    trapezoids,\n    isAnimationActive,\n    animationBegin,\n    animationDuration,\n    animationEasing,\n    onAnimationEnd,\n    onAnimationStart,\n  } = props;\n  const prevTrapezoids = previousTrapezoidsRef.current;\n\n  const [isAnimating, setIsAnimating] = useState(false);\n  const showLabels = !isAnimating;\n\n  const animationId = useAnimationId(trapezoids, 'recharts-funnel-');\n\n  const handleAnimationEnd = useCallback(() => {\n    if (typeof onAnimationEnd === 'function') {\n      onAnimationEnd();\n    }\n    setIsAnimating(false);\n  }, [onAnimationEnd]);\n\n  const handleAnimationStart = useCallback(() => {\n    if (typeof onAnimationStart === 'function') {\n      onAnimationStart();\n    }\n    setIsAnimating(true);\n  }, [onAnimationStart]);\n\n  return (\n    <FunnelLabelListProvider showLabels={showLabels} trapezoids={trapezoids}>\n      <JavascriptAnimate\n        animationId={animationId}\n        begin={animationBegin}\n        duration={animationDuration}\n        isActive={isAnimationActive}\n        easing={animationEasing}\n        key={animationId}\n        onAnimationStart={handleAnimationStart}\n        onAnimationEnd={handleAnimationEnd}\n      >\n        {(t: number) => {\n          const stepData: ReadonlyArray<FunnelTrapezoidItem> | undefined =\n            t === 1\n              ? trapezoids\n              : trapezoids.map((entry: FunnelTrapezoidItem, index: number): FunnelTrapezoidItem => {\n                  const prev = prevTrapezoids && prevTrapezoids[index];\n\n                  if (prev) {\n                    return {\n                      ...entry,\n                      x: interpolate(prev.x, entry.x, t),\n                      y: interpolate(prev.y, entry.y, t),\n                      upperWidth: interpolate(prev.upperWidth, entry.upperWidth, t),\n                      lowerWidth: interpolate(prev.lowerWidth, entry.lowerWidth, t),\n                      height: interpolate(prev.height, entry.height, t),\n                    };\n                  }\n\n                  return {\n                    ...entry,\n                    x: interpolate(entry.x + entry.upperWidth / 2, entry.x, t),\n                    y: interpolate(entry.y + entry.height / 2, entry.y, t),\n                    upperWidth: interpolate(0, entry.upperWidth, t),\n                    lowerWidth: interpolate(0, entry.lowerWidth, t),\n                    height: interpolate(0, entry.height, t),\n                  };\n                });\n\n          if (t > 0) {\n            // eslint-disable-next-line no-param-reassign\n            previousTrapezoidsRef.current = stepData;\n          }\n          return (\n            <Layer>\n              <FunnelTrapezoids trapezoids={stepData} allOtherFunnelProps={props} />\n            </Layer>\n          );\n        }}\n      </JavascriptAnimate>\n      <LabelListFromLabelProp label={props.label} />\n      {props.children}\n    </FunnelLabelListProvider>\n  );\n}\n\nfunction RenderTrapezoids(props: InternalProps) {\n  const previousTrapezoidsRef = useRef<ReadonlyArray<FunnelTrapezoidItem> | undefined>(undefined);\n\n  return <TrapezoidsWithAnimation props={props} previousTrapezoidsRef={previousTrapezoidsRef} />;\n}\n\nconst getRealWidthHeight = (customWidth: number | string | undefined, offset: ChartOffsetInternal) => {\n  const { width, height, left, top } = offset;\n\n  const realWidth: number = getPercentValue(customWidth, width, width);\n\n  return {\n    realWidth,\n    realHeight: height,\n    offsetX: left,\n    offsetY: top,\n  };\n};\n\nexport const defaultFunnelProps = {\n  animationBegin: 400,\n  animationDuration: 1500,\n  animationEasing: 'ease',\n  fill: '#808080',\n  hide: false,\n  isAnimationActive: 'auto',\n  lastShapeType: 'triangle',\n  legendType: 'rect',\n  nameKey: 'name',\n  reversed: false,\n  stroke: '#fff',\n} as const satisfies Partial<Props>;\n\nfunction FunnelImpl(props: WithIdRequired<RequiresDefaultProps<Props, typeof defaultFunnelProps>>) {\n  const plotArea = usePlotArea();\n\n  const {\n    stroke,\n    fill,\n    legendType,\n    hide,\n    isAnimationActive,\n    animationBegin,\n    animationDuration,\n    animationEasing,\n    nameKey,\n    lastShapeType,\n    id,\n    ...everythingElse\n  } = props;\n\n  const presentationProps = svgPropertiesNoEvents(props);\n  const cells = findAllByType(props.children, Cell);\n\n  const funnelSettings: ResolvedFunnelSettings = useMemo(\n    () => ({\n      dataKey: props.dataKey,\n      nameKey,\n      data: props.data,\n      tooltipType: props.tooltipType,\n      lastShapeType,\n      reversed: props.reversed,\n      customWidth: props.width,\n      cells,\n      presentationProps,\n      id,\n    }),\n    [\n      props.dataKey,\n      nameKey,\n      props.data,\n      props.tooltipType,\n      lastShapeType,\n      props.reversed,\n      props.width,\n      cells,\n      presentationProps,\n      id,\n    ],\n  );\n\n  const trapezoids = useAppSelector(state => selectFunnelTrapezoids(state, funnelSettings));\n\n  if (hide || !trapezoids || !trapezoids.length || !plotArea) {\n    return null;\n  }\n  const { height, width } = plotArea;\n\n  const layerClass = clsx('recharts-trapezoids', props.className);\n\n  return (\n    <>\n      <SetFunnelTooltipEntrySettings\n        dataKey={props.dataKey}\n        nameKey={props.nameKey}\n        stroke={props.stroke}\n        strokeWidth={props.strokeWidth}\n        fill={props.fill}\n        name={props.name}\n        hide={props.hide}\n        tooltipType={props.tooltipType}\n        data={props.data}\n        trapezoids={trapezoids}\n        id={id}\n      />\n      <Layer className={layerClass}>\n        <RenderTrapezoids\n          {...everythingElse}\n          id={id}\n          stroke={stroke}\n          fill={fill}\n          nameKey={nameKey}\n          lastShapeType={lastShapeType}\n          animationBegin={animationBegin}\n          animationDuration={animationDuration}\n          animationEasing={animationEasing}\n          isAnimationActive={isAnimationActive}\n          hide={hide}\n          legendType={legendType}\n          height={height}\n          width={width}\n          trapezoids={trapezoids}\n        />\n      </Layer>\n    </>\n  );\n}\n\nexport function computeFunnelTrapezoids({\n  dataKey,\n  nameKey,\n  displayedData,\n  tooltipType,\n  lastShapeType,\n  reversed,\n  offset,\n  customWidth,\n  graphicalItemId,\n}: {\n  dataKey: Props['dataKey'];\n  nameKey: Props['nameKey'];\n  offset: ChartOffsetInternal;\n  displayedData: ReadonlyArray<RealFunnelData>;\n  tooltipType?: TooltipType;\n  lastShapeType?: Props['lastShapeType'];\n  reversed?: boolean;\n  customWidth: number | string | undefined;\n  graphicalItemId: GraphicalItemId;\n}): ReadonlyArray<FunnelTrapezoidItem> {\n  const { realHeight, realWidth, offsetX, offsetY } = getRealWidthHeight(customWidth, offset);\n  const values = displayedData.map((entry: unknown) => {\n    const val = getValueByDataKey(entry, dataKey, 0);\n    return typeof val === 'number' ? val : 0;\n  });\n  const maxValue = Math.max.apply(null, values);\n  const len = displayedData.length;\n  const rowHeight = realHeight / len;\n  const parentViewBox = { x: offset.left, y: offset.top, width: offset.width, height: offset.height };\n\n  let trapezoids: ReadonlyArray<FunnelTrapezoidItem> = displayedData.map(\n    (entry: unknown, i: number): FunnelTrapezoidItem => {\n      // getValueByDataKey does not validate the output type\n      const rawVal: number | ReadonlyArray<number> = getValueByDataKey(entry, dataKey, 0);\n      const name: string = String(getValueByDataKey(entry, nameKey, i));\n      let val = rawVal;\n      let nextVal: number | ReadonlyArray<number> | undefined;\n\n      if (i !== len - 1) {\n        const nextDataValue = getValueByDataKey(displayedData[i + 1], dataKey, 0);\n        if (typeof nextDataValue === 'number') {\n          nextVal = nextDataValue;\n        } else if (Array.isArray(nextDataValue)) {\n          const [first, second] = nextDataValue;\n          if (typeof first === 'number') {\n            val = first;\n          }\n          if (typeof second === 'number') {\n            nextVal = second;\n          }\n        }\n      } else if (rawVal instanceof Array && rawVal.length === 2) {\n        const [first, second] = rawVal;\n        if (typeof first === 'number') {\n          val = first;\n        }\n        if (typeof second === 'number') {\n          nextVal = second;\n        }\n      } else if (lastShapeType === 'rectangle') {\n        nextVal = val;\n      } else {\n        nextVal = 0;\n      }\n\n      // @ts-expect-error this is a problem if we have ranged values because `val` can be an array\n      const x = ((maxValue - val) * realWidth) / (2 * maxValue) + offsetX;\n      const y = rowHeight * i + offsetY;\n      // @ts-expect-error getValueByDataKey does not validate the output type\n      const upperWidth = (val / maxValue) * realWidth;\n      // @ts-expect-error next